(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-023"]={"sura":23,"name_ar":"المؤمنون","name_en":"Al-Mu'minun","verses":118,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":118,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=11\" class=\"link\">23:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:11 ஐ பார்க்கவும்"},"11":{"html":"<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>இங்கு விவரிக்கப்பட்டுள்ள பண்புகளைக் கொண்ட மூஃமின்களுக்கே (இறைநம்பிக்கையாளர்களுக்கே) வெற்றி</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக மூஃமின்கள் வெற்றி பெற்றுவிட்டனர்.) அதாவது, அவர்கள் வெற்றியடைந்துவிட்டார்கள், பெரும் பாக்கியம் பெற்றுவிட்டார்கள். பின்வரும் பண்புகளைக் கொண்டவர்களே அந்த மூஃமின்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">صَلاَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">خَاشِعُونَ</span><br />\r\n<br />\r\n(அவர்கள் எத்தகையவர்கள் என்றால், தங்கள் ஸலாவில் (தொழுகையில்) 'காஷிஊன்'களாக - உள்ளச்சம் உடையவர்களாக இருப்பார்கள்.) அலி பின் அபீ தல்ஹா அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خَاشِعُونَ</span><br />\r\n<br />\r\n\"(காஷிஊன்) என்பது அச்சத்தோடும் மன அமைதியோடும் இருப்பவர்களைக் குறிக்கும்.\" இது முஜாஹித், அல்-ஹசன், கத்தாதா மற்றும் அஸ்-ஸுஹ்ரீ ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அலி பின் அபீ தாலிப் (ரழி) அவர்கள் 'குஷூஉ' என்றால் அது உள்ளத்தின் பணிவு என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது. இதுவே இப்ராஹீம் அந்-நகஈ அவர்களின் கருத்தாகவும் இருந்தது. அல்-ஹசன் அல்-பஸ்ரீ அவர்கள், \"அவர்களுடைய உள்ளச்சம் அவர்களின் உள்ளங்களில் இருந்தது, அதனால் அவர்கள் தங்கள் பார்வையைத் தாழ்த்திக் கொண்டனர், மற்றவர்களிடம் பணிவுடன் நடந்துகொண்டனர்\" என்று கூறினார்கள். தன் உள்ளத்தை முழுமையாக இறைச் சிந்தனையில் ஈடுபடுத்தி, தொழுகையைத் தவிர வேறு எதிலும் கவனம் செலுத்தாமல், எல்லாவற்றையும் விட அதற்கே முன்னுரிமை கொடுப்பவரால் மட்டுமே தொழுகையில் இந்த உள்ளச்சத்தை அடைய முடியும். அந்த நிலையில், தொழுகை ஒருவருக்குக் கண்ணின் குளிர்ச்சியாகவும், ஆன்மாவின் மகிழ்ச்சியாகவும் மாறிவிடும். இமாம் அஹ்மத் மற்றும் அந்-நஸாயீ அவர்கள் பதிவு செய்த ஹதீஸில் அனஸ் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حُبِّبَ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">الطِّيبُ</span> <span class=\"quran-arabic-font text-success\">وَالنِّسَاءُ،</span> <span class=\"quran-arabic-font text-success\">وَجُعِلَتْ</span> <span class=\"quran-arabic-font text-success\">قُرَّةُ</span> <span class=\"quran-arabic-font text-success\">عَيْنِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصَّلَاة</span>»<br />\r\n<br />\r\n(நறுமணமும் பெண்களும் எனக்கு விருப்பமானவைகளாக ஆக்கப்பட்டன; மேலும் தொழுகை என் கண்களின் குளிர்ச்சியாக ஆக்கப்பட்டது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">اللَّغْوِ</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் வீணானவற்றிலிருந்து விலகி இருப்பார்கள்.) இது பொய்யைக் குறிக்கிறது. இதில் ஷிர்க் (இணைவைத்தல்), பாவங்கள் மற்றும் எந்தப் பயனும் தராத வீணான பேச்சுக்கள் அல்லது செயல்கள் அனைத்தும் அடங்கும். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّغْوِ</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">كِراماً</span><br />\r\n<br />\r\n(மேலும், அவர்கள் வீணானவற்றைக் கடந்து செல்ல நேரிட்டால், கண்ணியமான முறையில் கடந்து செல்வார்கள்) <a href=\"qurandisp.php?sura=25&ayah=72\" class=\"link\">25:72</a>. கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக, தீயவற்றிலிருந்து அவர்களைத் தடுத்துக் காக்கும் அறிவுரை அல்லாஹ்விடமிருந்து அவர்களுக்கு வந்திருந்தது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لِلزَّكَاةِ</span> <span class=\"quran-arabic-font text-success\">فَاعِلُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் ஸகாத்தை நிறைவேற்றுவார்கள்.) இந்த வசனம் மக்காவில் அருளப்பட்டிருந்தாலும், பெரும்பாலான விரிவுரையாளர்கள் 'ஸகாத்' என்பது செல்வத்தின் மீது வழங்கப்படும் கடமையான தர்மத்தையே குறிப்பதாகக் கூறுகிறார்கள். உண்மையில், ஸகாத் ஹிஜ்ரி 2-ஆம் ஆண்டு மதீனாவில்தான் முறையான நிஸாப் (குறிப்பிட்ட அளவு) மற்றும் விகிதாச்சாரங்களுடன் கடமையாக்கப்பட்டது. இருப்பினும், ஸகாத்தின் அடிப்படைக் கொள்கை மக்காவிலேயே வலியுறுத்தப்பட்டது என்பதை இது காட்டுகிறது. மக்காவில் அருளப்பட்ட சூரத்துல் அன்ஆமில் அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَاتُواْ</span> <span class=\"quran-arabic-font text-success\">حَقَّهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">حَصَادِهِ</span><br />\r\n<br />\r\n(அறுவடை நாளில் அதற்குரிய கடமையை (ஏழைகளுக்கு) வழங்கிவிடுங்கள்) <a href=\"qurandisp.php?sura=6&ayah=141\" class=\"link\">6:141</a>. அல்லது இங்கு ஸகாத் என்பது, பின்வரும் வசனத்தில் கூறப்பட்டுள்ளது போல, ஷிர்க் மற்றும் அசுத்தங்களிலிருந்து ஆன்மாவைத் தூய்மைப்படுத்துவதையும் குறிக்கலாம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">زَكَّاهَا</span> - <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَابَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">دَسَّاهَا</span><br />\r\n<br />\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர் நிச்சயமாக வெற்றி பெற்றார். தன்னை அசுத்தப்படுத்திக் கொண்டவர் (பாவத்தில் புதைத்தவர்) நிச்சயமாகத் தோல்வியடைந்தார்.) <a href=\"qurandisp.php?sura=91&ayah=9\" class=\"link\">91:9</a>-10. ஆன்மாவைத் தூய்மைப்படுத்துதல் மற்றும் செல்வத்தைத் தூய்மைப்படுத்துதல் ஆகிய இரண்டுமே இங்கு நாடப்பட்டிருக்கலாம்; ஏனெனில் செல்வத்தைத் தூய்மைப்படுத்துவதும் ஆன்மத் தூய்மையின் ஒரு பகுதியாகும். ஒரு உண்மையான மூஃமின் இவ்விரண்டிலும் கவனம் செலுத்துபவராக இருப்பார். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لِفُرُوجِهِمْ</span> <span class=\"quran-arabic-font text-success\">حَافِظُونَ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَانُهُمْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">مَلُومِينَ</span> - <span class=\"quran-arabic-font text-success\">فَمَنِ</span> <span class=\"quran-arabic-font text-success\">ابْتَغَى</span> <span class=\"quran-arabic-font text-success\">وَرَآءَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَادُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்களின் மறைவிடங்களைக் காத்துக் கொள்வார்கள். தங்கள் மனைவிகளிடமோ அல்லது தங்கள் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்களிடமோ தவிர; அவ்வாறு இருப்பின் அவர்கள் பழிக்கப்பட மாட்டார்கள். ஆனால், இதற்கு அப்பால் எவரேனும் தேடினால், அவர்களே வரம்பு மீறியவர்கள்.) இதன் பொருள், அல்லாஹ் தடுத்த விபச்சாரம், ஓரினச்சேர்க்கை போன்ற அசிங்கமான செயல்களிலிருந்து தங்கள் மறைவிடங்களைப் பாதுகாப்பவர்கள். அல்லாஹ் அனுமதித்துள்ள மனைவிகள் மற்றும் போர்க்கைதிகளில் தங்கள் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்களிடம் தாம்பத்திய உறவு கொள்வதில் அவர்கள் மீது எந்தக் குற்றமும் இல்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">مَلُومِينَ</span> - <span class=\"quran-arabic-font text-success\">فَمَنِ</span> <span class=\"quran-arabic-font text-success\">ابْتَغَى</span> <span class=\"quran-arabic-font text-success\">وَرَآءَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் பழிக்கப்பட்டவர்கள் அல்லர். ஆனால், இதற்கு அப்பால் எவரேனும் தேடினால்,) அதாவது மனைவி அல்லது அடிமைப் பெண்ணைத் தவிர வேறு ஒருவரைத் தேடினால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَادُونَ</span><br />\r\n<br />\r\n(அவர்களே வரம்பு மீறியவர்கள்.) அதாவது சட்டத்தை மீறி அத்துமீறுபவர்கள். இமாம் ஷாஃபிஈ (ரஹ்) அவர்களும், மற்றும் பல அறிஞர்களும் இவ்வசனத்தை ஆதாரமாகக் கொண்டு, கையில் இன்பம் காண்பது (கைப்பழக்கம்) ஹராம் என்று தீர்ப்பளித்துள்ளனர். ஏனெனில், இவ்விரு வழிகளைத் (மனைவி மற்றும் அடிமைப் பெண்) தவிர வேறு வழிகள் அனுமதிக்கப்படவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لِأَمَانَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَعَهْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">رَعُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்களுடைய அமானிதங்களையும், வாக்குறுதிகளையும் பேணி நடப்பவர்கள்.) அவர்களிடம் ஏதாவது ஒரு பொறுப்போ அல்லது பொருளோ நம்பி ஒப்படைக்கப்பட்டால், அவர்கள் அதற்குத் துரோகம் செய்யாமல் முறையாக நிறைவேற்றுவார்கள். ஒரு வாக்குறுதி அளித்தால் அல்லது ஒப்பந்தம் செய்தால் அதைத் தவறாமல் கடைப்பிடிப்பார்கள். இது நயவஞ்சகர்களின் பண்புக்கு நேர்மாறானது. அவர்களைப் பற்றி அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">آيَةُ</span> <span class=\"quran-arabic-font text-success\">الْمُنَافِقِ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثٌ</span>: <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">حَدَّثَ</span> <span class=\"quran-arabic-font text-success\">كَذَبَ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">أَخْلَفَ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">اؤْتُمِنَ</span> <span class=\"quran-arabic-font text-success\">خَان</span>»<br />\r\n<br />\r\n(நயவஞ்சகனின் அடையாளங்கள் மூன்று: அவன் பேசினால் பொய் பேசுவான், வாக்குறுதி அளித்தால் அதை மீறுவான், அவனிடம் ஏதேனும் நம்பி ஒப்படைக்கப்பட்டால் அதற்குத் துரோகம் செய்வான்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صَلَوَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">يُحَافِظُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் ஸலவாத்தை (தொழுகைகளை) முறைப்படி பேணிக் கொள்வார்கள்.) அதாவது, அவர்கள் தங்கள் தொழுகைகளை அவற்றுக்குரிய நேரங்களில் முறையாக நிறைவேற்றுவார்கள். இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறுகிறார்கள்: \"நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம், 'அல்லாஹ்வின் தூதரே, அல்லாஹ்வுக்கு மிகவும் விருப்பமான செயல் எது?' என்று கேட்டேன். அதற்கு அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الصَّلَاةُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وَقْتِهَا</span>»<br />\r\n<br />\r\n(தொழுகையை அதற்குரிய நேரத்தில் நிறைவேற்றுவது) என்றார்கள். நான் 'பிறகு எது?' என்றேன். அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بِرُّ</span> <span class=\"quran-arabic-font text-success\">الْوَالِدَيْن</span>»<br />\r\n<br />\r\n(பெற்றோருக்குப் பணிவிடை செய்வது) என்றார்கள். நான் 'பிறகு எது?' என்றேன். அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْجِهَادُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">الله</span>»<br />\r\n<br />\r\n(அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வது) என்றார்கள்.\" இது புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது. கத்தாதா அவர்கள் கூறுகிறார்கள்: \"தொழுகையை அதற்குரிய நேரங்களில், முறையான ருகூஉ மற்றும் ஸஜ்தாக்களுடன் நிறைவேற்றுவதைக் குறிக்கும்.\" அல்லாஹ் இந்தப் புகழுக்குரிய பண்புகளின் பட்டியலைத் தொழுகையோடு தொடங்கித் தொழுகையோடு முடிக்கிறான். இது தொழுகையின் மகத்துவத்தைக் காட்டுகிறது. நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اسْتَقِيمُوا</span> <span class=\"quran-arabic-font text-success\">وَلَنْ</span> <span class=\"quran-arabic-font text-success\">تُحْصُوا،</span> <span class=\"quran-arabic-font text-success\">وَاعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">خَيْرَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالِكُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُحَافِظُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْوُضُوءِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مُؤْمِن</span>»<br />\r\n<br />\r\n(நேர்மையைக் கடைப்பிடியுங்கள், உங்களால் நன்மைகளை முழுமையாகக் கணக்கிட முடியாது. உங்கள் செயல்களில் சிறந்தது தொழுகை என்பதை அறிந்து கொள்ளுங்கள். ஒரு முஃமினைத் தவிர வேறு யாரும் தனது வுளூவைப் பேணிக் கொள்ள மாட்டார்.) இத்தகைய நற்பண்புகள் மற்றும் நற்செயல்களைக் கொண்டவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْوَارِثُونَ</span> - <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَرِثُونَ</span> <span class=\"quran-arabic-font text-success\">الْفِرْدَوْسَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">خَالِدُونَ</span><br />\r\n<br />\r\n(இவர்களே வாரிசுதாரர்கள். அவர்கள் ஃபிர்தவ்ஸை (எனும் உயரிய சுவனத்தை) வாரிசாகப் பெறுவார்கள். அதில் அவர்கள் நிரந்தரமாகத் தங்குவார்கள்.) புகாரி மற்றும் முஸ்லிமில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُمُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلُوهُ</span> <span class=\"quran-arabic-font text-success\">الْفِرْدَوْسَ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَى</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَأَوْسَطُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُ</span> <span class=\"quran-arabic-font text-success\">تَفَجَّرُ</span> <span class=\"quran-arabic-font text-success\">أَنْهَارُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَفَوْقَهُ</span> <span class=\"quran-arabic-font text-success\">عَرْشُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمن</span>»<br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்விடம் சுவனத்தைக் கேட்டால், அல்-ஃபிர்தவ்ஸைக் கேளுங்கள். ஏனெனில் அது சுவனத்தின் மிக உயர்ந்த பகுதியாகும், சுவனத்தின் மையப்பகுதியாகும். அங்கிருந்துதான் சுவனத்தின் ஆறுகள் உற்பத்தியாகின்றன. அதன் மேலே அளவற்ற அருளாளனின் (அல்லாஹ்வின்) அர்ஷ் உள்ளது.) இப்னு அபீ ஹாதிம் அவர்கள் அபூ ஹுரைரா (ரழி) வழியாகப் பதிவு செய்துள்ள ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">مَنْزِلَانِ</span>: <span class=\"quran-arabic-font text-success\">مَنْزِلٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْزِلٌ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">مَاتَ</span> <span class=\"quran-arabic-font text-success\">فَدَخَلَ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">وَرِثَ</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">مَنْزِلَهُ،</span> <span class=\"quran-arabic-font text-success\">فَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">قَوْلُهُ</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْوَارِثُونَ</span><br />\r\n<br />\r\n»<br />\r\n<br />\r\n(உங்களில் ஒவ்வொருவருக்கும் இரண்டு தங்குமிடங்கள் உள்ளன: ஒரு இடம் சுவனத்திலும், ஒரு இடம் நரகத்திலும். ஒருவர் இறந்து நரகத்திற்குச் சென்றால், சுவனவாசிகள் அவருடைய (சுவனத்து) இடத்தை வாரிசாகப் பெற்றுக் கொள்வார்கள். இதையே 'இவர்களே வாரிசுதாரர்கள்' எனும் வசனம் குறிப்பிடுகிறது.)<br />\r\n<br />\r\nமுஜாஹித் அவர்கள் கூறியதாக இப்னு ஜுரைஜ் கூறுகிறார்கள்: \"(இவர்களே வாரிசுதாரர்கள்) என்பதில் மூஃமின்கள் நிராகரிப்பாளர்களின் இடங்களைச் சுவீகரித்துக் கொள்வதைக் குறிக்கிறது. ஏனெனில், ஒவ்வொரு மனிதனும் இணை துணையற்ற அல்லாஹ்வை வணங்குவதற்காகவே படைக்கப்பட்டான். மூஃமின்கள் தங்களுக்குக் கட்டளையிடப்பட்ட வணக்கங்களைச் செய்தனர். ஆனால் நிராகரிப்பாளர்கள் எதற்காகப் படைக்கப்பட்டார்களோ, அந்தக் கட்டளையைப் புறக்கணித்தனர். எனவே, அவர்கள் இறைவனுக்குக் கீழ்ப்படிந்திருந்தால் அவர்களுக்குக் கிடைத்திருக்க வேண்டிய சுவனத்துப் பங்கை, மூஃமின்கள் பெற்றுக் கொள்கிறார்கள். மேலும் அவர்களுக்கு அதை விடவும் அதிகமாக வழங்கப்படலாம்.\"<br />\r\n<br />\r\nஇதை உறுதிப்படுத்தும் வகையில் ஸஹீஹ் முஸ்லிமில் அபூ புர்தா அவர்கள் தன் தந்தை வழியாக நபி (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"மறுமை நாளில் முஸ்லிம்களில் சிலர் மலைகளைப் போன்ற பாவங்களுடன் வருவார்கள். அல்லாஹ் அவர்களுக்கு மன்னிப்பு வழங்கிவிட்டு, அந்தப் பாவங்களை யூதர்கள் மற்றும் கிறிஸ்தவர்கள் மீது சுமத்துவான்.\" மற்றொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்: \"மறுமை நாளில் அல்லாஹ் ஒவ்வொரு முஸ்லிமுக்கும் ஒரு யூதரையும் கிறிஸ்தவரையும் ஒதுக்கிவிட்டு, 'இதுவே நரகத்திலிருந்து உனக்கான ஈட்டுத் தொகை (விடுபடும் வழி)' என்று கூறுவான்.\" உமர் பின் அப்துல் அஸீஸ் அவர்கள் அபூ புர்தாவிடம், தன் தந்தை நபி (ஸல்) அவர்களிடமிருந்துதான் இதைக் கூறினாரா என்று அல்லாஹ்வை முன்னிறுத்தி சத்தியம் கேட்டார்கள், அவரும் சத்தியம் செய்தார்.<br />\r\n<br />\r\nநான் கூறுகிறேன்: இந்த வசனம் அல்லாஹ்வின் பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">نُورِثُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِنَا</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">تَقِيّاً</span><br />\r\n<br />\r\n(அதுதான் சுவனம்; அதனை நமது அடியார்களில் தக்வா (இறையச்சம்) உடையவர்களுக்கு நாம் வாரிசாக்குவோம்.) <a href=\"qurandisp.php?sura=19&ayah=63\" class=\"link\">19:63</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أُورِثْتُمُوهَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(இதுதான் சுவனம்; நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக இதனை நீங்கள் வாரிசாகப் பெற்றுக்கொண்டீர்கள்.) <a href=\"qurandisp.php?sura=43&ayah=72\" class=\"link\">43:72</a><br />\r\n<br />","text":"بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஇங்கு விவரிக்கப்பட்டுள்ள பண்புகளைக் கொண்ட மூஃமின்களுக்கே (இறைநம்பிக்கையாளர்களுக்கே) வெற்றி\n\r\n\n\r\nقَدْ أَفْلَحَ الْمُؤْمِنُونَ\n\r\n\n\r\n(நிச்சயமாக மூஃமின்கள் வெற்றி பெற்றுவிட்டனர்.) அதாவது, அவர்கள் வெற்றியடைந்துவிட்டார்கள், பெரும் பாக்கியம் பெற்றுவிட்டார்கள். பின்வரும் பண்புகளைக் கொண்டவர்களே அந்த மூஃமின்கள்:\n\r\n\n\r\nالَّذِينَ هُمْ فِى صَلاَتِهِمْ خَاشِعُونَ\n\r\n\n\r\n(அவர்கள் எத்தகையவர்கள் என்றால், தங்கள் ஸலாவில் (தொழுகையில்) 'காஷிஊன்'களாக - உள்ளச்சம் உடையவர்களாக இருப்பார்கள்.) அலி பின் அபீ தல்ஹா அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nخَاشِعُونَ\n\r\n\n\r\n\"(காஷிஊன்) என்பது அச்சத்தோடும் மன அமைதியோடும் இருப்பவர்களைக் குறிக்கும்.\" இது முஜாஹித், அல்-ஹசன், கத்தாதா மற்றும் அஸ்-ஸுஹ்ரீ ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அலி பின் அபீ தாலிப் (ரழி) அவர்கள் 'குஷூஉ' என்றால் அது உள்ளத்தின் பணிவு என்று கூறியதாக அறிவிக்கப்பட்டுள்ளது. இதுவே இப்ராஹீம் அந்-நகஈ அவர்களின் கருத்தாகவும் இருந்தது. அல்-ஹசன் அல்-பஸ்ரீ அவர்கள், \"அவர்களுடைய உள்ளச்சம் அவர்களின் உள்ளங்களில் இருந்தது, அதனால் அவர்கள் தங்கள் பார்வையைத் தாழ்த்திக் கொண்டனர், மற்றவர்களிடம் பணிவுடன் நடந்துகொண்டனர்\" என்று கூறினார்கள். தன் உள்ளத்தை முழுமையாக இறைச் சிந்தனையில் ஈடுபடுத்தி, தொழுகையைத் தவிர வேறு எதிலும் கவனம் செலுத்தாமல், எல்லாவற்றையும் விட அதற்கே முன்னுரிமை கொடுப்பவரால் மட்டுமே தொழுகையில் இந்த உள்ளச்சத்தை அடைய முடியும். அந்த நிலையில், தொழுகை ஒருவருக்குக் கண்ணின் குளிர்ச்சியாகவும், ஆன்மாவின் மகிழ்ச்சியாகவும் மாறிவிடும். இமாம் அஹ்மத் மற்றும் அந்-நஸாயீ அவர்கள் பதிவு செய்த ஹதீஸில் அனஸ் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\n«حُبِّبَ إِلَيَّ الطِّيبُ وَالنِّسَاءُ، وَجُعِلَتْ قُرَّةُ عَيْنِي فِي الصَّلَاة»\n\r\n\n\r\n(நறுமணமும் பெண்களும் எனக்கு விருப்பமானவைகளாக ஆக்கப்பட்டன; மேலும் தொழுகை என் கண்களின் குளிர்ச்சியாக ஆக்கப்பட்டது.)\n\r\n\n\r\nوَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُّعْرِضُونَ\n\r\n\n\r\n(மேலும் அவர்கள் வீணானவற்றிலிருந்து விலகி இருப்பார்கள்.) இது பொய்யைக் குறிக்கிறது. இதில் ஷிர்க் (இணைவைத்தல்), பாவங்கள் மற்றும் எந்தப் பயனும் தராத வீணான பேச்சுக்கள் அல்லது செயல்கள் அனைத்தும் அடங்கும். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَإِذَا مَرُّواْ بِاللَّغْوِ مَرُّواْ كِراماً\n\r\n\n\r\n(மேலும், அவர்கள் வீணானவற்றைக் கடந்து செல்ல நேரிட்டால், கண்ணியமான முறையில் கடந்து செல்வார்கள்) 25:72. கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக, தீயவற்றிலிருந்து அவர்களைத் தடுத்துக் காக்கும் அறிவுரை அல்லாஹ்விடமிருந்து அவர்களுக்கு வந்திருந்தது.\"\n\r\n\n\r\nوَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ\n\r\n\n\r\n(மேலும் அவர்கள் ஸகாத்தை நிறைவேற்றுவார்கள்.) இந்த வசனம் மக்காவில் அருளப்பட்டிருந்தாலும், பெரும்பாலான விரிவுரையாளர்கள் 'ஸகாத்' என்பது செல்வத்தின் மீது வழங்கப்படும் கடமையான தர்மத்தையே குறிப்பதாகக் கூறுகிறார்கள். உண்மையில், ஸகாத் ஹிஜ்ரி 2-ஆம் ஆண்டு மதீனாவில்தான் முறையான நிஸாப் (குறிப்பிட்ட அளவு) மற்றும் விகிதாச்சாரங்களுடன் கடமையாக்கப்பட்டது. இருப்பினும், ஸகாத்தின் அடிப்படைக் கொள்கை மக்காவிலேயே வலியுறுத்தப்பட்டது என்பதை இது காட்டுகிறது. மக்காவில் அருளப்பட்ட சூரத்துல் அன்ஆமில் அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَءَاتُواْ حَقَّهُ يَوْمَ حَصَادِهِ\n\r\n\n\r\n(அறுவடை நாளில் அதற்குரிய கடமையை (ஏழைகளுக்கு) வழங்கிவிடுங்கள்) 6:141. அல்லது இங்கு ஸகாத் என்பது, பின்வரும் வசனத்தில் கூறப்பட்டுள்ளது போல, ஷிர்க் மற்றும் அசுத்தங்களிலிருந்து ஆன்மாவைத் தூய்மைப்படுத்துவதையும் குறிக்கலாம்:\n\r\n\n\r\nقَدْ أَفْلَحَ مَن زَكَّاهَا - وَقَدْ خَابَ مَن دَسَّاهَا\n\r\n\n\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர் நிச்சயமாக வெற்றி பெற்றார். தன்னை அசுத்தப்படுத்திக் கொண்டவர் (பாவத்தில் புதைத்தவர்) நிச்சயமாகத் தோல்வியடைந்தார்.) 91:9-10. ஆன்மாவைத் தூய்மைப்படுத்துதல் மற்றும் செல்வத்தைத் தூய்மைப்படுத்துதல் ஆகிய இரண்டுமே இங்கு நாடப்பட்டிருக்கலாம்; ஏனெனில் செல்வத்தைத் தூய்மைப்படுத்துவதும் ஆன்மத் தூய்மையின் ஒரு பகுதியாகும். ஒரு உண்மையான மூஃமின் இவ்விரண்டிலும் கவனம் செலுத்துபவராக இருப்பார். அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nوَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ - إِلاَّ عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ - فَمَنِ ابْتَغَى وَرَآءَ ذلِكَ فَأُوْلَـئِكَ هُمُ الْعَادُونَ\n\r\n\n\r\n(மேலும் அவர்கள் தங்களின் மறைவிடங்களைக் காத்துக் கொள்வார்கள். தங்கள் மனைவிகளிடமோ அல்லது தங்கள் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்களிடமோ தவிர; அவ்வாறு இருப்பின் அவர்கள் பழிக்கப்பட மாட்டார்கள். ஆனால், இதற்கு அப்பால் எவரேனும் தேடினால், அவர்களே வரம்பு மீறியவர்கள்.) இதன் பொருள், அல்லாஹ் தடுத்த விபச்சாரம், ஓரினச்சேர்க்கை போன்ற அசிங்கமான செயல்களிலிருந்து தங்கள் மறைவிடங்களைப் பாதுகாப்பவர்கள். அல்லாஹ் அனுமதித்துள்ள மனைவிகள் மற்றும் போர்க்கைதிகளில் தங்கள் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்களிடம் தாம்பத்திய உறவு கொள்வதில் அவர்கள் மீது எந்தக் குற்றமும் இல்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَإِنَّهُمْ غَيْرُ مَلُومِينَ - فَمَنِ ابْتَغَى وَرَآءَ ذلِكَ\n\r\n\n\r\n(நிச்சயமாக அவர்கள் பழிக்கப்பட்டவர்கள் அல்லர். ஆனால், இதற்கு அப்பால் எவரேனும் தேடினால்,) அதாவது மனைவி அல்லது அடிமைப் பெண்ணைத் தவிர வேறு ஒருவரைத் தேடினால்,\n\r\n\n\r\nفَأُوْلَـئِكَ هُمُ الْعَادُونَ\n\r\n\n\r\n(அவர்களே வரம்பு மீறியவர்கள்.) அதாவது சட்டத்தை மீறி அத்துமீறுபவர்கள். இமாம் ஷாஃபிஈ (ரஹ்) அவர்களும், மற்றும் பல அறிஞர்களும் இவ்வசனத்தை ஆதாரமாகக் கொண்டு, கையில் இன்பம் காண்பது (கைப்பழக்கம்) ஹராம் என்று தீர்ப்பளித்துள்ளனர். ஏனெனில், இவ்விரு வழிகளைத் (மனைவி மற்றும் அடிமைப் பெண்) தவிர வேறு வழிகள் அனுமதிக்கப்படவில்லை.\n\r\n\n\r\nوَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَعُونَ\n\r\n\n\r\n(மேலும் அவர்கள் தங்களுடைய அமானிதங்களையும், வாக்குறுதிகளையும் பேணி நடப்பவர்கள்.) அவர்களிடம் ஏதாவது ஒரு பொறுப்போ அல்லது பொருளோ நம்பி ஒப்படைக்கப்பட்டால், அவர்கள் அதற்குத் துரோகம் செய்யாமல் முறையாக நிறைவேற்றுவார்கள். ஒரு வாக்குறுதி அளித்தால் அல்லது ஒப்பந்தம் செய்தால் அதைத் தவறாமல் கடைப்பிடிப்பார்கள். இது நயவஞ்சகர்களின் பண்புக்கு நேர்மாறானது. அவர்களைப் பற்றி அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَان»\n\r\n\n\r\n(நயவஞ்சகனின் அடையாளங்கள் மூன்று: அவன் பேசினால் பொய் பேசுவான், வாக்குறுதி அளித்தால் அதை மீறுவான், அவனிடம் ஏதேனும் நம்பி ஒப்படைக்கப்பட்டால் அதற்குத் துரோகம் செய்வான்.)\n\r\n\n\r\nوَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் ஸலவாத்தை (தொழுகைகளை) முறைப்படி பேணிக் கொள்வார்கள்.) அதாவது, அவர்கள் தங்கள் தொழுகைகளை அவற்றுக்குரிய நேரங்களில் முறையாக நிறைவேற்றுவார்கள். இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறுகிறார்கள்: \"நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம், 'அல்லாஹ்வின் தூதரே, அல்லாஹ்வுக்கு மிகவும் விருப்பமான செயல் எது?' என்று கேட்டேன். அதற்கு அவர்கள்,\n\r\n\n\r\n«الصَّلَاةُ عَلَى وَقْتِهَا»\n\r\n\n\r\n(தொழுகையை அதற்குரிய நேரத்தில் நிறைவேற்றுவது) என்றார்கள். நான் 'பிறகு எது?' என்றேன். அவர்கள்,\n\r\n\n\r\n«بِرُّ الْوَالِدَيْن»\n\r\n\n\r\n(பெற்றோருக்குப் பணிவிடை செய்வது) என்றார்கள். நான் 'பிறகு எது?' என்றேன். அவர்கள்,\n\r\n\n\r\n«الْجِهَادُ فِي سَبِيلِ الله»\n\r\n\n\r\n(அல்லாஹ்வின் பாதையில் ஜிஹாத் செய்வது) என்றார்கள்.\" இது புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது. கத்தாதா அவர்கள் கூறுகிறார்கள்: \"தொழுகையை அதற்குரிய நேரங்களில், முறையான ருகூஉ மற்றும் ஸஜ்தாக்களுடன் நிறைவேற்றுவதைக் குறிக்கும்.\" அல்லாஹ் இந்தப் புகழுக்குரிய பண்புகளின் பட்டியலைத் தொழுகையோடு தொடங்கித் தொழுகையோடு முடிக்கிறான். இது தொழுகையின் மகத்துவத்தைக் காட்டுகிறது. நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اسْتَقِيمُوا وَلَنْ تُحْصُوا، وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمُ الصَّلَاةُ، وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِن»\n\r\n\n\r\n(நேர்மையைக் கடைப்பிடியுங்கள், உங்களால் நன்மைகளை முழுமையாகக் கணக்கிட முடியாது. உங்கள் செயல்களில் சிறந்தது தொழுகை என்பதை அறிந்து கொள்ளுங்கள். ஒரு முஃமினைத் தவிர வேறு யாரும் தனது வுளூவைப் பேணிக் கொள்ள மாட்டார்.) இத்தகைய நற்பண்புகள் மற்றும் நற்செயல்களைக் கொண்டவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأُوْلَـئِكَ هُمُ الْوَارِثُونَ - الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ\n\r\n\n\r\n(இவர்களே வாரிசுதாரர்கள். அவர்கள் ஃபிர்தவ்ஸை (எனும் உயரிய சுவனத்தை) வாரிசாகப் பெறுவார்கள். அதில் அவர்கள் நிரந்தரமாகத் தங்குவார்கள்.) புகாரி மற்றும் முஸ்லிமில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«إِذَا سَأَلْتُمُ اللهَ الْجَنَّةَ فَاسْأَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَعْلَى الْجَنَّةِ وَأَوْسَطُ الْجَنَّةِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ، وَفَوْقَهُ عَرْشُ الرَّحْمن»\n\r\n\n\r\n(நீங்கள் அல்லாஹ்விடம் சுவனத்தைக் கேட்டால், அல்-ஃபிர்தவ்ஸைக் கேளுங்கள். ஏனெனில் அது சுவனத்தின் மிக உயர்ந்த பகுதியாகும், சுவனத்தின் மையப்பகுதியாகும். அங்கிருந்துதான் சுவனத்தின் ஆறுகள் உற்பத்தியாகின்றன. அதன் மேலே அளவற்ற அருளாளனின் (அல்லாஹ்வின்) அர்ஷ் உள்ளது.) இப்னு அபீ ஹாதிம் அவர்கள் அபூ ஹுரைரா (ரழி) வழியாகப் பதிவு செய்துள்ள ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَلَهُ مَنْزِلَانِ: مَنْزِلٌ فِي الْجَنَّةِ، وَمَنْزِلٌ فِي النَّارِ، فَإِنْ مَاتَ فَدَخَلَ النَّارَ وَرِثَ أَهْلُ الْجَنَّةِ مَنْزِلَهُ، فَذَلِكَ قَوْلُهُ:\n\r\n\n\r\nأُوْلَـئِكَ هُمُ الْوَارِثُونَ\n\r\n\n\r\n»\n\r\n\n\r\n(உங்களில் ஒவ்வொருவருக்கும் இரண்டு தங்குமிடங்கள் உள்ளன: ஒரு இடம் சுவனத்திலும், ஒரு இடம் நரகத்திலும். ஒருவர் இறந்து நரகத்திற்குச் சென்றால், சுவனவாசிகள் அவருடைய (சுவனத்து) இடத்தை வாரிசாகப் பெற்றுக் கொள்வார்கள். இதையே 'இவர்களே வாரிசுதாரர்கள்' எனும் வசனம் குறிப்பிடுகிறது.)\n\r\n\n\r\nமுஜாஹித் அவர்கள் கூறியதாக இப்னு ஜுரைஜ் கூறுகிறார்கள்: \"(இவர்களே வாரிசுதாரர்கள்) என்பதில் மூஃமின்கள் நிராகரிப்பாளர்களின் இடங்களைச் சுவீகரித்துக் கொள்வதைக் குறிக்கிறது. ஏனெனில், ஒவ்வொரு மனிதனும் இணை துணையற்ற அல்லாஹ்வை வணங்குவதற்காகவே படைக்கப்பட்டான். மூஃமின்கள் தங்களுக்குக் கட்டளையிடப்பட்ட வணக்கங்களைச் செய்தனர். ஆனால் நிராகரிப்பாளர்கள் எதற்காகப் படைக்கப்பட்டார்களோ, அந்தக் கட்டளையைப் புறக்கணித்தனர். எனவே, அவர்கள் இறைவனுக்குக் கீழ்ப்படிந்திருந்தால் அவர்களுக்குக் கிடைத்திருக்க வேண்டிய சுவனத்துப் பங்கை, மூஃமின்கள் பெற்றுக் கொள்கிறார்கள். மேலும் அவர்களுக்கு அதை விடவும் அதிகமாக வழங்கப்படலாம்.\"\n\r\n\n\r\nஇதை உறுதிப்படுத்தும் வகையில் ஸஹீஹ் முஸ்லிமில் அபூ புர்தா அவர்கள் தன் தந்தை வழியாக நபி (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"மறுமை நாளில் முஸ்லிம்களில் சிலர் மலைகளைப் போன்ற பாவங்களுடன் வருவார்கள். அல்லாஹ் அவர்களுக்கு மன்னிப்பு வழங்கிவிட்டு, அந்தப் பாவங்களை யூதர்கள் மற்றும் கிறிஸ்தவர்கள் மீது சுமத்துவான்.\" மற்றொரு அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்: \"மறுமை நாளில் அல்லாஹ் ஒவ்வொரு முஸ்லிமுக்கும் ஒரு யூதரையும் கிறிஸ்தவரையும் ஒதுக்கிவிட்டு, 'இதுவே நரகத்திலிருந்து உனக்கான ஈட்டுத் தொகை (விடுபடும் வழி)' என்று கூறுவான்.\" உமர் பின் அப்துல் அஸீஸ் அவர்கள் அபூ புர்தாவிடம், தன் தந்தை நபி (ஸல்) அவர்களிடமிருந்துதான் இதைக் கூறினாரா என்று அல்லாஹ்வை முன்னிறுத்தி சத்தியம் கேட்டார்கள், அவரும் சத்தியம் செய்தார்.\n\r\n\n\r\nநான் கூறுகிறேன்: இந்த வசனம் அல்லாஹ்வின் பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nتِلْكَ الْجَنَّةُ الَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيّاً\n\r\n\n\r\n(அதுதான் சுவனம்; அதனை நமது அடியார்களில் தக்வா (இறையச்சம்) உடையவர்களுக்கு நாம் வாரிசாக்குவோம்.) 19:63\n\r\n\n\r\nوَتِلْكَ الْجَنَّةُ الَّتِى أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ\n\r\n\n\r\n(இதுதான் சுவனம்; நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக இதனை நீங்கள் வாரிசாகப் பெற்றுக்கொண்டீர்கள்.) 43:72"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=16\" class=\"link\">23:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:16 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=16\" class=\"link\">23:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:16 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=16\" class=\"link\">23:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:16 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=16\" class=\"link\">23:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>களிமண்ணிலிருந்தும் பின்னர் நுத்ஃபாவிலிருந்தும் அதனைத் தொடர்ந்து படிப்படியாக மனிதனைப் படைத்ததில் உள்ள அல்லாஹ்வின் அத்தாட்சி</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الْإِنسَـنَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سُلَـلَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">طِينٍ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் மனிதனைக் களிமண்ணின் சத்திலிருந்து படைத்தோம்.)<br />\r\n<br />\r\nதொடக்கத்தில் மனிதனை களிமண்ணின் சத்திலிருந்து எவ்வாறு படைத்தான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். அவர்தான் ஆதம் (அலை) அவர்கள். மாற்றமடைந்த கறுப்பு நிற வழவழப்பான சேற்றிலிருந்து உருவான ஓசை தரும் களிமண்ணால் அல்லாஹ் அவரைப் படைத்தான். இப்னு ஜரீர் (ரழி) அவர்கள், \"ஆதம் (அலை) அவர்கள் அதிலிருந்து படைக்கப்பட்டதால் 'தீன்' (மண்) என்று அழைக்கப்பட்டார்கள்\" என்று கூறினார்கள். கதாதா (ரழி) அவர்கள், \"ஆதம் (அலை) அவர்கள் களிமண்ணிலிருந்து படைக்கப்பட்டார்கள்\" என்று கூறினார்கள். இதுவே மிகவும் வெளிப்படையான கருத்தாகவும், சூழலுக்கு நெருக்கமானதாகவும் இருக்கிறது. ஏனெனில் ஆதம் (அலை) அவர்கள் ஒட்டும் தன்மையுள்ள களிமண்ணிலிருந்து படைக்கப்பட்டார்கள். அது மாற்றமடைந்த கறுப்பு நிற வழவழப்பான சேற்றிலிருந்து உருவான ஓசை தரும் களிமண்ணாகும். அது மண்ணிலிருந்து (தூசியிலிருந்து) உருவாக்கப்பட்டது. அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">تُرَابٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">تَنتَشِرُونَ</span><br />\r\n<br />\r\n(அவன் உங்களை (ஆதமை) மண்ணிலிருந்து படைத்ததும், பின்னர் நீங்கள் மனிதர்களாக (பூமியில்) பரவி வாழ்வதும் அவனது அத்தாட்சிகளில் ஒன்றாகும்.) <a href=\"qurandisp.php?sura=30&ayah=20\" class=\"link\">30:20</a>. இமாம் அஹ்மத் அவர்கள் அபூ மூஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَبْضَةٍ</span> <span class=\"quran-arabic-font text-success\">قَبَضَهَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ،</span> <span class=\"quran-arabic-font text-success\">فَجَاءَ</span> <span class=\"quran-arabic-font text-success\">بَنُو</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَدْرِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ،</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَحْمَرُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَبْيَضُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَسْوَدُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ،</span> <span class=\"quran-arabic-font text-success\">وَالْخَبِيثُ</span> <span class=\"quran-arabic-font text-success\">وَالطَّيِّبُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">ذلِك</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் பூமி முழுவதிலிருந்தும் எடுக்கப்பட்ட ஒரு கைப்பிடி மண்ணிலிருந்து ஆதமைப் படைத்தான். எனவே, ஆதமுடைய மக்கள் பூமியின் தன்மைகளுக்கு ஏற்ப உருவானார்கள். அவர்களில் சிவப்பானவர்கள், வெள்ளையானவர்கள், கருப்பானவர்கள் மற்றும் இவற்றுக்கு இடைப்பட்ட நிறத்தவர்களும், கெட்டவர்களும், நல்லவர்களும் மற்றும் இவற்றுக்கு இடைப்பட்ட சுபாவம் கொண்டவர்களும் வந்தனர்.) அபூ தாவூத் மற்றும் திர்மிதி (ரழி) அவர்களும் இத்தகைய செய்தியைப் பதிவு செய்துள்ளனர். திர்மிதி (ரழி) அவர்கள், \"இது ஸஹீஹ் ஹஸன்\" என்று குறிப்பிட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">نُطْفَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">مَّكِينٍ</span><br />\r\n<br />\r\n(பின்னர் நாம் அவனை ஒரு பாதுகாப்பான இடத்தில் ஒரு நுத்ஃபாவாக (இந்திரியத் துளியாக) ஆக்கினோம்.) இங்கு பிரதிப்பெயர்ச்சொல் மனித இனத்தைக் குறிக்கிறது. இது மற்றொரு வசனத்தில் வருவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُ</span> <span class=\"quran-arabic-font text-success\">وَبَدَأَ</span> <span class=\"quran-arabic-font text-success\">خَلْقَ</span> <span class=\"quran-arabic-font text-success\">الإِنْسَـنِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">طِينٍ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">نَسْلَهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سُلاَلَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّآءٍ</span> <span class=\"quran-arabic-font text-success\">مَّهِينٍ</span><br />\r\n<br />\r\n(அவனே தான் படைத்த ஒவ்வொன்றையும் அழகாக ஆக்கினான்; மேலும் அவன் மனிதனின் படைப்பைக் களிமண்ணிலிருந்து தொடங்கினான். பின்னர் அவனுடைய சந்ததியை அற்பமான நீரின் சத்திலிருந்து உண்டாக்கினான்.) <a href=\"qurandisp.php?sura=32&ayah=7\" class=\"link\">32:7</a>,8. அதாவது பலவீனமான நீர். அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">نَخْلُقكُّم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّآءٍ</span> <span class=\"quran-arabic-font text-success\">مَّهِينٍ</span> - <span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">مَّكِينٍ</span><br />\r\n<br />\r\n(அற்பமான நீரிலிருந்து நாம் உங்களைப் படைக்கவில்லையா? பின்னர் அதனை நாம் ஒரு பாதுகாப்பான இடத்தில் வைத்தோம்.) <a href=\"qurandisp.php?sura=77&ayah=20\" class=\"link\">77:20</a>-21. அதாவது இதற்காகவே தயார் செய்யப்பட்டு வசதிகள் கொண்ட கருப்பையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَدَرٍ</span> <span class=\"quran-arabic-font text-success\">مَّعْلُومٍ</span> - <span class=\"quran-arabic-font text-success\">فَقَدَرْنَا</span> <span class=\"quran-arabic-font text-success\">فَنِعْمَ</span> <span class=\"quran-arabic-font text-success\">الْقَـدِرُونَ</span><br />\r\n<br />\r\n(ஒரு குறிப்பிட்ட காலம் வரை. அவ்வாறு நாமே நிர்ணயித்தோம்; நிர்ணயிப்பவர்களில் நாமே மிகச் சிறந்தவர்கள்.) <a href=\"qurandisp.php?sura=77&ayah=22\" class=\"link\">77:22</a>-23. அதாவது, அது நிலைபெற்று ஒரு கட்டத்திலிருந்து அடுத்த கட்டத்திற்கு மாறும் வரை ஒரு குறிப்பிட்ட காலத்திற்கு அங்கு வைக்கப்படுகிறது. அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">النُّطْفَةَ</span> <span class=\"quran-arabic-font text-success\">عَلَقَةً</span><br />\r\n<br />\r\n(பின்னர் அந்த நுத்ஃபாவை இரத்தக் கட்டியாக மாற்றினோம்,) அதாவது 'பின்னர் நாம் நுத்ஃபாவை — இது ஆணின் முதுகந்தண்டிலிருந்தும், பெண்ணின் மார்பு எலும்புகளிலிருந்தும் (அதாவது அவளுடைய கழுத்துப்பட்டை எலும்புக்கும் மார்பகத்திற்கும் இடையிலுள்ள பகுதியில் இருந்து) வெளிப்படும் நீராகும் — அதனை ஒரு நீண்ட சிவந்த இரத்தக் கட்டியாக மாற்றினோம்.' இக்ரிமா (ரழி) அவர்கள், \"இது இரத்தம்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَخَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الْعَلَقَةَ</span> <span class=\"quran-arabic-font text-success\">مُضْغَةً</span><br />\r\n<br />\r\n(பின்னர் அந்த இரத்தக் கட்டியை ஒரு சிறு சதைத் துண்டாக ஆக்கினோம்,) அது எவ்வித வடிவமோ அல்லது அடையாளங்களோ இல்லாத ஒரு தசைத் துண்டைப் போன்றதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَخَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">الْمُضْغَةَ</span> <span class=\"quran-arabic-font text-success\">عِظَامًا</span><br />\r\n<br />\r\n(பின்னர் அந்தச் சிறு சதைத் துண்டிலிருந்து எலும்புகளை உருவாக்கினோம்,) அதாவது 'நாம் அதற்குத் தலை, இரண்டு கைகள், இரண்டு கால்கள் மற்றும் அதன் எலும்புகள், நரம்புகள், இரத்த நாளங்களுடன் ஒரு வடிவத்தைக் கொடுத்தோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَسَوْنَا</span> <span class=\"quran-arabic-font text-success\">الْعِظَامَ</span> <span class=\"quran-arabic-font text-success\">لَحْماً</span><br />\r\n<br />\r\n(பின்னர் அந்த எலும்புகளுக்குச் சதையை அணிவித்தோம்,) அதாவது 'அதை மூடிப் பலப்படுத்துவதற்காக நாம் அதற்கு ஒரு கவசத்தை அளிப்போம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنشَأْنَـهُ</span> <span class=\"quran-arabic-font text-success\">خَلْقاً</span> <span class=\"quran-arabic-font text-success\">ءَاخَرَ</span><br />\r\n<br />\r\n(பின்னர் நாம் அதனை வேறொரு படைப்பாக உருவாக்கினோம்.) இதன் பொருள், 'பிறகு நாம் அதில் ஆன்மாவை (ரூஹை) ஊதினோம். அது அசைந்து, கேட்கவும், பார்க்கவும், உணரவும் மற்றும் நகரவும் கூடிய ஒரு புதிய உயிரினமாக மாறியது.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">الْخَـلِقِينَ</span><br />\r\n<br />\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنشَأْنَـهُ</span> <span class=\"quran-arabic-font text-success\">خَلْقاً</span> <span class=\"quran-arabic-font text-success\">ءَاخَرَ</span><br />\r\n<br />\r\n(பின்னர் நாம் அதனை வேறொரு படைப்பாக உருவாக்கினோம்.) அல்-அவ்ஃபீ (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"அது ஒரு குழந்தையாக வெளிவரும் வரை நாம் அதனை ஒரு கட்டத்திலிருந்து மற்றொரு கட்டத்திற்கு மாற்றுகிறோம். பின்னர் அது குழந்தை, வளரிளம் பருவம், இளைஞன், முதிர்ந்த மனிதன், முதியவர் மற்றும் தள்ளாமையுள்ள முதியவர் எனப் பல நிலைகளைக் கடந்து வளர்கிறது.\" இமாம் அஹ்மத் அவர்கள் தனது முஸ்னதில் அப்துல்லாஹ் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"உண்மையாளரான அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمْ</span> <span class=\"quran-arabic-font text-success\">لَيُجْمَعُ</span> <span class=\"quran-arabic-font text-success\">خَلْقُهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بَطْنِ</span> <span class=\"quran-arabic-font text-success\">أُمِّهِ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعِينَ</span> <span class=\"quran-arabic-font text-success\">يَوْمًا</span> <span class=\"quran-arabic-font text-success\">نُطْفَةً،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">عَلَقَةً</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">مُضْغَةً</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُرْسَلُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْمَلَكُ</span> <span class=\"quran-arabic-font text-success\">فَيَنْفُخُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الرُّوحَ</span> <span class=\"quran-arabic-font text-success\">وَيُؤْمَرُ</span> <span class=\"quran-arabic-font text-success\">بِأَرْبَعِ</span> <span class=\"quran-arabic-font text-success\">كَلِمَاتٍ</span>: <span class=\"quran-arabic-font text-success\">رِزْقِهِ،</span> <span class=\"quran-arabic-font text-success\">وَأَجَلِهِ،</span> <span class=\"quran-arabic-font text-success\">وَعَمَلِهِ،</span> <span class=\"quran-arabic-font text-success\">وَهَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">شَقِيٌّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">سَعِيدٌ،</span> <span class=\"quran-arabic-font text-success\">فَوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">غَيْرُهُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">ذِرَاعٌ،</span> <span class=\"quran-arabic-font text-success\">فَيَسْبِقُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْخُلُهَا،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلَ</span> <span class=\"quran-arabic-font text-success\">لَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">ذِرَاعٌ،</span> <span class=\"quran-arabic-font text-success\">فَيَسْبِقُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْخُلُهَا</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவரது படைப்பு, அவரது தாயின் வயிற்றில் நாற்பது நாட்கள் நுத்ஃபாவாகச் சேகரிக்கப்படுகிறது. பின்னர் அதே போன்ற ஒரு காலத்திற்கு இரத்தக் கட்டியாக மாறுகிறது. பின்னர் அதே போன்ற ஒரு காலத்திற்குச் சிறு சதைத் துண்டாக மாறுகிறது. பிறகு அவரிடம் ஒரு வானவர் அனுப்பப்பட்டு, அவர் அதில் ஆன்மாவை ஊதுகிறார். மேலும் நான்கு விஷயங்கள் அவருக்கு நிர்ணயிக்கப்படுகின்றன: அவரது வாழ்வாதாரம் (ரிஸ்க்), அவரது ஆயுட்காலம், அவரது செயல்கள் மற்றும் அவர் துர்ப்பாக்கியசாலியா அல்லது பாக்கியசாலியா என்பது. யாரைத் தவிர வேறு இறைவன் இல்லையோ அவன் மீது சத்தியமாக! உங்களில் ஒருவர் சொர்க்கவாசிகளின் செயல்களைச் செய்து கொண்டே வருவார், அவருக்கும் சொர்க்கத்திற்கும் இடையே ஒரு முழம் தூரம் மட்டுமே இருக்கும் நிலை வரை. அப்போது விதி அவரை முந்திவிடும், அவர் நரகவாசிகளின் செயலைச் செய்து நரகில் நுழைவார். ஒரு மனிதர் நரகவாசிகளின் செயல்களைச் செய்து வருவார், அவருக்கும் நரகத்திற்கும் இடையே ஒரு முழம் தூரம் மட்டுமே இருக்கும் நிலை வரை. அப்போது விதி அவரை முந்திவிடும், இறுதியில் அவர் சொர்க்கவாசிகளின் செயலைச் செய்து சொர்க்கத்தில் நுழைவார்.) இதனை அல்-புகாரி மற்றும் முஸ்லிம் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">الْخَـلِقِينَ</span><br />\r\n<br />\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.) இதன் பொருள், அல்லாஹ் இந்த நுத்ஃபாவைப் படைப்பதில் தனது ஆற்றலையும் நுட்பத்தையும் வெளிப்படுத்தி, அதை ஒரு கட்டத்திலிருந்து மற்றொரு கட்டத்திற்கு நகர்த்தி, இறுதியில் ஒரு முழுமையான மனித வடிவத்தைப் பெறச் செய்வதைக் குறிப்பிடும்போது கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">الْخَـلِقِينَ</span><br />\r\n<br />\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.) இப்னு அபீ ஹாதீம் (ரஹ்) அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: “நான்கு விஷயங்களில் நான் என் இறைவனுடன் உடன்பட்டுள்ளேன்... (அவற்றில் ஒன்று) நான் கூறினேன்: ‘படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்’ (ஃபதபாரக்கல்லாஹு அஹ்சனுல் காலிகீன்). அப்போது, ‘(அவ்வாறே) அது அருளப்பட்டது’ என்று நபி (ஸல்) அவர்கள் கூறினார்கள்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">لَمَيِّتُونَ</span><br />\r\n<br />\r\n(அதற்குப் பிறகு, நிச்சயமாக நீங்கள் மரணிப்பீர்கள்.) அதாவது, முதலில் ஒன்றுமில்லாததிலிருந்து படைக்கப்பட்ட பிறகு, நீங்கள் இறுதியில் மரணத்தைத் தழுவுவீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">تُبْعَثُونَ</span><br />\r\n<br />\r\n(பின்னர், நிச்சயமாக நீங்கள் மறுமை நாளில் உயிர்ப்பிக்கப்படுவீர்கள்.) அதாவது, நீங்கள் மீண்டும் ஒருமுறை படைக்கப்படுவீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يُنشِئُ</span> <span class=\"quran-arabic-font text-success\">النَّشْأَةَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةَ</span><br />\r\n<br />\r\n(பின்னர் அல்லாஹ் மறுமையின் படைப்பை உருவாக்குவான்) <a href=\"qurandisp.php?sura=29&ayah=20\" class=\"link\">29:20</a>. அதாவது மீண்டும் திரும்பும் நாள். அன்று ஆன்மாக்கள் அவற்றின் உடல்களுக்குத் திரும்பக் கொண்டுவரப்பட்டு, அனைத்துப் படைப்புகளும் விசாரணைக்கு உட்படுத்தப்படும். ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்பப் பிரதிபலன் வழங்கப்படும் — அவை நல்லதாக இருந்தால் நற்கூலியும், தீயதாக இருந்தால் தண்டனையும் அளிக்கப்படும்.<br />\r\n<br />","text":"களிமண்ணிலிருந்தும் பின்னர் நுத்ஃபாவிலிருந்தும் அதனைத் தொடர்ந்து படிப்படியாக மனிதனைப் படைத்ததில் உள்ள அல்லாஹ்வின் அத்தாட்சி\n\r\n\n\r\nوَلَقَدْ خَلَقْنَا الْإِنسَـنَ مِن سُلَـلَةٍ مِّن طِينٍ\n\r\n\n\r\n(நிச்சயமாக நாம் மனிதனைக் களிமண்ணின் சத்திலிருந்து படைத்தோம்.)\n\r\n\n\r\nதொடக்கத்தில் மனிதனை களிமண்ணின் சத்திலிருந்து எவ்வாறு படைத்தான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். அவர்தான் ஆதம் (அலை) அவர்கள். மாற்றமடைந்த கறுப்பு நிற வழவழப்பான சேற்றிலிருந்து உருவான ஓசை தரும் களிமண்ணால் அல்லாஹ் அவரைப் படைத்தான். இப்னு ஜரீர் (ரழி) அவர்கள், \"ஆதம் (அலை) அவர்கள் அதிலிருந்து படைக்கப்பட்டதால் 'தீன்' (மண்) என்று அழைக்கப்பட்டார்கள்\" என்று கூறினார்கள். கதாதா (ரழி) அவர்கள், \"ஆதம் (அலை) அவர்கள் களிமண்ணிலிருந்து படைக்கப்பட்டார்கள்\" என்று கூறினார்கள். இதுவே மிகவும் வெளிப்படையான கருத்தாகவும், சூழலுக்கு நெருக்கமானதாகவும் இருக்கிறது. ஏனெனில் ஆதம் (அலை) அவர்கள் ஒட்டும் தன்மையுள்ள களிமண்ணிலிருந்து படைக்கப்பட்டார்கள். அது மாற்றமடைந்த கறுப்பு நிற வழவழப்பான சேற்றிலிருந்து உருவான ஓசை தரும் களிமண்ணாகும். அது மண்ணிலிருந்து (தூசியிலிருந்து) உருவாக்கப்பட்டது. அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَمِنْ ءَايَـتِهِ أَنْ خَلَقَكُمْ مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُمْ بَشَرٌ تَنتَشِرُونَ\n\r\n\n\r\n(அவன் உங்களை (ஆதமை) மண்ணிலிருந்து படைத்ததும், பின்னர் நீங்கள் மனிதர்களாக (பூமியில்) பரவி வாழ்வதும் அவனது அத்தாட்சிகளில் ஒன்றாகும்.) 30:20. இமாம் அஹ்மத் அவர்கள் அபூ மூஸா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ خَلَقَ آدَمَ مِنْ قَبْضَةٍ قَبَضَهَا مِنْ جَمِيعِ الْأَرْضِ، فَجَاءَ بَنُو آدَمَ عَلَى قَدْرِ الْأَرْضِ، جَاءَ مِنْهُمُ الْأَحْمَرُ وَالْأَبْيَضُ وَالْأَسْوَدُ وَبَيْنَ ذلِكَ، وَالْخَبِيثُ وَالطَّيِّبُ وَبَيْنَ ذلِك»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் பூமி முழுவதிலிருந்தும் எடுக்கப்பட்ட ஒரு கைப்பிடி மண்ணிலிருந்து ஆதமைப் படைத்தான். எனவே, ஆதமுடைய மக்கள் பூமியின் தன்மைகளுக்கு ஏற்ப உருவானார்கள். அவர்களில் சிவப்பானவர்கள், வெள்ளையானவர்கள், கருப்பானவர்கள் மற்றும் இவற்றுக்கு இடைப்பட்ட நிறத்தவர்களும், கெட்டவர்களும், நல்லவர்களும் மற்றும் இவற்றுக்கு இடைப்பட்ட சுபாவம் கொண்டவர்களும் வந்தனர்.) அபூ தாவூத் மற்றும் திர்மிதி (ரழி) அவர்களும் இத்தகைய செய்தியைப் பதிவு செய்துள்ளனர். திர்மிதி (ரழி) அவர்கள், \"இது ஸஹீஹ் ஹஸன்\" என்று குறிப்பிட்டார்கள்.\n\r\n\n\r\nثُمَّ جَعَلْنَـهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ\n\r\n\n\r\n(பின்னர் நாம் அவனை ஒரு பாதுகாப்பான இடத்தில் ஒரு நுத்ஃபாவாக (இந்திரியத் துளியாக) ஆக்கினோம்.) இங்கு பிரதிப்பெயர்ச்சொல் மனித இனத்தைக் குறிக்கிறது. இது மற்றொரு வசனத்தில் வருவது போல:\n\r\n\n\r\nالَّذِى أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُ وَبَدَأَ خَلْقَ الإِنْسَـنِ مِن طِينٍ - ثُمَّ جَعَلَ نَسْلَهُ مِن سُلاَلَةٍ مِّن مَّآءٍ مَّهِينٍ\n\r\n\n\r\n(அவனே தான் படைத்த ஒவ்வொன்றையும் அழகாக ஆக்கினான்; மேலும் அவன் மனிதனின் படைப்பைக் களிமண்ணிலிருந்து தொடங்கினான். பின்னர் அவனுடைய சந்ததியை அற்பமான நீரின் சத்திலிருந்து உண்டாக்கினான்.) 32:7,8. அதாவது பலவீனமான நீர். அவன் கூறுவது போல:\n\r\n\n\r\nأَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ - فَجَعَلْنَـهُ فِى قَرَارٍ مَّكِينٍ\n\r\n\n\r\n(அற்பமான நீரிலிருந்து நாம் உங்களைப் படைக்கவில்லையா? பின்னர் அதனை நாம் ஒரு பாதுகாப்பான இடத்தில் வைத்தோம்.) 77:20-21. அதாவது இதற்காகவே தயார் செய்யப்பட்டு வசதிகள் கொண்ட கருப்பையாகும்.\n\r\n\n\r\nإِلَى قَدَرٍ مَّعْلُومٍ - فَقَدَرْنَا فَنِعْمَ الْقَـدِرُونَ\n\r\n\n\r\n(ஒரு குறிப்பிட்ட காலம் வரை. அவ்வாறு நாமே நிர்ணயித்தோம்; நிர்ணயிப்பவர்களில் நாமே மிகச் சிறந்தவர்கள்.) 77:22-23. அதாவது, அது நிலைபெற்று ஒரு கட்டத்திலிருந்து அடுத்த கட்டத்திற்கு மாறும் வரை ஒரு குறிப்பிட்ட காலத்திற்கு அங்கு வைக்கப்படுகிறது. அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً\n\r\n\n\r\n(பின்னர் அந்த நுத்ஃபாவை இரத்தக் கட்டியாக மாற்றினோம்,) அதாவது 'பின்னர் நாம் நுத்ஃபாவை — இது ஆணின் முதுகந்தண்டிலிருந்தும், பெண்ணின் மார்பு எலும்புகளிலிருந்தும் (அதாவது அவளுடைய கழுத்துப்பட்டை எலும்புக்கும் மார்பகத்திற்கும் இடையிலுள்ள பகுதியில் இருந்து) வெளிப்படும் நீராகும் — அதனை ஒரு நீண்ட சிவந்த இரத்தக் கட்டியாக மாற்றினோம்.' இக்ரிமா (ரழி) அவர்கள், \"இது இரத்தம்\" என்று கூறினார்கள்.\n\r\n\n\r\nفَخَلَقْنَا الْعَلَقَةَ مُضْغَةً\n\r\n\n\r\n(பின்னர் அந்த இரத்தக் கட்டியை ஒரு சிறு சதைத் துண்டாக ஆக்கினோம்,) அது எவ்வித வடிவமோ அல்லது அடையாளங்களோ இல்லாத ஒரு தசைத் துண்டைப் போன்றதாகும்.\n\r\n\n\r\nفَخَلَقْنَا الْمُضْغَةَ عِظَامًا\n\r\n\n\r\n(பின்னர் அந்தச் சிறு சதைத் துண்டிலிருந்து எலும்புகளை உருவாக்கினோம்,) அதாவது 'நாம் அதற்குத் தலை, இரண்டு கைகள், இரண்டு கால்கள் மற்றும் அதன் எலும்புகள், நரம்புகள், இரத்த நாளங்களுடன் ஒரு வடிவத்தைக் கொடுத்தோம்.'\n\r\n\n\r\nفَكَسَوْنَا الْعِظَامَ لَحْماً\n\r\n\n\r\n(பின்னர் அந்த எலும்புகளுக்குச் சதையை அணிவித்தோம்,) அதாவது 'அதை மூடிப் பலப்படுத்துவதற்காக நாம் அதற்கு ஒரு கவசத்தை அளிப்போம்.'\n\r\n\n\r\nثُمَّ أَنشَأْنَـهُ خَلْقاً ءَاخَرَ\n\r\n\n\r\n(பின்னர் நாம் அதனை வேறொரு படைப்பாக உருவாக்கினோம்.) இதன் பொருள், 'பிறகு நாம் அதில் ஆன்மாவை (ரூஹை) ஊதினோம். அது அசைந்து, கேட்கவும், பார்க்கவும், உணரவும் மற்றும் நகரவும் கூடிய ஒரு புதிய உயிரினமாக மாறியது.'\n\r\n\n\r\nفَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَـلِقِينَ\n\r\n\n\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.)\n\r\n\n\r\nثُمَّ أَنشَأْنَـهُ خَلْقاً ءَاخَرَ\n\r\n\n\r\n(பின்னர் நாம் அதனை வேறொரு படைப்பாக உருவாக்கினோம்.) அல்-அவ்ஃபீ (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"அது ஒரு குழந்தையாக வெளிவரும் வரை நாம் அதனை ஒரு கட்டத்திலிருந்து மற்றொரு கட்டத்திற்கு மாற்றுகிறோம். பின்னர் அது குழந்தை, வளரிளம் பருவம், இளைஞன், முதிர்ந்த மனிதன், முதியவர் மற்றும் தள்ளாமையுள்ள முதியவர் எனப் பல நிலைகளைக் கடந்து வளர்கிறது.\" இமாம் அஹ்மத் அவர்கள் தனது முஸ்னதில் அப்துல்லாஹ் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"உண்மையாளரான அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ أَحَدَكُمْ لَيُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذلِكَ، ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَهَلْ هُوَ شَقِيٌّ أَوْ سَعِيدٌ، فَوَ الَّذِي لَا إِلهَ غَيْرُهُ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا، وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا»\n\r\n\n\r\n(உங்களில் ஒருவரது படைப்பு, அவரது தாயின் வயிற்றில் நாற்பது நாட்கள் நுத்ஃபாவாகச் சேகரிக்கப்படுகிறது. பின்னர் அதே போன்ற ஒரு காலத்திற்கு இரத்தக் கட்டியாக மாறுகிறது. பின்னர் அதே போன்ற ஒரு காலத்திற்குச் சிறு சதைத் துண்டாக மாறுகிறது. பிறகு அவரிடம் ஒரு வானவர் அனுப்பப்பட்டு, அவர் அதில் ஆன்மாவை ஊதுகிறார். மேலும் நான்கு விஷயங்கள் அவருக்கு நிர்ணயிக்கப்படுகின்றன: அவரது வாழ்வாதாரம் (ரிஸ்க்), அவரது ஆயுட்காலம், அவரது செயல்கள் மற்றும் அவர் துர்ப்பாக்கியசாலியா அல்லது பாக்கியசாலியா என்பது. யாரைத் தவிர வேறு இறைவன் இல்லையோ அவன் மீது சத்தியமாக! உங்களில் ஒருவர் சொர்க்கவாசிகளின் செயல்களைச் செய்து கொண்டே வருவார், அவருக்கும் சொர்க்கத்திற்கும் இடையே ஒரு முழம் தூரம் மட்டுமே இருக்கும் நிலை வரை. அப்போது விதி அவரை முந்திவிடும், அவர் நரகவாசிகளின் செயலைச் செய்து நரகில் நுழைவார். ஒரு மனிதர் நரகவாசிகளின் செயல்களைச் செய்து வருவார், அவருக்கும் நரகத்திற்கும் இடையே ஒரு முழம் தூரம் மட்டுமே இருக்கும் நிலை வரை. அப்போது விதி அவரை முந்திவிடும், இறுதியில் அவர் சொர்க்கவாசிகளின் செயலைச் செய்து சொர்க்கத்தில் நுழைவார்.) இதனை அல்-புகாரி மற்றும் முஸ்லிம் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nفَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَـلِقِينَ\n\r\n\n\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.) இதன் பொருள், அல்லாஹ் இந்த நுத்ஃபாவைப் படைப்பதில் தனது ஆற்றலையும் நுட்பத்தையும் வெளிப்படுத்தி, அதை ஒரு கட்டத்திலிருந்து மற்றொரு கட்டத்திற்கு நகர்த்தி, இறுதியில் ஒரு முழுமையான மனித வடிவத்தைப் பெறச் செய்வதைக் குறிப்பிடும்போது கூறுகிறான்:\n\r\n\n\r\nفَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَـلِقِينَ\n\r\n\n\r\n(ஆகவே, படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்.) இப்னு அபீ ஹாதீம் (ரஹ்) அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள்: உமர் பின் அல்கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: “நான்கு விஷயங்களில் நான் என் இறைவனுடன் உடன்பட்டுள்ளேன்... (அவற்றில் ஒன்று) நான் கூறினேன்: ‘படைப்பாளர்களிலெல்லாம் மிகச் சிறந்தவனான அல்லாஹ் மிகவும் அருள்மிக்கவன்’ (ஃபதபாரக்கல்லாஹு அஹ்சனுல் காலிகீன்). அப்போது, ‘(அவ்வாறே) அது அருளப்பட்டது’ என்று நபி (ஸல்) அவர்கள் கூறினார்கள்.”\n\r\n\n\r\nثُمَّ إِنَّكُمْ بَعْدَ ذلِكَ لَمَيِّتُونَ\n\r\n\n\r\n(அதற்குப் பிறகு, நிச்சயமாக நீங்கள் மரணிப்பீர்கள்.) அதாவது, முதலில் ஒன்றுமில்லாததிலிருந்து படைக்கப்பட்ட பிறகு, நீங்கள் இறுதியில் மரணத்தைத் தழுவுவீர்கள்.\n\r\n\n\r\nثُمَّ إِنَّكُمْ يَوْمَ الْقِيَـمَةِ تُبْعَثُونَ\n\r\n\n\r\n(பின்னர், நிச்சயமாக நீங்கள் மறுமை நாளில் உயிர்ப்பிக்கப்படுவீர்கள்.) அதாவது, நீங்கள் மீண்டும் ஒருமுறை படைக்கப்படுவீர்கள்.\n\r\n\n\r\nثُمَّ اللَّهُ يُنشِئُ النَّشْأَةَ الْآخِرَةَ\n\r\n\n\r\n(பின்னர் அல்லாஹ் மறுமையின் படைப்பை உருவாக்குவான்) 29:20. அதாவது மீண்டும் திரும்பும் நாள். அன்று ஆன்மாக்கள் அவற்றின் உடல்களுக்குத் திரும்பக் கொண்டுவரப்பட்டு, அனைத்துப் படைப்புகளும் விசாரணைக்கு உட்படுத்தப்படும். ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்பப் பிரதிபலன் வழங்கப்படும் — அவை நல்லதாக இருந்தால் நற்கூலியும், தீயதாக இருந்தால் தண்டனையும் அளிக்கப்படும்."},"17":{"html":"<strong>வானங்களைப் படைத்ததில் உள்ள அவனது அத்தாட்சி</strong><br />\r\n<br />\r\nமனிதனின் படைப்பைப் பற்றிக் குறிப்பிட்ட பிறகு, அல்லாஹ் ஏழு வானங்களின் படைப்பைப் பற்றிக் குறிப்பிடுகிறான். அல்லாஹ் மனிதப் படைப்போடு சேர்த்து வானங்கள் மற்றும் பூமியின் படைப்பைக் குறித்து அடிக்கடி குறிப்பிடுகிறான். இதனை வேறொரு வசனத்தில் அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَخَلْقُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span><br />\r\n<br />\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பதானது, மனிதர்களைப் படைப்பதை விடப் பெரியதாகும்) <a href=\"qurandisp.php?sura=40&ayah=57\" class=\"link\">40:57</a>. இது போன்ற ஒரு வசனம் ஸூரத்து அஸ்-ஸஜ்தாவின் ஆரம்பத்திலும் இடம்பெற்றுள்ளது. இதனை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வெள்ளிக்கிழமை அதிகாலைத் தொழுகைகளில் ஓதுபவர்களாக இருந்தார்கள். அதன் ஆரம்பத்தில் வானங்கள் மற்றும் பூமியின் படைப்பைப் பற்றிக் குறிப்பிடப்பட்டுள்ளது. பிறகு, களிமண்ணிலிருந்து மனிதன் எவ்வாறு விந்துத் துளியின் மூலம் படைக்கப்பட்டான் என்பதையும், அதுமட்டுமின்றி மறுமை நாள், நற்கூலிகள், தண்டனைகள் மற்றும் இதர விஷயங்களைப் பற்றியும் அந்த அத்தியாயம் விவரிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">طَرَائِقَ</span><br />\r\n<br />\r\n(ஏழு வழிகள்/தராயிக்.) முஜாஹித் அவர்கள், \"இதன் பொருள் ஏழு வானங்கள் என்பதாகும்\" என்று கூறினார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">السَّبْعُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span><br />\r\n<br />\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன) <a href=\"qurandisp.php?sura=17&ayah=44\" class=\"link\">17:44</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَوْا</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">طِبَاقًا</span><br />\r\n<br />\r\n(அல்லாஹ் எவ்வாறு ஏழு வானங்களை ஒன்றன் மேல் ஒன்றாகப் படைத்தான் என்பதை நீங்கள் பார்க்கவில்லையா?) <a href=\"qurandisp.php?sura=71&ayah=15\" class=\"link\">71:15</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مِثْلَهُنَّ</span> <span class=\"quran-arabic-font text-success\">يَتَنَزَّلُ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُنَّ</span> <span class=\"quran-arabic-font text-success\">لِتَعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَحَاطَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">عِلْمًا</span><br />\r\n<br />\r\n(அல்லாஹ்வே ஏழு வானங்களையும், பூமியிலிருந்து அவற்றைப் போன்றதையும் படைத்தான். அவனுடைய கட்டளை அவற்றுக்கிடையே (வானங்களுக்கும் பூமிக்கும் இடையில்) இறங்குகிறது. நிச்சயமாக அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன் என்பதையும், அல்லாஹ் தனது ஞானத்தால் அனைத்துப் பொருட்களையும் சூழ்ந்திருக்கிறான் என்பதையும் நீங்கள் அறிந்து கொள்வதற்காகவே (இவற்றைப் படைத்தான்)) <a href=\"qurandisp.php?sura=65&ayah=12\" class=\"link\">65:12</a>. அதேபோல், அல்லாஹ் இங்கும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">فَوْقَكُمْ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">طَرَائِقَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْخَلْقِ</span> <span class=\"quran-arabic-font text-success\">غَافِلِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உங்களுக்கு மேலே ஏழு வழிகளைப் படைத்தோம்; மேலும், நாம் படைப்பினங்களைப் பற்றிப் பராமுகமாக இருக்கவில்லை.) அதாவது, பூமிக்குள் நுழைவதையும் அதிலிருந்து வெளிப்படுவதையும், வானத்திலிருந்து இறங்குவதையும் அதில் ஏறுவதையும் அல்லாஹ் நன்கறிவான். நீங்கள் எங்கிருந்தாலும் அவன் உங்களுடன் இருக்கிறான், நீங்கள் செய்வதை அல்லாஹ் உற்று நோக்குகிறான். ஒரு வானம் மற்றொரு வானத்தையோ, ஒரு பூமி மற்றொரு பூமியையோ அவனிடமிருந்து மறைக்க முடியாது. அவன் அறியாத மலைகளோ, ஆழ்கடல் பகுதிகளோ எதுவுமே இல்லை. மலைகள், குன்றுகள், மணல் பரப்புகள், கடல்கள், நிலப்பரப்புகள் மற்றும் மரங்களில் உள்ளவற்றின் எண்ணிக்கையை அவன் துல்லியமாக அறிவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْقُطُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">وَرَقَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">رَطْبٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَابِسٍ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُبِينٍ</span><br />\r\n<br />\r\n(ஓர் இலை கீழே விழுந்தாலும் அதை அவன் அறியாமல் இருப்பதில்லை. பூமியின் இருள்களில் உள்ள ஒரு சிறு வித்தாக இருந்தாலும் சரி, பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும், அவை தெளிவான ஒரு பதிவேட்டில் பதிவு செய்யப்படாமல் இல்லை.) <a href=\"qurandisp.php?sura=6&ayah=59\" class=\"link\">6:59</a> மேலும், வானம் பூமியின் மீது விழுந்து விடாதவாறு அதனைப் பாதுகாப்பவனாகவும் அவனே இருக்கிறான். அவனது அனுமதியின்றி அது விழுந்து விடாது. (காண்க: <a href=\"qurandisp.php?sura=22&ayah=65\" class=\"link\">22:65</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">مَاءً</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span> <span class=\"quran-arabic-font text-success\">فَأَسْكَنَّاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَهَابٍ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">لَقَادِرُونَ</span><br />\r\n<br />","text":"வானங்களைப் படைத்ததில் உள்ள அவனது அத்தாட்சி\n\r\n\n\r\nமனிதனின் படைப்பைப் பற்றிக் குறிப்பிட்ட பிறகு, அல்லாஹ் ஏழு வானங்களின் படைப்பைப் பற்றிக் குறிப்பிடுகிறான். அல்லாஹ் மனிதப் படைப்போடு சேர்த்து வானங்கள் மற்றும் பூமியின் படைப்பைக் குறித்து அடிக்கடி குறிப்பிடுகிறான். இதனை வேறொரு வசனத்தில் அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nلَخَلْقُ السَّمَاوَاتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ\n\r\n\n\r\n(நிச்சயமாக வானங்களையும் பூமியையும் படைப்பதானது, மனிதர்களைப் படைப்பதை விடப் பெரியதாகும்) 40:57. இது போன்ற ஒரு வசனம் ஸூரத்து அஸ்-ஸஜ்தாவின் ஆரம்பத்திலும் இடம்பெற்றுள்ளது. இதனை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வெள்ளிக்கிழமை அதிகாலைத் தொழுகைகளில் ஓதுபவர்களாக இருந்தார்கள். அதன் ஆரம்பத்தில் வானங்கள் மற்றும் பூமியின் படைப்பைப் பற்றிக் குறிப்பிடப்பட்டுள்ளது. பிறகு, களிமண்ணிலிருந்து மனிதன் எவ்வாறு விந்துத் துளியின் மூலம் படைக்கப்பட்டான் என்பதையும், அதுமட்டுமின்றி மறுமை நாள், நற்கூலிகள், தண்டனைகள் மற்றும் இதர விஷயங்களைப் பற்றியும் அந்த அத்தியாயம் விவரிக்கிறது.\n\r\n\n\r\nسَبْعَ طَرَائِقَ\n\r\n\n\r\n(ஏழு வழிகள்/தராயிக்.) முஜாஹித் அவர்கள், \"இதன் பொருள் ஏழு வானங்கள் என்பதாகும்\" என்று கூறினார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nتُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَن فِيهِنَّ\n\r\n\n\r\n(ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன) 17:44\n\r\n\n\r\nأَلَمْ تَرَوْا كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ طِبَاقًا\n\r\n\n\r\n(அல்லாஹ் எவ்வாறு ஏழு வானங்களை ஒன்றன் மேல் ஒன்றாகப் படைத்தான் என்பதை நீங்கள் பார்க்கவில்லையா?) 71:15\n\r\n\n\r\nاللَّهُ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوا أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا\n\r\n\n\r\n(அல்லாஹ்வே ஏழு வானங்களையும், பூமியிலிருந்து அவற்றைப் போன்றதையும் படைத்தான். அவனுடைய கட்டளை அவற்றுக்கிடையே (வானங்களுக்கும் பூமிக்கும் இடையில்) இறங்குகிறது. நிச்சயமாக அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன் என்பதையும், அல்லாஹ் தனது ஞானத்தால் அனைத்துப் பொருட்களையும் சூழ்ந்திருக்கிறான் என்பதையும் நீங்கள் அறிந்து கொள்வதற்காகவே (இவற்றைப் படைத்தான்)) 65:12. அதேபோல், அல்லாஹ் இங்கும் கூறுகிறான்:\n\r\n\n\r\nوَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَائِقَ وَمَا كُنَّا عَنِ الْخَلْقِ غَافِلِينَ\n\r\n\n\r\n(நிச்சயமாக நாம் உங்களுக்கு மேலே ஏழு வழிகளைப் படைத்தோம்; மேலும், நாம் படைப்பினங்களைப் பற்றிப் பராமுகமாக இருக்கவில்லை.) அதாவது, பூமிக்குள் நுழைவதையும் அதிலிருந்து வெளிப்படுவதையும், வானத்திலிருந்து இறங்குவதையும் அதில் ஏறுவதையும் அல்லாஹ் நன்கறிவான். நீங்கள் எங்கிருந்தாலும் அவன் உங்களுடன் இருக்கிறான், நீங்கள் செய்வதை அல்லாஹ் உற்று நோக்குகிறான். ஒரு வானம் மற்றொரு வானத்தையோ, ஒரு பூமி மற்றொரு பூமியையோ அவனிடமிருந்து மறைக்க முடியாது. அவன் அறியாத மலைகளோ, ஆழ்கடல் பகுதிகளோ எதுவுமே இல்லை. மலைகள், குன்றுகள், மணல் பரப்புகள், கடல்கள், நிலப்பரப்புகள் மற்றும் மரங்களில் உள்ளவற்றின் எண்ணிக்கையை அவன் துல்லியமாக அறிவான்.\n\r\n\n\r\nوَمَا تَسْقُطُ مِنْ وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِي ظُلُمَاتِ الْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِي كِتَابٍ مُبِينٍ\n\r\n\n\r\n(ஓர் இலை கீழே விழுந்தாலும் அதை அவன் அறியாமல் இருப்பதில்லை. பூமியின் இருள்களில் உள்ள ஒரு சிறு வித்தாக இருந்தாலும் சரி, பசுமையானதோ அல்லது காய்ந்ததோ எதுவானாலும், அவை தெளிவான ஒரு பதிவேட்டில் பதிவு செய்யப்படாமல் இல்லை.) 6:59 மேலும், வானம் பூமியின் மீது விழுந்து விடாதவாறு அதனைப் பாதுகாப்பவனாகவும் அவனே இருக்கிறான். அவனது அனுமதியின்றி அது விழுந்து விடாது. (காண்க: 22:65)\n\r\n\n\r\nوَأَنزَلْنَا مِنَ السَّمَاءِ مَاءً بِقَدَرٍ فَأَسْكَنَّاهُ فِي الْأَرْضِ وَإِنَّا عَلَى ذَهَابٍ بِهِ لَقَادِرُونَ"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=22\" class=\"link\">23:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:22 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=22\" class=\"link\">23:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:22 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=22\" class=\"link\">23:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:22 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=22\" class=\"link\">23:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:22 ஐ பார்க்கவும்"},"22":{"html":"<strong>மழை, தாவரங்கள், மரங்கள் மற்றும் கால்நடைகளில் உள்ள அல்லாஹ்வின் அத்தாட்சிகளும் அருட்கொடைகளும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">مَاءً</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(வானத்திலிருந்து நாம் ஒரு குறிப்பிட்ட அளவில் தண்ணீரை இறக்கினோம்;)<br />\r\n<br />\r\nஅல்லாஹ் தன் அடியார்களுக்கு வழங்கியுள்ள எண்ணற்ற அருட்கொடைகளைக் குறிப்பிடுகிறான். அவன் மழையை அதற்குரிய அளவில் இறக்குகிறான்; அதாவது நிலங்களுக்கும் கட்டிடங்களுக்கும் சேதம் விளைவிக்கும் அளவுக்கு அதிகமில்லாமலும், பயிர்களுக்கும் பழங்களுக்கும் போதுமானதாக இல்லாத அளவுக்குக் குறைவில்லாமலும், நீர்ப்பாசனம், குடிநீர் மற்றும் பிற தேவைகளுக்குத் தேவையான அளவில் இறக்குகிறான். ஒரு நிலத்திற்கு நீர்ப்பாசனத்திற்கு அதிகத் தண்ணீர் தேவைப்படலாம், ஆனால் அங்கே மழை பெய்தால் அதன் வளமான மண் அடித்துச் செல்லப்படும் என்றிருந்தால், அல்லாஹ் வேறொரு நிலத்திலிருந்து அதற்குத் தண்ணீரை அனுப்புகிறான். உதாரணமாக, எகிப்து ஒரு வறண்ட நிலம் என்று சொல்லப்படுகிறது. அல்லாஹ் அதற்கு நைல் நதியின் நீரை அனுப்புகிறான். எத்தியோப்பியாவில் மழை பெய்யும்போது, அது அங்கிருந்து செம்மண்ணைக் கொண்டுவருகிறது. அந்தத் தண்ணீர் எகிப்தின் நிலத்திற்குப் பாய்ச்சப்படுகிறது; அதில் படியும் மண் விவசாயத்திற்குப் பயன்படுத்தப்படுகிறது. ஏனெனில் எகிப்தின் நிலம் இயற்கையிலேயே விளைச்சலுக்குத் தகுதியற்றது, அதன் பெரும்பகுதி மணலால் ஆனது. நுட்பமானவனும், யாவற்றையும் அறிந்தவனும், மகா கருணையாளனும், மன்னிப்பவனுமாகிய அல்லாஹ் தூய்மையானவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَسْكَنَّاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(அதனை நாம் பூமியில் தங்கச் செய்தோம்,) மேகங்களிலிருந்து தண்ணீர் இறங்கும்போது, அதனைப் பூமிக்குள் தங்கச் செய்து, பூமி அதனை உறிஞ்சிக் கொள்ளும்படி அல்லாஹ் செய்கிறான்; அதன் மூலம் பூமியில் உள்ள விதைகள் போன்றவை ஊட்டம்பெறுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَهَابٍ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">لَقَادِرُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அதனைப் போக்கிவிடவும் ஆற்றலுடையவன்.) அதாவது, 'நாம் மழை பெய்யாமல் செய்ய நாடினால், நம்மால் அதைச் செய்ய முடியும்; அதனை மக்கள் வசிக்காத வனாந்தரங்கள் மற்றும் பாழ்நிலங்களின் பக்கம் திருப்ப நாடினாலும் நம்மால் முடியும். நீங்கள் குடிப்பதற்கோ அல்லது நீர்ப்பாசனத்திற்கோ பயன்படுத்த முடியாதவாறு அதனை உப்பு நீராக மாற்ற நாடினாலும் நம்மால் முடியும்; அது பூமியால் உறிஞ்சப்படாமல் மேற்பரப்பிலேயே தேங்கி நிற்கும்படி செய்ய நாடினாலும் நம்மால் முடியும்; அல்லது நீங்கள் அடைய முடியாத அளவுக்குப் பூமிக்கு அடியில் ஆழமாகச் சென்றுவிடச் செய்யவும் நம்மால் முடியும்.' ஆனால், அல்லாஹ் தன் கிருபையாலும் கருணையாலும், மேகங்களிலிருந்து இனிமையான, தூய்மையான நீரை இறக்குகிறான். பின்னர் அது பூமியில் தங்கி நீரூற்றுகளையும் ஆறுகளையும் உருவாக்குகிறது. அதைக் கொண்டு நீங்கள் உங்கள் பயிர்களுக்கும் பழத்தோட்டங்களுக்கும் நீர் பாய்ச்சுகிறீர்கள்; நீங்களும் குடித்து உங்கள் கால்நடைகளுக்கும் புகட்டுகிறீர்கள்; மேலும் அதைக் கொண்டு குளித்து உங்களைத் தூய்மைப்படுத்திக் கொள்கிறீர்கள். புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَنشَأْنَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّخِيلٍ</span> <span class=\"quran-arabic-font text-success\">وَأَعْنَابٍ</span><br />\r\n<br />\r\n(அதன் மூலம் பேரீச்சை மற்றும் திராட்சைத் தோட்டங்களை உங்களுக்காக நாம் உண்டாக்கினோம்,) அதாவது, 'வானத்திலிருந்து நாம் இறக்கும் நீரைக் கொண்டு, அழகிய தோட்டங்களையும் பழத்தோப்புகளையும் உங்களுக்காக நாம் உருவாக்குகிறோம்' என்று அல்லாஹ் கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّخِيلٍ</span> <span class=\"quran-arabic-font text-success\">وَأَعْنَابٍ</span><br />\r\n<br />\r\n(பேரீச்சை மற்றும் திராட்சைகளால் ஆன,) இவை ஹிஜாஸ் மக்களுக்கு நன்கு தெரிந்த தோட்ட வகைகளாகும். எனினும், இவற்றுக்கு நிகரானவை வேறெதுவும் இல்லை. ஒவ்வொரு பகுதியினருக்கும் சில பழ வகைகள் அல்லாஹ்வின் அருட்கொடையாக வழங்கப்பட்டுள்ளன. அதற்காக அவர்கள் அல்லாஹ்வுக்கு எவ்வளவு நன்றி செலுத்தினாலும் அது ஈடாகாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَوَاكِهُ</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةٌ</span><br />\r\n<br />\r\n(அதில் உங்களுக்கு ஏராளமான கனிகள் உள்ளன,) அதாவது, எல்லா வகையான பழங்களும் உள்ளன. இதனை அல்லாஹ் வேறொரு இடத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُنبِتُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الزَّرْعَ</span> <span class=\"quran-arabic-font text-success\">وَالزَّيْتُونَ</span> <span class=\"quran-arabic-font text-success\">وَالنَّخِيلَ</span> <span class=\"quran-arabic-font text-success\">وَالْأَعْنَابَ</span> <span class=\"quran-arabic-font text-success\">وَمِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">الثَّمَرَاتِ</span><br />\r\n<br />\r\n(அதன் மூலம் அவன் உங்களுக்காகப் பயிர்களையும், ஒலிவத்தையும், பேரீச்சையையும், திராட்சையையும், இன்னும் அனைத்துக் கனிகளையும் விளைவிக்கிறான்) <a href=\"qurandisp.php?sura=16&ayah=11\" class=\"link\">16:11</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُونَ</span><br />\r\n<br />\r\n(அவற்றிலிருந்தே நீங்கள் உண்கிறீர்கள்.) நீங்கள் அதன் அழகைப் பார்க்கிறீர்கள், அது பழுக்கும் வரை காத்திருந்து, பின்னர் அதிலிருந்து உண்கிறீர்கள் என்பதை இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَشَجَرَةً</span> <span class=\"quran-arabic-font text-success\">تَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">طُورِ</span> <span class=\"quran-arabic-font text-success\">سَيْنَاءَ</span><br />\r\n<br />\r\n(மேலும் தூர் ஸைனாவிலிருந்து முளைக்கும் ஒரு மரத்தையும் உண்டாக்கினோம்,) இது ஒலிவ மரத்தைக் குறிக்கும். 'தூர்' என்றால் மலை என்று பொருள். சில அறிஞர்கள், \"மரங்கள் அடர்ந்த மலை 'தூர்' என்று அழைக்கப்படும்; மரங்கள் இல்லாவிட்டால் அது 'ஜபல்' என்று அழைக்கப்படும்\" என்று கூறியுள்ளனர். அல்லாஹ்வே மிக அறிந்தவன். ஸைனா மலை என்பது 'தூர் ஸினீன்' ஆகும். இம்மலையில்தான் அல்லாஹ் மூஸா பின் இம்ரான் (அலை) அவர்களுடன் பேசினான். இம்மலையைச் சுற்றியுள்ள பகுதிகளில் ஒலிவ மரங்கள் அதிகமுள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَنبُتُ</span> <span class=\"quran-arabic-font text-success\">بِالدُّهْنِ</span><br />\r\n<br />\r\n(அது எண்ணெயுடன் முளைக்கிறது,) சில அறிஞர்கள் மொழியியல் ரீதியாக இது 'எண்ணெயைத் தருகிறது' என்று பொருள் கொள்கிறார்கள். மற்றவர்கள் 'எண்ணெயுடன் வெளிவருகிறது' என்று கூறுகிறார்கள். அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصِبْغٍ</span><br />\r\n<br />\r\n(மேலும் தொடுகறியாகவும்) அதாவது, இது உணவுக்கு ஒரு துணை உணவாகும் என்று கதாதா கூறுகிறார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِلْآكِلِينَ</span><br />\r\n<br />\r\n(உண்பவர்களுக்கு.) அதாவது, இதில் பயனுள்ள எண்ணெயும் தொடுகறியும் உள்ளது. அப்து பின் ஹுமைத் தனது முஸ்னத் மற்றும் தஃப்ஸீரில் உமர் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ائْتَدِمُوا</span> <span class=\"quran-arabic-font text-success\">بِالزَّيْتِ</span> <span class=\"quran-arabic-font text-success\">وَادَّهِنُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةٍ</span> <span class=\"quran-arabic-font text-success\">مُبَارَكَة</span>»<br />\r\n<br />\r\n((ஒலிவ) எண்ணெயைத் தொடுகறியாகப் பயன்படுத்துங்கள், மேலும் அதனைத் தேய்த்துக் கொள்ளுங்கள் (உடலில் பூசுங்கள்); ஏனெனில் அது ஒரு பாக்கியம் மிக்க மரத்திலிருந்து கிடைப்பதாகும்.) இதனை அத்-திர்மிதி மற்றும் இப்னு மாஜா பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">لَعِبْرَةً</span> <span class=\"quran-arabic-font text-success\">نُّسْقِيكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بُطُونِهَا</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَنَافِعُ</span> <span class=\"quran-arabic-font text-success\">كَثِيرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَعَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">تُحْمَلُونَ</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக, கால்நடைகளிலும் உங்களுக்கு ஒரு படிப்பினை இருக்கிறது. அவற்றின் வயிறுகளில் இருப்பதிலிருந்து நாம் உங்களுக்குப் புகட்டுகிறோம். மேலும் அவற்றில் உங்களுக்கு ஏராளமான பயன்கள் உள்ளன; அவற்றிலிருந்து நீங்கள் உண்கிறீர்கள். அவற்றின் மீதும் கப்பல்கள் மீதும் நீங்கள் சுமந்து செல்லப்படுகிறீர்கள்.) இங்கு அல்லாஹ் கால்நடைகளின் மூலம் தன் அடியார்களுக்கு வழங்கியுள்ள நன்மைகளைக் குறிப்பிடுகிறான். கால்நடைகளின் சாணத்திற்கும் இரத்தத்திற்கும் இடையில் இருந்து வெளிவரும் பாலை அவர்கள் குடிக்கிறார்கள்; அவற்றின் இறைச்சியை உண்கிறார்கள்; அவற்றின் கம்பளி மற்றும் உரோமங்களைக் கொண்டு ஆடை அணிகிறார்கள்; அவற்றின் முதுகில் சவாரி செய்கிறார்கள்; மேலும் வெகுதொலைவில் உள்ள இடங்களுக்குப் பாரமான சுமைகளை அவற்றின் மூலம் சுமந்து செல்கிறார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">أَثْقَالَكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">بَلَدٍ</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">بَالِغِيهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِشِقِّ</span> <span class=\"quran-arabic-font text-success\">الأَنفُسِ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَرَؤُوفٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(உங்களால் பெரும் சிரமமின்றி அடைய முடியாத ஊர்களுக்கு அவை உங்கள் சுமைகளைச் சுமந்து செல்கின்றன. நிச்சயமாக உங்கள் இறைவன் மிக்க இரக்கமுடையவன், மகா கருணையாளன்.) <a href=\"qurandisp.php?sura=16&ayah=7\" class=\"link\">16:7</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">عَمِلَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْدِينَآ</span> <span class=\"quran-arabic-font text-success\">أَنْعَامًا</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مَالِكُونَ</span> - <span class=\"quran-arabic-font text-success\">وَذَلَّلْنَاهَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">رَكُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهَا</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَنَافِعُ</span> <span class=\"quran-arabic-font text-success\">وَمَشَارِبُ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">يَشْكُرُونَ</span><br />\r\n<br />\r\n(நமது கைகள் உருவாக்கியவற்றிலிருந்து நாம் அவர்களுக்காகக் கால்நடைகளைப் படைத்திருப்பதை அவர்கள் பார்க்கவில்லையா? அவர்கள் அவற்றிற்கு உரிமையாளர்களாக இருக்கிறார்கள். அவற்றை நாம் அவர்களுக்கு வசப்படுத்திக் கொடுத்தோம்; அவற்றில் சிலவற்றை அவர்கள் சவாரி செய்யவும், சிலவற்றை அவர்கள் உண்ணவும் செய்கின்றனர். அவற்றில் அவர்களுக்கு (வேறு பல) பயன்களும் பானங்களும் உள்ளன. அவர்கள் நன்றி செலுத்த வேண்டாமா?) <a href=\"qurandisp.php?sura=36&ayah=71\" class=\"link\">36:71</a>-73<br />\r\n<br />","text":"மழை, தாவரங்கள், மரங்கள் மற்றும் கால்நடைகளில் உள்ள அல்லாஹ்வின் அத்தாட்சிகளும் அருட்கொடைகளும்\n\r\n\n\r\nوَأَنزَلْنَا مِنَ السَّمَاءِ مَاءً بِقَدَرٍ\n\r\n\n\r\n(வானத்திலிருந்து நாம் ஒரு குறிப்பிட்ட அளவில் தண்ணீரை இறக்கினோம்;)\n\r\n\n\r\nஅல்லாஹ் தன் அடியார்களுக்கு வழங்கியுள்ள எண்ணற்ற அருட்கொடைகளைக் குறிப்பிடுகிறான். அவன் மழையை அதற்குரிய அளவில் இறக்குகிறான்; அதாவது நிலங்களுக்கும் கட்டிடங்களுக்கும் சேதம் விளைவிக்கும் அளவுக்கு அதிகமில்லாமலும், பயிர்களுக்கும் பழங்களுக்கும் போதுமானதாக இல்லாத அளவுக்குக் குறைவில்லாமலும், நீர்ப்பாசனம், குடிநீர் மற்றும் பிற தேவைகளுக்குத் தேவையான அளவில் இறக்குகிறான். ஒரு நிலத்திற்கு நீர்ப்பாசனத்திற்கு அதிகத் தண்ணீர் தேவைப்படலாம், ஆனால் அங்கே மழை பெய்தால் அதன் வளமான மண் அடித்துச் செல்லப்படும் என்றிருந்தால், அல்லாஹ் வேறொரு நிலத்திலிருந்து அதற்குத் தண்ணீரை அனுப்புகிறான். உதாரணமாக, எகிப்து ஒரு வறண்ட நிலம் என்று சொல்லப்படுகிறது. அல்லாஹ் அதற்கு நைல் நதியின் நீரை அனுப்புகிறான். எத்தியோப்பியாவில் மழை பெய்யும்போது, அது அங்கிருந்து செம்மண்ணைக் கொண்டுவருகிறது. அந்தத் தண்ணீர் எகிப்தின் நிலத்திற்குப் பாய்ச்சப்படுகிறது; அதில் படியும் மண் விவசாயத்திற்குப் பயன்படுத்தப்படுகிறது. ஏனெனில் எகிப்தின் நிலம் இயற்கையிலேயே விளைச்சலுக்குத் தகுதியற்றது, அதன் பெரும்பகுதி மணலால் ஆனது. நுட்பமானவனும், யாவற்றையும் அறிந்தவனும், மகா கருணையாளனும், மன்னிப்பவனுமாகிய அல்லாஹ் தூய்மையானவன்.\n\r\n\n\r\nفَأَسْكَنَّاهُ فِي الْأَرْضِ\n\r\n\n\r\n(அதனை நாம் பூமியில் தங்கச் செய்தோம்,) மேகங்களிலிருந்து தண்ணீர் இறங்கும்போது, அதனைப் பூமிக்குள் தங்கச் செய்து, பூமி அதனை உறிஞ்சிக் கொள்ளும்படி அல்லாஹ் செய்கிறான்; அதன் மூலம் பூமியில் உள்ள விதைகள் போன்றவை ஊட்டம்பெறுகின்றன.\n\r\n\n\r\nوَإِنَّا عَلَى ذَهَابٍ بِهِ لَقَادِرُونَ\n\r\n\n\r\n(நிச்சயமாக நாம் அதனைப் போக்கிவிடவும் ஆற்றலுடையவன்.) அதாவது, 'நாம் மழை பெய்யாமல் செய்ய நாடினால், நம்மால் அதைச் செய்ய முடியும்; அதனை மக்கள் வசிக்காத வனாந்தரங்கள் மற்றும் பாழ்நிலங்களின் பக்கம் திருப்ப நாடினாலும் நம்மால் முடியும். நீங்கள் குடிப்பதற்கோ அல்லது நீர்ப்பாசனத்திற்கோ பயன்படுத்த முடியாதவாறு அதனை உப்பு நீராக மாற்ற நாடினாலும் நம்மால் முடியும்; அது பூமியால் உறிஞ்சப்படாமல் மேற்பரப்பிலேயே தேங்கி நிற்கும்படி செய்ய நாடினாலும் நம்மால் முடியும்; அல்லது நீங்கள் அடைய முடியாத அளவுக்குப் பூமிக்கு அடியில் ஆழமாகச் சென்றுவிடச் செய்யவும் நம்மால் முடியும்.' ஆனால், அல்லாஹ் தன் கிருபையாலும் கருணையாலும், மேகங்களிலிருந்து இனிமையான, தூய்மையான நீரை இறக்குகிறான். பின்னர் அது பூமியில் தங்கி நீரூற்றுகளையும் ஆறுகளையும் உருவாக்குகிறது. அதைக் கொண்டு நீங்கள் உங்கள் பயிர்களுக்கும் பழத்தோட்டங்களுக்கும் நீர் பாய்ச்சுகிறீர்கள்; நீங்களும் குடித்து உங்கள் கால்நடைகளுக்கும் புகட்டுகிறீர்கள்; மேலும் அதைக் கொண்டு குளித்து உங்களைத் தூய்மைப்படுத்திக் கொள்கிறீர்கள். புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.\n\r\n\n\r\nفَأَنشَأْنَا لَكُمْ بِهِ جَنَّاتٍ مِّن نَّخِيلٍ وَأَعْنَابٍ\n\r\n\n\r\n(அதன் மூலம் பேரீச்சை மற்றும் திராட்சைத் தோட்டங்களை உங்களுக்காக நாம் உண்டாக்கினோம்,) அதாவது, 'வானத்திலிருந்து நாம் இறக்கும் நீரைக் கொண்டு, அழகிய தோட்டங்களையும் பழத்தோப்புகளையும் உங்களுக்காக நாம் உருவாக்குகிறோம்' என்று அல்லாஹ் கூறுகிறான்.\n\r\n\n\r\nمِّن نَّخِيلٍ وَأَعْنَابٍ\n\r\n\n\r\n(பேரீச்சை மற்றும் திராட்சைகளால் ஆன,) இவை ஹிஜாஸ் மக்களுக்கு நன்கு தெரிந்த தோட்ட வகைகளாகும். எனினும், இவற்றுக்கு நிகரானவை வேறெதுவும் இல்லை. ஒவ்வொரு பகுதியினருக்கும் சில பழ வகைகள் அல்லாஹ்வின் அருட்கொடையாக வழங்கப்பட்டுள்ளன. அதற்காக அவர்கள் அல்லாஹ்வுக்கு எவ்வளவு நன்றி செலுத்தினாலும் அது ஈடாகாது.\n\r\n\n\r\nلَّكُمْ فِيهَا فَوَاكِهُ كَثِيرَةٌ\n\r\n\n\r\n(அதில் உங்களுக்கு ஏராளமான கனிகள் உள்ளன,) அதாவது, எல்லா வகையான பழங்களும் உள்ளன. இதனை அல்லாஹ் வேறொரு இடத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nيُنبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخِيلَ وَالْأَعْنَابَ وَمِن كُلِّ الثَّمَرَاتِ\n\r\n\n\r\n(அதன் மூலம் அவன் உங்களுக்காகப் பயிர்களையும், ஒலிவத்தையும், பேரீச்சையையும், திராட்சையையும், இன்னும் அனைத்துக் கனிகளையும் விளைவிக்கிறான்) 16:11.\n\r\n\n\r\nوَمِنْهَا تَأْكُلُونَ\n\r\n\n\r\n(அவற்றிலிருந்தே நீங்கள் உண்கிறீர்கள்.) நீங்கள் அதன் அழகைப் பார்க்கிறீர்கள், அது பழுக்கும் வரை காத்திருந்து, பின்னர் அதிலிருந்து உண்கிறீர்கள் என்பதை இது குறிக்கிறது.\n\r\n\n\r\nوَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَاءَ\n\r\n\n\r\n(மேலும் தூர் ஸைனாவிலிருந்து முளைக்கும் ஒரு மரத்தையும் உண்டாக்கினோம்,) இது ஒலிவ மரத்தைக் குறிக்கும். 'தூர்' என்றால் மலை என்று பொருள். சில அறிஞர்கள், \"மரங்கள் அடர்ந்த மலை 'தூர்' என்று அழைக்கப்படும்; மரங்கள் இல்லாவிட்டால் அது 'ஜபல்' என்று அழைக்கப்படும்\" என்று கூறியுள்ளனர். அல்லாஹ்வே மிக அறிந்தவன். ஸைனா மலை என்பது 'தூர் ஸினீன்' ஆகும். இம்மலையில்தான் அல்லாஹ் மூஸா பின் இம்ரான் (அலை) அவர்களுடன் பேசினான். இம்மலையைச் சுற்றியுள்ள பகுதிகளில் ஒலிவ மரங்கள் அதிகமுள்ளன.\n\r\n\n\r\nتَنبُتُ بِالدُّهْنِ\n\r\n\n\r\n(அது எண்ணெயுடன் முளைக்கிறது,) சில அறிஞர்கள் மொழியியல் ரீதியாக இது 'எண்ணெயைத் தருகிறது' என்று பொருள் கொள்கிறார்கள். மற்றவர்கள் 'எண்ணெயுடன் வெளிவருகிறது' என்று கூறுகிறார்கள். அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nوَصِبْغٍ\n\r\n\n\r\n(மேலும் தொடுகறியாகவும்) அதாவது, இது உணவுக்கு ஒரு துணை உணவாகும் என்று கதாதா கூறுகிறார்.\n\r\n\n\r\nلِلْآكِلِينَ\n\r\n\n\r\n(உண்பவர்களுக்கு.) அதாவது, இதில் பயனுள்ள எண்ணெயும் தொடுகறியும் உள்ளது. அப்து பின் ஹுமைத் தனது முஸ்னத் மற்றும் தஃப்ஸீரில் உமர் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ائْتَدِمُوا بِالزَّيْتِ وَادَّهِنُوا بِهِ فَإِنَّهُ يَخْرُجُ مِنْ شَجَرَةٍ مُبَارَكَة»\n\r\n\n\r\n((ஒலிவ) எண்ணெயைத் தொடுகறியாகப் பயன்படுத்துங்கள், மேலும் அதனைத் தேய்த்துக் கொள்ளுங்கள் (உடலில் பூசுங்கள்); ஏனெனில் அது ஒரு பாக்கியம் மிக்க மரத்திலிருந்து கிடைப்பதாகும்.) இதனை அத்-திர்மிதி மற்றும் இப்னு மாஜா பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُمْ مِّمَّا فِي بُطُونِهَا وَلَكُمْ فِيهَا مَنَافِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ - وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ\n\r\n\n\r\n(மேலும் நிச்சயமாக, கால்நடைகளிலும் உங்களுக்கு ஒரு படிப்பினை இருக்கிறது. அவற்றின் வயிறுகளில் இருப்பதிலிருந்து நாம் உங்களுக்குப் புகட்டுகிறோம். மேலும் அவற்றில் உங்களுக்கு ஏராளமான பயன்கள் உள்ளன; அவற்றிலிருந்து நீங்கள் உண்கிறீர்கள். அவற்றின் மீதும் கப்பல்கள் மீதும் நீங்கள் சுமந்து செல்லப்படுகிறீர்கள்.) இங்கு அல்லாஹ் கால்நடைகளின் மூலம் தன் அடியார்களுக்கு வழங்கியுள்ள நன்மைகளைக் குறிப்பிடுகிறான். கால்நடைகளின் சாணத்திற்கும் இரத்தத்திற்கும் இடையில் இருந்து வெளிவரும் பாலை அவர்கள் குடிக்கிறார்கள்; அவற்றின் இறைச்சியை உண்கிறார்கள்; அவற்றின் கம்பளி மற்றும் உரோமங்களைக் கொண்டு ஆடை அணிகிறார்கள்; அவற்றின் முதுகில் சவாரி செய்கிறார்கள்; மேலும் வெகுதொலைவில் உள்ள இடங்களுக்குப் பாரமான சுமைகளை அவற்றின் மூலம் சுமந்து செல்கிறார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَتَحْمِلُ أَثْقَالَكُمْ إِلَى بَلَدٍ لَّمْ تَكُونُواْ بَالِغِيهِ إِلاَّ بِشِقِّ الأَنفُسِ إِنَّ رَبَّكُمْ لَرَؤُوفٌ رَّحِيمٌ\n\r\n\n\r\n(உங்களால் பெரும் சிரமமின்றி அடைய முடியாத ஊர்களுக்கு அவை உங்கள் சுமைகளைச் சுமந்து செல்கின்றன. நிச்சயமாக உங்கள் இறைவன் மிக்க இரக்கமுடையவன், மகா கருணையாளன்.) 16:7\n\r\n\n\r\nأَوَلَمْ يَرَوْاْ أَنَّا خَلَقْنَا لَهُم مِمَّا عَمِلَتْ أَيْدِينَآ أَنْعَامًا فَهُمْ لَهَا مَالِكُونَ - وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ - وَلَهُمْ فِيهَا مَنَافِعُ وَمَشَارِبُ أَفَلاَ يَشْكُرُونَ\n\r\n\n\r\n(நமது கைகள் உருவாக்கியவற்றிலிருந்து நாம் அவர்களுக்காகக் கால்நடைகளைப் படைத்திருப்பதை அவர்கள் பார்க்கவில்லையா? அவர்கள் அவற்றிற்கு உரிமையாளர்களாக இருக்கிறார்கள். அவற்றை நாம் அவர்களுக்கு வசப்படுத்திக் கொடுத்தோம்; அவற்றில் சிலவற்றை அவர்கள் சவாரி செய்யவும், சிலவற்றை அவர்கள் உண்ணவும் செய்கின்றனர். அவற்றில் அவர்களுக்கு (வேறு பல) பயன்களும் பானங்களும் உள்ளன. அவர்கள் நன்றி செலுத்த வேண்டாமா?) 36:71-73"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=25\" class=\"link\">23:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:25 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=25\" class=\"link\">23:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:25 ஐ பார்க்கவும்"},"25":{"html":"<strong>நூஹ் (அலை) மற்றும் அவரது சமூகத்தாரின் வரலாறு</strong><br />\r\n<br />\r\nஅல்லாஹ்வுக்கு இணை கற்பித்தவர்கள், அவனது கட்டளைகளை மீறியவர்கள் மற்றும் அவனது தூதர்களை நிராகரித்தவர்கள் மீது அல்லாஹ் விதிக்கவிருக்கும் கடுமையான தண்டனை மற்றும் அவனது கடுமையான பழிவாங்கல் குறித்து எச்சரிப்பதற்காக, அவரது சமூகத்தாரிடம் அனுப்பப்பட்ட நூஹ் (அலை) அவர்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾فَقَالَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">إِلَٰهٍ</span> <span class=\"quran-arabic-font text-success\">غَيْرُهُ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர் கூறினார்கள்: \"எனது சமூகத்தாரே! அல்லாஹ்வையே வணங்குங்கள்! அவனைத் தவிர உங்களுக்கு வேறு இறைவன் இல்லை. நீங்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டீர்களா?\") அதாவது, \"நீங்கள் அல்லாஹ்வுக்கு இணை வைத்து வணங்கும்போது அவனுக்குப் பயப்படமாட்டீர்களா?\" என்று அவர் கேட்டார்கள். அப்போது அவரது சமூகத்தின் தலைவர்கள் கூறினார்கள்:<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">هَٰذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّثْلُكُمْ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَتَفَضَّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ﴿</span><br />\r\n<br />\r\n(\"இவர் உங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை; இவர் உங்களை விடத் தன்னை மேன்மைப்படுத்திக் கொள்ளவே விரும்புகிறார்.\") அதாவது, 'இவர் ஒரு நபி என்று கூறிக்கொள்வதன் மூலம் உங்களை விடத் தன்னை உயர்ந்தவராகவும் பெரியவராகவும் ஆக்கிக் கொள்ள முயற்சிக்கிறார். ஆனால் இவர் உங்களைப் போன்ற ஒரு மனிதர்தான்; உங்களுக்கு வஹீ (இறைச்செய்தி) வராத நிலையில் இவருக்கு மட்டும் அது எப்படி வர முடியும்?' என்பது இதன் பொருளாகும்.<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">مَلَائِكَةً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">سَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">بِهَٰذَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آبَائِنَا</span> <span class=\"quran-arabic-font text-success\">الأَوَّلِينَ﴿</span><br />\r\n<br />\r\n(\"அல்லாஹ் நாடியிருந்தால், நிச்சயமாக அவன் வானவர்களையே இறக்கியிருப்பான்; எங்கள் முன்னோர்களான மூதாதையர்களிடத்தில் இதுபற்றி நாங்கள் கேள்விப்பட்டதே இல்லை.\") அதாவது, 'அல்லாஹ் ஒரு தூதரை அனுப்ப விரும்பியிருந்தால், அவன் தன்னிடமிருந்து ஒரு வானவரைத்தான் அனுப்பியிருப்பான், ஒரு மனிதரை அல்ல. முன்சென்ற எமது முன்னோர்களின் காலத்தில் கூட இப்படி ஒரு மனிதர் தூதராக வந்ததாக நாம் கேள்விப்பட்டதே இல்லை' என்று அவர்கள் கூறினர்.<span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">جِنَّةٌ﴿</span><br />\r\n<br />\r\n(\"இவர் பைத்தியம் பிடித்த ஒரு மனிதரே அன்றி வேறில்லை,\") அதாவது, 'அல்லாஹ் தன்னைத் தூதராக அனுப்பியுள்ளான் என்றும், வஹீ (இறைச்செய்தி) பெறுவதற்காக உங்களிலிருந்து தன்னைத் தேர்ந்தெடுத்துள்ளான் என்றும் இவர் கூறுவது ஒரு பைத்தியக்காரத்தனமான வாதமாகும்' என்பது இதன் பொருளாகும்.<span class=\"quran-arabic-font text-success\">﴾فَتَرَبَّصُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">حِينٍ﴿</span><br />\r\n<br />\r\n(\"எனவே, அவருக்காகச் சிறிது காலம் காத்திருங்கள்.\") அதாவது, 'அவர் மரணிக்கும் வரை காத்திருங்கள், அவரிடமிருந்து நீங்கள் விடுபடும் வரை அவரைப் பொறுத்துக் கொள்ளுங்கள்' என்பதாகும்.<br />\r\n<br />","text":"நூஹ் (அலை) மற்றும் அவரது சமூகத்தாரின் வரலாறு\n\r\n\n\r\nஅல்லாஹ்வுக்கு இணை கற்பித்தவர்கள், அவனது கட்டளைகளை மீறியவர்கள் மற்றும் அவனது தூதர்களை நிராகரித்தவர்கள் மீது அல்லாஹ் விதிக்கவிருக்கும் கடுமையான தண்டனை மற்றும் அவனது கடுமையான பழிவாங்கல் குறித்து எச்சரிப்பதற்காக, அவரது சமூகத்தாரிடம் அனுப்பப்பட்ட நூஹ் (அலை) அவர்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான்:﴾فَقَالَ يَا قَوْمِ اعْبُدُواْ اللَّهَ مَا لَكُمْ مِّنْ إِلَٰهٍ غَيْرُهُ أَفَلاَ تَتَّقُونَ﴿\n\r\n\n\r\n(மேலும் அவர் கூறினார்கள்: \"எனது சமூகத்தாரே! அல்லாஹ்வையே வணங்குங்கள்! அவனைத் தவிர உங்களுக்கு வேறு இறைவன் இல்லை. நீங்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டீர்களா?\") அதாவது, \"நீங்கள் அல்லாஹ்வுக்கு இணை வைத்து வணங்கும்போது அவனுக்குப் பயப்படமாட்டீர்களா?\" என்று அவர் கேட்டார்கள். அப்போது அவரது சமூகத்தின் தலைவர்கள் கூறினார்கள்:﴾مَا هَٰذَا إِلاَّ بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ﴿\n\r\n\n\r\n(\"இவர் உங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை; இவர் உங்களை விடத் தன்னை மேன்மைப்படுத்திக் கொள்ளவே விரும்புகிறார்.\") அதாவது, 'இவர் ஒரு நபி என்று கூறிக்கொள்வதன் மூலம் உங்களை விடத் தன்னை உயர்ந்தவராகவும் பெரியவராகவும் ஆக்கிக் கொள்ள முயற்சிக்கிறார். ஆனால் இவர் உங்களைப் போன்ற ஒரு மனிதர்தான்; உங்களுக்கு வஹீ (இறைச்செய்தி) வராத நிலையில் இவருக்கு மட்டும் அது எப்படி வர முடியும்?' என்பது இதன் பொருளாகும்.﴾وَلَوْ شَآءَ اللَّهُ لَأَنزَلَ مَلَائِكَةً مَّا سَمِعْنَا بِهَٰذَا فِي آبَائِنَا الأَوَّلِينَ﴿\n\r\n\n\r\n(\"அல்லாஹ் நாடியிருந்தால், நிச்சயமாக அவன் வானவர்களையே இறக்கியிருப்பான்; எங்கள் முன்னோர்களான மூதாதையர்களிடத்தில் இதுபற்றி நாங்கள் கேள்விப்பட்டதே இல்லை.\") அதாவது, 'அல்லாஹ் ஒரு தூதரை அனுப்ப விரும்பியிருந்தால், அவன் தன்னிடமிருந்து ஒரு வானவரைத்தான் அனுப்பியிருப்பான், ஒரு மனிதரை அல்ல. முன்சென்ற எமது முன்னோர்களின் காலத்தில் கூட இப்படி ஒரு மனிதர் தூதராக வந்ததாக நாம் கேள்விப்பட்டதே இல்லை' என்று அவர்கள் கூறினர்.﴾إِنْ هُوَ إِلاَّ رَجُلٌ بِهِ جِنَّةٌ﴿\n\r\n\n\r\n(\"இவர் பைத்தியம் பிடித்த ஒரு மனிதரே அன்றி வேறில்லை,\") அதாவது, 'அல்லாஹ் தன்னைத் தூதராக அனுப்பியுள்ளான் என்றும், வஹீ (இறைச்செய்தி) பெறுவதற்காக உங்களிலிருந்து தன்னைத் தேர்ந்தெடுத்துள்ளான் என்றும் இவர் கூறுவது ஒரு பைத்தியக்காரத்தனமான வாதமாகும்' என்பது இதன் பொருளாகும்.﴾فَتَرَبَّصُواْ بِهِ حَتَّى حِينٍ﴿\n\r\n\n\r\n(\"எனவே, அவருக்காகச் சிறிது காலம் காத்திருங்கள்.\") அதாவது, 'அவர் மரணிக்கும் வரை காத்திருங்கள், அவரிடமிருந்து நீங்கள் விடுபடும் வரை அவரைப் பொறுத்துக் கொள்ளுங்கள்' என்பதாகும்."},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=30\" class=\"link\">23:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:30 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=30\" class=\"link\">23:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:30 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=30\" class=\"link\">23:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:30 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=30\" class=\"link\">23:30</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:30 ஐ பார்க்கவும்"},"30":{"html":"<strong>நூஹ் (அலை) அவர்கள் தம் மக்களுக்கு எதிராகத் தமக்கு உதவுமாறு தம் இறைவனிடம் பிரார்த்தனை செய்தார்கள் என்று அல்லாஹ் நமக்குக் கூறுகிறான்.</strong><br />\r\n<br />\r\nஅல்லாஹ் மற்றொரு வசனத்தில் குறிப்பிடுவதைப் போல: <span class=\"quran-arabic-font text-success\">﴾فَدَعَا</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنِّي</span> <span class=\"quran-arabic-font text-success\">مَغْلُوبٌ</span> <span class=\"quran-arabic-font text-success\">فَانتَصِرْ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"நிச்சயமாக நான் தோல்வியுற்றேன், எனவே நீ எனக்கு உதவி செய்\" என்று அவர் தன் இறைவனிடம் பிரார்த்தனை செய்தார்.) <a href=\"qurandisp.php?sura=54&ayah=10\" class=\"link\">54:10</a>. இங்கே அவர்கள் கூறுகிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">انصُرْنِى</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَذَّبُونِ﴿</span><br />\r\n(\"என் இறைவனே! அவர்கள் என்னைப் பொய்யாக்கியதால் எனக்கு உதவி செய்வாயாக.\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَوْحَيْنَا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اصْنَعِ</span> <span class=\"quran-arabic-font text-success\">الْفُلْكَ</span> <span class=\"quran-arabic-font text-success\">بِأَعْيُنِنَا</span> <span class=\"quran-arabic-font text-success\">وَوَحْيِنَا</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَا</span> <span class=\"quran-arabic-font text-success\">وَفَارَ</span> <span class=\"quran-arabic-font text-success\">التَّنُّورُ</span> <span class=\"quran-arabic-font text-success\">فَاسْلُكْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلٍّ</span> <span class=\"quran-arabic-font text-success\">زَوْجَيْنِ</span> <span class=\"quran-arabic-font text-success\">اثْنَيْنِ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلَكَ﴿</span><br />\r\n<br />\r\nஅந்த நேரத்தில், நம்முடைய கண்காணிப்பிலும், நம்முடைய வஹி (அறிவிப்பு) படியும் ஒரு கப்பலைக் கட்டுமாறும், அதை உறுதியாகவும் பலமாகவும் உருவாக்குமாறும், நம் உத்தரவு வந்து, (தண்ணீர்) அடுப்பிலிருந்து பொங்கி எழும்போது, அதில் விலங்குகள், தாவரங்கள் மற்றும் பழங்கள் போன்ற ஒவ்வொரு உயிரினத்திலிருந்தும் ஆண் மற்றும் பெண் எனச் சோடியாக இரண்டிரண்டைத் தாங்கிச் செல்லுமாறும் அல்லாஹ் அவர்களுக்குக் கட்டளையிட்டான். அவர்கள் தம் குடும்பத்தினரையும் ஏற்றிச் செல்ல வேண்டும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">سَبَقَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ﴿</span><br />\r\n(அவர்களில் எவர்களுக்கு எதிராக (அழிவு பற்றிய) தீர்ப்பு ஏற்கனவே வந்துவிட்டதோ அவர்களைத் தவிர.)<br />\r\n<br />\r\nஅதாவது, அழிக்கப்பட வேண்டும் என்று அல்லாஹ் ஏற்கனவே தீர்மானித்தவர்கள். இவர்கள், நூஹ் (அலை) அவர்களை நம்பாத இவர்களுடைய குடும்ப உறுப்பினர்களான இவர்களுடைய மகனும் மனைவியும் ஆவர். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُخَـطِبْنِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّغْرَقُونَ﴿</span><br />\r\n(அநியாயம் செய்தவர்களுக்காக என்னிடம் பரிந்து பேசாதீர்கள். நிச்சயமாக அவர்கள் மூழ்கடிக்கப்படுவார்கள்.)<br />\r\n<br />\r\nஇதன் பொருள்: \"கனமழை பொழிவதை நீங்கள் காணும்போது, உங்கள் மக்கள் மீது கொண்ட கருணையாலும் இரக்கத்தாலும் உங்களை ஆட்கொள்ள விடாதீர்கள்; அல்லது அவர்கள் நம்பிக்கை கொள்வதற்காக அவர்களுக்குக் கூடுதல் அவகாசம் வேண்டும் என்று விரும்பாதீர்கள். ஏனெனில், அவர்கள் மூழ்கடிக்கப்படுவார்கள் என்றும், அவர்கள் தங்கள் இறைமறுப்பு மற்றும் அநியாயமான நிலையிலேயே மரணிப்பார்கள் என்றும் நான் ஏற்கனவே தீர்மானித்துவிட்டேன்.\" இந்தக் கதை ஸூரா ஹூதில் விரிவாகக் கூறப்பட்டுள்ளது, எனவே அதை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَوَيْتَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">مَّعَكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">فَقُلِ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَجَّانَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"நீரும் உம்முடன் இருப்பவர்களும் கப்பலில் அமர்ந்து கொண்டதும்: அநியாயம் செய்த மக்களிடமிருந்து எங்களைக் காப்பாற்றிய அல்லாஹ்வுக்கே எல்லாப் புகழும் என்று கூறுவீராக.\")<br />\r\n<br />\r\nஇது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَزْوَجَ</span> <span class=\"quran-arabic-font text-success\">كُلَّهَا</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرْكَبُونَ</span> - <span class=\"quran-arabic-font text-success\">لِتَسْتَوُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَوَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَتَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">سَخَّرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُقْرِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لَمُنقَلِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"அவனே சகல ஜோடிகளையும் படைத்தான்; நீங்கள் ஏறிச் சவாரி செய்வதற்காகக் கப்பல்களையும் கால்நடைகளையும் உங்களுக்கு ஏற்படுத்தினான். நீங்கள் அவற்றின் முதுகுகள் மீது அமர்ந்து கொண்டதும், உங்கள் இறைவனின் அருட்கொடையை நினைவு கூர்ந்து, 'எங்களுக்கு இதனை வசப்படுத்திக் கொடுத்தவன் தூய்மையானவன்; இதனை அடக்கும் ஆற்றல் உடையவர்களாக நாங்கள் இருந்ததில்லை. நிச்சயமாக நாங்கள் எங்கள் இறைவனிடமே திரும்பிச் செல்பவர்கள்' என்று கூறுவதற்காகவே (இவ்வாறு செய்தான்).\") <a href=\"qurandisp.php?sura=43&ayah=12\" class=\"link\">43:12</a>-14<br />\r\n<br />\r\nஎனவே, நிச்சயமாக நூஹ் (அலை) அவர்கள் தங்களுக்குக் கட்டளையிடப்பட்டதைச் சரியாகக் கடைப்பிடித்தார்கள். அல்லாஹ் மற்றோரிடத்தில் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">ارْكَبُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَجْرَاهَا</span> <span class=\"quran-arabic-font text-success\">وَمُرْسَاهَا﴿</span><br />\r\n(\"அவர் கூறினார்: இதில் ஏறுங்கள்! இது செல்வதும், இது நங்கூரமிடுவதும் அல்லாஹ்வின் பெயராலேயே அமையும்.\") <a href=\"qurandisp.php?sura=11&ayah=41\" class=\"link\">11:41</a>.<br />\r\n<br />\r\nஇவ்வாறு நூஹ் (அலை) அவர்கள் தமது பயணத்தின் தொடக்கத்திலும் முடிவிலும் அல்லாஹ்வைத் துதித்தார்கள். மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقُل</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">أَنزِلْنِى</span> <span class=\"quran-arabic-font text-success\">مُنزَلاً</span> <span class=\"quran-arabic-font text-success\">مُّبَارَكاً</span> <span class=\"quran-arabic-font text-success\">وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الْمُنزِلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"மேலும், 'என் இறைவனே! என்னைப் பாக்கியம் நிறைந்த ஓர் இடத்தில் இறக்கி வைப்பாயாக! நீயே இறக்கி வைப்பவர்களில் மிகச் சிறந்தவன்' என்றும் கூறுவீராக.\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">لأيَـتٍ﴿</span><br />\r\n(நிச்சயமாக இதில் பல அத்தாட்சிகள் உள்ளன.)<br />\r\n<br />\r\nஇதன் பொருள், நம்பிக்கையாளர்கள் காப்பாற்றப்பட்டதும் இறைமறுப்பாளர்கள் அழிக்கப்பட்டதுமான இந்த நிகழ்வில் அத்தாட்சிகள் உள்ளன. அதாவது, தூதர்கள் அல்லாஹ்விடமிருந்து கொண்டு வரும் செய்திகளில் அவர்கள் உண்மையாளர்களே என்பதற்கும், மேன்மைமிக்க அல்லாஹ் தான் நாடியதைச் செய்கிறான், அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன் மற்றும் அனைத்தையும் அறிந்தவன் என்பதற்கும் இதில் தெளிவான சான்றுகளும் ஆதாரங்களும் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُبْتَلِينَ﴿</span><br />\r\n(நிச்சயமாக நாம் (மக்களைச்) சோதிப்பவர்களாகவே இருக்கிறோம்.)<br />\r\n<br />\r\nஇதன் பொருள், \"நாம் தூதர்களை அனுப்புவதன் மூலம் நமது அடியார்களைச் சோதிக்கிறோம்\" என்பதாகும்.<br />\r\n<br />","text":"நூஹ் (அலை) அவர்கள் தம் மக்களுக்கு எதிராகத் தமக்கு உதவுமாறு தம் இறைவனிடம் பிரார்த்தனை செய்தார்கள் என்று அல்லாஹ் நமக்குக் கூறுகிறான்.\n\r\n\n\r\nஅல்லாஹ் மற்றொரு வசனத்தில் குறிப்பிடுவதைப் போல: ﴾فَدَعَا رَبَّهُ أَنِّي مَغْلُوبٌ فَانتَصِرْ ﴿\n\r\n(\"நிச்சயமாக நான் தோல்வியுற்றேன், எனவே நீ எனக்கு உதவி செய்\" என்று அவர் தன் இறைவனிடம் பிரார்த்தனை செய்தார்.) 54:10. இங்கே அவர்கள் கூறுகிறார்கள்: ﴾رَبِّ انصُرْنِى بِمَا كَذَّبُونِ﴿\n\r\n(\"என் இறைவனே! அவர்கள் என்னைப் பொய்யாக்கியதால் எனக்கு உதவி செய்வாயாக.\")\n\r\n\n\r\n﴾فَأَوْحَيْنَا إِلَيْهِ أَنِ اصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ التَّنُّورُ فَاسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ﴿\n\r\n\n\r\nஅந்த நேரத்தில், நம்முடைய கண்காணிப்பிலும், நம்முடைய வஹி (அறிவிப்பு) படியும் ஒரு கப்பலைக் கட்டுமாறும், அதை உறுதியாகவும் பலமாகவும் உருவாக்குமாறும், நம் உத்தரவு வந்து, (தண்ணீர்) அடுப்பிலிருந்து பொங்கி எழும்போது, அதில் விலங்குகள், தாவரங்கள் மற்றும் பழங்கள் போன்ற ஒவ்வொரு உயிரினத்திலிருந்தும் ஆண் மற்றும் பெண் எனச் சோடியாக இரண்டிரண்டைத் தாங்கிச் செல்லுமாறும் அல்லாஹ் அவர்களுக்குக் கட்டளையிட்டான். அவர்கள் தம் குடும்பத்தினரையும் ஏற்றிச் செல்ல வேண்டும்,\n\r\n\n\r\n﴾إِلاَّ مَن سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْ﴿\n\r\n(அவர்களில் எவர்களுக்கு எதிராக (அழிவு பற்றிய) தீர்ப்பு ஏற்கனவே வந்துவிட்டதோ அவர்களைத் தவிர.)\n\r\n\n\r\nஅதாவது, அழிக்கப்பட வேண்டும் என்று அல்லாஹ் ஏற்கனவே தீர்மானித்தவர்கள். இவர்கள், நூஹ் (அலை) அவர்களை நம்பாத இவர்களுடைய குடும்ப உறுப்பினர்களான இவர்களுடைய மகனும் மனைவியும் ஆவர். அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\n﴾وَلاَ تُخَـطِبْنِى فِى الَّذِينَ ظَلَمُواْ إِنَّهُمْ مُّغْرَقُونَ﴿\n\r\n(அநியாயம் செய்தவர்களுக்காக என்னிடம் பரிந்து பேசாதீர்கள். நிச்சயமாக அவர்கள் மூழ்கடிக்கப்படுவார்கள்.)\n\r\n\n\r\nஇதன் பொருள்: \"கனமழை பொழிவதை நீங்கள் காணும்போது, உங்கள் மக்கள் மீது கொண்ட கருணையாலும் இரக்கத்தாலும் உங்களை ஆட்கொள்ள விடாதீர்கள்; அல்லது அவர்கள் நம்பிக்கை கொள்வதற்காக அவர்களுக்குக் கூடுதல் அவகாசம் வேண்டும் என்று விரும்பாதீர்கள். ஏனெனில், அவர்கள் மூழ்கடிக்கப்படுவார்கள் என்றும், அவர்கள் தங்கள் இறைமறுப்பு மற்றும் அநியாயமான நிலையிலேயே மரணிப்பார்கள் என்றும் நான் ஏற்கனவே தீர்மானித்துவிட்டேன்.\" இந்தக் கதை ஸூரா ஹூதில் விரிவாகக் கூறப்பட்டுள்ளது, எனவே அதை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை.\n\r\n\n\r\n﴾فَإِذَا اسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ للَّهِ الَّذِى نَجَّانَا مِنَ الْقَوْمِ الظَّـلِمِينَ ﴿\n\r\n(\"நீரும் உம்முடன் இருப்பவர்களும் கப்பலில் அமர்ந்து கொண்டதும்: அநியாயம் செய்த மக்களிடமிருந்து எங்களைக் காப்பாற்றிய அல்லாஹ்வுக்கே எல்லாப் புகழும் என்று கூறுவீராக.\")\n\r\n\n\r\nஇது பின்வரும் வசனத்தைப் போன்றது: ﴾وَالَّذِى خَلَقَ الأَزْوَجَ كُلَّهَا وَجَعَلَ لَكُمْ مِّنَ الْفُلْكِ وَالْأَنْعَامِ مَا تَرْكَبُونَ - لِتَسْتَوُواْ عَلَى ظُهُورِهِ ثُمَّ تَذْكُرُواْ نِعْمَةَ رَبِّكُمْ إِذَا اسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُواْ سُبْحَـنَ الَّذِى سَخَّرَ لَنَا هَـذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ - وَإِنَّآ إِلَى رَبِّنَا لَمُنقَلِبُونَ ﴿\n\r\n(\"அவனே சகல ஜோடிகளையும் படைத்தான்; நீங்கள் ஏறிச் சவாரி செய்வதற்காகக் கப்பல்களையும் கால்நடைகளையும் உங்களுக்கு ஏற்படுத்தினான். நீங்கள் அவற்றின் முதுகுகள் மீது அமர்ந்து கொண்டதும், உங்கள் இறைவனின் அருட்கொடையை நினைவு கூர்ந்து, 'எங்களுக்கு இதனை வசப்படுத்திக் கொடுத்தவன் தூய்மையானவன்; இதனை அடக்கும் ஆற்றல் உடையவர்களாக நாங்கள் இருந்ததில்லை. நிச்சயமாக நாங்கள் எங்கள் இறைவனிடமே திரும்பிச் செல்பவர்கள்' என்று கூறுவதற்காகவே (இவ்வாறு செய்தான்).\") 43:12-14\n\r\n\n\r\nஎனவே, நிச்சயமாக நூஹ் (அலை) அவர்கள் தங்களுக்குக் கட்டளையிடப்பட்டதைச் சரியாகக் கடைப்பிடித்தார்கள். அல்லாஹ் மற்றோரிடத்தில் இவ்வாறு கூறுகிறான்: ﴾وَقَالَ ارْكَبُواْ فِيهَا بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا﴿\n\r\n(\"அவர் கூறினார்: இதில் ஏறுங்கள்! இது செல்வதும், இது நங்கூரமிடுவதும் அல்லாஹ்வின் பெயராலேயே அமையும்.\") 11:41.\n\r\n\n\r\nஇவ்வாறு நூஹ் (அலை) அவர்கள் தமது பயணத்தின் தொடக்கத்திலும் முடிவிலும் அல்லாஹ்வைத் துதித்தார்கள். மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾وَقُل رَّبِّ أَنزِلْنِى مُنزَلاً مُّبَارَكاً وَأَنتَ خَيْرُ الْمُنزِلِينَ ﴿\n\r\n(\"மேலும், 'என் இறைவனே! என்னைப் பாக்கியம் நிறைந்த ஓர் இடத்தில் இறக்கி வைப்பாயாக! நீயே இறக்கி வைப்பவர்களில் மிகச் சிறந்தவன்' என்றும் கூறுவீராக.\")\n\r\n\n\r\n﴾إِنَّ فِى ذلِكَ لأيَـتٍ﴿\n\r\n(நிச்சயமாக இதில் பல அத்தாட்சிகள் உள்ளன.)\n\r\n\n\r\nஇதன் பொருள், நம்பிக்கையாளர்கள் காப்பாற்றப்பட்டதும் இறைமறுப்பாளர்கள் அழிக்கப்பட்டதுமான இந்த நிகழ்வில் அத்தாட்சிகள் உள்ளன. அதாவது, தூதர்கள் அல்லாஹ்விடமிருந்து கொண்டு வரும் செய்திகளில் அவர்கள் உண்மையாளர்களே என்பதற்கும், மேன்மைமிக்க அல்லாஹ் தான் நாடியதைச் செய்கிறான், அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன் மற்றும் அனைத்தையும் அறிந்தவன் என்பதற்கும் இதில் தெளிவான சான்றுகளும் ஆதாரங்களும் உள்ளன.\n\r\n\n\r\n﴾وَإِن كُنَّا لَمُبْتَلِينَ﴿\n\r\n(நிச்சயமாக நாம் (மக்களைச்) சோதிப்பவர்களாகவே இருக்கிறோம்.)\n\r\n\n\r\nஇதன் பொருள், \"நாம் தூதர்களை அனுப்புவதன் மூலம் நமது அடியார்களைச் சோதிக்கிறோம்\" என்பதாகும்."},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=41\" class=\"link\">23:41</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:41 ஐ பார்க்கவும்"},"41":{"html":"<strong>ஆத் அல்லது ஸமூத் கூட்டத்தினரின் வரலாறு</strong><br />\r\n<br />\r\nநூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பிறகு, தான் மற்றொரு சமூகத்தைப் படைத்ததாக அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் நூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பின் வந்தவர்கள் என்பதால், அவர்கள் ‘ஆத்’ கூட்டத்தினர் என்று கூறப்பட்டது. அல்லது அவர்கள் ‘ஸமூத்’ கூட்டத்தினர் என்றும் கூறப்பட்டது, ஏனெனில் ‘ஸமூத்’ கூட்டத்தினரே பேரிரைச்சல் மூலம் அழிக்கப்பட்டனர். ஆனால் இங்கு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَخَذَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّيْحَةُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(ஆகவே, அந்தப் பேரிரைச்சல் (ஸய்ஹா) அவர்களை உண்மையாகவே பிடித்துக்கொண்டது.) அல்லாஹ் அவர்களிலிருந்தே ஒரு தூதரை அவர்களிடம் அனுப்பினான். இணைதுணையின்றி அல்லாஹ்வை மட்டுமே வணங்குமாறு அவர் அவர்களை அழைத்தார். ஆனால் அவர்கள் அவரைப் பொய்யாக்கினார்கள், அவரை எதிர்த்தார்கள். தங்களைப் போன்ற ஒரு மனிதராக இருந்ததால் அவரைப் பின்பற்ற அவர்கள் மறுத்தனர்; மேலும் ஒரு மனிதத் தூதரைப் பின்பற்ற அவர்கள் விரும்பவில்லை. அவர்கள் மறுமை நாளில் அல்லாஹ்வைச் சந்திப்போம் என்பதை நம்பவில்லை, உடல் ரீதியான உயிர்த்தெழுதலையும் அவர்கள் மறுத்தனர். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَيَعِدُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مِتُّمْ</span> <span class=\"quran-arabic-font text-success\">وَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تُرَاباً</span> <span class=\"quran-arabic-font text-success\">وَعِظَامًا</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">مُّخْرَجُونَ</span> - <span class=\"quran-arabic-font text-success\">هَيْهَاتَ</span> <span class=\"quran-arabic-font text-success\">هَيْهَاتَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">تُوعَدُونَ</span><br />\r\n<br />\r\n(நீங்கள் இறந்து, மண்ணாகவும் எலும்புகளாகவும் ஆகிவிட்ட பிறகு, நீங்கள் மீண்டும் (உயிர்ப்பித்து) வெளியே கொண்டு வரப்படுவீர்கள் என்று அவர் உங்களுக்கு வாக்குறுதியளிக்கிறாரா? உங்களுக்கு வாக்களிக்கப்படும் இந்த விஷயம் வெகு தொலைவானது, வெகு தொலைவானது!) அதாவது, இது நடப்பது சாத்தியமே இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">افْتَرَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">كَذِباً</span><br />\r\n<br />\r\n(அவர் அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டிய ஒரு மனிதரே அன்றி வேறில்லை.) அதாவது, ‘அவர் உங்களிடம் கொண்டு வந்த செய்தி, அவரது எச்சரிக்கைகள் மற்றும் உயிர்த்தெழுதல் பற்றிய வாக்குறுதி ஆகியவற்றில் (அவர் பொய் சொல்கிறார்)’ என்பது இதன் பொருளாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">انصُرْنِى</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَذَّبُونِ</span><br />\r\n<br />\r\n(மேலும், நாங்கள் அவரை நம்பப் போவதில்லை. அவர், \"என் இறைவனே! இவர்கள் என்னைப் பொய்யாக்குவதால் எனக்கு உதவி செய்வாயாக!\" என்று கூறினார்.) அதாவது, அந்தத் தூதர் (அலை) அவர்கள் தம் சமூகத்திற்கு எதிராகப் பிரார்த்தனை செய்து, அவர்களுக்கு எதிராகத் தமக்கு உதவுமாறு தம் இறைவனிடம் வேண்டினார்கள். அல்லாஹ் அவருடைய பிரார்த்தனைக்குப் பதிலளித்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">قَلِيلٍ</span> <span class=\"quran-arabic-font text-success\">لَّيُصْبِحُنَّ</span> <span class=\"quran-arabic-font text-success\">نَادِمِينَ</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"வெகு விரைவில் அவர்கள் நிச்சயமாக வருந்துபவர்களாகி விடுவார்கள்.\") அதாவது, ‘உமக்கு அவர்கள் காட்டிய எதிர்ப்பு மற்றும் நீர் அவர்களிடம் கொண்டு வந்த செய்தியை அவர்கள் பிடிவாதமாக நிராகரித்ததற்காக (அவர்கள் வருந்துவார்கள்)’ என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَخَذَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّيْحَةُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(ஆகவே, அந்தப் பேரிரைச்சல் (ஸய்ஹா) அவர்களை உண்மையாகவே பிடித்துக்கொண்டது.) அதாவது, அவர்களுடைய இறைநிராகரிப்பு மற்றும் அநியாயத்தின் காரணமாக அவர்கள் அல்லாஹ்விடமிருந்து அத்தண்டனைக்குத் தகுதியானவர்களானார்கள். அந்தப் பேரிரைச்சல் ஒரு கடும் குளிர்க்காற்றுடன் இணைந்திருந்தது என்பதே இதன் வெளிப்படையான பொருளாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُدَمِّرُ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">بِأَمْرِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهَا</span> <span class=\"quran-arabic-font text-success\">فَأَصْبَحُوا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُرَى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَسَاكِنُهُمْ</span><br />\r\n<br />\r\n(அது தனது இறைவனின் கட்டளையினால் அனைத்துப் பொருட்களையும் அழித்துவிடும்! ஆகவே, அவர்களுடைய குடியிருப்புகளைத் தவிர வேறெதுவும் காணப்படாதவாறு அவர்கள் ஆகிப்போனார்கள்!) <a href=\"qurandisp.php?sura=46&ayah=25\" class=\"link\">46:25</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">غُثَآءً</span><br />\r\n<br />\r\n(பின்னர் நாம் அவர்களைக் காய்ந்த சருகுக் குப்பைகளாக ஆக்கினோம்.) இதன் பொருள், அவர்கள் அழிக்கப்பட்டு, வெள்ளத்தினால் அடித்து வரப்படும் பயனற்ற கசடுகளைப் போல மடிந்து போனார்கள். அதாவது, எவருக்கும் எந்தப் பயனும் அளிக்காத, ஒரு அற்பமான பொருளைப் போல அவர்கள் ஆகிவிட்டனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَبُعْداً</span> <span class=\"quran-arabic-font text-success\">لِّلْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span><br />\r\n<br />\r\n(ஆகவே, அநியாயக்காரச் சமூகம் (அல்லாஹ்வின் அருளிலிருந்து) வெகுதூரம் தள்ளப்படட்டும்.) அல்லாஹ்வின் இந்தக் கூற்றைப் போலவே:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">ظَلَمْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span><br />\r\n<br />\r\n(நாம் அவர்களுக்கு அநியாயம் செய்யவில்லை; மாறாக, அவர்கள்தான் அநியாயக்காரர்களாக இருந்தனர்.) <a href=\"qurandisp.php?sura=43&ayah=76\" class=\"link\">43:76</a>. அதாவது, அவர்கள் இறைநிராகரிப்பின் மூலமும், அல்லாஹ்வின் தூதர் (அலை) அவர்களுக்குக் காட்டிய பிடிவாதமான எதிர்ப்பின் மூலமும் அநியாயக்காரர்களாக இருந்தனர். எனவே, இதைக் கேட்பவர்கள் தங்கள் தூதர்களை நிராகரிப்பதைக் குறித்து எச்சரிக்கையாக இருக்கட்டும்.<br />\r\n<br />","text":"ஆத் அல்லது ஸமூத் கூட்டத்தினரின் வரலாறு\n\r\n\n\r\nநூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பிறகு, தான் மற்றொரு சமூகத்தைப் படைத்ததாக அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் நூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பின் வந்தவர்கள் என்பதால், அவர்கள் ‘ஆத்’ கூட்டத்தினர் என்று கூறப்பட்டது. அல்லது அவர்கள் ‘ஸமூத்’ கூட்டத்தினர் என்றும் கூறப்பட்டது, ஏனெனில் ‘ஸமூத்’ கூட்டத்தினரே பேரிரைச்சல் மூலம் அழிக்கப்பட்டனர். ஆனால் இங்கு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَأَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ\n\r\n\n\r\n(ஆகவே, அந்தப் பேரிரைச்சல் (ஸய்ஹா) அவர்களை உண்மையாகவே பிடித்துக்கொண்டது.) அல்லாஹ் அவர்களிலிருந்தே ஒரு தூதரை அவர்களிடம் அனுப்பினான். இணைதுணையின்றி அல்லாஹ்வை மட்டுமே வணங்குமாறு அவர் அவர்களை அழைத்தார். ஆனால் அவர்கள் அவரைப் பொய்யாக்கினார்கள், அவரை எதிர்த்தார்கள். தங்களைப் போன்ற ஒரு மனிதராக இருந்ததால் அவரைப் பின்பற்ற அவர்கள் மறுத்தனர்; மேலும் ஒரு மனிதத் தூதரைப் பின்பற்ற அவர்கள் விரும்பவில்லை. அவர்கள் மறுமை நாளில் அல்லாஹ்வைச் சந்திப்போம் என்பதை நம்பவில்லை, உடல் ரீதியான உயிர்த்தெழுதலையும் அவர்கள் மறுத்தனர். அவர்கள் கூறினார்கள்:\n\r\n\n\r\nأَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَاباً وَعِظَامًا أَنَّكُمْ مُّخْرَجُونَ - هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ\n\r\n\n\r\n(நீங்கள் இறந்து, மண்ணாகவும் எலும்புகளாகவும் ஆகிவிட்ட பிறகு, நீங்கள் மீண்டும் (உயிர்ப்பித்து) வெளியே கொண்டு வரப்படுவீர்கள் என்று அவர் உங்களுக்கு வாக்குறுதியளிக்கிறாரா? உங்களுக்கு வாக்களிக்கப்படும் இந்த விஷயம் வெகு தொலைவானது, வெகு தொலைவானது!) அதாவது, இது நடப்பது சாத்தியமே இல்லை.\n\r\n\n\r\nإِنْ هُوَ إِلاَّ رَجُلٌ افْتَرَى عَلَى اللَّهِ كَذِباً\n\r\n\n\r\n(அவர் அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டிய ஒரு மனிதரே அன்றி வேறில்லை.) அதாவது, ‘அவர் உங்களிடம் கொண்டு வந்த செய்தி, அவரது எச்சரிக்கைகள் மற்றும் உயிர்த்தெழுதல் பற்றிய வாக்குறுதி ஆகியவற்றில் (அவர் பொய் சொல்கிறார்)’ என்பது இதன் பொருளாகும்.\n\r\n\n\r\nوَمَا نَحْنُ لَهُ بِمُؤْمِنِينَ قَالَ رَبِّ انصُرْنِى بِمَا كَذَّبُونِ\n\r\n\n\r\n(மேலும், நாங்கள் அவரை நம்பப் போவதில்லை. அவர், \"என் இறைவனே! இவர்கள் என்னைப் பொய்யாக்குவதால் எனக்கு உதவி செய்வாயாக!\" என்று கூறினார்.) அதாவது, அந்தத் தூதர் (அலை) அவர்கள் தம் சமூகத்திற்கு எதிராகப் பிரார்த்தனை செய்து, அவர்களுக்கு எதிராகத் தமக்கு உதவுமாறு தம் இறைவனிடம் வேண்டினார்கள். அல்லாஹ் அவருடைய பிரார்த்தனைக்குப் பதிலளித்தான்:\n\r\n\n\r\nقَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَادِمِينَ\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"வெகு விரைவில் அவர்கள் நிச்சயமாக வருந்துபவர்களாகி விடுவார்கள்.\") அதாவது, ‘உமக்கு அவர்கள் காட்டிய எதிர்ப்பு மற்றும் நீர் அவர்களிடம் கொண்டு வந்த செய்தியை அவர்கள் பிடிவாதமாக நிராகரித்ததற்காக (அவர்கள் வருந்துவார்கள்)’ என்று பொருள்.\n\r\n\n\r\nفَأَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ\n\r\n\n\r\n(ஆகவே, அந்தப் பேரிரைச்சல் (ஸய்ஹா) அவர்களை உண்மையாகவே பிடித்துக்கொண்டது.) அதாவது, அவர்களுடைய இறைநிராகரிப்பு மற்றும் அநியாயத்தின் காரணமாக அவர்கள் அல்லாஹ்விடமிருந்து அத்தண்டனைக்குத் தகுதியானவர்களானார்கள். அந்தப் பேரிரைச்சல் ஒரு கடும் குளிர்க்காற்றுடன் இணைந்திருந்தது என்பதே இதன் வெளிப்படையான பொருளாகும்.\n\r\n\n\r\nتُدَمِّرُ كُلَّ شَىْءٍ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا لاَ يُرَى إِلاَّ مَسَاكِنُهُمْ\n\r\n\n\r\n(அது தனது இறைவனின் கட்டளையினால் அனைத்துப் பொருட்களையும் அழித்துவிடும்! ஆகவே, அவர்களுடைய குடியிருப்புகளைத் தவிர வேறெதுவும் காணப்படாதவாறு அவர்கள் ஆகிப்போனார்கள்!) 46:25\n\r\n\n\r\nفَجَعَلْنَاهُمْ غُثَآءً\n\r\n\n\r\n(பின்னர் நாம் அவர்களைக் காய்ந்த சருகுக் குப்பைகளாக ஆக்கினோம்.) இதன் பொருள், அவர்கள் அழிக்கப்பட்டு, வெள்ளத்தினால் அடித்து வரப்படும் பயனற்ற கசடுகளைப் போல மடிந்து போனார்கள். அதாவது, எவருக்கும் எந்தப் பயனும் அளிக்காத, ஒரு அற்பமான பொருளைப் போல அவர்கள் ஆகிவிட்டனர்.\n\r\n\n\r\nفَبُعْداً لِّلْقَوْمِ الظَّالِمِينَ\n\r\n\n\r\n(ஆகவே, அநியாயக்காரச் சமூகம் (அல்லாஹ்வின் அருளிலிருந்து) வெகுதூரம் தள்ளப்படட்டும்.) அல்லாஹ்வின் இந்தக் கூற்றைப் போலவே:\n\r\n\n\r\nوَمَا ظَلَمْنَاهُمْ وَلَـكِن كَانُواْ هُمُ الظَّالِمِينَ\n\r\n\n\r\n(நாம் அவர்களுக்கு அநியாயம் செய்யவில்லை; மாறாக, அவர்கள்தான் அநியாயக்காரர்களாக இருந்தனர்.) 43:76. அதாவது, அவர்கள் இறைநிராகரிப்பின் மூலமும், அல்லாஹ்வின் தூதர் (அலை) அவர்களுக்குக் காட்டிய பிடிவாதமான எதிர்ப்பின் மூலமும் அநியாயக்காரர்களாக இருந்தனர். எனவே, இதைக் கேட்பவர்கள் தங்கள் தூதர்களை நிராகரிப்பதைக் குறித்து எச்சரிக்கையாக இருக்கட்டும்."},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=44\" class=\"link\">23:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:44 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=44\" class=\"link\">23:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:44 ஐ பார்க்கவும்"},"44":{"html":"<strong>ஏனைய சமுதாயங்களைப் பற்றிய குறிப்பு; அல்லாஹ் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنشَأْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">قُرُوناً</span> <span class=\"quran-arabic-font text-success\">ءَاخَرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பின்னர் அவர்களுக்குப் பிறகு வேறு தலைமுறையினரை நாம் உருவாக்கினோம்.) அதாவது, பல சமூகங்களையும் மக்களையும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">تَسْبِقُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">أَجَلَهَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَأْخِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எந்த ஒரு சமுதாயமும் தனக்குரிய தவணையை முந்தவும் முடியாது, அதைப் பிந்தச் செய்யவும் முடியாது.) அதாவது, அவர்கள் படைக்கப்படுவதற்கு முன்பே அல்லாஹ்விடம் பாதுகாக்கப்பட்ட ஏட்டில் அவனால் விதிக்கப்பட்டபடி, சமுதாயத்திற்குப் பின் சமுதாயமாக, நூற்றாண்டுக்குப் பின் நூற்றாண்டாக, தலைமுறைக்குப் பின் தலைமுறையாக, முன்னோர்களுக்குப் பின் பின்னோர்களாக என உரிய நேரத்தில் அவர்கள் அழிக்கப்படுகிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">تَتْرَى﴿</span><br />\r\n<br />\r\n(பின்னர் நாம் நம் தூதர்களைத் தொடர்ச்சியாக அனுப்பினோம்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"(இதன் பொருள்) ஒருவரைத் தொடர்ந்து ஒருவராகத் தொடர்ச்சியாக வருவது\" என்று கூறினார்கள். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">رَّسُولاً</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَاجْتَنِبُواْ</span> <span class=\"quran-arabic-font text-success\">الطَّاغُوتَ</span> <span class=\"quran-arabic-font text-success\">فَمِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">هَدَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">حَقَّتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الضَّلَالَةُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமுதாயத்திலும், \"அல்லாஹ்வை வணங்குங்கள், தாகூத்தை (போலி தெய்வங்களை)த் தவிர்த்துக் கொள்ளுங்கள்\" என்று (கூற) ஒரு தூதரை அனுப்பினோம். அவர்களில் சிலருக்கு அல்லாஹ் நேர்வழி காட்டினான்; இன்னும் சிலரோ வழிகேட்டில் இருக்க வேண்டியவர்கள் என முடிவானது) <a href=\"qurandisp.php?sura=16&ayah=36\" class=\"link\">16:36</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كُلَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">رَّسُولُهَا</span> <span class=\"quran-arabic-font text-success\">كَذَّبُوهُ﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு சமுதாயத்திடமும் அவர்களுக்குரிய தூதர் வந்தபோதெல்லாம், அவர்கள் அவரைப் பொய்யாக்கினார்கள்;) அதாவது அவர்களில் பெரும்பாலானோர் அவ்வாறு செய்தனர். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">حَسْرَةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّسُولٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்த அடியார்களுக்குக் கைசேதமே! எந்த ஒரு தூதர் அவர்களிடம் வந்தபோதும், அவரை அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) <a href=\"qurandisp.php?sura=36&ayah=30\" class=\"link\">36:30</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَتْبَعْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً﴿</span><br />\r\n<br />\r\n(ஆகவே, நாம் அவர்களை ஒருவர்பின் ஒருவராகப் பின்தொடரச் செய்தோம்,) இதன் பொருள், 'நாம் அவர்களை அழித்துவிட்டோம்' என்பதாகும். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ﴿</span><br />\r\n<br />\r\n(நூஹ் (அலை) அவர்களுக்குப் பிறகு எத்தனையோ தலைமுறையினரை நாம் அழித்துள்ளோம்!) <a href=\"qurandisp.php?sura=17&ayah=17\" class=\"link\">17:17</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">أَحَادِيثَ﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களை அஹாதீஸ்களாக (பேசப்படும் கதைகளாக) ஆக்கினோம்) அதாவது, மனிதர்களுக்குக் கதைகளாகவும் படிப்பினைகளாகவும் ஆக்கினோம். அல்லாஹ் வேறோரிடத்தில் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَجَعَلْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَحَادِيثَ</span> <span class=\"quran-arabic-font text-success\">وَمَزَّقْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">مُمَزَّقٍ﴿</span><br />\r\n<br />\r\n(ஆகவே, நாம் அவர்களைப் பழங்கதைகளாக ஆக்கினோம்; மேலும் அவர்களை முற்றிலும் சிதறடித்தோம்) <a href=\"qurandisp.php?sura=34&ayah=19\" class=\"link\">34:19</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَبُعْداً</span> <span class=\"quran-arabic-font text-success\">لِّقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ﴿</span><br />\r\n<br />\r\n(ஆகவே, ஈமான் கொள்ளாத கூட்டத்தார் (இறை அருளை விட்டும்) தூரமாவார்களாக!)<br />\r\n<br />","text":"ஏனைய சமுதாயங்களைப் பற்றிய குறிப்பு; அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾ثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قُرُوناً ءَاخَرِينَ ﴿\n\r\n\n\r\n(பின்னர் அவர்களுக்குப் பிறகு வேறு தலைமுறையினரை நாம் உருவாக்கினோம்.) அதாவது, பல சமூகங்களையும் மக்களையும்.\n\r\n\n\r\n﴾مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَأْخِرُونَ ﴿\n\r\n\n\r\n(எந்த ஒரு சமுதாயமும் தனக்குரிய தவணையை முந்தவும் முடியாது, அதைப் பிந்தச் செய்யவும் முடியாது.) அதாவது, அவர்கள் படைக்கப்படுவதற்கு முன்பே அல்லாஹ்விடம் பாதுகாக்கப்பட்ட ஏட்டில் அவனால் விதிக்கப்பட்டபடி, சமுதாயத்திற்குப் பின் சமுதாயமாக, நூற்றாண்டுக்குப் பின் நூற்றாண்டாக, தலைமுறைக்குப் பின் தலைமுறையாக, முன்னோர்களுக்குப் பின் பின்னோர்களாக என உரிய நேரத்தில் அவர்கள் அழிக்கப்படுகிறார்கள்.\n\r\n\n\r\n﴾ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَى﴿\n\r\n\n\r\n(பின்னர் நாம் நம் தூதர்களைத் தொடர்ச்சியாக அனுப்பினோம்.) இப்னு அப்பாஸ் (ரழி) அவர்கள், \"(இதன் பொருள்) ஒருவரைத் தொடர்ந்து ஒருவராகத் தொடர்ச்சியாக வருவது\" என்று கூறினார்கள். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولاً أَنِ اعْبُدُواْ اللَّهَ وَاجْتَنِبُواْ الطَّاغُوتَ فَمِنْهُم مَّنْ هَدَى اللَّهُ وَمِنْهُمْ مَّنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் ஒவ்வொரு சமுதாயத்திலும், \"அல்லாஹ்வை வணங்குங்கள், தாகூத்தை (போலி தெய்வங்களை)த் தவிர்த்துக் கொள்ளுங்கள்\" என்று (கூற) ஒரு தூதரை அனுப்பினோம். அவர்களில் சிலருக்கு அல்லாஹ் நேர்வழி காட்டினான்; இன்னும் சிலரோ வழிகேட்டில் இருக்க வேண்டியவர்கள் என முடிவானது) 16:36.\n\r\n\n\r\n﴾كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ﴿\n\r\n\n\r\n(ஒவ்வொரு சமுதாயத்திடமும் அவர்களுக்குரிய தூதர் வந்தபோதெல்லாம், அவர்கள் அவரைப் பொய்யாக்கினார்கள்;) அதாவது அவர்களில் பெரும்பாலானோர் அவ்வாறு செய்தனர். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾يَا حَسْرَةً عَلَى الْعِبَادِ مَا يَأْتِيهِمْ مِّن رَّسُولٍ إِلاَّ كَانُواْ بِهِ يَسْتَهْزِءُونَ ﴿\n\r\n\n\r\n(அந்த அடியார்களுக்குக் கைசேதமே! எந்த ஒரு தூதர் அவர்களிடம் வந்தபோதும், அவரை அவர்கள் ஏளனம் செய்யாமல் இருந்ததில்லை.) 36:30\n\r\n\n\r\n﴾فَأَتْبَعْنَا بَعْضَهُمْ بَعْضاً﴿\n\r\n\n\r\n(ஆகவே, நாம் அவர்களை ஒருவர்பின் ஒருவராகப் பின்தொடரச் செய்தோம்,) இதன் பொருள், 'நாம் அவர்களை அழித்துவிட்டோம்' என்பதாகும். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n﴾وَكَمْ أَهْلَكْنَا مِنَ الْقُرُونِ مِن بَعْدِ نُوحٍ﴿\n\r\n\n\r\n(நூஹ் (அலை) அவர்களுக்குப் பிறகு எத்தனையோ தலைமுறையினரை நாம் அழித்துள்ளோம்!) 17:17\n\r\n\n\r\n﴾وَجَعَلْنَـهُمْ أَحَادِيثَ﴿\n\r\n\n\r\n(மேலும் நாம் அவர்களை அஹாதீஸ்களாக (பேசப்படும் கதைகளாக) ஆக்கினோம்) அதாவது, மனிதர்களுக்குக் கதைகளாகவும் படிப்பினைகளாகவும் ஆக்கினோம். அல்லாஹ் வேறோரிடத்தில் கூறுவது போல:\n\r\n\n\r\n﴾فَجَعَلْنَاهُمْ أَحَادِيثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ﴿\n\r\n\n\r\n(ஆகவே, நாம் அவர்களைப் பழங்கதைகளாக ஆக்கினோம்; மேலும் அவர்களை முற்றிலும் சிதறடித்தோம்) 34:19.\n\r\n\n\r\n﴾فَبُعْداً لِّقَوْمٍ لاَّ يُؤْمِنُونَ﴿\n\r\n\n\r\n(ஆகவே, ஈமான் கொள்ளாத கூட்டத்தார் (இறை அருளை விட்டும்) தூரமாவார்களாக!)"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=49\" class=\"link\">23:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:49 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=49\" class=\"link\">23:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:49 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=49\" class=\"link\">23:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:49 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=49\" class=\"link\">23:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:49 ஐ பார்க்கவும்"},"49":{"html":"<strong>மூஸா (அலை) மற்றும் ஃபிர்அவ்னின் வரலாறு</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்களையும், அவர்களது சகோதரர் ஹாரூன் (அலை) அவர்களையும் தெளிவான அத்தாட்சிகளுடனும் உறுதியான சான்றுகளுடனும் ஃபிர்அவ்னிடமும் அவனது பிரமுகர்களிடமும் அனுப்பியதாக அல்லாஹ் நமக்குக் கூறுகிறான். இருப்பினும், முந்தைய சமுதாயத்தினர் மனிதத் தூதர்களின் செய்தியை நிராகரித்ததைப் போலவே, ஃபிர்அவ்னும் அவனது மக்களும் அவர்கள் மனிதர்களாக இருந்த காரணத்தால் அவர்களைப் பின்பற்றவும் அவர்களது கட்டளைகளுக்குக் கீழ்ப்படியவும் மறுத்துப் பெருமையடித்தனர்.<br />\r\n<br />\r\nஅவர்களும் அதே போன்ற மனநிலையையே கொண்டிருந்தனர். எனவே, அல்லாஹ் ஃபிர்அவ்னையும் அவனது பிரமுகர்களையும் அழித்தான்; அவர்கள் அனைவரையும் ஒரே நாளில் மூழ்கடித்தான்.<br />\r\n<br />\r\nதான் நாடியதைச் செயல்படுத்தும் வல்லமை மிக்க பேராற்றல் கொண்டவனின் தண்டனையால் ஃபிர்அவ்னையும் எகிப்தியர்களையும் பிடித்து, அவர்களை அழித்த பிறகு, அல்லாஹ் மூஸா (அலை) அவர்களுக்கு தவ்ராத் வேதத்தை அருளினான்; அதில் சட்டங்களும், ஏவல்களும், விலக்கல்களும் இருந்தன.<br />\r\n<br />\r\nகதாதா (ரஹ்) அவர்கள் கூறினார்கள்: அல்லாஹ் தவ்ராத் வேதத்தை அருளிய பிறகு, எந்தவொரு சமுதாயத்தையும் ஒட்டுமொத்தப் பேரழிவைக் கொண்டு அழிக்கவில்லை. மாறாக, அவன் கூறுவது போல், நிராகரிப்பாளர்களுக்கு எதிராகப் போரிடுமாறு இறைநம்பிக்கையாளர்களுக்குக் கட்டளையிட்டான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">آتَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">الْقُرُونَ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> <span class=\"quran-arabic-font text-success\">بَصَائِرَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَهُدًى</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَةً</span> <span class=\"quran-arabic-font text-success\">لَّعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُونَ﴿</span><br />\r\n<br />\r\n(முந்தைய தலைமுறையினரை நாம் அழித்த பின்னர், மனிதர்களுக்குத் தெளிவான சான்றுகளாகவும், நேர்வழியாகவும், அருளாகவும் மூஸா (அலை) அவர்களுக்கு நிச்சயமாக நாம் வேதத்தைக் கொடுத்தோம்; அவர்கள் நல்லுணர்வு பெறுவதற்காக.) <a href=\"qurandisp.php?sura=28&ayah=43\" class=\"link\">28:43</a><br />\r\n<br />\r\n<br />\r\n<br />","text":"மூஸா (அலை) மற்றும் ஃபிர்அவ்னின் வரலாறு\n\r\n\n\r\nமூஸா (அலை) அவர்களையும், அவர்களது சகோதரர் ஹாரூன் (அலை) அவர்களையும் தெளிவான அத்தாட்சிகளுடனும் உறுதியான சான்றுகளுடனும் ஃபிர்அவ்னிடமும் அவனது பிரமுகர்களிடமும் அனுப்பியதாக அல்லாஹ் நமக்குக் கூறுகிறான். இருப்பினும், முந்தைய சமுதாயத்தினர் மனிதத் தூதர்களின் செய்தியை நிராகரித்ததைப் போலவே, ஃபிர்அவ்னும் அவனது மக்களும் அவர்கள் மனிதர்களாக இருந்த காரணத்தால் அவர்களைப் பின்பற்றவும் அவர்களது கட்டளைகளுக்குக் கீழ்ப்படியவும் மறுத்துப் பெருமையடித்தனர்.\n\r\n\n\r\nஅவர்களும் அதே போன்ற மனநிலையையே கொண்டிருந்தனர். எனவே, அல்லாஹ் ஃபிர்அவ்னையும் அவனது பிரமுகர்களையும் அழித்தான்; அவர்கள் அனைவரையும் ஒரே நாளில் மூழ்கடித்தான்.\n\r\n\n\r\nதான் நாடியதைச் செயல்படுத்தும் வல்லமை மிக்க பேராற்றல் கொண்டவனின் தண்டனையால் ஃபிர்அவ்னையும் எகிப்தியர்களையும் பிடித்து, அவர்களை அழித்த பிறகு, அல்லாஹ் மூஸா (அலை) அவர்களுக்கு தவ்ராத் வேதத்தை அருளினான்; அதில் சட்டங்களும், ஏவல்களும், விலக்கல்களும் இருந்தன.\n\r\n\n\r\nகதாதா (ரஹ்) அவர்கள் கூறினார்கள்: அல்லாஹ் தவ்ராத் வேதத்தை அருளிய பிறகு, எந்தவொரு சமுதாயத்தையும் ஒட்டுமொத்தப் பேரழிவைக் கொண்டு அழிக்கவில்லை. மாறாக, அவன் கூறுவது போல், நிராகரிப்பாளர்களுக்கு எதிராகப் போரிடுமாறு இறைநம்பிக்கையாளர்களுக்குக் கட்டளையிட்டான்:\n\r\n\n\r\n﴾وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ مِن بَعْدِ مَا أَهْلَكْنَا الْقُرُونَ الْأُولَى بَصَائِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ﴿\n\r\n\n\r\n(முந்தைய தலைமுறையினரை நாம் அழித்த பின்னர், மனிதர்களுக்குத் தெளிவான சான்றுகளாகவும், நேர்வழியாகவும், அருளாகவும் மூஸா (அலை) அவர்களுக்கு நிச்சயமாக நாம் வேதத்தைக் கொடுத்தோம்; அவர்கள் நல்லுணர்வு பெறுவதற்காக.) 28:43"},"50":{"html":"<strong>ஈஸாவும் மர்யமும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">وَأُمَّهُ</span> <span class=\"quran-arabic-font text-success\">آيَةً﴿</span><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும் தனது தூதருமான மர்யமின் மகன் ஈஸா (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான் - அவர்கள் இருவர் மீதும் சாந்தி உண்டாவதாக. தான் நாடியதைச் செய்யும் தனது ஆற்றலுக்கு ஒரு தெளிவான சான்றாக அவர்களை மனிதகுலத்திற்கு ஓர் அத்தாட்சியாக அவன் ஆக்கினான். ஏனெனில், அவன் ஆதம் (அலை) அவர்களைத் தந்தை, தாய் இருவருமின்றிப் படைத்தான்; ஹவ்வா (அலை) அவர்களைப் பெண் இன்றி ஓர் ஆணிலிருந்து படைத்தான்; ஈஸா (அலை) அவர்களை ஆண் இன்றி ஒரு பெண்ணிலிருந்து படைத்தான். ஆனால், மற்ற மனிதர்களை ஆண் மற்றும் பெண் ஆகிய இருவரிடமிருந்தும் அவன் படைத்தான். <span class=\"quran-arabic-font text-success\">﴾وَآوَيْنَاهُمَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(மேலும், நாம் அவர்களுக்கு உயரமான, தங்குவதற்கும் பாதுகாப்புக்கும் உகந்த, ஓடும் நீரோடைகளைக் கொண்ட ஓர் இடத்தில் புகலிடம் அளித்தோம்.) அத்-தஹ்ஹாக், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"அர்-ரப்வா என்பது மேடான நிலப்பகுதியாகும், இது பயிர்கள் செழித்து வளர மிகச் சிறந்த இடமாகும்.\" முஜாஹித், இக்ரிமா, ஸஈத் பின் ஜுபைர் மற்றும் கத்தாதா ஆகியோரின் கருத்தும் இதுவேயாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ﴿</span><br />\r\n<br />\r\n(தாத் கரார்) \"வளமான இடம்.\" <span class=\"quran-arabic-font text-success\">﴾وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(வ மஈன்) என்பது \"நிலப்பரப்பில் ஓடும் நீர்\" என்று பொருள்படும். முஜாஹித், இக்ரிமா, ஸஈத் பின் ஜுபைர் மற்றும் கத்தாதா ஆகியோரின் கருத்தும் இதுவேயாகும். முஜாஹித் அவர்கள் \"சமமான குன்று\" என்று கூறினார்கள். ஸஈத் பின் ஜுபைர் அவர்கள் <span class=\"quran-arabic-font text-success\">﴾ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span> என்பது,<br />\r\n<br />\r\n(தாத் கரார் வ மஈன்) \"தண்ணீர் மென்மையாக ஓடிக்கொண்டிருக்கும் இடம்\" என்று கூறினார்கள். முஜாஹித் மற்றும் கத்தாதா ஆகியோர் <span class=\"quran-arabic-font text-success\">﴾وَمَعِينٍ﴿</span> பற்றிக் கூறும்போது:<br />\r\n<br />\r\n(வ மஈன்) \"ஓடும் நீர்\" என்றார்கள். இப்னு அபீ ஹாதிம், ஸஈத் பின் அல்-முஸய்யிப் வழியாகப் பதிவு செய்துள்ளார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَآوَيْنَاهُمَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில் புகலிடம் அளித்தோம்.) \"அது டமாஸ்கஸ் ஆகும்\" என்று அவர் கூறினார்கள். அப்துல்லாஹ் பின் ஸலாம் (ரழி), அல்-ஹஸன், ஸைத் பின் அஸ்லம் மற்றும் காலித் பின் மஃதான் ஆகியோரிடமிருந்தும் இதே போன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. இந்த வசனம் டமாஸ்கஸின் ஆறுகளைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இக்ரிமா வழியாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். <span class=\"quran-arabic-font text-success\">﴾وَآوَيْنَاهُمَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ﴿</span> எனும் சொற்களைப் பற்றி லைத் பின் அபீ சுலைம், முஜாஹித் வழியாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில் புகலிடம் அளித்தோம்) என்பது ஈஸா பின் மர்யம் (அலை) அவர்களும் அவர்களின் தாயாரும் டமாஸ்கஸிலும் அதைச் சுற்றியுள்ள சமவெளிகளிலும் தஞ்சம் புகுந்ததைக் குறிக்கிறது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாக அப்துர்-ரஸ்ஸாக் பதிவு செய்துள்ளார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில்) \"அது பாலஸ்தீனத்தில் உள்ள ரம்லா ஆகும்.\" இந்த விஷயத்தில் மிகவும் சரியான கருத்து இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அல்-அவ்ஃபீ அறிவித்ததாகும். அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَآوَيْنَاهُمَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில் புகலிடம் அளித்தோம்.) \"மஈன் என்பது ஓடும் நீரைக் குறிக்கிறது. அல்லாஹ் பின்வரும் வசனத்தில் குறிப்பிட்ட நதி இதுவேயாகும்: <span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكِ</span> <span class=\"quran-arabic-font text-success\">تَحْتَكِ</span> <span class=\"quran-arabic-font text-success\">سَرِيّاً﴿</span><br />\r\n<br />\r\n(உனது இறைவன் உனக்குக் கீழே ஒரு நீரோடையை ஏற்படுத்தியுள்ளான்.)\" <a href=\"qurandisp.php?sura=19&ayah=24\" class=\"link\">19:24</a> அத்-தஹ்ஹாக் மற்றும் கத்தாதா ஆகியோர் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبْوَةٍ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">قَرَارٍ</span> <span class=\"quran-arabic-font text-success\">وَمَعِينٍ﴿</span><br />\r\n<br />\r\n(உயரமான, தங்குவதற்கும் பாதுகாப்புக்கும் உகந்த, ஓடும் நீரோடைகளைக் கொண்ட ஓர் இடம்) என்பது ஜெருசலேமைக் குறிக்கிறது. இதுவே - அல்லாஹ் மிக அறிந்தவன் - மிகவும் தெளிவான கருத்தாகும். ஏனெனில் இது மற்றொரு வசனத்தில் குறிப்பிடப்பட்டுள்ளது. அதாவது: <span class=\"quran-arabic-font text-success\">﴾فَحَمَلَتْهُ</span> <span class=\"quran-arabic-font text-success\">فَانتَبَذَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مَكَاناً</span> <span class=\"quran-arabic-font text-success\">قَصِيّاً﴿</span> (எனவே, அவர் (ஈஸாவை) கருவுற்றார். பின்னர் அவர் கர்ப்பத்துடன் தொலைவான ஒரு இடத்திற்கு ஒதுங்கிச் சென்றார்.) <a href=\"qurandisp.php?sura=19&ayah=22\" class=\"link\">19:22</a> குர்ஆனின் ஒரு பகுதி மற்றொரு பகுதியை விளக்குகிறது. எனவே, ஒரு வசனத்திற்கு மற்றொரு வசனத்தின் மூலமே விளக்கம் அளிப்பது மிகவும் பொருத்தமானது. அதற்கு அடுத்ததாக ஸஹீஹான ஹதீஸ்கள், அதன் பிறகு ஏனைய அறிவிப்புகள் மூலம் விளக்கம் அளிக்கலாம்.<br />\r\n<br />","text":"ஈஸாவும் மர்யமும்\n\r\n\n\r\n﴾وَجَعَلْنَا ابْنَ مَرْيَمَ وَأُمَّهُ آيَةً﴿\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும் தனது தூதருமான மர்யமின் மகன் ஈஸா (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான் - அவர்கள் இருவர் மீதும் சாந்தி உண்டாவதாக. தான் நாடியதைச் செய்யும் தனது ஆற்றலுக்கு ஒரு தெளிவான சான்றாக அவர்களை மனிதகுலத்திற்கு ஓர் அத்தாட்சியாக அவன் ஆக்கினான். ஏனெனில், அவன் ஆதம் (அலை) அவர்களைத் தந்தை, தாய் இருவருமின்றிப் படைத்தான்; ஹவ்வா (அலை) அவர்களைப் பெண் இன்றி ஓர் ஆணிலிருந்து படைத்தான்; ஈஸா (அலை) அவர்களை ஆண் இன்றி ஒரு பெண்ணிலிருந்து படைத்தான். ஆனால், மற்ற மனிதர்களை ஆண் மற்றும் பெண் ஆகிய இருவரிடமிருந்தும் அவன் படைத்தான். ﴾وَآوَيْنَاهُمَا إِلَى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴿\n\r\n\n\r\n(மேலும், நாம் அவர்களுக்கு உயரமான, தங்குவதற்கும் பாதுகாப்புக்கும் உகந்த, ஓடும் நீரோடைகளைக் கொண்ட ஓர் இடத்தில் புகலிடம் அளித்தோம்.) அத்-தஹ்ஹாக், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"அர்-ரப்வா என்பது மேடான நிலப்பகுதியாகும், இது பயிர்கள் செழித்து வளர மிகச் சிறந்த இடமாகும்.\" முஜாஹித், இக்ரிமா, ஸஈத் பின் ஜுபைர் மற்றும் கத்தாதா ஆகியோரின் கருத்தும் இதுவேயாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: ﴾ذَاتِ قَرَارٍ﴿\n\r\n\n\r\n(தாத் கரார்) \"வளமான இடம்.\" ﴾وَمَعِينٍ﴿\n\r\n\n\r\n(வ மஈன்) என்பது \"நிலப்பரப்பில் ஓடும் நீர்\" என்று பொருள்படும். முஜாஹித், இக்ரிமா, ஸஈத் பின் ஜுபைர் மற்றும் கத்தாதா ஆகியோரின் கருத்தும் இதுவேயாகும். முஜாஹித் அவர்கள் \"சமமான குன்று\" என்று கூறினார்கள். ஸஈத் பின் ஜுபைர் அவர்கள் ﴾ذَاتِ قَرَارٍ وَمَعِينٍ﴿ என்பது,\n\r\n\n\r\n(தாத் கரார் வ மஈன்) \"தண்ணீர் மென்மையாக ஓடிக்கொண்டிருக்கும் இடம்\" என்று கூறினார்கள். முஜாஹித் மற்றும் கத்தாதா ஆகியோர் ﴾وَمَعِينٍ﴿ பற்றிக் கூறும்போது:\n\r\n\n\r\n(வ மஈன்) \"ஓடும் நீர்\" என்றார்கள். இப்னு அபீ ஹாதிம், ஸஈத் பின் அல்-முஸய்யிப் வழியாகப் பதிவு செய்துள்ளார்கள்: ﴾وَآوَيْنَاهُمَا إِلَى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴿\n\r\n\n\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில் புகலிடம் அளித்தோம்.) \"அது டமாஸ்கஸ் ஆகும்\" என்று அவர் கூறினார்கள். அப்துல்லாஹ் பின் ஸலாம் (ரழி), அல்-ஹஸன், ஸைத் பின் அஸ்லம் மற்றும் காலித் பின் மஃதான் ஆகியோரிடமிருந்தும் இதே போன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. இந்த வசனம் டமாஸ்கஸின் ஆறுகளைக் குறிக்கிறது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இக்ரிமா வழியாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். ﴾وَآوَيْنَاهُمَا إِلَى رَبْوَةٍ﴿ எனும் சொற்களைப் பற்றி லைத் பின் அபீ சுலைம், முஜாஹித் வழியாக அறிவிக்கிறார்கள்:\n\r\n\n\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில் புகலிடம் அளித்தோம்) என்பது ஈஸா பின் மர்யம் (அலை) அவர்களும் அவர்களின் தாயாரும் டமாஸ்கஸிலும் அதைச் சுற்றியுள்ள சமவெளிகளிலும் தஞ்சம் புகுந்ததைக் குறிக்கிறது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாக அப்துர்-ரஸ்ஸாக் பதிவு செய்துள்ளார்கள்: ﴾إِلَى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴿\n\r\n\n\r\n(ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில்) \"அது பாலஸ்தீனத்தில் உள்ள ரம்லா ஆகும்.\" இந்த விஷயத்தில் மிகவும் சரியான கருத்து இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அல்-அவ்ஃபீ அறிவித்ததாகும். அவர்கள் கூறினார்கள்: ﴾وَآوَيْنَاهُمَا إِلَى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴿\n\r\n\n\r\n(மேலும் நாம் அவர்களுக்கு ஒரு ரப்வாவில், தாத் கரார் மற்றும் மஈனில் புகலிடம் அளித்தோம்.) \"மஈன் என்பது ஓடும் நீரைக் குறிக்கிறது. அல்லாஹ் பின்வரும் வசனத்தில் குறிப்பிட்ட நதி இதுவேயாகும்: ﴾قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيّاً﴿\n\r\n\n\r\n(உனது இறைவன் உனக்குக் கீழே ஒரு நீரோடையை ஏற்படுத்தியுள்ளான்.)\" 19:24 அத்-தஹ்ஹாக் மற்றும் கத்தாதா ஆகியோர் கூறினார்கள்: ﴾إِلَى رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴿\n\r\n\n\r\n(உயரமான, தங்குவதற்கும் பாதுகாப்புக்கும் உகந்த, ஓடும் நீரோடைகளைக் கொண்ட ஓர் இடம்) என்பது ஜெருசலேமைக் குறிக்கிறது. இதுவே - அல்லாஹ் மிக அறிந்தவன் - மிகவும் தெளிவான கருத்தாகும். ஏனெனில் இது மற்றொரு வசனத்தில் குறிப்பிடப்பட்டுள்ளது. அதாவது: ﴾فَحَمَلَتْهُ فَانتَبَذَتْ بِهِ مَكَاناً قَصِيّاً﴿ (எனவே, அவர் (ஈஸாவை) கருவுற்றார். பின்னர் அவர் கர்ப்பத்துடன் தொலைவான ஒரு இடத்திற்கு ஒதுங்கிச் சென்றார்.) 19:22 குர்ஆனின் ஒரு பகுதி மற்றொரு பகுதியை விளக்குகிறது. எனவே, ஒரு வசனத்திற்கு மற்றொரு வசனத்தின் மூலமே விளக்கம் அளிப்பது மிகவும் பொருத்தமானது. அதற்கு அடுத்ததாக ஸஹீஹான ஹதீஸ்கள், அதன் பிறகு ஏனைய அறிவிப்புகள் மூலம் விளக்கம் அளிக்கலாம்."},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=56\" class=\"link\">23:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:56 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=56\" class=\"link\">23:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:56 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=56\" class=\"link\">23:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:56 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=56\" class=\"link\">23:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:56 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=56\" class=\"link\">23:56</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:56 ஐ பார்க்கவும்"},"56":{"html":"<strong>ஹலாலான உணவை உண்பதற்கும் நல்லறங்கள் செய்வதற்கும் உள்ள கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் அடியார்களுக்கும் தன் தூதர்களுக்கும் (அவர்கள் அனைவர் மீதும் சாந்தி உண்டாவதாக) அனுமதிக்கப்பட்ட (ஹலால்) உணவுகளை உண்ணுமாறும், நற்செயல்கள் புரியுமாறும் கட்டளையிடுகிறான். இது, அனுமதிக்கப்பட்டவற்றை உண்பது ஒருவருக்கு நற்செயல்கள் செய்யத் தூண்டுகோலாக அமையும் என்பதைக் காட்டுகிறது. நபிமார்கள் (அலை) இதனை மிகச் சிறந்த முறையில் கடைப்பிடித்தார்கள்; சொல்லால், செயலால், வழிகாட்டலால் மற்றும் அறிவுரைகளால் அனைத்து வகையான நற்செயல்களையும் செய்தார்கள். மக்கள் சார்பாக அல்லாஹ் அவர்களுக்கு நற்கூலி வழங்குவானாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّبَاتِ</span><br />\r\n(தூய்மையானவற்றிலிருந்து உண்ணுங்கள்) ஸயீத் பின் ஜுபைர் மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"இதன் பொருள் அனுமதிக்கப்பட்டவை (ஹலால்) ஆகும்\" என்று கூறினார்கள். ஸஹீஹ் நூலில் இவ்வாறு இடம்பெற்றுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">رَعَى</span> <span class=\"quran-arabic-font text-success\">الْغَنَم</span>»<br />\r\n(ஆடு மேய்க்காத எந்த ஒரு நபியும் இருந்ததில்லை.) அப்போது அவர்கள், \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَعَمْ،</span> <span class=\"quran-arabic-font text-success\">كُنْتُ</span> <span class=\"quran-arabic-font text-success\">أَرْعَاهَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَرَارِيطَ</span> <span class=\"quran-arabic-font text-success\">لِأَهْلِ</span> <span class=\"quran-arabic-font text-success\">مَكَّةَ</span>»<br />\r\n(ஆம், நான் மக்காவாசிகளுக்காக சில 'கீராத்' கூலிக்காக ஆடு மேய்த்து வந்தேன்.) ஸஹீஹ் நூலில் இவ்வாறு உள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">دَاوُدَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">السَّلَامُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">كَسْبِ</span> <span class=\"quran-arabic-font text-success\">يَدِه</span>»<br />\r\n(நிச்சயமாக தாவூத் (அலை) அவர்கள் தனது கை உழைப்பின் மூலமே உண்டு வந்தார்கள்.) ஸஹீஹ் முஸ்லிம், ஜாமிஉத் திர்மிதீ மற்றும் முஸ்னத் இமாம் அஹ்மத் ஆகிய நூல்களில் இது பதிவு செய்யப்பட்டுள்ளது (இந்த வாசகம் அஹ்மத் நூலில் உள்ளவாறு அமைந்துள்ளது). அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்தார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">طَيِّبٌ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَقْبَلُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">طَيِّبًا،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">أَمَرَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">أَمَرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِين</span>»<br />\r\n(மக்களே! நிச்சயமாக அல்லாஹ் தூய்மையானவன்; அவன் தூய்மையானவற்றையே ஏற்றுக்கொள்கிறான். மேலும் அல்லாஹ் தன் தூதர்களுக்கு எதை ஏவினானோ, அதையே இறைநம்பிக்கையாளர்களுக்கும் (முஃமின்களுக்கும்) ஏவுகிறான் என்று கூறிவிட்டு பின்வரும் வசனங்களை ஓதினார்கள்:)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الرُّسُلُ</span> <span class=\"quran-arabic-font text-success\">كُلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّبَاتِ</span> <span class=\"quran-arabic-font text-success\">وَاعْمَلُواْ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n(தூதர்களே! தூய்மையானவற்றிலிருந்து உண்ணுங்கள், நற்செயல்கள் புரியுங்கள். நிச்சயமாக நீங்கள் செய்பவற்றை நான் நன்கு அறிவேன்.) <a href=\"qurandisp.php?sura=23&ayah=51\" class=\"link\">23:51</a> மற்றும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">كُلُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">رَزَقْنَـكُمْ</span><br />\r\n(இறைநம்பிக்கை கொண்டவர்களே! நாம் உங்களுக்கு வழங்கியவற்றிலிருந்து தூய்மையானவற்றையே உண்ணுங்கள்.) <a href=\"qurandisp.php?sura=2&ayah=172\" class=\"link\">2:172</a>. பிறகு அவர்கள் (ஸல்), ஒரு மனிதர் நீண்ட தூரம் பயணம் செய்கிறார், அவர் தலைமுடி கலைந்து புழுதி படிந்த நிலையில் இருக்கிறார் என்று குறிப்பிட்டார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَمَطْعَمُهُ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ،</span> <span class=\"quran-arabic-font text-success\">وَمَشْرَبُهُ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ،</span> <span class=\"quran-arabic-font text-success\">وَمَلْبَسُهُ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ،</span> <span class=\"quran-arabic-font text-success\">وَغُذِّيَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَرَامِ</span> <span class=\"quran-arabic-font text-success\">يَمُدُّ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">فَأَنَّى</span> <span class=\"quran-arabic-font text-success\">يُسْتَجَابُ</span> <span class=\"quran-arabic-font text-success\">لِذَلِك</span>»<br />\r\n(அவருடைய உணவோ ஹராம் (தடுக்கப்பட்டது), அவருடைய பானமோ ஹராம், அவருடைய ஆடையும் ஹராம்; அவர் ஹராமானவற்றாலேயே ஊட்டம் பெற்றிருக்கிறார். இத்தகைய நிலையில் அவர் வானத்தை நோக்கித் தனது கைகளை ஏந்தி 'என் இறைவா! என் இறைவா!' என்று பிரார்த்திக்கிறார். இவருக்கு எவ்வாறு பதில் அளிக்கப்படும்?) இது 'ஹஸன் கரீப்' என்று திர்மிதீ அவர்கள் கூறியுள்ளார்கள்.<br />\r\n<br />\r\n<strong>அனைத்து நபிமார்களின் மார்க்கமும் தவ்ஹீத்; மேலும் பிரிவினைகளுக்கு எதிரான எச்சரிக்கை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">أُمَّتُكُمْ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span><br />\r\n(நிச்சயமாக உங்கள் இந்த மார்க்கம் ஒரே மார்க்கம்தான்.) இதன் பொருள், 'நபிமார்களே! உங்கள் மார்க்கம் ஒரே மார்க்கம், உங்கள் கூட்டம் ஒரே கூட்டம்; அது எவ்வித இணைதுணையும் இன்றி அல்லாஹ் ஒருவனையே வணங்க வேண்டும் என அழைப்பதாகும்.' அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">فَاتَّقُونِ</span><br />\r\n(மேலும் நானே உங்கள் இறைவன், எனவே எனக்கே அஞ்சுங்கள்.) இதனை நாம் ஏற்கனவே சூரா அல்-அன்பியாவில் விளக்கியுள்ளோம்.<br />\r\n<span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span><br />\r\n(ஒரே சமூகம்) எனும் சொற்றொடர் விளக்கமாக வந்துள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَتَقَطَّعُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْرَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">زُبُراً</span><br />\r\n(ஆனால் அவர்கள் தங்களுக்குள்ளே தங்கள் காரியத்தை (வேதம்) வேதங்களாகப் பிரித்துக் கொண்டார்கள்.) அதாவது, நபிமார்கள் அனுப்பப்பட்ட அந்தச் சமூகத்தினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">حِزْبٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">لَدَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">فَرِحُونَ</span><br />\r\n(ஒவ்வொரு கூட்டத்தாரும் தங்களிடம் இருப்பதைக் கொண்டு மகிழ்ச்சியடைகின்றனர்.) இதன் பொருள், தாங்கள் நேர்வழியில் இருப்பதாக எண்ணிக்கொண்டு, தங்கள் வழிகேட்டிலேயே அவர்கள் மகிழ்ச்சியடைகிறார்கள். அல்லாஹ் அச்சுறுத்தியும் எச்சரித்தும் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَمْرَتِهِمْ</span><br />\r\n(எனவே, அவர்களை அவர்களின் வழிகேட்டிலேயே விட்டுவிடுவீராக)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">حِينٍ</span><br />\r\n(ஒரு காலம் வரை.) இதன் பொருள், அவர்களுக்கான அழிவின் நேரம் வரும் வரை. இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَهِّلِ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">أَمْهِلْهُمْ</span> <span class=\"quran-arabic-font text-success\">رُوَيْداً</span><br />\r\n(ஆகவே, நிராகரிப்பாளர்களுக்கு அவகாசம் அளிப்பீராக; அவர்களுக்குச் சிறிது காலம் அவகாசம் கொடுப்பீராக.) <a href=\"qurandisp.php?sura=86&ayah=17\" class=\"link\">86:17</a> மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُواْ</span> <span class=\"quran-arabic-font text-success\">وَيَتَمَتَّعُواْ</span> <span class=\"quran-arabic-font text-success\">وَيُلْهِهِمُ</span> <span class=\"quran-arabic-font text-success\">الْأَمَلُ</span> <span class=\"quran-arabic-font text-success\">فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n(அவர்களை உண்ணவும், இன்பம் அனுபவிக்கவும் விட்டுவிடுவீராக; (தவறான) கற்பனைகள் அவர்களைப் பராக்காக வைத்திருக்கட்டும். அவர்கள் விரைவில் அறிந்து கொள்வார்கள்!) <a href=\"qurandisp.php?sura=15&ayah=3\" class=\"link\">15:3</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">نُمِدُّهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّالٍ</span> <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> - <span class=\"quran-arabic-font text-success\">نُسَارِعُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَاتِ</span> <span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n(செல்வத்தைக் கொண்டும் பிள்ளைகளைக் கொண்டும் நாம் அவர்களுக்கு எதை நீட்டிக்கிறோமோ அதைக் கொண்டு, அவர்களுக்கு நன்மைகளை விரைந்து வழங்குகிறோம் என்று அவர்கள் எண்ணுகிறார்களா? இல்லை, அவர்கள் அதனை உணர்வதில்லை.) இதன் பொருள்: 'ஏமாற்றப்பட்ட இந்த மக்கள், நாம் அவர்களுக்கு வழங்கும் செல்வமும் பிள்ளைகளும் நம்மிடத்தில் அவர்களுக்குள்ள கண்ணியத்தினாலும் மதிப்பினாலும் வழங்கப்படுகின்றன என்று நினைக்கிறார்களா? இல்லை, அவர்கள் கூறுவது போல் அதுவல்ல விஷயம். அவர்கள் கூறுகிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَكْثَـرُ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلاً</span> <span class=\"quran-arabic-font text-success\">وَأَوْلَـداً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمُعَذَّبِينَ</span><br />\r\n(நாங்கள் செல்வத்திலும் பிள்ளைகளிலும் மிக அதிகமானவர்கள், நாங்கள் தண்டிக்கப்பட மாட்டோம்.) <a href=\"qurandisp.php?sura=34&ayah=35\" class=\"link\">34:35</a> ஆனால் இந்த எண்ணம் தவறானது, அவர்களது நம்பிக்கைகள் வீணாகும். நாம் அவர்களுக்கு அவற்றை வழங்குவதெல்லாம், அவர்கள் (பாவத்தில்) மேலும் மூழ்கவும், அவர்களுக்கு இன்னும் அவகாசம் அளிக்கவுமே ஆகும்.' அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span><br />\r\n(ஆனால் அவர்கள் உணர்வதில்லை.) மற்றோர் இடத்தில் அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تُعْجِبْكَ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِيُعَذِّبَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n(அவர்களுடைய செல்வங்களும் பிள்ளைகளும் உம்மை ஆச்சரியப்படுத்த வேண்டாம்; நிச்சயமாக இவ்வுலக வாழ்வில் அவற்றைக் கொண்டு அவர்களைத் தண்டிக்கவே அல்லாஹ் நாடுகிறான்...) <a href=\"qurandisp.php?sura=9&ayah=55\" class=\"link\">9:55</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">نُمْلِى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِيَزْدَادُواْ</span> <span class=\"quran-arabic-font text-success\">إِثْمَاً</span><br />\r\n(அவர்கள் பாவத்தை அதிகமாக்கிக் கொள்வதற்காகவே நாம் அவர்களுக்கு அவகாசம் அளிக்கிறோம்.) <a href=\"qurandisp.php?sura=3&ayah=178\" class=\"link\">3:178</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَرْنِى</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْحَدِيثِ</span> <span class=\"quran-arabic-font text-success\">سَنَسْتَدْرِجُهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">وَأَمْلَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n(எனவே, இவ்வேதத்தைப் பொய்யாக்குபவர்களுடன் என்னை விட்டுவிடுவீராக. அவர்கள் அறியாத விதத்தில் படிப்படியாக நாம் அவர்களைப் பிடிப்போம். மேலும் அவர்களுக்கு நான் அவகாசம் அளிக்கிறேன்.) <a href=\"qurandisp.php?sura=68&ayah=44\" class=\"link\">68:44</a>-45<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَرْنِى</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">خَلَقْتُ</span> <span class=\"quran-arabic-font text-success\">وَحِيداً</span><br />\r\n(யாரைத் தனிமையாகப் படைத்தேனோ அவனுடன் என்னை விட்டுவிடுவீராக.) அல்லாஹ் கூறுவது வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَنِيداً</span><br />\r\n(பிடிவாதக்காரனாக) <a href=\"qurandisp.php?sura=74&ayah=11\" class=\"link\">74:11</a>-16<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">تُقَرِّبُكُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَنَا</span> <span class=\"quran-arabic-font text-success\">زُلْفَى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span><br />\r\n(உங்களுடைய செல்வங்களோ அல்லது பிள்ளைகளோ உங்களை நம்மிடம் நெருக்கி வைப்பவை அல்ல; ஆனால் யார் ஈமான் கொண்டு நற்செயல்கள் புரிகிறாரோ அவரைத் தவிர...) <a href=\"qurandisp.php?sura=34&ayah=37\" class=\"link\">34:37</a> இது போன்ற பல வசனங்கள் இதே கருத்தைக் கூறுகின்றன. இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவித்தார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">قَسَمَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَخْلَاقَكُمْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">قَسَمَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَرْزَاقَكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">يُعْطِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُعْطِي</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ،</span> <span class=\"quran-arabic-font text-success\">فَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْطَاهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّهُ،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُسْلِمُ</span> <span class=\"quran-arabic-font text-success\">عَبْدٌ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَسْلَمَ</span> <span class=\"quran-arabic-font text-success\">قَلْبُهُ</span> <span class=\"quran-arabic-font text-success\">وَلِسَانُهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَأْمَنَ</span> <span class=\"quran-arabic-font text-success\">جَارُهُ</span> <span class=\"quran-arabic-font text-success\">بَوَائِقَهُ</span>»<br />\r\n(நிச்சயமாக அல்லாஹ் உங்கள் வாழ்வாதாரத்தைப் பங்கிட்டது போலவே உங்கள் நற்குணங்களையும் உங்களுக்கிடையே பங்கிட்டுள்ளான். அல்லாஹ் இவ்வுலகச் செல்வத்தைத் தான் நேசிப்பவர்களுக்கும் நேசிக்காதவர்களுக்கும் வழங்குகிறான்; ஆனால் மார்க்கப் பற்றினை (தீனை) தான் நேசிப்பவர்களுக்கு மட்டுமே வழங்குகிறான். அல்லாஹ் யாருக்கு மார்க்கப் பற்றை வழங்குகிறானோ அவரை அவன் நேசிக்கிறான். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, ஒரு அடியானின் உள்ளமும் நாவும் அடிபணியாத வரை அவர் உண்மையாக அடிபணிய மாட்டார். மேலும் தனது அண்டை வீட்டார் தனது தீங்குகளிலிருந்து பாதுகாப்புப் பெறாத வரை அவர் உண்மையான இறைநம்பிக்கையாளராக முடியாது.) அவர்கள் கேட்டார்கள், 'அல்லாஹ்வின் தூதரே! அவருடைய தீங்கு என்பது என்ன?' அவர்கள் (ஸல்) கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">غَشْمُهُ</span> <span class=\"quran-arabic-font text-success\">وَظُلْمُهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَكْسِبُ</span> <span class=\"quran-arabic-font text-success\">عَبْدٌ</span> <span class=\"quran-arabic-font text-success\">مَالًا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَرَامٍ</span> <span class=\"quran-arabic-font text-success\">فَيُنْفِقَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">فَيُبَارَكَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَتَصَدَّقَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">فَيُقْبَلَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَتْرُكَهُ</span> <span class=\"quran-arabic-font text-success\">خَلْفَ</span> <span class=\"quran-arabic-font text-success\">ظَهْرِهِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">زَادَهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمْحُو</span> <span class=\"quran-arabic-font text-success\">السَّيِّءَ</span> <span class=\"quran-arabic-font text-success\">بِالسَّيِّءِ</span> <span class=\"quran-arabic-font text-success\">وَلَكِنْ</span> <span class=\"quran-arabic-font text-success\">يَمْحُو</span> <span class=\"quran-arabic-font text-success\">السَّيِّءَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَسَنِ،</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْخَبِيثَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمْحُو</span> <span class=\"quran-arabic-font text-success\">الْخَبِيث</span>»<br />\r\n('அவருடைய அக்கிரமமும் அநீதியும் ஆகும். ஹராமான முறையில் செல்வத்தைச் சம்பாதித்து, அதிலிருந்து செலவு செய்யும் எவருக்கும் அதில் பரக்கத் (அருள்வளம்) அளிக்கப்பட மாட்டாது; அதிலிருந்து அவர் தர்மம் செய்தாலும் அது அவரிடமிருந்து ஏற்றுக் கொள்ளப்பட மாட்டாது; அவர் அதனைத் தனக்குப் பின் விட்டுச் சென்றால், அது அவரை நரகத்திற்கு இட்டுச் செல்லும் வழித்துணையாகவே அமையும். நிச்சயமாக அல்லாஹ் ஒரு தீமையை மற்றொரு தீமையைக் கொண்டு துடைப்பதில்லை; மாறாக, தீமைகளை நன்மையைக் கொண்டே துடைக்கிறான். ஏனெனில் அசுத்தத்தைக் கொண்டு அசுத்தத்தைத் துடைக்க முடியாது.')<br />\r\n<br />\r\n<strong>இறைநம்பிக்கையாளர்களின் நற்பண்புகள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّشْفِقُونَ</span> - <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهِمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n(நிச்சயமாக எவர்கள் தங்கள் இறைவனின் அச்சத்தால் நடுங்குகிறார்களோ - இன்னும் எவர்கள் தங்கள் இறைவனின் வசனங்களை நம்புகிறார்களோ)<br />\r\n<br />","text":"ஹலாலான உணவை உண்பதற்கும் நல்லறங்கள் செய்வதற்கும் உள்ள கட்டளை\n\r\n\n\r\nஅல்லாஹ் தன் அடியார்களுக்கும் தன் தூதர்களுக்கும் (அவர்கள் அனைவர் மீதும் சாந்தி உண்டாவதாக) அனுமதிக்கப்பட்ட (ஹலால்) உணவுகளை உண்ணுமாறும், நற்செயல்கள் புரியுமாறும் கட்டளையிடுகிறான். இது, அனுமதிக்கப்பட்டவற்றை உண்பது ஒருவருக்கு நற்செயல்கள் செய்யத் தூண்டுகோலாக அமையும் என்பதைக் காட்டுகிறது. நபிமார்கள் (அலை) இதனை மிகச் சிறந்த முறையில் கடைப்பிடித்தார்கள்; சொல்லால், செயலால், வழிகாட்டலால் மற்றும் அறிவுரைகளால் அனைத்து வகையான நற்செயல்களையும் செய்தார்கள். மக்கள் சார்பாக அல்லாஹ் அவர்களுக்கு நற்கூலி வழங்குவானாக.\n\r\n\n\r\nكُلُواْ مِنَ الطَّيِّبَاتِ\n\r\n(தூய்மையானவற்றிலிருந்து உண்ணுங்கள்) ஸயீத் பின் ஜுபைர் மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"இதன் பொருள் அனுமதிக்கப்பட்டவை (ஹலால்) ஆகும்\" என்று கூறினார்கள். ஸஹீஹ் நூலில் இவ்வாறு இடம்பெற்றுள்ளது:\n\r\n\n\r\n«وَمَا مِنْ نَبِيٍّ إِلَّا رَعَى الْغَنَم»\n\r\n(ஆடு மேய்க்காத எந்த ஒரு நபியும் இருந்ததில்லை.) அப்போது அவர்கள், \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«نَعَمْ، كُنْتُ أَرْعَاهَا عَلَى قَرَارِيطَ لِأَهْلِ مَكَّةَ»\n\r\n(ஆம், நான் மக்காவாசிகளுக்காக சில 'கீராத்' கூலிக்காக ஆடு மேய்த்து வந்தேன்.) ஸஹீஹ் நூலில் இவ்வாறு உள்ளது:\n\r\n\n\r\n«إِنَّ دَاوُدَ عَلَيْهِ السَّلَامُ كَانَ يَأْكُلُ مِنْ كَسْبِ يَدِه»\n\r\n(நிச்சயமாக தாவூத் (அலை) அவர்கள் தனது கை உழைப்பின் மூலமே உண்டு வந்தார்கள்.) ஸஹீஹ் முஸ்லிம், ஜாமிஉத் திர்மிதீ மற்றும் முஸ்னத் இமாம் அஹ்மத் ஆகிய நூல்களில் இது பதிவு செய்யப்பட்டுள்ளது (இந்த வாசகம் அஹ்மத் நூலில் உள்ளவாறு அமைந்துள்ளது). அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்தார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا أَيُّهَا النَّاسُ إِنَّ اللهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِين»\n\r\n(மக்களே! நிச்சயமாக அல்லாஹ் தூய்மையானவன்; அவன் தூய்மையானவற்றையே ஏற்றுக்கொள்கிறான். மேலும் அல்லாஹ் தன் தூதர்களுக்கு எதை ஏவினானோ, அதையே இறைநம்பிக்கையாளர்களுக்கும் (முஃமின்களுக்கும்) ஏவுகிறான் என்று கூறிவிட்டு பின்வரும் வசனங்களை ஓதினார்கள்:)\n\r\n\n\r\nيَا أَيُّهَا الرُّسُلُ كُلُواْ مِنَ الطَّيِّبَاتِ وَاعْمَلُواْ صَـلِحاً إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ\n\r\n(தூதர்களே! தூய்மையானவற்றிலிருந்து உண்ணுங்கள், நற்செயல்கள் புரியுங்கள். நிச்சயமாக நீங்கள் செய்பவற்றை நான் நன்கு அறிவேன்.) 23:51 மற்றும்\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَاتِ مَا رَزَقْنَـكُمْ\n\r\n(இறைநம்பிக்கை கொண்டவர்களே! நாம் உங்களுக்கு வழங்கியவற்றிலிருந்து தூய்மையானவற்றையே உண்ணுங்கள்.) 2:172. பிறகு அவர்கள் (ஸல்), ஒரு மனிதர் நீண்ட தூரம் பயணம் செய்கிறார், அவர் தலைமுடி கலைந்து புழுதி படிந்த நிலையில் இருக்கிறார் என்று குறிப்பிட்டார்கள்,\n\r\n\n\r\n«وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِّيَ بِالْحَرَامِ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ: يَا رَبِّ يَا رَبِّ فَأَنَّى يُسْتَجَابُ لِذَلِك»\n\r\n(அவருடைய உணவோ ஹராம் (தடுக்கப்பட்டது), அவருடைய பானமோ ஹராம், அவருடைய ஆடையும் ஹராம்; அவர் ஹராமானவற்றாலேயே ஊட்டம் பெற்றிருக்கிறார். இத்தகைய நிலையில் அவர் வானத்தை நோக்கித் தனது கைகளை ஏந்தி 'என் இறைவா! என் இறைவா!' என்று பிரார்த்திக்கிறார். இவருக்கு எவ்வாறு பதில் அளிக்கப்படும்?) இது 'ஹஸன் கரீப்' என்று திர்மிதீ அவர்கள் கூறியுள்ளார்கள்.\n\r\n\n\r\nஅனைத்து நபிமார்களின் மார்க்கமும் தவ்ஹீத்; மேலும் பிரிவினைகளுக்கு எதிரான எச்சரிக்கை\n\r\n\n\r\nوَإِنَّ هَـذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً\n\r\n(நிச்சயமாக உங்கள் இந்த மார்க்கம் ஒரே மார்க்கம்தான்.) இதன் பொருள், 'நபிமார்களே! உங்கள் மார்க்கம் ஒரே மார்க்கம், உங்கள் கூட்டம் ஒரே கூட்டம்; அது எவ்வித இணைதுணையும் இன்றி அல்லாஹ் ஒருவனையே வணங்க வேண்டும் என அழைப்பதாகும்.' அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَأَنَاْ رَبُّكُمْ فَاتَّقُونِ\n\r\n(மேலும் நானே உங்கள் இறைவன், எனவே எனக்கே அஞ்சுங்கள்.) இதனை நாம் ஏற்கனவே சூரா அல்-அன்பியாவில் விளக்கியுள்ளோம்.\n\r\nأُمَّةً وَاحِدَةً\n\r\n(ஒரே சமூகம்) எனும் சொற்றொடர் விளக்கமாக வந்துள்ளது.\n\r\n\n\r\nفَتَقَطَّعُواْ أَمْرَهُمْ بَيْنَهُمْ زُبُراً\n\r\n(ஆனால் அவர்கள் தங்களுக்குள்ளே தங்கள் காரியத்தை (வேதம்) வேதங்களாகப் பிரித்துக் கொண்டார்கள்.) அதாவது, நபிமார்கள் அனுப்பப்பட்ட அந்தச் சமூகத்தினர்.\n\r\n\n\r\nكُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ\n\r\n(ஒவ்வொரு கூட்டத்தாரும் தங்களிடம் இருப்பதைக் கொண்டு மகிழ்ச்சியடைகின்றனர்.) இதன் பொருள், தாங்கள் நேர்வழியில் இருப்பதாக எண்ணிக்கொண்டு, தங்கள் வழிகேட்டிலேயே அவர்கள் மகிழ்ச்சியடைகிறார்கள். அல்லாஹ் அச்சுறுத்தியும் எச்சரித்தும் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nفَذَرْهُمْ فِى غَمْرَتِهِمْ\n\r\n(எனவே, அவர்களை அவர்களின் வழிகேட்டிலேயே விட்டுவிடுவீராக)\n\r\n\n\r\nحَتَّى حِينٍ\n\r\n(ஒரு காலம் வரை.) இதன் பொருள், அவர்களுக்கான அழிவின் நேரம் வரும் வரை. இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nفَمَهِّلِ الْكَـفِرِينَ أَمْهِلْهُمْ رُوَيْداً\n\r\n(ஆகவே, நிராகரிப்பாளர்களுக்கு அவகாசம் அளிப்பீராக; அவர்களுக்குச் சிறிது காலம் அவகாசம் கொடுப்பீராக.) 86:17 மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nذَرْهُمْ يَأْكُلُواْ وَيَتَمَتَّعُواْ وَيُلْهِهِمُ الْأَمَلُ فَسَوْفَ يَعْلَمُونَ\n\r\n(அவர்களை உண்ணவும், இன்பம் அனுபவிக்கவும் விட்டுவிடுவீராக; (தவறான) கற்பனைகள் அவர்களைப் பராக்காக வைத்திருக்கட்டும். அவர்கள் விரைவில் அறிந்து கொள்வார்கள்!) 15:3\n\r\n\n\r\nأَيَحْسَبُونَ أَنَّمَا نُمِدُّهُمْ بِهِ مِن مَّالٍ وَبَنِينَ - نُسَارِعُ لَهُمْ فِى الْخَيْرَاتِ بَل لاَّ يَشْعُرُونَ\n\r\n(செல்வத்தைக் கொண்டும் பிள்ளைகளைக் கொண்டும் நாம் அவர்களுக்கு எதை நீட்டிக்கிறோமோ அதைக் கொண்டு, அவர்களுக்கு நன்மைகளை விரைந்து வழங்குகிறோம் என்று அவர்கள் எண்ணுகிறார்களா? இல்லை, அவர்கள் அதனை உணர்வதில்லை.) இதன் பொருள்: 'ஏமாற்றப்பட்ட இந்த மக்கள், நாம் அவர்களுக்கு வழங்கும் செல்வமும் பிள்ளைகளும் நம்மிடத்தில் அவர்களுக்குள்ள கண்ணியத்தினாலும் மதிப்பினாலும் வழங்கப்படுகின்றன என்று நினைக்கிறார்களா? இல்லை, அவர்கள் கூறுவது போல் அதுவல்ல விஷயம். அவர்கள் கூறுகிறார்கள்:\n\r\n\n\r\nنَحْنُ أَكْثَـرُ أَمْوَلاً وَأَوْلَـداً وَمَا نَحْنُ بِمُعَذَّبِينَ\n\r\n(நாங்கள் செல்வத்திலும் பிள்ளைகளிலும் மிக அதிகமானவர்கள், நாங்கள் தண்டிக்கப்பட மாட்டோம்.) 34:35 ஆனால் இந்த எண்ணம் தவறானது, அவர்களது நம்பிக்கைகள் வீணாகும். நாம் அவர்களுக்கு அவற்றை வழங்குவதெல்லாம், அவர்கள் (பாவத்தில்) மேலும் மூழ்கவும், அவர்களுக்கு இன்னும் அவகாசம் அளிக்கவுமே ஆகும்.' அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبَل لاَّ يَشْعُرُونَ\n\r\n(ஆனால் அவர்கள் உணர்வதில்லை.) மற்றோர் இடத்தில் அவன் கூறுவது போல:\n\r\n\n\r\nفَلاَ تُعْجِبْكَ أَمْوَلُهُمْ وَلاَ أَوْلَـدُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُمْ بِهَا فِي الْحَيَوةِ الدُّنْيَا\n\r\n(அவர்களுடைய செல்வங்களும் பிள்ளைகளும் உம்மை ஆச்சரியப்படுத்த வேண்டாம்; நிச்சயமாக இவ்வுலக வாழ்வில் அவற்றைக் கொண்டு அவர்களைத் தண்டிக்கவே அல்லாஹ் நாடுகிறான்...) 9:55\n\r\n\n\r\nإِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُواْ إِثْمَاً\n\r\n(அவர்கள் பாவத்தை அதிகமாக்கிக் கொள்வதற்காகவே நாம் அவர்களுக்கு அவகாசம் அளிக்கிறோம்.) 3:178.\n\r\n\n\r\nفَذَرْنِى وَمَن يُكَذِّبُ بِهَـذَا الْحَدِيثِ سَنَسْتَدْرِجُهُمْ مِّنْ حَيْثُ لاَ يَعْلَمُونَ وَأَمْلَى لَهُمْ\n\r\n(எனவே, இவ்வேதத்தைப் பொய்யாக்குபவர்களுடன் என்னை விட்டுவிடுவீராக. அவர்கள் அறியாத விதத்தில் படிப்படியாக நாம் அவர்களைப் பிடிப்போம். மேலும் அவர்களுக்கு நான் அவகாசம் அளிக்கிறேன்.) 68:44-45\n\r\n\n\r\nذَرْنِى وَمَنْ خَلَقْتُ وَحِيداً\n\r\n(யாரைத் தனிமையாகப் படைத்தேனோ அவனுடன் என்னை விட்டுவிடுவீராக.) அல்லாஹ் கூறுவது வரை:\n\r\n\n\r\nعَنِيداً\n\r\n(பிடிவாதக்காரனாக) 74:11-16\n\r\n\n\r\nوَمَآ أَمْوَلُكُمْ وَلاَ أَوْلَـدُكُمْ بِالَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَى إِلاَّ مَنْ ءَامَنَ وَعَمِلَ صَـلِحاً\n\r\n(உங்களுடைய செல்வங்களோ அல்லது பிள்ளைகளோ உங்களை நம்மிடம் நெருக்கி வைப்பவை அல்ல; ஆனால் யார் ஈமான் கொண்டு நற்செயல்கள் புரிகிறாரோ அவரைத் தவிர...) 34:37 இது போன்ற பல வசனங்கள் இதே கருத்தைக் கூறுகின்றன. இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவித்தார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ قَسَمَ بَيْنَكُمْ أَخْلَاقَكُمْ كَمَا قَسَمَ بَيْنَكُمْ أَرْزَاقَكُمْ، وَإِنَّ اللهَ يُعْطِي الدُّنْيَا مَنْ يُحِبُّ وَمَنْ لَا يُحِبُّ، وَلَا يُعْطِي الدِّينَ إِلَّا لِمَنْ أَحَبَّ، فَمَنْ أَعْطَاهُ اللهُ الدِّينَ فَقَدْ أَحَبَّهُ، وَالَّذِي نَفْسِي بِيَدِهِ لَا يُسْلِمُ عَبْدٌ حَتَّى يَسْلَمَ قَلْبُهُ وَلِسَانُهُ، وَلَا يُؤْمِنُ حَتَّى يَأْمَنَ جَارُهُ بَوَائِقَهُ»\n\r\n(நிச்சயமாக அல்லாஹ் உங்கள் வாழ்வாதாரத்தைப் பங்கிட்டது போலவே உங்கள் நற்குணங்களையும் உங்களுக்கிடையே பங்கிட்டுள்ளான். அல்லாஹ் இவ்வுலகச் செல்வத்தைத் தான் நேசிப்பவர்களுக்கும் நேசிக்காதவர்களுக்கும் வழங்குகிறான்; ஆனால் மார்க்கப் பற்றினை (தீனை) தான் நேசிப்பவர்களுக்கு மட்டுமே வழங்குகிறான். அல்லாஹ் யாருக்கு மார்க்கப் பற்றை வழங்குகிறானோ அவரை அவன் நேசிக்கிறான். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, ஒரு அடியானின் உள்ளமும் நாவும் அடிபணியாத வரை அவர் உண்மையாக அடிபணிய மாட்டார். மேலும் தனது அண்டை வீட்டார் தனது தீங்குகளிலிருந்து பாதுகாப்புப் பெறாத வரை அவர் உண்மையான இறைநம்பிக்கையாளராக முடியாது.) அவர்கள் கேட்டார்கள், 'அல்லாஹ்வின் தூதரே! அவருடைய தீங்கு என்பது என்ன?' அவர்கள் (ஸல்) கூறினார்கள்,\n\r\n\n\r\n«غَشْمُهُ وَظُلْمُهُ، وَلَا يَكْسِبُ عَبْدٌ مَالًا مِنْ حَرَامٍ فَيُنْفِقَ مِنْهُ فَيُبَارَكَ لَهُ فِيهِ، وَلَا يَتَصَدَّقَ بِهِ فَيُقْبَلَ مِنْهُ، وَلَا يَتْرُكَهُ خَلْفَ ظَهْرِهِ إِلَّا كَانَ زَادَهُ إِلَى النَّارِ، إِنَّ اللهَ لَا يَمْحُو السَّيِّءَ بِالسَّيِّءِ وَلَكِنْ يَمْحُو السَّيِّءَ بِالْحَسَنِ، إِنَّ الْخَبِيثَ لَا يَمْحُو الْخَبِيث»\n\r\n('அவருடைய அக்கிரமமும் அநீதியும் ஆகும். ஹராமான முறையில் செல்வத்தைச் சம்பாதித்து, அதிலிருந்து செலவு செய்யும் எவருக்கும் அதில் பரக்கத் (அருள்வளம்) அளிக்கப்பட மாட்டாது; அதிலிருந்து அவர் தர்மம் செய்தாலும் அது அவரிடமிருந்து ஏற்றுக் கொள்ளப்பட மாட்டாது; அவர் அதனைத் தனக்குப் பின் விட்டுச் சென்றால், அது அவரை நரகத்திற்கு இட்டுச் செல்லும் வழித்துணையாகவே அமையும். நிச்சயமாக அல்லாஹ் ஒரு தீமையை மற்றொரு தீமையைக் கொண்டு துடைப்பதில்லை; மாறாக, தீமைகளை நன்மையைக் கொண்டே துடைக்கிறான். ஏனெனில் அசுத்தத்தைக் கொண்டு அசுத்தத்தைத் துடைக்க முடியாது.')\n\r\n\n\r\nஇறைநம்பிக்கையாளர்களின் நற்பண்புகள்\n\r\n\n\r\nإِنَّ الَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِمْ مُّشْفِقُونَ - وَالَّذِينَ هُم بِآيَاتِ رَبَّهِمْ يُؤْمِنُونَ\n\r\n(நிச்சயமாக எவர்கள் தங்கள் இறைவனின் அச்சத்தால் நடுங்குகிறார்களோ - இன்னும் எவர்கள் தங்கள் இறைவனின் வசனங்களை நம்புகிறார்களோ)"},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=61\" class=\"link\">23:61</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:61 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=61\" class=\"link\">23:61</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:61 ஐ பார்க்கவும்"},"59":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=61\" class=\"link\">23:61</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:61 ஐ பார்க்கவும்"},"60":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=61\" class=\"link\">23:61</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:61 ஐ பார்க்கவும்"},"61":{"html":"<strong>நற்செயல் புரிவோரின் பண்புகள்</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّشْفِقُونَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, எவர்கள் தங்கள் இறைவனின் அச்சத்தால் நடுங்குகிறார்களோ;) இதன் பொருள், அவர்கள் இஹ்ஸான் எனும் சிறந்த நிலையை அடைந்து, ஈமான் கொண்டு நற்செயல்கள் புரிந்தாலும், அவர்கள் அல்லாஹ்வைக் குறித்தும், அவனது மறைவான திட்டங்களைக் குறித்தும் இன்னும் அச்சத்துடனேயே இருக்கிறார்கள். அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"ஒரு முஃமின் (இறைநம்பிக்கையாளர்) இஹ்ஸானையும் அச்சத்தையும் ஒன்றிணைக்கிறார்; ஆனால் ஒரு காஃபிரோ (நிராகரிப்பாளர்) தீய செயல்களையும் (தண்டனை வராது என்ற) பாதுகாப்பு உணர்வையும் ஒன்றிணைக்கிறான்.\"<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهِمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், எவர்கள் தங்கள் இறைவனின் வசனங்களை (அத்தாட்சிகளை) நம்புகிறார்களோ;) இதன் பொருள், அவர்கள் அவனது பிரபஞ்ச ரீதியான அத்தாட்சிகளையும் மார்க்க சட்டங்களையும் நம்புகிறார்கள். மர்யம் (அலை) அவர்களைப் பற்றி அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَصَدَّقَتْ</span> <span class=\"quran-arabic-font text-success\">بِكَلِمَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهَا</span> <span class=\"quran-arabic-font text-success\">وَكُتُبِهِ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அவர் தனது இறைவனின் வார்த்தைகளையும் அவனது வேதங்களையும் உண்மையென நம்பினார்) <a href=\"qurandisp.php?sura=66&ayah=12\" class=\"link\">66:12</a>. அதாவது, உலகில் நிகழும் அனைத்தும் அல்லாஹ்வின் நாட்டம் மற்றும் விதியின்படியே நடக்கின்றன என்று அவர் நம்பினார். அல்லாஹ் எதை ஏவினானோ, அதை அவர் விரும்பி ஏற்றுக்கொள்கிறார்; எதைத் தடுத்தானோ, அதை அவர் வெறுத்து நிராகரிக்கிறார்; அவன் சொன்ன செய்திகள் அனைத்தும் உண்மையானவை என்று மர்யம் (அலை) நம்பினார். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِرَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், எவர்கள் தங்கள் இறைவனுக்கு எவரையும் இணையாக்க மாட்டார்களோ;) இதன் பொருள், அவர்கள் அல்லாஹ்வைத் தவிர வேறு எவரையும் அல்லது எதனையும் வணங்கமாட்டார்கள்; மாறாக, அவனை மட்டுமே வணங்குவார்கள். அல்லாஹ்வைத் தவிர வேறு இறைவன் இல்லை என்பதையும், அவன் ஒருவன், அவன் தேவையற்றவன், அவனுக்கு மனைவியோ குழந்தைகளோ இல்லை, அவனுக்கு நிகராகவோ சமமாகவோ எவரும் இல்லை என்பதையும் அவர்கள் உறுதியாக அறிவார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُؤْتُونَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">ءاتَواْ</span> <span class=\"quran-arabic-font text-success\">وَّقُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجِلَةٌ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">رَجِعُونَ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">يُسَارِعُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَاتِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">سَابِقُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், தாங்கள் கொடுப்பவற்றை, நிச்சயமாகத் தங்கள் இறைவனிடம் திரும்பிச் செல்ல வேண்டியவர்கள் என்ற அச்சத்துடன் கூடிய இதயங்களுடன் எவர்கள் கொடுக்கிறார்களோ (அவர்கள்);) (இவர்களே நற்செயல்களில் விரைந்து செல்பவர்கள்; மேலும் அவர்கள் அவற்றை அடைவதில் முந்திக்கொள்கின்றனர்.) இதன் பொருள், அவர்கள் தர்மங்கள் செய்யும் போது, அவற்றில் ஏதேனும் குறைகள் இருந்தாலோ அல்லது அதற்குரிய நிபந்தனைகள் பூர்த்தியாகாமல் இருந்தாலோ, அவை ஏற்றுக்கொள்ளப்படாமல் போய்விடுமோ என்று அஞ்சுகிறார்கள். இது அச்சம் மற்றும் மிகுந்த எச்சரிக்கையுடன் தொடர்புடையதாகும். இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பின்வருமாறு பதிவு செய்துள்ளார்கள்: நான் கேட்டேன்: \"அல்லாஹ்வின் தூதரே (ஸல்)!<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُؤْتُونَ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">ءاتَواْ</span> <span class=\"quran-arabic-font text-success\">وَّقُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجِلَةٌ</span><br />\r\n<br />\r\n<br />\r\n(தாங்கள் கொடுப்பவற்றை, அஞ்சிய உள்ளங்களுடன் எவர்கள் கொடுக்கிறார்களோ...) இவர்கள் அல்லாஹ்வுக்குப் பயந்து கொண்டே திருடுபவர்கள், விபச்சாரம் செய்பவர்கள் மற்றும் மது அருந்துபவர்களா?\" அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بِنْتَ</span> <span class=\"quran-arabic-font text-success\">أَبِي</span> <span class=\"quran-arabic-font text-success\">بَكْرٍ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بِنْتَ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقِ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يُصَلِّي</span> <span class=\"quran-arabic-font text-success\">وَيَصُومُ</span> <span class=\"quran-arabic-font text-success\">وَيَتَصَدَّقُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَخَافُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَل</span>»<br />\r\n<br />\r\n<br />\r\n\"இல்லை, அபூபக்ரின் மகளே! ஸித்தீக்கின் மகளே! மாறாக, அவர்கள் தொழுகை, நோன்பு மற்றும் தர்மம் போன்ற நற்செயல்களைச் செய்தும், அவை (தங்களிடமிருந்து) ஏற்றுக் கொள்ளப்படாமல் போய்விடுமோ என்று அல்லாஹ்வை அஞ்சக்கூடியவர்கள் ஆவார்கள்.\" இதனை அத்-திர்மிதி பதிவு செய்துள்ளார். இப்னு அபி ஹாதிம் அவர்கள் இதே போன்ற ஒரு செய்தியைப் பதிவு செய்துள்ளார்கள், அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بِنْتَ</span> <span class=\"quran-arabic-font text-success\">الصِّدِّيقِ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُصَلُّونَ</span> <span class=\"quran-arabic-font text-success\">وَيَصُومُونَ</span> <span class=\"quran-arabic-font text-success\">وَيَتَصَدَّقُونَ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَخَافُونَ</span> <span class=\"quran-arabic-font text-success\">أَلَّا</span> <span class=\"quran-arabic-font text-success\">يُقْبَلَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">يُسَارِعُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَاتِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">سَابِقُونَ</span>»<br />\r\n<br />\r\n<br />\r\n\"இல்லை ஸித்தீக்கின் மகளே! அவர்கள் தொழுது, நோன்பு நோற்று, தர்மம் செய்தும், அது தங்களிடமிருந்து ஏற்றுக்கொள்ளப்படாமல் போய்விடுமோ என்று அஞ்சுகிறார்கள். (இவர்களே நற்செயல்களில் விரைந்து செல்பவர்கள்; மேலும் அவர்கள் அவற்றை அடைவதில் முந்திக்கொள்கின்றனர்.)\" இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஃப் அல்-குரழி மற்றும் அல்-ஹஸன் அல்-பஸரி ஆகியோரும் இவ்வசனத்திற்கு இவ்வாறுதான் விளக்கம் அளித்துள்ளார்கள்.<br />\r\n<br />","text":"நற்செயல் புரிவோரின் பண்புகள்\n\r\n\n\r\n\n\r\nإِنَّ الَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِمْ مُّشْفِقُونَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக, எவர்கள் தங்கள் இறைவனின் அச்சத்தால் நடுங்குகிறார்களோ;) இதன் பொருள், அவர்கள் இஹ்ஸான் எனும் சிறந்த நிலையை அடைந்து, ஈமான் கொண்டு நற்செயல்கள் புரிந்தாலும், அவர்கள் அல்லாஹ்வைக் குறித்தும், அவனது மறைவான திட்டங்களைக் குறித்தும் இன்னும் அச்சத்துடனேயே இருக்கிறார்கள். அல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"ஒரு முஃமின் (இறைநம்பிக்கையாளர்) இஹ்ஸானையும் அச்சத்தையும் ஒன்றிணைக்கிறார்; ஆனால் ஒரு காஃபிரோ (நிராகரிப்பாளர்) தீய செயல்களையும் (தண்டனை வராது என்ற) பாதுகாப்பு உணர்வையும் ஒன்றிணைக்கிறான்.\"\n\r\n\n\r\n\n\r\nوَالَّذِينَ هُم بِآيَاتِ رَبَّهِمْ يُؤْمِنُونَ\n\r\n\n\r\n\n\r\n(மேலும், எவர்கள் தங்கள் இறைவனின் வசனங்களை (அத்தாட்சிகளை) நம்புகிறார்களோ;) இதன் பொருள், அவர்கள் அவனது பிரபஞ்ச ரீதியான அத்தாட்சிகளையும் மார்க்க சட்டங்களையும் நம்புகிறார்கள். மர்யம் (அலை) அவர்களைப் பற்றி அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n\n\r\nوَصَدَّقَتْ بِكَلِمَاتِ رَبَّهَا وَكُتُبِهِ\n\r\n\n\r\n\n\r\n(மேலும், அவர் தனது இறைவனின் வார்த்தைகளையும் அவனது வேதங்களையும் உண்மையென நம்பினார்) 66:12. அதாவது, உலகில் நிகழும் அனைத்தும் அல்லாஹ்வின் நாட்டம் மற்றும் விதியின்படியே நடக்கின்றன என்று அவர் நம்பினார். அல்லாஹ் எதை ஏவினானோ, அதை அவர் விரும்பி ஏற்றுக்கொள்கிறார்; எதைத் தடுத்தானோ, அதை அவர் வெறுத்து நிராகரிக்கிறார்; அவன் சொன்ன செய்திகள் அனைத்தும் உண்மையானவை என்று மர்யம் (அலை) நம்பினார். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n\n\r\nوَالَّذِينَ هُم بِرَبِّهِمْ لاَ يُشْرِكُونَ\n\r\n\n\r\n\n\r\n(மேலும், எவர்கள் தங்கள் இறைவனுக்கு எவரையும் இணையாக்க மாட்டார்களோ;) இதன் பொருள், அவர்கள் அல்லாஹ்வைத் தவிர வேறு எவரையும் அல்லது எதனையும் வணங்கமாட்டார்கள்; மாறாக, அவனை மட்டுமே வணங்குவார்கள். அல்லாஹ்வைத் தவிர வேறு இறைவன் இல்லை என்பதையும், அவன் ஒருவன், அவன் தேவையற்றவன், அவனுக்கு மனைவியோ குழந்தைகளோ இல்லை, அவனுக்கு நிகராகவோ சமமாகவோ எவரும் இல்லை என்பதையும் அவர்கள் உறுதியாக அறிவார்கள்.\n\r\n\n\r\n\n\r\nوَالَّذِينَ يُؤْتُونَ مَآ ءاتَواْ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَى رَبِّهِمْ رَجِعُونَ\n\r\n\n\r\nأُولَئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ\n\r\n\n\r\n\n\r\n(மேலும், தாங்கள் கொடுப்பவற்றை, நிச்சயமாகத் தங்கள் இறைவனிடம் திரும்பிச் செல்ல வேண்டியவர்கள் என்ற அச்சத்துடன் கூடிய இதயங்களுடன் எவர்கள் கொடுக்கிறார்களோ (அவர்கள்);) (இவர்களே நற்செயல்களில் விரைந்து செல்பவர்கள்; மேலும் அவர்கள் அவற்றை அடைவதில் முந்திக்கொள்கின்றனர்.) இதன் பொருள், அவர்கள் தர்மங்கள் செய்யும் போது, அவற்றில் ஏதேனும் குறைகள் இருந்தாலோ அல்லது அதற்குரிய நிபந்தனைகள் பூர்த்தியாகாமல் இருந்தாலோ, அவை ஏற்றுக்கொள்ளப்படாமல் போய்விடுமோ என்று அஞ்சுகிறார்கள். இது அச்சம் மற்றும் மிகுந்த எச்சரிக்கையுடன் தொடர்புடையதாகும். இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்களிடமிருந்து பின்வருமாறு பதிவு செய்துள்ளார்கள்: நான் கேட்டேன்: \"அல்லாஹ்வின் தூதரே (ஸல்)!\n\r\n\n\r\n\n\r\nوَالَّذِينَ يُؤْتُونَ مَآ ءاتَواْ وَّقُلُوبُهُمْ وَجِلَةٌ\n\r\n\n\r\n\n\r\n(தாங்கள் கொடுப்பவற்றை, அஞ்சிய உள்ளங்களுடன் எவர்கள் கொடுக்கிறார்களோ...) இவர்கள் அல்லாஹ்வுக்குப் பயந்து கொண்டே திருடுபவர்கள், விபச்சாரம் செய்பவர்கள் மற்றும் மது அருந்துபவர்களா?\" அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n\n\r\n«لَا، يَا بِنْتَ أَبِي بَكْرٍ يَا بِنْتَ الصِّدِّيقِ، وَلَكِنَّهُ الَّذِي يُصَلِّي وَيَصُومُ وَيَتَصَدَّقُ وَهُوَ يَخَافُ اللهَ عَزَّ وَجَل»\n\r\n\n\r\n\n\r\n\"இல்லை, அபூபக்ரின் மகளே! ஸித்தீக்கின் மகளே! மாறாக, அவர்கள் தொழுகை, நோன்பு மற்றும் தர்மம் போன்ற நற்செயல்களைச் செய்தும், அவை (தங்களிடமிருந்து) ஏற்றுக் கொள்ளப்படாமல் போய்விடுமோ என்று அல்லாஹ்வை அஞ்சக்கூடியவர்கள் ஆவார்கள்.\" இதனை அத்-திர்மிதி பதிவு செய்துள்ளார். இப்னு அபி ஹாதிம் அவர்கள் இதே போன்ற ஒரு செய்தியைப் பதிவு செய்துள்ளார்கள், அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«لَا يَا بِنْتَ الصِّدِّيقِ، وَلَكِنَّهُمُ الَّذِينَ يُصَلُّونَ وَيَصُومُونَ وَيَتَصَدَّقُونَ وَهُمْ يَخَافُونَ أَلَّا يُقْبَلَ مِنْهُمْ:\n\r\n\n\r\nأُولَئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ»\n\r\n\n\r\n\n\r\n\"இல்லை ஸித்தீக்கின் மகளே! அவர்கள் தொழுது, நோன்பு நோற்று, தர்மம் செய்தும், அது தங்களிடமிருந்து ஏற்றுக்கொள்ளப்படாமல் போய்விடுமோ என்று அஞ்சுகிறார்கள். (இவர்களே நற்செயல்களில் விரைந்து செல்பவர்கள்; மேலும் அவர்கள் அவற்றை அடைவதில் முந்திக்கொள்கின்றனர்.)\" இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஃப் அல்-குரழி மற்றும் அல்-ஹஸன் அல்-பஸரி ஆகியோரும் இவ்வசனத்திற்கு இவ்வாறுதான் விளக்கம் அளித்துள்ளார்கள்."},"62":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=67\" class=\"link\">23:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:67 ஐ பார்க்கவும்"},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=67\" class=\"link\">23:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:67 ஐ பார்க்கவும்"},"64":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=67\" class=\"link\">23:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:67 ஐ பார்க்கவும்"},"65":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=67\" class=\"link\">23:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:67 ஐ பார்க்கவும்"},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=67\" class=\"link\">23:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:67 ஐ பார்க்கவும்"},"67":{"html":"<strong>அல்லாஹ்வின் நீதியும் இணைவைப்பாளர்களின் வீண் பேச்சும்</strong><br />\r\n<br />\r\n<br />\r\nதன் அடியார்களுக்கு அல்லாஹ் இழைக்கும் நீதியைப் பற்றி அவன் நமக்குக் கூறுகிறான். எவருக்கும் அவரவர் சக்திக்கு மீறிய எதையும் அவன் கடமையாக்குவதில்லை; அதாவது, எந்த ஓர் ஆத்மாவையும் அதன் வசதிக்கு மேல் அவன் சிரமப்படுத்துவதில்லை. மறுமை நாளில், அவர்களின் செயல்களைப் பற்றி அவன் கணக்குக் கேட்பான். எதையும் விட்டுவிடாமல் ஒரு புத்தகத்தில் அவன் அவற்றைப் பதிவு செய்துள்ளான். அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلَدَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">يَنطِقُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴿</span><br />\r\n<br />\r\n<br />\r\n(உண்மையை எடுத்துரைக்கும் ஒரு பதிவுப் புத்தகம் நம்மிடம் உள்ளது.) அதாவது, செயல்களின் ஏடு. <span class=\"quran-arabic-font text-success\">﴾وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُظْلَمُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் அநீதி இழைக்கப்பட மாட்டார்கள்.) அதாவது, அவர்களின் நற்செயல்களின் பதிவிலிருந்து எதுவும் விடுபடாது. தீய செயல்களைப் பொறுத்தவரை, தன் நம்பிக்கையுள்ள அடியார்களின் பல தவறுகளை அவன் மன்னித்து, கண்டுகொள்ளாமல் விட்டுவிடுவான். பின்னர், குறைஷிகளில் உள்ள நிராகரிப்பாளர்களையும் இணைவைப்பாளர்களையும் கண்டித்து அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَمْرَةٍ﴿</span><br />\r\n<br />\r\n<br />\r\n(இல்லை, அவர்களின் உள்ளங்கள் ஒரு திரையினால் மூடப்பட்டுள்ளன.) அதாவது, கவனக்குறைவு மற்றும் வழிகேட்டின் காரணமாக, <span class=\"quran-arabic-font text-success\">﴾مِّنْ</span> <span class=\"quran-arabic-font text-success\">هَذَا﴿</span><br />\r\n<br />\r\n<br />\r\n(இதிலிருந்து.) அதாவது, அல்லாஹ் தன் தூதருக்கு (ஸல்) அருளிய குர்ஆனிலிருந்து (அவர்கள் விலகி இருக்கிறார்கள்). <span class=\"quran-arabic-font text-success\">﴾وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">عَامِلُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் இதைத் தவிர மற்ற செயல்களையும் செய்கிறார்கள்.) இக்ரிமா (ரஹ்) அவர்கள் வாயிலாக இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிப்பதாவது: <span class=\"quran-arabic-font text-success\">﴾وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுக்கு இன்னும் பல செயல்கள் உள்ளன.) அதாவது, 'ஷிர்க்' (இணைவைத்தல்) போன்ற தீய செயல்கள். <span class=\"quran-arabic-font text-success\">﴾هُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">عَامِلُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவற்றை அவர்கள் செய்கிறார்கள்.) அதாவது, அவர்கள் அதைத் தவிர்க்க முடியாமல் செய்வார்கள். இது முஜாஹித் (ரஹ்), அல்-ஹஸன் (ரஹ்) மற்றும் பிறரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. <br />\r\n<br />\r\n<br />\r\nமற்றவர்கள் இந்த சொற்றொடருக்கு இவ்வாறு பொருள் கூறுகிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">عَامِلُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் இதைத் தவிர மற்ற செயல்களையும் செய்கிறார்கள்.) அவர்கள் தீய செயல்களைச் செய்வார்கள் என்று விதிக்கப்பட்டுள்ளது. தண்டனை பற்றிய அல்லாஹ்வின் வாக்கு அவர்கள் மீது உறுதியாகும்பொருட்டு, அவர்கள் இறப்பதற்கு முன் அவற்றைச் செய்தே தீருவார்கள். இதே போன்ற ஒரு கருத்து முகாதில் பின் ஹய்யான் (ரஹ்), அஸ்-ஸுத்தி (ரஹ்) மற்றும் அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரஹ்) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. இது ஒரு தெளிவான மற்றும் பொருத்தமான பொருளாகும். இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸை நாம் ஏற்கனவே மேற்கோள் காட்டியுள்ளோம்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">غَيْرُهُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلَ</span> <span class=\"quran-arabic-font text-success\">لَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">ذِرَاعٌ،</span> <span class=\"quran-arabic-font text-success\">فَيَسْبِقُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْخُلُهَا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(அவனைத் தவிர வேறு இறைவன் இல்லை. ஒரு மனிதன் சொர்க்கவாசிகளின் செயல்களைச் செய்து கொண்டே வருவான்; சொர்க்கத்திற்கும் அவருக்கும் இடையே ஒரு முழம் தூரமே இருக்கும்போது, விதி அவரை முந்திவிடும். அவர் நரகவாசிகளின் செயல்களைச் செய்வார், அதனால் நரகில் நுழைவார்...) <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">أَخَذْنَا</span> <span class=\"quran-arabic-font text-success\">مُتْرَفِيهِم</span> <span class=\"quran-arabic-font text-success\">بِالْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَجْأَرُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் ஆடம்பர வாழ்க்கை வாழ்பவர்களை நாம் வேதனையால் பிடிக்கும்போது, இதோ, அவர்கள் உரத்த குரலில் உதவி தேடி அலறுகிறார்கள்.) அதாவது, இவ்வுலகில் சுகபோகங்களில் திளைப்போரை அல்லாஹ்வின் தண்டனையும் பழிவாங்கலும் வந்து தாக்கும்போது, <span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَجْأَرُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(இதோ, அவர்கள் உதவி கோரி அலறுகிறார்கள்.) அதாவது, அவர்கள் உதவிக்காகக் கூச்சலிடுவார்கள். இது பின்வரும் வசனங்களைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَذَرْنِى</span> <span class=\"quran-arabic-font text-success\">وَالْمُكَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">النَّعْمَةِ</span> <span class=\"quran-arabic-font text-success\">وَمَهِّلْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> - <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لَدَيْنَآ</span> <span class=\"quran-arabic-font text-success\">أَنكَالاً</span> <span class=\"quran-arabic-font text-success\">وَجَحِيماً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நல்ல வாழ்க்கை வசதிகளைப் பெற்றிருக்கும் அந்தப் பொய்யர்களை (சமாளிப்பதை) என்னிடமே விட்டுவிடு. அவர்களுக்கு சிறிது அவகாசம் கொடு. நிச்சயமாக நம்மிடம் விலங்குகளும், கொழுந்துவிட்டு எரியும் நரக நெருப்பும் உள்ளன.) <a href=\"qurandisp.php?sura=73&ayah=11\" class=\"link\">73:11</a>-12 <span class=\"quran-arabic-font text-success\">﴾كَمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْنٍ</span> <span class=\"quran-arabic-font text-success\">فَنَادَواْ</span> <span class=\"quran-arabic-font text-success\">وَّلاَتَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">مَنَاصٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்களுக்கு முன் எத்தனையோ தலைமுறைகளை நாம் அழித்திருக்கிறோம்! தப்பிக்க வழியில்லாத நேரத்தில் அவர்கள் கூக்குரலிட்டார்கள்.) <a href=\"qurandisp.php?sura=38&ayah=3\" class=\"link\">38:3</a> <span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">تَجْأَرُوا</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكُم</span> <span class=\"quran-arabic-font text-success\">مِّنَّا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُنصَرُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(இன்று அலறாதீர்கள்! நிச்சயமாக நம்மால் உங்களுக்கு உதவி செய்யப்படாது.) அதாவது, உங்களுக்கு நேர்ந்த துயரிலிருந்து யாராலும் உங்களைக் காப்பாற்ற முடியாது. நீங்கள் உரக்கக் கத்தினாலும் சரி, மௌனமாக இருந்தாலும் சரி, தப்பிக்க வழியே இல்லை. தண்டனை வருவது தவிர்க்க முடியாதது. பின்னர் அல்லாஹ் அவர்களின் மிகப்பெரிய பாவங்களைக் குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِي</span> <span class=\"quran-arabic-font text-success\">تُتْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">فَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَعْقَابِكُمْ</span> <span class=\"quran-arabic-font text-success\">تَنكِصُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக என் வசனங்கள் உங்களுக்கு ஓதிக் காட்டப்பட்டன, ஆனால் நீங்கள் உங்கள் குதிகால்களில் பின்வாங்கினீர்கள்.) அதாவது, நீங்கள் சத்தியத்தின் பக்கம் அழைக்கப்பட்டபோது, அதனை மறுத்துத் தலைதெறிக்க ஓடினீர்கள். <span class=\"quran-arabic-font text-success\">﴾ذَلِكُم</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دُعِىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">كَـفَرْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يُشْرَكْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">فَالْحُكْمُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِـىِّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(\"ஏனென்றால், அல்லாஹ் ஒருவன் மட்டுமே அழைக்கப்பட்டபோது நீங்கள் நிராகரித்தீர்கள்; ஆனால் அவனுடன் மற்றவை இணைவைக்கப்பட்டபோது நீங்கள் விசுவாசித்தீர்கள்! எனவே தீர்ப்பு மிக உயர்ந்தவனும், மிகப் பெரியவனுமாகிய அல்லாஹ்வுக்கே உரியது!\") <a href=\"qurandisp.php?sura=40&ayah=12\" class=\"link\">40:12</a> <span class=\"quran-arabic-font text-success\">﴾مُسْتَكْبِرِينَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">سَامِرًا</span> <span class=\"quran-arabic-font text-success\">تَهْجُرُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அகந்தையுடன், இரவு நேரத்தில் அதைப் பற்றித் தீயதாகப் பேசிக் கொண்டிருந்தீர்கள்.) இது குறைஷிகள் தங்களைக் கஃபாவின் பாதுகாவலர்கள் என்று கருதிக்கொண்ட அந்த வீண் பெருமையைக் குறிக்கிறது, ஆனால் உண்மையில் அவர்கள் அதற்குத் தகுதியானவர்கள் அல்ல.<br />\r\n<br />\r\n<br />\r\nஇமாம் அன்-நஸாஈ (ரஹ்) அவர்கள் தனது சுனனில் இந்த வசனத்திற்கான தஃப்ஸீரில் குறிப்பிட்டிருப்பதாவது: சயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"இந்த வசனம் அருளப்பட்டபோதுதான், இரவு நேரங்களில் அமர்ந்து வீணாகப் பேசுவது வெறுக்கப்பட்டது: <span class=\"quran-arabic-font text-success\">﴾مُسْتَكْبِرِينَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">سَامِرًا</span> <span class=\"quran-arabic-font text-success\">تَهْجُرُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அகந்தையுடன், இரவு நேரத்தில் அதைப் பற்றித் தீயதாகப் பேசிக் கொண்டிருந்தீர்கள்.) அவர் மேலும் கூறினார்கள்: \"அவர்கள் கஃபாவைக் குறித்துப் பெருமை பேசிக் கொண்டு, 'நாங்கள் அதன் மக்கள், இரவு முழுதும் விழித்திருந்து பேசிக்கொண்டிருப்போம்' என்று கூறுவார்கள். கஃபாவைச் சுற்றி அவர்கள் வீண் பெருமையுடன் பேசிக்கொண்டிருந்தார்களே தவிர, அதன் புனிதத்தைப் பேணவில்லை; எனவே உண்மையில் அவர்கள் அதனைப் புறக்கணித்தவர்களாகவே இருந்தார்கள்.\" <span class=\"quran-arabic-font text-success\">﴾أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَدَّبَّرُوا</span> <span class=\"quran-arabic-font text-success\">الْقَوْلَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">جَاءَهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتِ</span> <span class=\"quran-arabic-font text-success\">آبَاءَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ﴿</span><br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ்வின் நீதியும் இணைவைப்பாளர்களின் வீண் பேச்சும்\n\r\n\n\r\n\n\r\nதன் அடியார்களுக்கு அல்லாஹ் இழைக்கும் நீதியைப் பற்றி அவன் நமக்குக் கூறுகிறான். எவருக்கும் அவரவர் சக்திக்கு மீறிய எதையும் அவன் கடமையாக்குவதில்லை; அதாவது, எந்த ஓர் ஆத்மாவையும் அதன் வசதிக்கு மேல் அவன் சிரமப்படுத்துவதில்லை. மறுமை நாளில், அவர்களின் செயல்களைப் பற்றி அவன் கணக்குக் கேட்பான். எதையும் விட்டுவிடாமல் ஒரு புத்தகத்தில் அவன் அவற்றைப் பதிவு செய்துள்ளான். அவன் கூறுகிறான்: ﴾وَلَدَيْنَا كِتَابٌ يَنطِقُ بِالْحَقِّ﴿\n\r\n\n\r\n\n\r\n(உண்மையை எடுத்துரைக்கும் ஒரு பதிவுப் புத்தகம் நம்மிடம் உள்ளது.) அதாவது, செயல்களின் ஏடு. ﴾وَهُمْ لاَ يُظْلَمُونَ﴿\n\r\n\n\r\n\n\r\n(அவர்கள் அநீதி இழைக்கப்பட மாட்டார்கள்.) அதாவது, அவர்களின் நற்செயல்களின் பதிவிலிருந்து எதுவும் விடுபடாது. தீய செயல்களைப் பொறுத்தவரை, தன் நம்பிக்கையுள்ள அடியார்களின் பல தவறுகளை அவன் மன்னித்து, கண்டுகொள்ளாமல் விட்டுவிடுவான். பின்னர், குறைஷிகளில் உள்ள நிராகரிப்பாளர்களையும் இணைவைப்பாளர்களையும் கண்டித்து அல்லாஹ் கூறுகிறான்: ﴾بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ﴿\n\r\n\n\r\n\n\r\n(இல்லை, அவர்களின் உள்ளங்கள் ஒரு திரையினால் மூடப்பட்டுள்ளன.) அதாவது, கவனக்குறைவு மற்றும் வழிகேட்டின் காரணமாக, ﴾مِّنْ هَذَا﴿\n\r\n\n\r\n\n\r\n(இதிலிருந்து.) அதாவது, அல்லாஹ் தன் தூதருக்கு (ஸல்) அருளிய குர்ஆனிலிருந்து (அவர்கள் விலகி இருக்கிறார்கள்). ﴾وَلَهُمْ أَعْمَالٌ مِّن دُونِ ذَلِكَ هُمْ لَهَا عَامِلُونَ﴿\n\r\n\n\r\n\n\r\n(அவர்கள் இதைத் தவிர மற்ற செயல்களையும் செய்கிறார்கள்.) இக்ரிமா (ரஹ்) அவர்கள் வாயிலாக இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிப்பதாவது: ﴾وَلَهُمْ أَعْمَالٌ﴿\n\r\n\n\r\n\n\r\n(அவர்களுக்கு இன்னும் பல செயல்கள் உள்ளன.) அதாவது, 'ஷிர்க்' (இணைவைத்தல்) போன்ற தீய செயல்கள். ﴾هُمْ لَهَا عَامِلُونَ﴿\n\r\n\n\r\n\n\r\n(அவற்றை அவர்கள் செய்கிறார்கள்.) அதாவது, அவர்கள் அதைத் தவிர்க்க முடியாமல் செய்வார்கள். இது முஜாஹித் (ரஹ்), அல்-ஹஸன் (ரஹ்) மற்றும் பிறரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது.\n\r\n\n\r\n\n\r\nமற்றவர்கள் இந்த சொற்றொடருக்கு இவ்வாறு பொருள் கூறுகிறார்கள்: ﴾وَلَهُمْ أَعْمَالٌ مِّن دُونِ ذَلِكَ هُمْ لَهَا عَامِلُونَ﴿\n\r\n\n\r\n\n\r\n(அவர்கள் இதைத் தவிர மற்ற செயல்களையும் செய்கிறார்கள்.) அவர்கள் தீய செயல்களைச் செய்வார்கள் என்று விதிக்கப்பட்டுள்ளது. தண்டனை பற்றிய அல்லாஹ்வின் வாக்கு அவர்கள் மீது உறுதியாகும்பொருட்டு, அவர்கள் இறப்பதற்கு முன் அவற்றைச் செய்தே தீருவார்கள். இதே போன்ற ஒரு கருத்து முகாதில் பின் ஹய்யான் (ரஹ்), அஸ்-ஸுத்தி (ரஹ்) மற்றும் அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரஹ்) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. இது ஒரு தெளிவான மற்றும் பொருத்தமான பொருளாகும். இப்னு மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸை நாம் ஏற்கனவே மேற்கோள் காட்டியுள்ளோம்: ﴾«فَوَ الَّذِي لَا إِلهَ غَيْرُهُ إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا»﴿\n\r\n\n\r\n\n\r\n(அவனைத் தவிர வேறு இறைவன் இல்லை. ஒரு மனிதன் சொர்க்கவாசிகளின் செயல்களைச் செய்து கொண்டே வருவான்; சொர்க்கத்திற்கும் அவருக்கும் இடையே ஒரு முழம் தூரமே இருக்கும்போது, விதி அவரை முந்திவிடும். அவர் நரகவாசிகளின் செயல்களைச் செய்வார், அதனால் நரகில் நுழைவார்...) ﴾حَتَّى إِذَا أَخَذْنَا مُتْرَفِيهِم بِالْعَذَابِ إِذَا هُمْ يَجْأَرُونَ﴿\n\r\n\n\r\n\n\r\n(அவர்களில் ஆடம்பர வாழ்க்கை வாழ்பவர்களை நாம் வேதனையால் பிடிக்கும்போது, இதோ, அவர்கள் உரத்த குரலில் உதவி தேடி அலறுகிறார்கள்.) அதாவது, இவ்வுலகில் சுகபோகங்களில் திளைப்போரை அல்லாஹ்வின் தண்டனையும் பழிவாங்கலும் வந்து தாக்கும்போது, ﴾إِذَا هُمْ يَجْأَرُونَ﴿\n\r\n\n\r\n\n\r\n(இதோ, அவர்கள் உதவி கோரி அலறுகிறார்கள்.) அதாவது, அவர்கள் உதவிக்காகக் கூச்சலிடுவார்கள். இது பின்வரும் வசனங்களைப் போன்றது: ﴾وَذَرْنِى وَالْمُكَذِّبِينَ أُوْلِى النَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاً - إِنَّ لَدَيْنَآ أَنكَالاً وَجَحِيماً ﴿\n\r\n\n\r\n\n\r\n(நல்ல வாழ்க்கை வசதிகளைப் பெற்றிருக்கும் அந்தப் பொய்யர்களை (சமாளிப்பதை) என்னிடமே விட்டுவிடு. அவர்களுக்கு சிறிது அவகாசம் கொடு. நிச்சயமாக நம்மிடம் விலங்குகளும், கொழுந்துவிட்டு எரியும் நரக நெருப்பும் உள்ளன.) 73:11-12 ﴾كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَواْ وَّلاَتَ حِينَ مَنَاصٍ ﴿\n\r\n\n\r\n\n\r\n(அவர்களுக்கு முன் எத்தனையோ தலைமுறைகளை நாம் அழித்திருக்கிறோம்! தப்பிக்க வழியில்லாத நேரத்தில் அவர்கள் கூக்குரலிட்டார்கள்.) 38:3 ﴾لَا تَجْأَرُوا الْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ﴿\n\r\n\n\r\n\n\r\n(இன்று அலறாதீர்கள்! நிச்சயமாக நம்மால் உங்களுக்கு உதவி செய்யப்படாது.) அதாவது, உங்களுக்கு நேர்ந்த துயரிலிருந்து யாராலும் உங்களைக் காப்பாற்ற முடியாது. நீங்கள் உரக்கக் கத்தினாலும் சரி, மௌனமாக இருந்தாலும் சரி, தப்பிக்க வழியே இல்லை. தண்டனை வருவது தவிர்க்க முடியாதது. பின்னர் அல்லாஹ் அவர்களின் மிகப்பெரிய பாவங்களைக் குறிப்பிடுகிறான்: ﴾قَدْ كَانَتْ آيَاتِي تُتْلَى عَلَيْكُمْ فَكُنتُمْ عَلَى أَعْقَابِكُمْ تَنكِصُونَ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக என் வசனங்கள் உங்களுக்கு ஓதிக் காட்டப்பட்டன, ஆனால் நீங்கள் உங்கள் குதிகால்களில் பின்வாங்கினீர்கள்.) அதாவது, நீங்கள் சத்தியத்தின் பக்கம் அழைக்கப்பட்டபோது, அதனை மறுத்துத் தலைதெறிக்க ஓடினீர்கள். ﴾ذَلِكُم بِأَنَّهُ إِذَا دُعِىَ اللَّهُ وَحْدَهُ كَـفَرْتُمْ وَإِن يُشْرَكْ بِهِ تُؤْمِنُواْ فَالْحُكْمُ للَّهِ الْعَلِـىِّ الْكَبِيرِ ﴿\n\r\n\n\r\n\n\r\n(\"ஏனென்றால், அல்லாஹ் ஒருவன் மட்டுமே அழைக்கப்பட்டபோது நீங்கள் நிராகரித்தீர்கள்; ஆனால் அவனுடன் மற்றவை இணைவைக்கப்பட்டபோது நீங்கள் விசுவாசித்தீர்கள்! எனவே தீர்ப்பு மிக உயர்ந்தவனும், மிகப் பெரியவனுமாகிய அல்லாஹ்வுக்கே உரியது!\") 40:12 ﴾مُسْتَكْبِرِينَ بِهِ سَامِرًا تَهْجُرُونَ﴿\n\r\n\n\r\n\n\r\n(அகந்தையுடன், இரவு நேரத்தில் அதைப் பற்றித் தீயதாகப் பேசிக் கொண்டிருந்தீர்கள்.) இது குறைஷிகள் தங்களைக் கஃபாவின் பாதுகாவலர்கள் என்று கருதிக்கொண்ட அந்த வீண் பெருமையைக் குறிக்கிறது, ஆனால் உண்மையில் அவர்கள் அதற்குத் தகுதியானவர்கள் அல்ல.\n\r\n\n\r\n\n\r\nஇமாம் அன்-நஸாஈ (ரஹ்) அவர்கள் தனது சுனனில் இந்த வசனத்திற்கான தஃப்ஸீரில் குறிப்பிட்டிருப்பதாவது: சயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"இந்த வசனம் அருளப்பட்டபோதுதான், இரவு நேரங்களில் அமர்ந்து வீணாகப் பேசுவது வெறுக்கப்பட்டது: ﴾مُسْتَكْبِرِينَ بِهِ سَامِرًا تَهْجُرُونَ﴿\n\r\n\n\r\n\n\r\n(அகந்தையுடன், இரவு நேரத்தில் அதைப் பற்றித் தீயதாகப் பேசிக் கொண்டிருந்தீர்கள்.) அவர் மேலும் கூறினார்கள்: \"அவர்கள் கஃபாவைக் குறித்துப் பெருமை பேசிக் கொண்டு, 'நாங்கள் அதன் மக்கள், இரவு முழுதும் விழித்திருந்து பேசிக்கொண்டிருப்போம்' என்று கூறுவார்கள். கஃபாவைச் சுற்றி அவர்கள் வீண் பெருமையுடன் பேசிக்கொண்டிருந்தார்களே தவிர, அதன் புனிதத்தைப் பேணவில்லை; எனவே உண்மையில் அவர்கள் அதனைப் புறக்கணித்தவர்களாகவே இருந்தார்கள்.\" ﴾أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ أَمْ جَاءَهُم مَّا لَمْ يَأْتِ آبَاءَهُمُ الْأَوَّلِينَ﴿"},"68":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"70":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"71":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"73":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"74":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=75\" class=\"link\">23:75</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:75 ஐ பார்க்கவும்"},"75":{"html":"<strong>இணைவைப்பாளர்களுக்கு மறுப்பும் கண்டனமும்</strong><br />\r\n<br />\r\nஅல்லாஹ் இணைவைப்பாளர்களைக் கண்டிக்கிறான். அவர்கள் குர்ஆனைப் புரிந்து கொள்ளாமலும், அதன் கருத்துக்களைச் சிந்திக்காமலும் அதிலிருந்து விலகிச் செல்கிறார்கள். அல்லாஹ் எந்தத் தூதருக்கும் இதை விட மிக முழுமையான, கண்ணியமான ஒரு வேதத்தை வஹீ (இறைச்செய்தி)யாக அருளவில்லை. இந்த வேதத்தில் அவர்களுக்கென்றே பிரத்யேகமாகப் பல விஷயங்கள் கூறப்பட்டிருந்தும், அவர்கள் இதைப் புறக்கணிக்கிறார்கள். குறிப்பாக, ஜாஹிலிய்யா (அறியாமை) காலத்தில் மறைந்த அவர்களின் முன்னோர்களுக்கு எந்த வேதமோ அல்லது எச்சரிக்கை செய்பவரோ வந்திருக்காத நிலையில், இவர்களுக்கு வழங்கப்பட்ட இந்த அருட்கொடையை அவர்கள் ஏற்று, அதற்கு நன்றி செலுத்தி, அதைப் புரிந்துகொண்டு இரவும் பகலும் அதன்படி செயல்பட்டிருக்க வேண்டும். அவர்களில் இஸ்லாத்தை ஏற்று நபிகள் நாயகத்தைப் (ஸல்) பின்பற்றிய விவேகமுள்ள ஸஹாபாக்கள் (ரழி) செய்தது போல இவர்களும் செய்திருக்க வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَدَّبَّرُواْ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلَ﴿</span><br />\r\n<br />\r\n(அவர்கள் இந்த வார்த்தையைச் சிந்திக்கவில்லையா?) கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! மக்கள் இதன் பொருளைச் சிந்தித்துச் சரியாகப் புரிந்திருந்தால், அல்லாஹ்வுக்கு மாறு செய்வதைத் தடுக்கும் விஷயத்தை அவர்கள் குர்ஆனில் கண்டிருப்பார்கள். ஆனால் அவர்கள் முற்றிலும் தெளிவில்லாத வசனங்களில் மட்டுமே கவனம் செலுத்தினார்கள், அதன் காரணமாகவே அவர்கள் அழிந்து போனார்கள்.\" பிறகு, குரைஷி காஃபிர்களைக் கண்டித்து அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَعْرِفُواْ</span> <span class=\"quran-arabic-font text-success\">رَسُولَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُنكِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லது அவர்கள் தங்கள் தூதரை அடையாளம் காணவில்லையா, அதனால் அவரை மறுக்கிறார்களா?) அதாவது, 'முஹம்மது (ஸல்) அவர்களையும், அவர்களுக்கு மத்தியில் அவர் வளர்ந்த நேர்மை, நம்பகத்தன்மை மற்றும் நற்பண்புகளையும் அவர்கள் அறியவில்லையா? அதை அவர்களால் மறுக்க முடியுமா அல்லது அதற்கு எதிராக வாதிட முடியுமா?' ஜஃபர் இப்னு அபீ தாலிப் (ரழி) அவர்கள் எத்தியோப்பிய மன்னர் நஜாஷியிடம் கூறினார்கள்: \"மன்னரே! அல்லாஹ் எங்களுக்கு ஒரு தூதரை அனுப்பியுள்ளான். அவருடைய வம்சம், நேர்மை மற்றும் நம்பகத்தன்மையை நாங்கள் நன்கு அறிவோம்.\" அல்-முஃகீரா இப்னு ஷுஃபா (ரழி) அவர்களும் கிஸ்ராவின் பிரதிநிதியிடம் சவால் விடுத்தபோது இதே போன்ற ஒன்றைக் கூறினார்கள். பைசாந்திய மன்னர் ஹெராக்ளியஸ், அபூ சுஃப்யான் ஸக்ர் இப்னு ஹர்ப் (ரழி) மற்றும் அவருடைய தோழர்களிடம் - அவர்கள் அப்போது இன்னும் இஸ்லாத்தை ஏற்காத காஃபிர்களாக இருந்தனர் - நபி (ஸல்) அவர்களின் பண்புகள், வம்சம், நேர்மை மற்றும் நம்பகத்தன்மை பற்றி கேட்டபோது, அவர்களால் உண்மையை மட்டுமே கூற முடிந்தது. அவர் நிச்சயமாகக் கண்ணியமானவர் மற்றும் உண்மையாளர் என்பதை அவர்களும் ஒப்புக்கொண்டனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">جِنَّةٌ﴿</span><br />\r\n<br />\r\n(அல்லது \"அவரிடம் பைத்தியம் இருக்கிறது\" என்று அவர்கள் கூறுகிறார்களா?) இது நபி (ஸல்) அவர்களைப் பற்றி குரைஷிகள் சொன்னதை விவரிக்கிறது. அவர் குர்ஆனைத் தானாகவே இட்டுக்கட்டுகிறார் என்றோ அல்லது அவர் ஒரு பைத்தியம், என்ன சொல்கிறார் என்று அவருக்கே தெரியவில்லை என்றோ அவர்கள் கூறினார்கள். ஆனால் அவர்களுடைய உள்ளங்கள் அதை நம்பவில்லை என்று அல்லாஹ் நமக்குத் தெரிவிக்கிறான். குர்ஆனைப் பற்றித் தாங்கள் சொல்வது பொய் என்பதை அவர்கள் அறிந்திருந்தார்கள். ஏனெனில் அது அல்லாஹ்வின் வார்த்தைகளாக அவர்களிடம் வந்தது, அதை எதிர்க்கவோ நிராகரிக்கவோ முடியாது. எனவே, அல்லாஹ் அவர்களுக்கும் உலக மக்கள் அனைவருக்கும் இது போன்ற ஒன்றைக் கொண்டு வருமாறு சவால் விடுத்தான் - ஆனால் அவர்களால் முடியவில்லை, ஒருபோதும் அவ்வாறு செய்ய முடியாது. எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَأَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِلْحَقِّ</span> <span class=\"quran-arabic-font text-success\">كَـرِهُونَ﴿</span><br />\r\n<br />\r\n(மாறாக, அவர் அவர்களிடம் சத்தியத்தைக் கொண்டு வந்தார். ஆனால் அவர்களில் பெரும்பாலோர் அந்தச் சத்தியத்தை வெறுக்கிறார்கள்.)<br />\r\n<br />\r\n<strong>சத்தியம் மனோ இச்சைகளைப் பின்பற்றுவதில்லை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">أَهْوَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَفَسَدَتِ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ﴿</span><br />\r\n<br />\r\n(சத்தியம் (அல்-ஹக்) அவர்களுடைய மனோ இச்சைகளைப் பின்பற்றியிருந்தால், நிச்சயமாக வானங்களும் பூமியும் அவற்றில் உள்ளவைகளும் சீரழிந்திருக்கும்!) முஜாஹித், அபூ ஸாலிஹ் மற்றும் அஸ்-ஸுத்தீ (ரழி) ஆகியோர், \"அல்-ஹக் என்பது அல்லாஹ்வை (அவன் தூய்மையானவன்) குறிக்கிறது\" என்று கூறினார்கள். அல்லாஹ் அவர்களின் உள்ளங்களில் உள்ள ஆசைகளுக்கு ஏற்பச் சட்டங்களை வகுத்திருந்தால், அவர்களின் சீரழிந்த மற்றும் முரண்பாடான ஆசைகளால் வானங்களும் பூமியும் அவற்றில் உள்ள அனைத்தும் நாசமாகி இருக்கும் என்பதே இந்த வசனத்தின் கருத்தாகும். வேறு இடத்தில் அவர்களைப் பற்றி அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقَرْيَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ﴿</span><br />\r\n<br />\r\n(\"இந்த குர்ஆன் ஏன் இரு ஊர்களிலுள்ள ஒரு பெரிய மனிதர் மீது இறக்கப்படவில்லை?\") <a href=\"qurandisp.php?sura=43&ayah=31\" class=\"link\">43:31</a>. பிறகு அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَقْسِمُونَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ﴿</span><br />\r\n<br />\r\n(உமது இறைவனின் அருளை அவர்களா பங்கிடுகிறார்கள்?) <a href=\"qurandisp.php?sura=43&ayah=32\" class=\"link\">43:32</a>. மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُل</span> <span class=\"quran-arabic-font text-success\">لَّوْ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">خَزَآئِنَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةِ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">إِذًا</span> <span class=\"quran-arabic-font text-success\">لأمْسَكْتُمْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةَ</span> <span class=\"quran-arabic-font text-success\">الإِنفَاقِ﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"எனது இறைவனின் அருட்கொடையான கருவூலங்களை நீங்கள் பெற்றிருந்தால், செலவாகி விடுமோ என்ற பயத்தில் அவற்றை நீங்கள் பிடித்து வைத்திருப்பீர்கள்.\") <a href=\"qurandisp.php?sura=17&ayah=100\" class=\"link\">17:100</a>,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">نَصِيبٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكِ</span> <span class=\"quran-arabic-font text-success\">فَإِذاً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْتُونَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">نَقِيراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லது அவர்களுக்கு ஆட்சியில் ஏதேனும் பங்குண்டா? அப்படியிருந்தால் அவர்கள் மக்களுக்கு ஒரு கடுகளவு கூட கொடுத்திருக்க மாட்டார்கள்.) <a href=\"qurandisp.php?sura=4&ayah=53\" class=\"link\">4:53</a>. மனிதர்கள் எவ்வளவு பலவீனமானவர்கள் என்பதையும், அவர்களின் கருத்துக்களும் விருப்பங்களும் எவ்வளவு முரண்பட்டவை என்பதையும் இவை அனைத்தும் காட்டுகின்றன. அல்லாஹ் மட்டுமே (அவன் தூய்மையானவன்) தனது பண்புகள், வார்த்தைகள், செயல்கள், சட்டங்கள் மற்றும் படைப்புகளின் மீதான கட்டுப்பாடு ஆகியவற்றில் முழுமையானவன். அவனைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை, அவனைத் தவிர இரட்சகன் யாருமில்லை. பிறகு அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">أَتَيْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">بِذِكْرِهِمْ﴿</span><br />\r\n<br />\r\n(மாறாக, நாம் அவர்களுக்குரிய நினைவூட்டலைக் கொண்டு வந்தோம்,) அதாவது குர்ஆன்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் தங்களுக்குரிய நினைவூட்டலைப் புறக்கணிக்கிறார்கள்.)<br />\r\n<br />\r\n<strong>நபி (ஸல்) அவர்கள் எந்தக் கூலியையும் கேட்பதில்லை, மேலும் அவர்கள் நேரான பாதைக்கு அழைக்கிறார்கள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">تَسْأَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">خَرْجاً﴿</span><br />\r\n<br />\r\n(அல்லது நீர் அவர்களிடம் ஏதேனும் 'கர்ஜ்' (கூலி) கேட்கிறீரா?) அல்-ஹஸன் (ரழி) அவர்கள் \"வெகுமதி\" என்று கூறினார்கள். கதாதா (ரழி) அவர்கள் \"ஏதேனும் கூலி\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَخَرَاجُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ﴿</span><br />\r\n<br />\r\n(ஆனால், உமது இறைவனின் பிரதிபலன் மிகச் சிறந்தது,) அதாவது, நீர் அவர்களை நேர்வழிக்கு அழைப்பதற்காக எந்த ஊதியத்தையோ கூலியையோ கேட்கவில்லை. மாறாக, நீர் அல்லாஹ்விடமிருந்து ஒரு மகத்தான வெகுமதியை எதிர்பார்க்கிறீர். அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرِىَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"நான் உங்களிடம் ஏதேனும் கூலி கேட்டிருந்தால் அது உங்களுக்கே இருக்கட்டும். எனது கூலி அல்லாஹ்விடமேயன்றி வேறில்லை.\") <a href=\"qurandisp.php?sura=34&ayah=47\" class=\"link\">34:47</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنَآ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَلِّفِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை. மேலும் நான் வீணாகப் பேசுபவர்களில் ஒருவனும் அல்ல.\") <a href=\"qurandisp.php?sura=38&ayah=86\" class=\"link\">38:86</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمَوَدَّةَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْقُرْبَى﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"உறவினர்களிடம் அன்பு காட்டுவதைத் தவிர இதற்காக நான் உங்களிடம் வேறெந்தக் கூலியையும் கேட்கவில்லை.\") <a href=\"qurandisp.php?sura=42&ayah=23\" class=\"link\">42:23</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَآءَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَقْصَى</span> <span class=\"quran-arabic-font text-success\">الْمَدِينَةِ</span> <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">يَسْعَى</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">يقَوْمِ</span> <span class=\"quran-arabic-font text-success\">اتَّبِعُواْ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> <span class=\"quran-arabic-font text-success\">اتَّبِعُواْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْراً﴿</span><br />\r\n<br />\r\n(நகரத்தின் கடைகோடியிலிருந்து ஒரு மனிதர் ஓடி வந்து கூறினார்: \"எனது மக்களே! இத்தூதர்களைப் பின்பற்றுங்கள். உங்களிடம் எந்தக் கூலியையும் கேட்காதவர்களைப் பின்பற்றுங்கள்; அவர்களோ நேர்வழி பெற்றவர்கள்.\") <a href=\"qurandisp.php?sura=36&ayah=20\" class=\"link\">36:20</a>-21.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَتَدْعُوهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صِرَطٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الصِّرَطِ</span> <span class=\"quran-arabic-font text-success\">لَنَـكِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீர் அவர்களை நேரான பாதைக்கு அழைக்கிறீர். மேலும் நிச்சயமாக மறுமையை நம்பாதவர்கள் அந்தப் பாதையை விட்டுத் தவறி விலகிச் செல்பவர்களே.)<br />\r\n<br />\r\n<strong>நிராகரிப்பாளர்களின் நிலை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الصِّرَطِ</span> <span class=\"quran-arabic-font text-success\">لَنَـكِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக மறுமையை நம்பாதவர்கள் அந்தப் பாதையை விட்டுத் தவறி விலகிச் செல்பவர்களே.) அதாவது, அவர்கள் வழிதவறிவிட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رَحِمْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">وَكَشَفْنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ضُرٍّ</span> <span class=\"quran-arabic-font text-success\">لَّلَجُّواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">طُغْيَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَهُونَ﴿</span><br />\r\n<br />\r\n(நாம் அவர்கள் மீது கருணை காட்டி, அவர்களுக்கு ஏற்பட்ட துன்பத்தை நீக்கினாலும், அவர்கள் தங்கள் வரம்புமீறலிலேயே பிடிவாதமாகத் தட்டழிந்து திரிவார்கள்.) இங்கே அல்லாஹ் அவர்களின் குஃபிரில் (நிராகரிப்பில்) உள்ள பிடிவாதத்தைப் பற்றிக் கூறுகிறான். அதாவது, அவன் அவர்களிடமிருந்து சோதனையை நீக்கி, குர்ஆனை அவர்களுக்குப் புரியச் செய்தாலும் அவர்கள் அதைப் பின்பற்ற மாட்டார்கள். அவர்கள் தங்களின் நிராகரிப்பிலும் பிடிவாதமான வரம்புமீறலிலும் தொடர்ந்திருப்பார்கள். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">عَلِمَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِمْ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">لأَسْمَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَسْمَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَتَوَلَّواْ</span> <span class=\"quran-arabic-font text-success\">وَّهُم</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்களிடம் ஏதேனும் நன்மை இருப்பதாக அல்லாஹ் அறிந்திருந்தால், அவன் அவர்களைக் கேட்கச் செய்திருப்பான். அவன் அவர்களைக் கேட்கச் செய்திருந்தாலும், அவர்கள் வெறுப்புடன் புறக்கணித்துத் திரும்பியிருப்பார்கள்.) <a href=\"qurandisp.php?sura=8&ayah=23\" class=\"link\">8:23</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">وُقِفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">يلَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُكَذِّبَ</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">وَنَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">بَدَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُخْفُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رُدُّواْ</span> <span class=\"quran-arabic-font text-success\">لَعَـدُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">نُهُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَاذِبُونَ</span> * <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هِيَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">حَيَاتُنَا</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمَبْعُوثِينَ﴿</span><br />\r\n<br />\r\n(மேலும் (லவ்) நீர் பார்க்க முடிந்தால், அவர்கள் (நரக) நெருப்பின் முன் நிறுத்தப்படும்போது! அவர்கள் கூறுவார்கள்: \"நாங்கள் மீண்டும் (உலகுக்குத்) திருப்பி அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்யாக்க மாட்டோம்; மேலும் நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக இருப்போம்!\" இல்லை, அவர்கள் முன்பு மறைத்து வைத்திருந்தது அவர்களுக்கு வெளிப்பட்டுவிட்டது. ஆனால் அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ அதற்கே மீண்டும் திரும்புவார்கள். மேலும் நிச்சயமாக அவர்கள் பொய்யர்களே! அவர்கள்: \"நமது இந்த உலக வாழ்க்கையைத் தவிர வேறு வாழ்க்கை இல்லை; நாம் உயிர்ப்பிக்கப்படுபவர்கள் அல்ல\" என்று கூறுகிறார்கள்.) <a href=\"qurandisp.php?sura=6&ayah=27\" class=\"link\">6:27</a>-29.<br />\r\n<br />\r\nஎன்று முடியும் வரை. இது அல்லாஹ்வின் ஞானத்துடன் தொடர்புடையது. நடக்காத ஒரு விஷயம், ஒருவேளை நடந்தால் அது எப்படி இருக்கும் என்பதை அவன் அறிவான். அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) வழியாக அறிவிக்கிறார்கள்: \"<span class=\"quran-arabic-font text-success\">﴾لَوْ﴿</span> ((லவ்) என்றால்) என்ற சொல்லின் மூலம் குறிப்பிடப்படும் அனைத்தும் ஒருபோதும் நிகழாத விஷயங்களாகும்.\"<br />\r\n<br />","text":"இணைவைப்பாளர்களுக்கு மறுப்பும் கண்டனமும்\n\r\n\n\r\nஅல்லாஹ் இணைவைப்பாளர்களைக் கண்டிக்கிறான். அவர்கள் குர்ஆனைப் புரிந்து கொள்ளாமலும், அதன் கருத்துக்களைச் சிந்திக்காமலும் அதிலிருந்து விலகிச் செல்கிறார்கள். அல்லாஹ் எந்தத் தூதருக்கும் இதை விட மிக முழுமையான, கண்ணியமான ஒரு வேதத்தை வஹீ (இறைச்செய்தி)யாக அருளவில்லை. இந்த வேதத்தில் அவர்களுக்கென்றே பிரத்யேகமாகப் பல விஷயங்கள் கூறப்பட்டிருந்தும், அவர்கள் இதைப் புறக்கணிக்கிறார்கள். குறிப்பாக, ஜாஹிலிய்யா (அறியாமை) காலத்தில் மறைந்த அவர்களின் முன்னோர்களுக்கு எந்த வேதமோ அல்லது எச்சரிக்கை செய்பவரோ வந்திருக்காத நிலையில், இவர்களுக்கு வழங்கப்பட்ட இந்த அருட்கொடையை அவர்கள் ஏற்று, அதற்கு நன்றி செலுத்தி, அதைப் புரிந்துகொண்டு இரவும் பகலும் அதன்படி செயல்பட்டிருக்க வேண்டும். அவர்களில் இஸ்லாத்தை ஏற்று நபிகள் நாயகத்தைப் (ஸல்) பின்பற்றிய விவேகமுள்ள ஸஹாபாக்கள் (ரழி) செய்தது போல இவர்களும் செய்திருக்க வேண்டும்.\n\r\n\n\r\n﴾أَفَلَمْ يَدَّبَّرُواْ الْقَوْلَ﴿\n\r\n\n\r\n(அவர்கள் இந்த வார்த்தையைச் சிந்திக்கவில்லையா?) கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! மக்கள் இதன் பொருளைச் சிந்தித்துச் சரியாகப் புரிந்திருந்தால், அல்லாஹ்வுக்கு மாறு செய்வதைத் தடுக்கும் விஷயத்தை அவர்கள் குர்ஆனில் கண்டிருப்பார்கள். ஆனால் அவர்கள் முற்றிலும் தெளிவில்லாத வசனங்களில் மட்டுமே கவனம் செலுத்தினார்கள், அதன் காரணமாகவே அவர்கள் அழிந்து போனார்கள்.\" பிறகு, குரைஷி காஃபிர்களைக் கண்டித்து அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾أَمْ لَمْ يَعْرِفُواْ رَسُولَهُمْ فَهُمْ لَهُ مُنكِرُونَ ﴿\n\r\n\n\r\n(அல்லது அவர்கள் தங்கள் தூதரை அடையாளம் காணவில்லையா, அதனால் அவரை மறுக்கிறார்களா?) அதாவது, 'முஹம்மது (ஸல்) அவர்களையும், அவர்களுக்கு மத்தியில் அவர் வளர்ந்த நேர்மை, நம்பகத்தன்மை மற்றும் நற்பண்புகளையும் அவர்கள் அறியவில்லையா? அதை அவர்களால் மறுக்க முடியுமா அல்லது அதற்கு எதிராக வாதிட முடியுமா?' ஜஃபர் இப்னு அபீ தாலிப் (ரழி) அவர்கள் எத்தியோப்பிய மன்னர் நஜாஷியிடம் கூறினார்கள்: \"மன்னரே! அல்லாஹ் எங்களுக்கு ஒரு தூதரை அனுப்பியுள்ளான். அவருடைய வம்சம், நேர்மை மற்றும் நம்பகத்தன்மையை நாங்கள் நன்கு அறிவோம்.\" அல்-முஃகீரா இப்னு ஷுஃபா (ரழி) அவர்களும் கிஸ்ராவின் பிரதிநிதியிடம் சவால் விடுத்தபோது இதே போன்ற ஒன்றைக் கூறினார்கள். பைசாந்திய மன்னர் ஹெராக்ளியஸ், அபூ சுஃப்யான் ஸக்ர் இப்னு ஹர்ப் (ரழி) மற்றும் அவருடைய தோழர்களிடம் - அவர்கள் அப்போது இன்னும் இஸ்லாத்தை ஏற்காத காஃபிர்களாக இருந்தனர் - நபி (ஸல்) அவர்களின் பண்புகள், வம்சம், நேர்மை மற்றும் நம்பகத்தன்மை பற்றி கேட்டபோது, அவர்களால் உண்மையை மட்டுமே கூற முடிந்தது. அவர் நிச்சயமாகக் கண்ணியமானவர் மற்றும் உண்மையாளர் என்பதை அவர்களும் ஒப்புக்கொண்டனர்.\n\r\n\n\r\n﴾أَمْ يَقُولُونَ بِهِ جِنَّةٌ﴿\n\r\n\n\r\n(அல்லது \"அவரிடம் பைத்தியம் இருக்கிறது\" என்று அவர்கள் கூறுகிறார்களா?) இது நபி (ஸல்) அவர்களைப் பற்றி குரைஷிகள் சொன்னதை விவரிக்கிறது. அவர் குர்ஆனைத் தானாகவே இட்டுக்கட்டுகிறார் என்றோ அல்லது அவர் ஒரு பைத்தியம், என்ன சொல்கிறார் என்று அவருக்கே தெரியவில்லை என்றோ அவர்கள் கூறினார்கள். ஆனால் அவர்களுடைய உள்ளங்கள் அதை நம்பவில்லை என்று அல்லாஹ் நமக்குத் தெரிவிக்கிறான். குர்ஆனைப் பற்றித் தாங்கள் சொல்வது பொய் என்பதை அவர்கள் அறிந்திருந்தார்கள். ஏனெனில் அது அல்லாஹ்வின் வார்த்தைகளாக அவர்களிடம் வந்தது, அதை எதிர்க்கவோ நிராகரிக்கவோ முடியாது. எனவே, அல்லாஹ் அவர்களுக்கும் உலக மக்கள் அனைவருக்கும் இது போன்ற ஒன்றைக் கொண்டு வருமாறு சவால் விடுத்தான் - ஆனால் அவர்களால் முடியவில்லை, ஒருபோதும் அவ்வாறு செய்ய முடியாது. எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾بَلْ جَآءَهُمْ بِالْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَـرِهُونَ﴿\n\r\n\n\r\n(மாறாக, அவர் அவர்களிடம் சத்தியத்தைக் கொண்டு வந்தார். ஆனால் அவர்களில் பெரும்பாலோர் அந்தச் சத்தியத்தை வெறுக்கிறார்கள்.)\n\r\n\n\r\nசத்தியம் மனோ இச்சைகளைப் பின்பற்றுவதில்லை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَلَوِ اتَّبَعَ الْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ السَّمَـوَتُ وَالاٌّرْضُ وَمَن فِيهِنَّ﴿\n\r\n\n\r\n(சத்தியம் (அல்-ஹக்) அவர்களுடைய மனோ இச்சைகளைப் பின்பற்றியிருந்தால், நிச்சயமாக வானங்களும் பூமியும் அவற்றில் உள்ளவைகளும் சீரழிந்திருக்கும்!) முஜாஹித், அபூ ஸாலிஹ் மற்றும் அஸ்-ஸுத்தீ (ரழி) ஆகியோர், \"அல்-ஹக் என்பது அல்லாஹ்வை (அவன் தூய்மையானவன்) குறிக்கிறது\" என்று கூறினார்கள். அல்லாஹ் அவர்களின் உள்ளங்களில் உள்ள ஆசைகளுக்கு ஏற்பச் சட்டங்களை வகுத்திருந்தால், அவர்களின் சீரழிந்த மற்றும் முரண்பாடான ஆசைகளால் வானங்களும் பூமியும் அவற்றில் உள்ள அனைத்தும் நாசமாகி இருக்கும் என்பதே இந்த வசனத்தின் கருத்தாகும். வேறு இடத்தில் அவர்களைப் பற்றி அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n﴾لَوْلاَ نُزِّلَ هَـذَا الْقُرْءَانُ عَلَى رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيمٍ﴿\n\r\n\n\r\n(\"இந்த குர்ஆன் ஏன் இரு ஊர்களிலுள்ள ஒரு பெரிய மனிதர் மீது இறக்கப்படவில்லை?\") 43:31. பிறகு அவன் கூறுகிறான்:\n\r\n\n\r\n﴾أَهُمْ يَقْسِمُونَ رَحْمَةَ رَبِّكَ﴿\n\r\n\n\r\n(உமது இறைவனின் அருளை அவர்களா பங்கிடுகிறார்கள்?) 43:32. மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّى إِذًا لأمْسَكْتُمْ خَشْيَةَ الإِنفَاقِ﴿\n\r\n\n\r\n(கூறுவீராக: \"எனது இறைவனின் அருட்கொடையான கருவூலங்களை நீங்கள் பெற்றிருந்தால், செலவாகி விடுமோ என்ற பயத்தில் அவற்றை நீங்கள் பிடித்து வைத்திருப்பீர்கள்.\") 17:100,\n\r\n\n\r\n﴾أَمْ لَهُمْ نَصِيبٌ مِّنَ الْمُلْكِ فَإِذاً لاَّ يُؤْتُونَ النَّاسَ نَقِيراً ﴿\n\r\n\n\r\n(அல்லது அவர்களுக்கு ஆட்சியில் ஏதேனும் பங்குண்டா? அப்படியிருந்தால் அவர்கள் மக்களுக்கு ஒரு கடுகளவு கூட கொடுத்திருக்க மாட்டார்கள்.) 4:53. மனிதர்கள் எவ்வளவு பலவீனமானவர்கள் என்பதையும், அவர்களின் கருத்துக்களும் விருப்பங்களும் எவ்வளவு முரண்பட்டவை என்பதையும் இவை அனைத்தும் காட்டுகின்றன. அல்லாஹ் மட்டுமே (அவன் தூய்மையானவன்) தனது பண்புகள், வார்த்தைகள், செயல்கள், சட்டங்கள் மற்றும் படைப்புகளின் மீதான கட்டுப்பாடு ஆகியவற்றில் முழுமையானவன். அவனைத் தவிர வணக்கத்திற்குரியவன் யாருமில்லை, அவனைத் தவிர இரட்சகன் யாருமில்லை. பிறகு அவன் கூறுகிறான்:\n\r\n\n\r\n﴾بَلْ أَتَيْنَـهُمْ بِذِكْرِهِمْ﴿\n\r\n\n\r\n(மாறாக, நாம் அவர்களுக்குரிய நினைவூட்டலைக் கொண்டு வந்தோம்,) அதாவது குர்ஆன்,\n\r\n\n\r\n﴾فَهُمْ عَن ذِكْرِهِمْ مُّعْرِضُونَ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் தங்களுக்குரிய நினைவூட்டலைப் புறக்கணிக்கிறார்கள்.)\n\r\n\n\r\nநபி (ஸல்) அவர்கள் எந்தக் கூலியையும் கேட்பதில்லை, மேலும் அவர்கள் நேரான பாதைக்கு அழைக்கிறார்கள்\n\r\n\n\r\n﴾أَمْ تَسْأَلُهُمْ خَرْجاً﴿\n\r\n\n\r\n(அல்லது நீர் அவர்களிடம் ஏதேனும் 'கர்ஜ்' (கூலி) கேட்கிறீரா?) அல்-ஹஸன் (ரழி) அவர்கள் \"வெகுமதி\" என்று கூறினார்கள். கதாதா (ரழி) அவர்கள் \"ஏதேனும் கூலி\" என்று கூறினார்கள்.\n\r\n\n\r\n﴾فَخَرَاجُ رَبِّكَ خَيْرٌ﴿\n\r\n\n\r\n(ஆனால், உமது இறைவனின் பிரதிபலன் மிகச் சிறந்தது,) அதாவது, நீர் அவர்களை நேர்வழிக்கு அழைப்பதற்காக எந்த ஊதியத்தையோ கூலியையோ கேட்கவில்லை. மாறாக, நீர் அல்லாஹ்விடமிருந்து ஒரு மகத்தான வெகுமதியை எதிர்பார்க்கிறீர். அவன் கூறுவது போல:\n\r\n\n\r\n﴾قُلْ مَا سَأَلْتُكُم مِّن أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلاَّ عَلَى اللَّهِ﴿\n\r\n\n\r\n(கூறுவீராக: \"நான் உங்களிடம் ஏதேனும் கூலி கேட்டிருந்தால் அது உங்களுக்கே இருக்கட்டும். எனது கூலி அல்லாஹ்விடமேயன்றி வேறில்லை.\") 34:47.\n\r\n\n\r\n﴾قُلْ مَآ أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَآ مِنَ الْمُتَكَلِّفِينَ ﴿\n\r\n\n\r\n(கூறுவீராக: \"இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை. மேலும் நான் வீணாகப் பேசுபவர்களில் ஒருவனும் அல்ல.\") 38:86.\n\r\n\n\r\n﴾قُل لاَّ أَسْأَلُكُمْ عَلَيْهِ أَجْراً إِلاَّ الْمَوَدَّةَ فِى الْقُرْبَى﴿\n\r\n\n\r\n(கூறுவீராக: \"உறவினர்களிடம் அன்பு காட்டுவதைத் தவிர இதற்காக நான் உங்களிடம் வேறெந்தக் கூலியையும் கேட்கவில்லை.\") 42:23.\n\r\n\n\r\n﴾وَجَآءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى قَالَ يقَوْمِ اتَّبِعُواْ الْمُرْسَلِينَ اتَّبِعُواْ مَن لاَّ يَسْأَلُكُمْ أَجْراً﴿\n\r\n\n\r\n(நகரத்தின் கடைகோடியிலிருந்து ஒரு மனிதர் ஓடி வந்து கூறினார்: \"எனது மக்களே! இத்தூதர்களைப் பின்பற்றுங்கள். உங்களிடம் எந்தக் கூலியையும் கேட்காதவர்களைப் பின்பற்றுங்கள்; அவர்களோ நேர்வழி பெற்றவர்கள்.\") 36:20-21.\n\r\n\n\r\n﴾وَإِنَّكَ لَتَدْعُوهُمْ إِلَى صِرَطٍ مُّسْتَقِيمٍ - وَإِنَّ الَّذِينَ لاَ يُؤْمِنُونَ بِالاٌّخِرَةِ عَنِ الصِّرَطِ لَنَـكِبُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக நீர் அவர்களை நேரான பாதைக்கு அழைக்கிறீர். மேலும் நிச்சயமாக மறுமையை நம்பாதவர்கள் அந்தப் பாதையை விட்டுத் தவறி விலகிச் செல்பவர்களே.)\n\r\n\n\r\nநிராகரிப்பாளர்களின் நிலை\n\r\n\n\r\n﴾وَإِنَّ الَّذِينَ لاَ يُؤْمِنُونَ بِالاٌّخِرَةِ عَنِ الصِّرَطِ لَنَـكِبُونَ ﴿\n\r\n\n\r\n(மேலும் நிச்சயமாக மறுமையை நம்பாதவர்கள் அந்தப் பாதையை விட்டுத் தவறி விலகிச் செல்பவர்களே.) அதாவது, அவர்கள் வழிதவறிவிட்டார்கள்.\n\r\n\n\r\n﴾وَلَوْ رَحِمْنَـهُمْ وَكَشَفْنَا مَا بِهِمْ مِّن ضُرٍّ لَّلَجُّواْ فِى طُغْيَانِهِمْ يَعْمَهُونَ﴿\n\r\n\n\r\n(நாம் அவர்கள் மீது கருணை காட்டி, அவர்களுக்கு ஏற்பட்ட துன்பத்தை நீக்கினாலும், அவர்கள் தங்கள் வரம்புமீறலிலேயே பிடிவாதமாகத் தட்டழிந்து திரிவார்கள்.) இங்கே அல்லாஹ் அவர்களின் குஃபிரில் (நிராகரிப்பில்) உள்ள பிடிவாதத்தைப் பற்றிக் கூறுகிறான். அதாவது, அவன் அவர்களிடமிருந்து சோதனையை நீக்கி, குர்ஆனை அவர்களுக்குப் புரியச் செய்தாலும் அவர்கள் அதைப் பின்பற்ற மாட்டார்கள். அவர்கள் தங்களின் நிராகரிப்பிலும் பிடிவாதமான வரம்புமீறலிலும் தொடர்ந்திருப்பார்கள். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾وَلَوْ عَلِمَ اللَّهُ فِيهِمْ خَيْرًا لأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّواْ وَّهُم مُّعْرِضُونَ ﴿\n\r\n\n\r\n(அவர்களிடம் ஏதேனும் நன்மை இருப்பதாக அல்லாஹ் அறிந்திருந்தால், அவன் அவர்களைக் கேட்கச் செய்திருப்பான். அவன் அவர்களைக் கேட்கச் செய்திருந்தாலும், அவர்கள் வெறுப்புடன் புறக்கணித்துத் திரும்பியிருப்பார்கள்.) 8:23.\n\r\n\n\r\n﴾وَلَوْ تَرَى إِذْ وُقِفُواْ عَلَى النَّارِ فَقَالُواْ يلَيْتَنَا نُرَدُّ وَلاَ نُكَذِّبَ بِآيَاتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِنِينَ بَلْ بَدَا لَهُمْ مَّا كَانُواْ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّواْ لَعَـدُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَاذِبُونَ * وَقَالُواْ إِنْ هِيَ إِلاَّ حَيَاتُنَا الدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ﴿\n\r\n\n\r\n(மேலும் (லவ்) நீர் பார்க்க முடிந்தால், அவர்கள் (நரக) நெருப்பின் முன் நிறுத்தப்படும்போது! அவர்கள் கூறுவார்கள்: \"நாங்கள் மீண்டும் (உலகுக்குத்) திருப்பி அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்யாக்க மாட்டோம்; மேலும் நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக இருப்போம்!\" இல்லை, அவர்கள் முன்பு மறைத்து வைத்திருந்தது அவர்களுக்கு வெளிப்பட்டுவிட்டது. ஆனால் அவர்கள் திருப்பி அனுப்பப்பட்டாலும், அவர்கள் எதை விட்டும் தடுக்கப்பட்டார்களோ அதற்கே மீண்டும் திரும்புவார்கள். மேலும் நிச்சயமாக அவர்கள் பொய்யர்களே! அவர்கள்: \"நமது இந்த உலக வாழ்க்கையைத் தவிர வேறு வாழ்க்கை இல்லை; நாம் உயிர்ப்பிக்கப்படுபவர்கள் அல்ல\" என்று கூறுகிறார்கள்.) 6:27-29.\n\r\n\n\r\nஎன்று முடியும் வரை. இது அல்லாஹ்வின் ஞானத்துடன் தொடர்புடையது. நடக்காத ஒரு விஷயம், ஒருவேளை நடந்தால் அது எப்படி இருக்கும் என்பதை அவன் அறிவான். அத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) வழியாக அறிவிக்கிறார்கள்: \"﴾لَوْ﴿ ((லவ்) என்றால்) என்ற சொல்லின் மூலம் குறிப்பிடப்படும் அனைத்தும் ஒருபோதும் நிகழாத விஷயங்களாகும்.\""},"76":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"77":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"78":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"79":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"80":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"81":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"82":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=83\" class=\"link\">23:83</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:83 ஐ பார்க்கவும்"},"83":{"html":"<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَخَذْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْعَذَابِ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவர்களை வேதனையைக் கொண்டு தண்டித்தோம்,) இதன் பொருள்: \"நாம் அவர்களைச் சோதனைகள் மற்றும் துன்பங்கள் மூலம் சோதித்தோம்.\" அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">لِرَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَتَضَرَّعُونَ</span><br />\r\n<br />\r\n(ஆயினும் அவர்கள் தங்கள் இறைவனுக்குப் பணியவில்லை; அவனிடம் கெஞ்சிப் பிரார்த்திக்கவுமில்லை.) இதன் பொருள்: அந்தத் தண்டனைகள் அவர்களை இறைநிராகரிப்பிலிருந்தோ அல்லது பிடிவாதத்திலிருந்தோ தடுக்கவில்லை. மாறாக, அவர்கள் தங்கள் பாவத்திலும் வழிகேட்டிலுமே நிலைத்திருந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَكَانُواْ</span><br />\r\n<br />\r\n(ஆயினும் அவர்கள் பணியவில்லை.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَتَضَرَّعُونَ</span><br />\r\n<br />\r\n(அவனிடம் (அல்லாஹ்விடம்) பணிந்து பிரார்த்திக்கவுமில்லை.) அவர்கள் அவனை அழைக்கவில்லை. இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَوْلا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَأْسُنَا</span> <span class=\"quran-arabic-font text-success\">تَضَرَّعُواْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">قَسَتْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُهُمْ</span><br />\r\n<br />\r\n(நமது வேதனை அவர்களை வந்தடைந்தபோது, அவர்கள் ஏன் பணிந்து கொள்ளவில்லை? ஆனால் அவர்களின் இதயங்கள் கடினமாகிவிட்டன.) (<a href=\"qurandisp.php?sura=6&ayah=43\" class=\"link\">6:43</a>). இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: \"அபூ சுஃப்யான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'முஹம்மதே! அல்லாஹ்வின் மீதும், நமக்கிடையிலான உறவின் முறையின் மீதும் ஆணையிட்டுக் கேட்கிறேன்; நாங்கள் ஒட்டக ரோமத்தையும் இரத்தத்தையும் உண்ணும் நிலைக்குத் தள்ளப்பட்டுள்ளோம்' என்று கூறினார்கள்.\" பின்னர் அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَخَذْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَكَانُواْ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவர்களை வேதனையைக் கொண்டு தண்டித்தோம், ஆயினும் அவர்கள் பணியவில்லை.) இதனை அந்-நஸாயீ அவர்களும் பதிவு செய்துள்ளார்கள். இந்த ஹதீஸின் அடிப்படை ஸஹீஹுல் புகாரீ மற்றும் ஸஹீஹுல் முஸ்லிம் ஆகிய இரு நூல்களிலும் உள்ளது. அதில், குறைஷிகளிடம் எவ்வித நல்மாற்றத்தையும் காணாதபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராகப் பிரார்த்தனை செய்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">أَعِنِّي</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">بِسَبْعٍ</span> <span class=\"quran-arabic-font text-success\">كَسَبْعِ</span> <span class=\"quran-arabic-font text-success\">يُوسُف</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! யூசுஃப் (அலை) அவர்களின் காலத்து ஏழு ஆண்டுகளைப் போன்ற ஏழு ஆண்டுகளைக் (பஞ்சத்தை) கொண்டு எனக்கு அவர்களுக்கு எதிராக உதவுவாயாக.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">بَاباً</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">شَدِيدٍ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مُبْلِسُونَ</span><br />\r\n<br />\r\n(இறுதியாக, நாம் அவர்கள் மீது கடுமையான வேதனையின் வாசலைத் திறக்கும்போது, உடனே அவர்கள் அதில் அடியோடு நம்பிக்கையிழந்தவர்களாகி விடுவார்கள்.) அல்லாஹ்வின் கட்டளை அவர்களை வந்தடையும் போதும், மறுமை நாள் திடீரென வரும்போதும், அவர்கள் எதிர்பாராத நிலையில் அல்லாஹ்வின் வேதனை அவர்களைச் சூழும். அப்போது அவர்கள் எந்த நன்மையின் மீதும் நம்பிக்கையின்றித் தவிப்பார்கள்; அவர்களின் எல்லா எதிர்பார்ப்புகளும் தகர்ந்துவிடும்.<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் அருட்கொடைகள் மற்றும் அவனது மகத்தான ஆற்றல் பற்றிய நினைவூட்டல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنشَأَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">السَّمْعَ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّبْصَـرَ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّفْئِدَةَ</span><br />\r\n<br />\r\n(அவன்தான் உங்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இருதயங்களையும் படைத்தான்;)<br />\r\n<br />\r\nபின்னர் அல்லாஹ் தன் அடியார்களுக்குச் செய்த அருட்கொடைகளைக் குறிப்பிடுகிறான். அதாவது, அவன் அவர்களுக்குச் செவிப்புலன், பார்வை மற்றும் சிந்திக்கும் ஆற்றலை வழங்கியுள்ளான். அவற்றின் மூலம் அவர்கள் விஷயங்களை அறிந்து, படிப்பினைகளைப் பெறுகிறார்கள். இவை அல்லாஹ்வின் ஏகத்துவத்திற்குச் சான்றாகவும், அவன் தான் நாடியதைச் செய்பவன், தான் விரும்புவதைத் தேர்ந்தெடுப்பவன் என்பதற்கான அடையாளங்களாகவும் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَشْكُرُونَ</span><br />\r\n<br />\r\n(நீங்கள் மிகக் குறைவாகவே நன்றி செலுத்துகிறீர்கள்.) அதாவது, அல்லாஹ் உங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக நீங்கள் அவனுக்கு எவ்வளவு குறைவாக நன்றி செலுத்துகிறீர்கள்! இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">حَرَصْتَ</span> <span class=\"quran-arabic-font text-success\">بِمُؤْمِنِينَ</span><br />\r\n<br />\r\n(நீர் எவ்வளவு ஆசைப்பட்டாலும் மனிதர்களில் பெரும்பாலோர் ஈமான் கொள்ளமாட்டார்கள்.) (<a href=\"qurandisp.php?sura=12&ayah=103\" class=\"link\">12:103</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ذَرَأَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">وَإِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تُحْشَرُونَ</span><br />\r\n<br />\r\n(அவன்தான் உங்களைப் பூமியில் பரவச் செய்தான்; அவனிடமே நீங்கள் ஒன்றுசேர்க்கப்படுவீர்கள்.)<br />\r\n<br />\r\nபின்னர் அல்லாஹ் தனது மகத்தான வல்லமை மற்றும் ஆதிக்கம் குறித்து நமக்கு உணர்த்துகிறான். ஏனெனில், அவன்தான் படைப்பைத் தொடங்கி, மக்களைப் பல்வேறு சமூகங்களாகவும், மொழிகளாகவும், குணாதிசயங்களாகவும் பூமியின் பல பாகங்களில் பரவச் செய்தான். பின்னர் மறுமை நாளில், முந்தியவர்கள் பிந்தியவர்கள் என அனைவரையும் ஒரு குறிப்பிட்ட நாளில் ஒன்று சேர்ப்பான். சிறியவர், பெரியவர், ஆண், பெண், உயர்ந்தவர், தாழ்ந்தவர் என எவரும் விடுபட மாட்டார்கள். அனைவரும் முதலில் படைக்கப்பட்டது போன்றே மீண்டும் கொண்டு வரப்படுவார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُحْىِ</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ</span><br />\r\n<br />\r\n(அவன்தான் உயிர்ப்பிக்கிறான், இன்னும் மரணிக்கச் செய்கிறான்,) அதாவது, அவன் சிதறிப்போன எலும்புகளுக்கு மீண்டும் உயிர் கொடுப்பான்; சமூகங்களை மரணிக்கச் செய்வான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">اخْتِلَـفُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span><br />\r\n<br />\r\n(இரவு மற்றும் பகல் மாறி மாறி வருவதும் அவனுக்கே உரியதாகும்.) அதாவது, அவனது கட்டளையினால் இரவும் பகலும் கட்டுப்படுத்தப்பட்டுள்ளன. ஒவ்வொன்றும் மற்றொன்றைத் தொடர்ந்து வருகின்றன; இந்த ஒழுங்கிலிருந்து அவை ஒருபோதும் விலகுவதில்லை. அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">يَنبَغِى</span> <span class=\"quran-arabic-font text-success\">لَهَآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تدْرِكَ</span> <span class=\"quran-arabic-font text-success\">القَمَرَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">الَّيْلُ</span> <span class=\"quran-arabic-font text-success\">سَابِقُ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span><br />\r\n<br />\r\n(சூரியன் சந்திரனை முந்த முடியாது; இரவு பகலை முந்த முடியாது.) (<a href=\"qurandisp.php?sura=36&ayah=40\" class=\"link\">36:40</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ</span><br />\r\n<br />\r\n(அப்படியென்றால் நீங்கள் சிந்தித்துப் பார்க்க வேண்டாமா?) இதன் பொருள்: அனைத்தையும் கட்டுப்படுத்தும் சர்வ வல்லமையுள்ள, எல்லாம் அறிந்த இறைவனைப் பற்றி உங்களுக்கு உணர்த்தும் அறிவு உங்களிடம் இல்லையா? அவனுக்கே அனைத்தும் அடிபணிகின்றன.<br />\r\n<br />\r\n<strong>மரணத்திற்குப் பின் மீண்டும் உயிர்ப்பிக்கப்படுவதை இணைவைப்பாளர்கள் சாத்தியமற்றதாகக் கருதினர்</strong><br />\r\n<br />\r\nபின்னர், தங்களுக்கு முன் வாழ்ந்த நிராகரிப்பாளர்களைப் போலவே உயிர்த்தெழுதலை மறுப்பவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">مِثْلَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَءِذَا</span> <span class=\"quran-arabic-font text-success\">مِتْنَا</span> <span class=\"quran-arabic-font text-success\">وَكُنَّا</span> <span class=\"quran-arabic-font text-success\">تُرَاباً</span> <span class=\"quran-arabic-font text-success\">وَعِظَـماً</span> <span class=\"quran-arabic-font text-success\">أَءِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَبْعُوثُونَ</span><br />\r\n<br />\r\n(மாறாக, அவர்கள் தங்களுக்கு முன் வாழ்ந்தவர்கள் கூறியதைப் போன்றே கூறுகின்றனர். அவர்கள் கூறினர்: \"நாங்கள் மரணித்து, மண்ணாகவும் எலும்புகளாகவும் போன பிறகா? நாங்கள் மீண்டும் உயிர்ப்பிக்கப்படுவோமா?\") தாங்கள் மண்ணோடு மண்ணாகச் சிதைந்த பிறகு இது நடப்பது மிகவும் சாத்தியமற்றது என அவர்கள் கருதினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">وُعِدْنَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">وَءَابَآؤُنَا</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَسَـطِيرُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span><br />\r\n<br />\r\n(\"நிச்சயமாக இவ்வாறே எங்களுக்கும், இதற்கு முன் எங்கள் முன்னோர்களுக்கும் வாக்குறுதி அளிக்கப்பட்டது. இது முன்னோர்களின் கட்டுக்கதைகளே தவிர வேறில்லை!\") அதாவது, \"நாங்கள் மீண்டும் எழுப்பப்படுவது சாத்தியமற்றது. முன்னோர்களின் புத்தகங்கள் மற்றும் தர்க்கங்களிலிருந்து கற்றவர்களே இவ்வாறு கூறுகிறார்கள்\" என அவர்கள் கூறுகின்றனர். அவர்களின் இந்த மறுப்பும் புறக்கணிப்பும், பின்வரும் வசனங்களில் அல்லாஹ் அவர்களைப் பற்றிக் கூறுவது போன்றே உள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَءِذَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">عِظَـماً</span> <span class=\"quran-arabic-font text-success\">نَّخِرَةً</span> - <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">إِذاً</span> <span class=\"quran-arabic-font text-success\">كَرَّةٌ</span> <span class=\"quran-arabic-font text-success\">خَـسِرَةٌ</span> - <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">زَجْرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَحِدَةٌ</span> - <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِالسَّاهِرَةِ</span><br />\r\n<br />\r\n(\"நாங்கள் மட்கிப்போன எலும்புகளாக ஆன பிறகா?\" \"அப்படியானால் அது நஷ்டமான திரும்புதலாகும்\" என்று அவர்கள் கூறுகின்றனர். அதுவோ ஒரே ஒரு சத்தம்தான்; உடனே அவர்கள் பூமியின் மேல் மட்டத்தில் உயிருடன் இருப்பார்கள்.) (<a href=\"qurandisp.php?sura=79&ayah=11\" class=\"link\">79:11</a>-14).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَـهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُّطْفَةٍ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">خَصِيمٌ</span> <span class=\"quran-arabic-font text-success\">مٌّبِينٌ</span> - <span class=\"quran-arabic-font text-success\">وَضَرَبَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مَثَلاً</span> <span class=\"quran-arabic-font text-success\">وَنَسِىَ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يُحىِ</span> <span class=\"quran-arabic-font text-success\">الْعِظَـمَ</span> <span class=\"quran-arabic-font text-success\">وَهِىَ</span> <span class=\"quran-arabic-font text-success\">رَمِيمٌ</span> - <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يُحْيِيهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنشَأَهَآ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">خَلْقٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(மனிதன் பார்க்கவில்லையா? நாம் அவனை விந்துத் துளியிலிருந்து (நுத்ஃபாவிலிருந்து) படைத்தோம். அப்படியிருந்தும் அவன் பகிரங்கமாக விவாதிப்பவனாக இருக்கிறான். அவன் நமக்காக ஓர் உவமையைச் சொல்கிறான்; ஆனால் தனது சொந்தப் படைப்பை மறந்துவிடுகிறான். \"மட்கிப்போன இந்த எலும்புகளை மீண்டும் உயிர்ப்பிப்பவன் யார்?\" எனக் கேட்கிறான். நீர் கூறுவீராக: \"முதன் முதலில் அவற்றை உருவாக்கியவனே அவற்றுக்கு உயிர் கொடுப்பான். அவன் ஒவ்வொரு படைப்பையும் நன்கறிந்தவன்.\") (<a href=\"qurandisp.php?sura=36&ayah=77\" class=\"link\">36:77</a>-79).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لِّمَنِ</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n((நபியே!) நீர் கேளும்: \"பூமியும், அதிலுள்ளவர்களும் யாருக்குச் சொந்தம்? நீங்கள் அறிந்திருந்தால் (கூறுங்கள்).\")<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span><br />\r\n<br />\r\n(\"அல்லாஹ்வுக்கே\" என்று அவர்கள் கூறுவார்கள்; \"அப்படியாயின் நீங்கள் நல்லுணர்வு பெறமாட்டீர்களா?\" என்று நீர் கேட்பீராக!)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">رَّبُّ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">السَّبْعِ</span> <span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(\"ஏழு வானங்களுக்கு இறைவனும், மகத்தான அர்ஷுக்கு இறைவனும் யார்?\" என்று நீர் கேளும்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span><br />\r\n<br />\r\n(\"அல்லாஹ்வுக்கே\" என்று அவர்கள் கூறுவார்கள். \"அப்படியாயின் நீங்கள் அவனுக்கு அஞ்சமாட்டீர்களா?\" என்று நீர் கேட்பீராக!)<br />\r\n<br />","text":"وَلَقَدْ أَخَذْنَـهُمْ بِالْعَذَابِ\n\r\n\n\r\n(நிச்சயமாக நாம் அவர்களை வேதனையைக் கொண்டு தண்டித்தோம்,) இதன் பொருள்: \"நாம் அவர்களைச் சோதனைகள் மற்றும் துன்பங்கள் மூலம் சோதித்தோம்.\" அவனது கூற்று:\n\r\n\n\r\nفَمَا اسْتَكَانُواْ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ\n\r\n\n\r\n(ஆயினும் அவர்கள் தங்கள் இறைவனுக்குப் பணியவில்லை; அவனிடம் கெஞ்சிப் பிரார்த்திக்கவுமில்லை.) இதன் பொருள்: அந்தத் தண்டனைகள் அவர்களை இறைநிராகரிப்பிலிருந்தோ அல்லது பிடிவாதத்திலிருந்தோ தடுக்கவில்லை. மாறாக, அவர்கள் தங்கள் பாவத்திலும் வழிகேட்டிலுமே நிலைத்திருந்தார்கள்.\n\r\n\n\r\nفَمَا اسْتَكَانُواْ\n\r\n\n\r\n(ஆயினும் அவர்கள் பணியவில்லை.)\n\r\n\n\r\nوَمَا يَتَضَرَّعُونَ\n\r\n\n\r\n(அவனிடம் (அல்லாஹ்விடம்) பணிந்து பிரார்த்திக்கவுமில்லை.) அவர்கள் அவனை அழைக்கவில்லை. இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nفَلَوْلا إِذْ جَآءَهُمْ بَأْسُنَا تَضَرَّعُواْ وَلَـكِن قَسَتْ قُلُوبُهُمْ\n\r\n\n\r\n(நமது வேதனை அவர்களை வந்தடைந்தபோது, அவர்கள் ஏன் பணிந்து கொள்ளவில்லை? ஆனால் அவர்களின் இதயங்கள் கடினமாகிவிட்டன.) (6:43). இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்: \"அபூ சுஃப்யான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'முஹம்மதே! அல்லாஹ்வின் மீதும், நமக்கிடையிலான உறவின் முறையின் மீதும் ஆணையிட்டுக் கேட்கிறேன்; நாங்கள் ஒட்டக ரோமத்தையும் இரத்தத்தையும் உண்ணும் நிலைக்குத் தள்ளப்பட்டுள்ளோம்' என்று கூறினார்கள்.\" பின்னர் அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَلَقَدْ أَخَذْنَـهُمْ بِالْعَذَابِ فَمَا اسْتَكَانُواْ\n\r\n\n\r\n(நிச்சயமாக நாம் அவர்களை வேதனையைக் கொண்டு தண்டித்தோம், ஆயினும் அவர்கள் பணியவில்லை.) இதனை அந்-நஸாயீ அவர்களும் பதிவு செய்துள்ளார்கள். இந்த ஹதீஸின் அடிப்படை ஸஹீஹுல் புகாரீ மற்றும் ஸஹீஹுல் முஸ்லிம் ஆகிய இரு நூல்களிலும் உள்ளது. அதில், குறைஷிகளிடம் எவ்வித நல்மாற்றத்தையும் காணாதபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராகப் பிரார்த்தனை செய்தார்கள்:\n\r\n\n\r\n«اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُف»\n\r\n\n\r\n(யா அல்லாஹ்! யூசுஃப் (அலை) அவர்களின் காலத்து ஏழு ஆண்டுகளைப் போன்ற ஏழு ஆண்டுகளைக் (பஞ்சத்தை) கொண்டு எனக்கு அவர்களுக்கு எதிராக உதவுவாயாக.)\n\r\n\n\r\nحَتَّى إِذَا فَتَحْنَا عَلَيْهِمْ بَاباً ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ\n\r\n\n\r\n(இறுதியாக, நாம் அவர்கள் மீது கடுமையான வேதனையின் வாசலைத் திறக்கும்போது, உடனே அவர்கள் அதில் அடியோடு நம்பிக்கையிழந்தவர்களாகி விடுவார்கள்.) அல்லாஹ்வின் கட்டளை அவர்களை வந்தடையும் போதும், மறுமை நாள் திடீரென வரும்போதும், அவர்கள் எதிர்பாராத நிலையில் அல்லாஹ்வின் வேதனை அவர்களைச் சூழும். அப்போது அவர்கள் எந்த நன்மையின் மீதும் நம்பிக்கையின்றித் தவிப்பார்கள்; அவர்களின் எல்லா எதிர்பார்ப்புகளும் தகர்ந்துவிடும்.\n\r\n\n\r\nஅல்லாஹ்வின் அருட்கொடைகள் மற்றும் அவனது மகத்தான ஆற்றல் பற்றிய நினைவூட்டல்\n\r\n\n\r\nوَهُوَ الَّذِى أَنشَأَ لَكُمُ السَّمْعَ وَالاٌّبْصَـرَ وَالاٌّفْئِدَةَ\n\r\n\n\r\n(அவன்தான் உங்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இருதயங்களையும் படைத்தான்;)\n\r\n\n\r\nபின்னர் அல்லாஹ் தன் அடியார்களுக்குச் செய்த அருட்கொடைகளைக் குறிப்பிடுகிறான். அதாவது, அவன் அவர்களுக்குச் செவிப்புலன், பார்வை மற்றும் சிந்திக்கும் ஆற்றலை வழங்கியுள்ளான். அவற்றின் மூலம் அவர்கள் விஷயங்களை அறிந்து, படிப்பினைகளைப் பெறுகிறார்கள். இவை அல்லாஹ்வின் ஏகத்துவத்திற்குச் சான்றாகவும், அவன் தான் நாடியதைச் செய்பவன், தான் விரும்புவதைத் தேர்ந்தெடுப்பவன் என்பதற்கான அடையாளங்களாகவும் உள்ளன.\n\r\n\n\r\nقَلِيلاً مَّا تَشْكُرُونَ\n\r\n\n\r\n(நீங்கள் மிகக் குறைவாகவே நன்றி செலுத்துகிறீர்கள்.) அதாவது, அல்லாஹ் உங்களுக்கு வழங்கிய அருட்கொடைகளுக்காக நீங்கள் அவனுக்கு எவ்வளவு குறைவாக நன்றி செலுத்துகிறீர்கள்! இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَمَآ أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ\n\r\n\n\r\n(நீர் எவ்வளவு ஆசைப்பட்டாலும் மனிதர்களில் பெரும்பாலோர் ஈமான் கொள்ளமாட்டார்கள்.) (12:103).\n\r\n\n\r\nوَهُوَ الَّذِى ذَرَأَكُمْ فِى الاٌّرْضِ وَإِلَيْهِ تُحْشَرُونَ\n\r\n\n\r\n(அவன்தான் உங்களைப் பூமியில் பரவச் செய்தான்; அவனிடமே நீங்கள் ஒன்றுசேர்க்கப்படுவீர்கள்.)\n\r\n\n\r\nபின்னர் அல்லாஹ் தனது மகத்தான வல்லமை மற்றும் ஆதிக்கம் குறித்து நமக்கு உணர்த்துகிறான். ஏனெனில், அவன்தான் படைப்பைத் தொடங்கி, மக்களைப் பல்வேறு சமூகங்களாகவும், மொழிகளாகவும், குணாதிசயங்களாகவும் பூமியின் பல பாகங்களில் பரவச் செய்தான். பின்னர் மறுமை நாளில், முந்தியவர்கள் பிந்தியவர்கள் என அனைவரையும் ஒரு குறிப்பிட்ட நாளில் ஒன்று சேர்ப்பான். சிறியவர், பெரியவர், ஆண், பெண், உயர்ந்தவர், தாழ்ந்தவர் என எவரும் விடுபட மாட்டார்கள். அனைவரும் முதலில் படைக்கப்பட்டது போன்றே மீண்டும் கொண்டு வரப்படுவார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَهُوَ الَّذِى يُحْىِ وَيُمِيتُ\n\r\n\n\r\n(அவன்தான் உயிர்ப்பிக்கிறான், இன்னும் மரணிக்கச் செய்கிறான்,) அதாவது, அவன் சிதறிப்போன எலும்புகளுக்கு மீண்டும் உயிர் கொடுப்பான்; சமூகங்களை மரணிக்கச் செய்வான்.\n\r\n\n\r\nوَلَهُ اخْتِلَـفُ الَّيْلِ وَالنَّهَارِ\n\r\n\n\r\n(இரவு மற்றும் பகல் மாறி மாறி வருவதும் அவனுக்கே உரியதாகும்.) அதாவது, அவனது கட்டளையினால் இரவும் பகலும் கட்டுப்படுத்தப்பட்டுள்ளன. ஒவ்வொன்றும் மற்றொன்றைத் தொடர்ந்து வருகின்றன; இந்த ஒழுங்கிலிருந்து அவை ஒருபோதும் விலகுவதில்லை. அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nلاَ الشَّمْسُ يَنبَغِى لَهَآ أَن تدْرِكَ القَمَرَ وَلاَ الَّيْلُ سَابِقُ النَّهَارِ\n\r\n\n\r\n(சூரியன் சந்திரனை முந்த முடியாது; இரவு பகலை முந்த முடியாது.) (36:40).\n\r\n\n\r\nأَفَلاَ تَعْقِلُونَ\n\r\n\n\r\n(அப்படியென்றால் நீங்கள் சிந்தித்துப் பார்க்க வேண்டாமா?) இதன் பொருள்: அனைத்தையும் கட்டுப்படுத்தும் சர்வ வல்லமையுள்ள, எல்லாம் அறிந்த இறைவனைப் பற்றி உங்களுக்கு உணர்த்தும் அறிவு உங்களிடம் இல்லையா? அவனுக்கே அனைத்தும் அடிபணிகின்றன.\n\r\n\n\r\nமரணத்திற்குப் பின் மீண்டும் உயிர்ப்பிக்கப்படுவதை இணைவைப்பாளர்கள் சாத்தியமற்றதாகக் கருதினர்\n\r\n\n\r\nபின்னர், தங்களுக்கு முன் வாழ்ந்த நிராகரிப்பாளர்களைப் போலவே உயிர்த்தெழுதலை மறுப்பவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبَلْ قَالُواْ مِثْلَ مَا قَالَ الاٌّوَّلُونَ - قَالُواْ أَءِذَا مِتْنَا وَكُنَّا تُرَاباً وَعِظَـماً أَءِنَّا لَمَبْعُوثُونَ\n\r\n\n\r\n(மாறாக, அவர்கள் தங்களுக்கு முன் வாழ்ந்தவர்கள் கூறியதைப் போன்றே கூறுகின்றனர். அவர்கள் கூறினர்: \"நாங்கள் மரணித்து, மண்ணாகவும் எலும்புகளாகவும் போன பிறகா? நாங்கள் மீண்டும் உயிர்ப்பிக்கப்படுவோமா?\") தாங்கள் மண்ணோடு மண்ணாகச் சிதைந்த பிறகு இது நடப்பது மிகவும் சாத்தியமற்றது என அவர்கள் கருதினார்கள்.\n\r\n\n\r\nلَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَـذَا مِن قَبْلُ إِنْ هَـذَآ إِلاَّ أَسَـطِيرُ الاٌّوَّلِينَ\n\r\n\n\r\n(\"நிச்சயமாக இவ்வாறே எங்களுக்கும், இதற்கு முன் எங்கள் முன்னோர்களுக்கும் வாக்குறுதி அளிக்கப்பட்டது. இது முன்னோர்களின் கட்டுக்கதைகளே தவிர வேறில்லை!\") அதாவது, \"நாங்கள் மீண்டும் எழுப்பப்படுவது சாத்தியமற்றது. முன்னோர்களின் புத்தகங்கள் மற்றும் தர்க்கங்களிலிருந்து கற்றவர்களே இவ்வாறு கூறுகிறார்கள்\" என அவர்கள் கூறுகின்றனர். அவர்களின் இந்த மறுப்பும் புறக்கணிப்பும், பின்வரும் வசனங்களில் அல்லாஹ் அவர்களைப் பற்றிக் கூறுவது போன்றே உள்ளது:\n\r\n\n\r\nأَءِذَا كُنَّا عِظَـماً نَّخِرَةً - قَالُواْ تِلْكَ إِذاً كَرَّةٌ خَـسِرَةٌ - فَإِنَّمَا هِىَ زَجْرَةٌ وَحِدَةٌ - فَإِذَا هُم بِالسَّاهِرَةِ\n\r\n\n\r\n(\"நாங்கள் மட்கிப்போன எலும்புகளாக ஆன பிறகா?\" \"அப்படியானால் அது நஷ்டமான திரும்புதலாகும்\" என்று அவர்கள் கூறுகின்றனர். அதுவோ ஒரே ஒரு சத்தம்தான்; உடனே அவர்கள் பூமியின் மேல் மட்டத்தில் உயிருடன் இருப்பார்கள்.) (79:11-14).\n\r\n\n\r\nأَوَلَمْ يَرَ الإِنسَـنُ أَنَّا خَلَقْنَـهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مٌّبِينٌ - وَضَرَبَ لَنَا مَثَلاً وَنَسِىَ خَلْقَهُ قَالَ مَن يُحىِ الْعِظَـمَ وَهِىَ رَمِيمٌ - قُلْ يُحْيِيهَا الَّذِى أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ\n\r\n\n\r\n(மனிதன் பார்க்கவில்லையா? நாம் அவனை விந்துத் துளியிலிருந்து (நுத்ஃபாவிலிருந்து) படைத்தோம். அப்படியிருந்தும் அவன் பகிரங்கமாக விவாதிப்பவனாக இருக்கிறான். அவன் நமக்காக ஓர் உவமையைச் சொல்கிறான்; ஆனால் தனது சொந்தப் படைப்பை மறந்துவிடுகிறான். \"மட்கிப்போன இந்த எலும்புகளை மீண்டும் உயிர்ப்பிப்பவன் யார்?\" எனக் கேட்கிறான். நீர் கூறுவீராக: \"முதன் முதலில் அவற்றை உருவாக்கியவனே அவற்றுக்கு உயிர் கொடுப்பான். அவன் ஒவ்வொரு படைப்பையும் நன்கறிந்தவன்.\") (36:77-79).\n\r\n\n\r\nقُل لِّمَنِ الاٌّرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ\n\r\n\n\r\n((நபியே!) நீர் கேளும்: \"பூமியும், அதிலுள்ளவர்களும் யாருக்குச் சொந்தம்? நீங்கள் அறிந்திருந்தால் (கூறுங்கள்).\")\n\r\n\n\r\nسَيَقُولُونَ لِلَّهِ قُلْ أَفَلاَ تَذَكَّرُونَ\n\r\n\n\r\n(\"அல்லாஹ்வுக்கே\" என்று அவர்கள் கூறுவார்கள்; \"அப்படியாயின் நீங்கள் நல்லுணர்வு பெறமாட்டீர்களா?\" என்று நீர் கேட்பீராக!)\n\r\n\n\r\nقُلْ مَن رَّبُّ السَّمَـوَتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْعَظِيمِ\n\r\n\n\r\n(\"ஏழு வானங்களுக்கு இறைவனும், மகத்தான அர்ஷுக்கு இறைவனும் யார்?\" என்று நீர் கேளும்.)\n\r\n\n\r\nسَيَقُولُونَ لِلَّهِ قُلْ أَفَلاَ تَتَّقُونَ\n\r\n\n\r\n(\"அல்லாஹ்வுக்கே\" என்று அவர்கள் கூறுவார்கள். \"அப்படியாயின் நீங்கள் அவனுக்கு அஞ்சமாட்டீர்களா?\" என்று நீர் கேட்பீராக!)"},"84":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"85":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"86":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"87":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"88":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"89":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=90\" class=\"link\">23:90</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:90 ஐ பார்க்கவும்"},"90":{"html":"<strong>இணைவைப்பாளர்கள் தவ்ஹீத் அர்-ருபூபிய்யாவை (இறைவனின் இரட்சகத்தன்மையை) நம்புகின்றனர்; அது அவர்கள் தவ்ஹீத் அல்-உலூஹிய்யாவையும் (வணக்கத்திற்குரியவன் அல்லாஹ் ஒருவனே என்பதை) நம்புவதை அவசியமாக்குகிறது</strong><br />\r\n<br />\r\nஅல்லாஹ் ஒருவன் என்பதும், அவன் தனது படைப்பு, அதிகாரம், ஆட்சி மற்றும் நிர்வாகத்தில் தனித்தவன் என்பதும், அவனைத் தவிர வேறு இறைவனில்லை என்பதையும், இணையில்லாத அவனையே வணங்க வேண்டும் என்பதையும் உணரச் செய்கிறது என்று அல்லாஹ் கூறுகிறான். அவனைத் தவிர மற்றவர்களை வணங்கும் இணைவைப்பாளர்களிடம் —அவர்கள் அவனது இறைமையை (Lordship) ஒப்புக்கொண்ட போதிலும்— 'இறைமையில் அவனுக்குப் பங்குதாரர் எவருமில்லை' என்று கூறுமாறு தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கு அல்லாஹ் கட்டளையிடுகிறான். இருப்பினும், அவர்கள் வணங்கும் சிலைகள் எதையும் படைக்க முடியாது, எதற்கும் உரிமையாளராக இருக்க முடியாது, எதனையும் கட்டுப்படுத்த முடியாது என்று அவர்கள் அறிந்திருந்தும், அவனுக்குத் தெய்வத்தன்மையில் கூட்டாளிகளை ஏற்படுத்தி, அல்லாஹ்வையன்றி மற்றவர்களை வணங்கினர். அந்தப் படைப்புகள் தங்களை அல்லாஹ்விடம் நெருக்கமாக்கும் என்று அவர்கள் நம்பினர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نَعْبُدُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِيُقَرِّبُونَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">زُلْفَى</span><br />\r\n<br />\r\n(நாங்கள் அவர்களை வணங்குவதெல்லாம், அவர்கள் எங்களை அல்லாஹ்விடம் நெருக்கமாக்கி வைப்பார்கள் என்பதற்காகவேயன்றி வேறில்லை) <a href=\"qurandisp.php?sura=39&ayah=3\" class=\"link\">39:3</a>. எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لِّمَنِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span><br />\r\n<br />\r\n(\"பூமியும் அதிலுள்ளவைகளும் யாருக்குச் சொந்தமானவை?\" என்று கேளுங்கள்) அதாவது, \"இவற்றைப் படைத்த உரிமையாளர் யார்? இதிலுள்ள விலங்குகள், தாவரங்கள், கனிகள் மற்றும் ஏனைய படைப்பினங்களைப் படைத்தவர் யார்?\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span> - <span class=\"quran-arabic-font text-success\">سَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span><br />\r\n<br />\r\n(\"நீங்கள் அறிந்திருந்தால் (கூறுங்கள்)!\" அவர்கள் \"அல்லாஹ்வுக்கே!\" என்று கூறுவார்கள்) அதாவது, இவை அனைத்தும் எவ்விதத் துணையுமின்றி அல்லாஹ் ஒருவனுக்கே உரியது என்பதை அவர்கள் ஒப்புக்கொள்வார்கள். அவ்வாறாயின்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span><br />\r\n<br />\r\n(நீர் கேளும்: \"அப்படியாயின் நீங்கள் (சிந்தித்து) உணர்வு பெற மாட்டீர்களா?\") அதாவது, படைப்பவனையும் வாழ்வாதாரம் அளிப்பவனையும் தவிர வேறு எவரும் வணங்கப்படத் தகுதியானவர் அல்ல என்பதை உணர மாட்டீர்களா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">رَّبُّ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">السَّبْعِ</span> <span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(\"ஏழு வானங்களின் இறைவன் யார்? மகத்தான அர்ஷின் இறைவன் யார்?\" என்று கேளுங்கள்) அதாவது, \"உயர்ந்த உலகங்களையும், அங்கிருக்கும் கோள்கள், ஒளிகள் மற்றும் எல்லா திசைகளிலும் அவனுக்குக் கீழ்ப்படியும் வானவர்களையும் படைத்தவர் யார்? படைக்கப்பட்டவற்றிலேயே மிகவும் உயர்ந்ததான மகத்தான அர்ஷின் இறைவன் யார்?\" அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span><br />\r\n<br />\r\n(மகத்தான அர்ஷின் இறைவன்), அதாவது வலிமைமிக்க அர்ஷ். இந்த அத்தியாயத்தின் இறுதியில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمِ</span><br />\r\n<br />\r\n(கண்ணியமிக்க அர்ஷின் இறைவன்!) <a href=\"qurandisp.php?sura=23&ayah=116\" class=\"link\">23:116</a>, அதாவது மிக உன்னதமான மற்றும் மகத்துவமிக்கது. அர்ஷ் என்பது உயரம், விசாலம், பிரம்மாண்டம் மற்றும் மகத்துவம் ஆகிய சிறப்புகளைத் தன்னகத்தே கொண்டது. அதனால்தான் அது சிவப்பு மாணிக்கக் கற்களால் ஆனது என்று கூறப்படுகிறது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"உங்களது இறைவனிடம் இரவு அல்லது பகல் என்பது இல்லை; அர்ஷின் ஒளியானது அவனது திருமுகத்தின் ஒளியிலிருந்தே பிரகாசிக்கிறது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span><br />\r\n<br />\r\n(அவர்கள் \"அல்லாஹ்வுக்கே\" என்று கூறுவார்கள். நீர் கேளும்: \"அப்படியாயின் நீங்கள் (அவனுக்கு) அஞ்ச மாட்டீர்களா?\") அதாவது, அவனே வானங்களின் இறைவன் என்றும் மகத்தான அர்ஷின் இறைவன் என்றும் நீங்கள் ஒப்புக்கொண்ட பிறகு, அவனுக்கு இணைகளை ஏற்படுத்தி வணங்குவதற்காக அவனது தண்டனையை நீங்கள் பயப்படமாட்டீர்களா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">مَلَكُوتُ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(கேளுங்கள்: \"ஒவ்வொரு பொருளின் மீதான முழு அதிகாரமும் யாருடைய கையில் இருக்கிறது?\") அதாவது, முழுமையான அதிகாரம் அவனது கைகளிலேயே உள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَآبَّةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">آخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِنَاصِيَتِهَا</span><br />\r\n<br />\r\n(எந்த ஒரு உயிரினமானாலும் அதன் முன்நெற்றியை அவன் பிடித்தவனாகவே இருக்கிறான்) <a href=\"qurandisp.php?sura=11&ayah=56\" class=\"link\">11:56</a>. அதாவது, அவன் அவற்றின் மீது முழுக் கட்டுப்பாடு வைத்துள்ளான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சத்தியம் செய்யும்போது,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِه</span>»<br />\r\n<br />\r\n(எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக!) என்றும், சத்தியம் செய்யும்போது,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">وَمُقَلِّبِ</span> <span class=\"quran-arabic-font text-success\">الْقُلُوب</span>»<br />\r\n<br />\r\n(உள்ளங்களைப் புரட்டுபவன் மீது சத்தியமாக!) என்றும் கூறுவார்கள். தூயவனாகிய அவனே படைப்பவன், அதிபதி மற்றும் அனைத்தையும் கட்டுப்படுத்துபவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">يُجْيِرُ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُجَارُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n(அவன் பாதுகாப்பளிக்கிறான்; அவனுக்கு எதிராக எவரும் பாதுகாக்கப்பட முடியாது, நீங்கள் அறிந்திருந்தால்!) அரபிகளிடையே ஒரு வழக்கம் இருந்தது; ஒரு தலைவர் ஒருவருக்குப் பாதுகாப்பு அளிப்பதாக அறிவித்துவிட்டால், அவருக்கு எதிராக யாரும் செல்ல முடியாது. ஆனால், அந்தத் தலைவரிடமிருந்து எவரும் எவருக்கும் பாதுகாப்பு அளிக்க முடியாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">يُجْيِرُ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُجَارُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(அவன் பாதுகாப்பளிக்கிறான்; அவனுக்கு எதிராக எவரும் பாதுகாக்கப்பட முடியாது,) அதாவது, அவனே மிக உன்னதமான எஜமானன், அவனை விடப் பெரியவர் எவருமில்லை. படைப்பதும் கட்டளையிடுவதும் அவனுக்கே உரிய அதிகாரம். அவனது தீர்ப்பை எவராலும் மாற்றவோ எதிர்க்கவோ முடியாது. அவன் நாடியது நடக்கும், அவன் நாடாதது நடக்காது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُسْأَلُ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يُسْأَلُونَ</span><br />\r\n<br />\r\n(அவன் செய்பவை பற்றி எவராலும் கேள்வி கேட்கப்பட முடியாது; ஆனால் அவர்கள் (படைப்புகள்) கேள்வி கேட்கப்படுவார்கள்.) <a href=\"qurandisp.php?sura=21&ayah=23\" class=\"link\">21:23</a> அவனது மகத்துவம், பெருமை, அடக்கியாளும் வல்லமை, ஞானம் மற்றும் நீதி ஆகியவற்றின் காரணமாக அவன் செய்வதைப் பற்றி எவரும் கேட்க முடியாது. ஆனால் படைப்புகள் அனைத்தும் அவை செய்த செயல்கள் குறித்து வினவப்படும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوَرَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لَنَسْأَلَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span> - <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span><br />\r\n<br />\r\n(உமது இறைவன் மீது சத்தியமாக! அவர்கள் செய்து கொண்டிருந்தவை பற்றி நாம் அவர்கள் அனைவரிடமும் நிச்சயமாகக் கேள்வி கேட்போம்.) <a href=\"qurandisp.php?sura=15&ayah=92\" class=\"link\">15:92</a>-93<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span><br />\r\n<br />\r\n(அவர்கள் \"(இவை அனைத்தும்) அல்லாஹ்வுக்கே\" என்று கூறுவார்கள்.) அதாவது, அனைவருக்கும் பாதுகாப்பளிப்பவனும், தனக்கு எதிராகப் பாதுகாப்பவர் எவருமில்லாதவனும் ஆகிய எல்லாம் வல்ல எஜமானன், எவ்விதக் கூட்டாளியுமற்ற அல்லாஹ் ஒருவனே என்பதை அவர்கள் ஒப்புக்கொள்வார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">فَأَنَّى</span> <span class=\"quran-arabic-font text-success\">تُسْحَرُونَ</span><br />\r\n<br />\r\n(நீர் கேளும்: \"அப்படியாயின் நீங்கள் எவ்வாறு மதிமயக்கப்பட்டு (உண்மையை விட்டும்) திருப்பப்படுகிறீர்கள்?\") அதாவது, இவற்றை நீங்கள் அங்கீகரித்து ஒப்புக்கொண்ட பிறகு, அவனையன்றி மற்றவர்களை வணங்குவதை உங்கள் புத்தி எவ்வாறு ஏற்கிறது? பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَتَيْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span><br />\r\n<br />\r\n(மாறாக, நாம் அவர்களிடம் சத்தியத்தையே கொண்டு வந்திருக்கிறோம்,) அதாவது, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை என்ற பிரகடனத்தையும், அதற்கான தெளிவான, உறுதியான மற்றும் சரியான ஆதாரங்களையும் வழங்கியுள்ளோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَاذِبُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே.) அதாவது, எவ்வித ஆதாரமும் இன்றி அல்லாஹ்வுக்கு இணையாக மற்றவர்களை வணங்குவதில் அவர்கள் பொய்யர்களாக இருக்கிறார்கள். இந்த அத்தியாயத்தின் இறுதியில் அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَدْعُ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَٰهًا</span> <span class=\"quran-arabic-font text-success\">آخَرَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">بُرْهَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">حِسَابُهُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُفْلِحُ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُونَ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளை எவன் அழைக்கிறானோ, அதற்கோ அவனிடம் எந்த ஆதாரமும் இல்லை; அவனது விசாரணை அவனது இறைவனிடமே இருக்கிறது. நிச்சயமாக நிராகரிப்பாளர்கள் வெற்றி பெற மாட்டார்கள்.) <a href=\"qurandisp.php?sura=23&ayah=117\" class=\"link\">23:117</a> இணைவைப்பாளர்கள் தாங்கள் செய்வதற்கு எந்த ஆதாரமும் வைத்திருக்கவில்லை; இது அவர்களைப் பொய்களுக்கும் வழிகேட்டிற்கும் இட்டுச் சென்றுள்ளது. அவர்கள் குழப்பத்திலும் அறியாமையிலும் இருந்த தங்கள் முன்னோர்களையே பின்பற்றுகின்றனர். அல்லாஹ் அவர்களை இவ்வாறு விவரிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أُمَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">آثَارِهِم</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدُونَ</span><br />\r\n<br />\r\n(\"நாங்கள் எங்கள் முன்னோர்களை ஒரு வழியில் (மதத்தில்) கண்டோம்; நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்.\") <a href=\"qurandisp.php?sura=43&ayah=23\" class=\"link\">43:23</a><br />\r\n<br />","text":"இணைவைப்பாளர்கள் தவ்ஹீத் அர்-ருபூபிய்யாவை (இறைவனின் இரட்சகத்தன்மையை) நம்புகின்றனர்; அது அவர்கள் தவ்ஹீத் அல்-உலூஹிய்யாவையும் (வணக்கத்திற்குரியவன் அல்லாஹ் ஒருவனே என்பதை) நம்புவதை அவசியமாக்குகிறது\n\r\n\n\r\nஅல்லாஹ் ஒருவன் என்பதும், அவன் தனது படைப்பு, அதிகாரம், ஆட்சி மற்றும் நிர்வாகத்தில் தனித்தவன் என்பதும், அவனைத் தவிர வேறு இறைவனில்லை என்பதையும், இணையில்லாத அவனையே வணங்க வேண்டும் என்பதையும் உணரச் செய்கிறது என்று அல்லாஹ் கூறுகிறான். அவனைத் தவிர மற்றவர்களை வணங்கும் இணைவைப்பாளர்களிடம் —அவர்கள் அவனது இறைமையை (Lordship) ஒப்புக்கொண்ட போதிலும்— 'இறைமையில் அவனுக்குப் பங்குதாரர் எவருமில்லை' என்று கூறுமாறு தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்கு அல்லாஹ் கட்டளையிடுகிறான். இருப்பினும், அவர்கள் வணங்கும் சிலைகள் எதையும் படைக்க முடியாது, எதற்கும் உரிமையாளராக இருக்க முடியாது, எதனையும் கட்டுப்படுத்த முடியாது என்று அவர்கள் அறிந்திருந்தும், அவனுக்குத் தெய்வத்தன்மையில் கூட்டாளிகளை ஏற்படுத்தி, அல்லாஹ்வையன்றி மற்றவர்களை வணங்கினர். அந்தப் படைப்புகள் தங்களை அல்லாஹ்விடம் நெருக்கமாக்கும் என்று அவர்கள் நம்பினர்:\n\r\n\n\r\nمَا نَعْبُدُهُمْ إِلاَّ لِيُقَرِّبُونَآ إِلَى اللَّهِ زُلْفَى\n\r\n\n\r\n(நாங்கள் அவர்களை வணங்குவதெல்லாம், அவர்கள் எங்களை அல்லாஹ்விடம் நெருக்கமாக்கி வைப்பார்கள் என்பதற்காகவேயன்றி வேறில்லை) 39:3. எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُل لِّمَنِ الْأَرْضُ وَمَن فِيهَآ\n\r\n\n\r\n(\"பூமியும் அதிலுள்ளவைகளும் யாருக்குச் சொந்தமானவை?\" என்று கேளுங்கள்) அதாவது, \"இவற்றைப் படைத்த உரிமையாளர் யார்? இதிலுள்ள விலங்குகள், தாவரங்கள், கனிகள் மற்றும் ஏனைய படைப்பினங்களைப் படைத்தவர் யார்?\"\n\r\n\n\r\nإِن كُنتُمْ تَعْلَمُونَ - سَيَقُولُونَ لِلَّهِ\n\r\n\n\r\n(\"நீங்கள் அறிந்திருந்தால் (கூறுங்கள்)!\" அவர்கள் \"அல்லாஹ்வுக்கே!\" என்று கூறுவார்கள்) அதாவது, இவை அனைத்தும் எவ்விதத் துணையுமின்றி அல்லாஹ் ஒருவனுக்கே உரியது என்பதை அவர்கள் ஒப்புக்கொள்வார்கள். அவ்வாறாயின்,\n\r\n\n\r\nقُلْ أَفَلاَ تَذَكَّرُونَ\n\r\n\n\r\n(நீர் கேளும்: \"அப்படியாயின் நீங்கள் (சிந்தித்து) உணர்வு பெற மாட்டீர்களா?\") அதாவது, படைப்பவனையும் வாழ்வாதாரம் அளிப்பவனையும் தவிர வேறு எவரும் வணங்கப்படத் தகுதியானவர் அல்ல என்பதை உணர மாட்டீர்களா?\n\r\n\n\r\nقُلْ مَن رَّبُّ السَّمَاوَاتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْعَظِيمِ\n\r\n\n\r\n(\"ஏழு வானங்களின் இறைவன் யார்? மகத்தான அர்ஷின் இறைவன் யார்?\" என்று கேளுங்கள்) அதாவது, \"உயர்ந்த உலகங்களையும், அங்கிருக்கும் கோள்கள், ஒளிகள் மற்றும் எல்லா திசைகளிலும் அவனுக்குக் கீழ்ப்படியும் வானவர்களையும் படைத்தவர் யார்? படைக்கப்பட்டவற்றிலேயே மிகவும் உயர்ந்ததான மகத்தான அர்ஷின் இறைவன் யார்?\" அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nوَرَبُّ الْعَرْشِ الْعَظِيمِ\n\r\n\n\r\n(மகத்தான அர்ஷின் இறைவன்), அதாவது வலிமைமிக்க அர்ஷ். இந்த அத்தியாயத்தின் இறுதியில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nرَبُّ الْعَرْشِ الْكَرِيمِ\n\r\n\n\r\n(கண்ணியமிக்க அர்ஷின் இறைவன்!) 23:116, அதாவது மிக உன்னதமான மற்றும் மகத்துவமிக்கது. அர்ஷ் என்பது உயரம், விசாலம், பிரம்மாண்டம் மற்றும் மகத்துவம் ஆகிய சிறப்புகளைத் தன்னகத்தே கொண்டது. அதனால்தான் அது சிவப்பு மாணிக்கக் கற்களால் ஆனது என்று கூறப்படுகிறது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"உங்களது இறைவனிடம் இரவு அல்லது பகல் என்பது இல்லை; அர்ஷின் ஒளியானது அவனது திருமுகத்தின் ஒளியிலிருந்தே பிரகாசிக்கிறது.\"\n\r\n\n\r\nسَيَقُولُونَ لِلَّهِ قُلْ أَفَلاَ تَتَّقُونَ\n\r\n\n\r\n(அவர்கள் \"அல்லாஹ்வுக்கே\" என்று கூறுவார்கள். நீர் கேளும்: \"அப்படியாயின் நீங்கள் (அவனுக்கு) அஞ்ச மாட்டீர்களா?\") அதாவது, அவனே வானங்களின் இறைவன் என்றும் மகத்தான அர்ஷின் இறைவன் என்றும் நீங்கள் ஒப்புக்கொண்ட பிறகு, அவனுக்கு இணைகளை ஏற்படுத்தி வணங்குவதற்காக அவனது தண்டனையை நீங்கள் பயப்படமாட்டீர்களா?\n\r\n\n\r\nقُلْ مَن بِيَدِهِ مَلَكُوتُ كُلِّ شَىْءٍ\n\r\n\n\r\n(கேளுங்கள்: \"ஒவ்வொரு பொருளின் மீதான முழு அதிகாரமும் யாருடைய கையில் இருக்கிறது?\") அதாவது, முழுமையான அதிகாரம் அவனது கைகளிலேயே உள்ளது.\n\r\n\n\r\nمَّا مِن دَآبَّةٍ إِلاَّ هُوَ آخِذٌ بِنَاصِيَتِهَا\n\r\n\n\r\n(எந்த ஒரு உயிரினமானாலும் அதன் முன்நெற்றியை அவன் பிடித்தவனாகவே இருக்கிறான்) 11:56. அதாவது, அவன் அவற்றின் மீது முழுக் கட்டுப்பாடு வைத்துள்ளான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சத்தியம் செய்யும்போது,\n\r\n\n\r\n«لَا وَالَّذِي نَفْسِي بِيَدِه»\n\r\n\n\r\n(எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக!) என்றும், சத்தியம் செய்யும்போது,\n\r\n\n\r\n«لَا وَمُقَلِّبِ الْقُلُوب»\n\r\n\n\r\n(உள்ளங்களைப் புரட்டுபவன் மீது சத்தியமாக!) என்றும் கூறுவார்கள். தூயவனாகிய அவனே படைப்பவன், அதிபதி மற்றும் அனைத்தையும் கட்டுப்படுத்துபவன்.\n\r\n\n\r\nوَهُوَ يُجْيِرُ وَلاَ يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ\n\r\n\n\r\n(அவன் பாதுகாப்பளிக்கிறான்; அவனுக்கு எதிராக எவரும் பாதுகாக்கப்பட முடியாது, நீங்கள் அறிந்திருந்தால்!) அரபிகளிடையே ஒரு வழக்கம் இருந்தது; ஒரு தலைவர் ஒருவருக்குப் பாதுகாப்பு அளிப்பதாக அறிவித்துவிட்டால், அவருக்கு எதிராக யாரும் செல்ல முடியாது. ஆனால், அந்தத் தலைவரிடமிருந்து எவரும் எவருக்கும் பாதுகாப்பு அளிக்க முடியாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَهُوَ يُجْيِرُ وَلاَ يُجَارُ عَلَيْهِ\n\r\n\n\r\n(அவன் பாதுகாப்பளிக்கிறான்; அவனுக்கு எதிராக எவரும் பாதுகாக்கப்பட முடியாது,) அதாவது, அவனே மிக உன்னதமான எஜமானன், அவனை விடப் பெரியவர் எவருமில்லை. படைப்பதும் கட்டளையிடுவதும் அவனுக்கே உரிய அதிகாரம். அவனது தீர்ப்பை எவராலும் மாற்றவோ எதிர்க்கவோ முடியாது. அவன் நாடியது நடக்கும், அவன் நாடாதது நடக்காது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَ يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ\n\r\n\n\r\n(அவன் செய்பவை பற்றி எவராலும் கேள்வி கேட்கப்பட முடியாது; ஆனால் அவர்கள் (படைப்புகள்) கேள்வி கேட்கப்படுவார்கள்.) 21:23 அவனது மகத்துவம், பெருமை, அடக்கியாளும் வல்லமை, ஞானம் மற்றும் நீதி ஆகியவற்றின் காரணமாக அவன் செய்வதைப் பற்றி எவரும் கேட்க முடியாது. ஆனால் படைப்புகள் அனைத்தும் அவை செய்த செயல்கள் குறித்து வினவப்படும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ - عَمَّا كَانُواْ يَعْمَلُونَ\n\r\n\n\r\n(உமது இறைவன் மீது சத்தியமாக! அவர்கள் செய்து கொண்டிருந்தவை பற்றி நாம் அவர்கள் அனைவரிடமும் நிச்சயமாகக் கேள்வி கேட்போம்.) 15:92-93\n\r\n\n\r\nسَيَقُولُونَ لِلَّهِ\n\r\n\n\r\n(அவர்கள் \"(இவை அனைத்தும்) அல்லாஹ்வுக்கே\" என்று கூறுவார்கள்.) அதாவது, அனைவருக்கும் பாதுகாப்பளிப்பவனும், தனக்கு எதிராகப் பாதுகாப்பவர் எவருமில்லாதவனும் ஆகிய எல்லாம் வல்ல எஜமானன், எவ்விதக் கூட்டாளியுமற்ற அல்லாஹ் ஒருவனே என்பதை அவர்கள் ஒப்புக்கொள்வார்கள்.\n\r\n\n\r\nقُلْ فَأَنَّى تُسْحَرُونَ\n\r\n\n\r\n(நீர் கேளும்: \"அப்படியாயின் நீங்கள் எவ்வாறு மதிமயக்கப்பட்டு (உண்மையை விட்டும்) திருப்பப்படுகிறீர்கள்?\") அதாவது, இவற்றை நீங்கள் அங்கீகரித்து ஒப்புக்கொண்ட பிறகு, அவனையன்றி மற்றவர்களை வணங்குவதை உங்கள் புத்தி எவ்வாறு ஏற்கிறது? பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبَلْ أَتَيْنَاهُم بِالْحَقِّ\n\r\n\n\r\n(மாறாக, நாம் அவர்களிடம் சத்தியத்தையே கொண்டு வந்திருக்கிறோம்,) அதாவது, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை என்ற பிரகடனத்தையும், அதற்கான தெளிவான, உறுதியான மற்றும் சரியான ஆதாரங்களையும் வழங்கியுள்ளோம்.\n\r\n\n\r\nوَإِنَّهُمْ لَكَاذِبُونَ\n\r\n\n\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே.) அதாவது, எவ்வித ஆதாரமும் இன்றி அல்லாஹ்வுக்கு இணையாக மற்றவர்களை வணங்குவதில் அவர்கள் பொய்யர்களாக இருக்கிறார்கள். இந்த அத்தியாயத்தின் இறுதியில் அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nوَمَن يَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ لاَ بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ إِنَّهُ لاَ يُفْلِحُ الْكَافِرُونَ\n\r\n\n\r\n(மேலும் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளை எவன் அழைக்கிறானோ, அதற்கோ அவனிடம் எந்த ஆதாரமும் இல்லை; அவனது விசாரணை அவனது இறைவனிடமே இருக்கிறது. நிச்சயமாக நிராகரிப்பாளர்கள் வெற்றி பெற மாட்டார்கள்.) 23:117 இணைவைப்பாளர்கள் தாங்கள் செய்வதற்கு எந்த ஆதாரமும் வைத்திருக்கவில்லை; இது அவர்களைப் பொய்களுக்கும் வழிகேட்டிற்கும் இட்டுச் சென்றுள்ளது. அவர்கள் குழப்பத்திலும் அறியாமையிலும் இருந்த தங்கள் முன்னோர்களையே பின்பற்றுகின்றனர். அல்லாஹ் அவர்களை இவ்வாறு விவரிக்கிறான்:\n\r\n\n\r\nإِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم مُّقْتَدُونَ\n\r\n\n\r\n(\"நாங்கள் எங்கள் முன்னோர்களை ஒரு வழியில் (மதத்தில்) கண்டோம்; நிச்சயமாக நாங்கள் அவர்களின் அடிச்சுவடுகளையே பின்பற்றுவோம்.\") 43:23"},"91":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=92\" class=\"link\">23:92</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:92 ஐ பார்க்கவும்"},"92":{"html":"<strong>அல்லாஹ்வுக்கு எந்தக் கூட்டாளியோ அல்லது இணையோ இல்லை</strong><br />\r\n<br />\r\nஆட்சியிலும், அதிகாரத்திலும், வணக்கத்திலும் தனக்கு எந்தப் பிள்ளையோ அல்லது கூட்டாளியோ இல்லை என்று அல்லாஹ் பிரகடனப்படுத்துகிறான். அவன் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">اتَّخَذَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَلَدٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٍ</span> <span class=\"quran-arabic-font text-success\">إِذًا</span> <span class=\"quran-arabic-font text-success\">لَّذَهَبَ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">وَلَعَلاَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் எந்த மகனையும் ஏற்படுத்திக் கொள்ளவில்லை; அவனுடன் வேறு எந்தக் கடவுளும் இல்லை. அவ்வாறு இருந்திருந்தால், ஒவ்வொரு கடவுளும் தான் படைத்தவற்றைத் தனியே கொண்டு சென்றிருப்பார்; மேலும் அவர்களில் சிலர் மற்றவர்களை மிகைக்க முயன்றிருப்பார்கள்.) அதாவது, ஒன்றுக்கும் மேற்பட்ட கடவுள்கள் இருக்க வேண்டும் என்று விதிக்கப்பட்டிருந்தால், அவர்கள் ஒவ்வொருவரும் தான் படைத்தவற்றின் மீது பிரத்தியேகக் கட்டுப்பாட்டைக் கொண்டிருந்திருப்பார்கள். அதன் விளைவாக, இந்தப் பிரபஞ்சத்தில் ஒருபோதும் ஒழுங்கு இருந்திருக்காது. ஆனால், இந்தப் பிரபஞ்சம் சீராகவும் ஒருங்கிணைந்தும் இருப்பதை நாம் காண்கிறோம்; மேல் உலகங்களும் கீழ் உலகங்களும் மிகவும் நேர்த்தியான முறையில் ஒன்றோடொன்று பிணைக்கப்பட்டுள்ளன.<span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَفَاوُتٍ﴿</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனின் படைப்பில் நீர் எந்தக் குறையையும் காணமாட்டீர்) <a href=\"qurandisp.php?sura=67&ayah=3\" class=\"link\">67:3</a>. மேலும், பல கடவுள்கள் இருந்திருந்தால், அவர்களில் ஒவ்வொருவரும் மற்றவரைப் பகைமையுடன் அடக்க முயன்றிருப்பார்கள், மேலும் ஒருவர் மற்றவர் மீது ஆதிக்கம் செலுத்தியிருப்பார். இதனை 'இல்முல் கலாம்' அறிஞர்கள் 'பரஸ்பர எதிர்ப்பு' (Mutual Resistance) என்ற ஆதாரத்தைக் கொண்டு விளக்கியுள்ளனர். இந்தத் தர்க்கத்தின்படி, இரண்டு அல்லது அதற்கு மேற்பட்ட படைப்பாளர்கள் இருந்தால், அவர்களில் ஒருவர் ஒரு பொருளை அசைக்க விரும்பும்போது மற்றவர் அதை அசையாமல் வைக்க விரும்புவார். இருவராலும் தங்கள் விருப்பத்தை நிறைவேற்ற முடியாவிட்டால், இருவருமே ஆற்றலற்றவர்கள் ஆகிவிடுவார்கள். ஆனால் யாருடைய இருப்பு அவசியமானதோ (வாஜிபுல் வுஜூத்), அந்த அல்லாஹ் ஆற்றலற்றவனாக இருக்க முடியாது. முரண்பாடு காரணமாக இருவருடைய விருப்பமும் ஒரே நேரத்தில் நிறைவேற வாய்ப்பில்லை. இந்தச் சிக்கல் பல கடவுள்கள் இருப்பதாகக் கருதும்போது மட்டுமே எழுகிறது. எனவே, அத்தகைய பன்மைத்துவம் என்பது சாத்தியமற்றது. ஏனெனில், ஒருவரின் விருப்பம் நிறைவேறி, மற்றவருடையது நிறைவேறவில்லை என்றால், வெற்றி பெற்றவரே உண்மையான கடவுளாக இருப்பார்; தோல்வியுற்றவர் தெய்வீகத்தன்மை அற்றவராகவே கருதப்படுவார். ஏனெனில், உண்மையான இறைவன் தோல்வியடைவது என்பது அவனது கண்ணியத்திற்குப் பொருத்தமற்றது. அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَلَعَلاَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يَصِفُونَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்களில் சிலர் மற்றவர்களை மிகைக்க முயன்றிருப்பார்கள்! அவர்கள் வர்ணிப்பவற்றை விட்டும் அல்லாஹ் மிகவும் தூய்மையானவன்!) அதாவது, தனக்கு ஒரு மகன் அல்லது கூட்டாளி இருப்பதாகப் பிடிவாதமான அநியாயக்காரர்கள் கூறுவதை விட்டும் அவன் மிக உயர்ந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَـلِمِ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">وَالشَّهَادَةِ﴿</span><br />\r\n<br />\r\n(மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன்!) அதாவது, தன் படைப்புகளுக்குத் தெரியாதவற்றையும் அவர்கள் காண்பவற்றையும் அவன் நன்கு அறிவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَتَعَـلَى</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் இணை வைப்பவற்றை விட்டும் அவன் மிகவும் உயர்ந்தவன்!) அதாவது, அநியாயக்காரர்களும் பொய்யர்களும் கூறுவதை விட்டும் அவன் பரிசுத்தமானவன், போற்றுதலுக்குரியவன் மற்றும் மிக உயர்ந்தவன்.<br />\r\n<br />","text":"அல்லாஹ்வுக்கு எந்தக் கூட்டாளியோ அல்லது இணையோ இல்லை\n\r\n\n\r\nஆட்சியிலும், அதிகாரத்திலும், வணக்கத்திலும் தனக்கு எந்தப் பிள்ளையோ அல்லது கூட்டாளியோ இல்லை என்று அல்லாஹ் பிரகடனப்படுத்துகிறான். அவன் கூறுகிறான்:﴾مَا اتَّخَذَ اللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ إِلَـهٍ إِذًا لَّذَهَبَ كُلُّ إِلَـهٍ بِمَا خَلَقَ وَلَعَلاَ بَعْضُهُمْ عَلَى بَعْضٍ﴿\n\r\n\n\r\n(அல்லாஹ் எந்த மகனையும் ஏற்படுத்திக் கொள்ளவில்லை; அவனுடன் வேறு எந்தக் கடவுளும் இல்லை. அவ்வாறு இருந்திருந்தால், ஒவ்வொரு கடவுளும் தான் படைத்தவற்றைத் தனியே கொண்டு சென்றிருப்பார்; மேலும் அவர்களில் சிலர் மற்றவர்களை மிகைக்க முயன்றிருப்பார்கள்.) அதாவது, ஒன்றுக்கும் மேற்பட்ட கடவுள்கள் இருக்க வேண்டும் என்று விதிக்கப்பட்டிருந்தால், அவர்கள் ஒவ்வொருவரும் தான் படைத்தவற்றின் மீது பிரத்தியேகக் கட்டுப்பாட்டைக் கொண்டிருந்திருப்பார்கள். அதன் விளைவாக, இந்தப் பிரபஞ்சத்தில் ஒருபோதும் ஒழுங்கு இருந்திருக்காது. ஆனால், இந்தப் பிரபஞ்சம் சீராகவும் ஒருங்கிணைந்தும் இருப்பதை நாம் காண்கிறோம்; மேல் உலகங்களும் கீழ் உலகங்களும் மிகவும் நேர்த்தியான முறையில் ஒன்றோடொன்று பிணைக்கப்பட்டுள்ளன.﴾مَّا تَرَى فِى خَلْقِ الرَّحْمَـنِ مِن تَفَاوُتٍ﴿\n\r\n\n\r\n(அளவற்ற அருளாளனின் படைப்பில் நீர் எந்தக் குறையையும் காணமாட்டீர்) 67:3. மேலும், பல கடவுள்கள் இருந்திருந்தால், அவர்களில் ஒவ்வொருவரும் மற்றவரைப் பகைமையுடன் அடக்க முயன்றிருப்பார்கள், மேலும் ஒருவர் மற்றவர் மீது ஆதிக்கம் செலுத்தியிருப்பார். இதனை 'இல்முல் கலாம்' அறிஞர்கள் 'பரஸ்பர எதிர்ப்பு' (Mutual Resistance) என்ற ஆதாரத்தைக் கொண்டு விளக்கியுள்ளனர். இந்தத் தர்க்கத்தின்படி, இரண்டு அல்லது அதற்கு மேற்பட்ட படைப்பாளர்கள் இருந்தால், அவர்களில் ஒருவர் ஒரு பொருளை அசைக்க விரும்பும்போது மற்றவர் அதை அசையாமல் வைக்க விரும்புவார். இருவராலும் தங்கள் விருப்பத்தை நிறைவேற்ற முடியாவிட்டால், இருவருமே ஆற்றலற்றவர்கள் ஆகிவிடுவார்கள். ஆனால் யாருடைய இருப்பு அவசியமானதோ (வாஜிபுல் வுஜூத்), அந்த அல்லாஹ் ஆற்றலற்றவனாக இருக்க முடியாது. முரண்பாடு காரணமாக இருவருடைய விருப்பமும் ஒரே நேரத்தில் நிறைவேற வாய்ப்பில்லை. இந்தச் சிக்கல் பல கடவுள்கள் இருப்பதாகக் கருதும்போது மட்டுமே எழுகிறது. எனவே, அத்தகைய பன்மைத்துவம் என்பது சாத்தியமற்றது. ஏனெனில், ஒருவரின் விருப்பம் நிறைவேறி, மற்றவருடையது நிறைவேறவில்லை என்றால், வெற்றி பெற்றவரே உண்மையான கடவுளாக இருப்பார்; தோல்வியுற்றவர் தெய்வீகத்தன்மை அற்றவராகவே கருதப்படுவார். ஏனெனில், உண்மையான இறைவன் தோல்வியடைவது என்பது அவனது கண்ணியத்திற்குப் பொருத்தமற்றது. அல்லாஹ் கூறுகிறான்:﴾وَلَعَلاَ بَعْضُهُمْ عَلَى بَعْضٍ سُبْحَـنَ اللَّهِ عَمَّا يَصِفُونَ﴿\n\r\n\n\r\n(மேலும் அவர்களில் சிலர் மற்றவர்களை மிகைக்க முயன்றிருப்பார்கள்! அவர்கள் வர்ணிப்பவற்றை விட்டும் அல்லாஹ் மிகவும் தூய்மையானவன்!) அதாவது, தனக்கு ஒரு மகன் அல்லது கூட்டாளி இருப்பதாகப் பிடிவாதமான அநியாயக்காரர்கள் கூறுவதை விட்டும் அவன் மிக உயர்ந்தவன்.\n\r\n\n\r\n﴾عَـلِمِ الْغَيْبِ وَالشَّهَادَةِ﴿\n\r\n\n\r\n(மறைவானவற்றையும் வெளிப்படையானவற்றையும் நன்கறிந்தவன்!) அதாவது, தன் படைப்புகளுக்குத் தெரியாதவற்றையும் அவர்கள் காண்பவற்றையும் அவன் நன்கு அறிவான்.\n\r\n\n\r\n﴾فَتَعَـلَى عَمَّا يُشْرِكُونَ﴿\n\r\n\n\r\n(அவர்கள் இணை வைப்பவற்றை விட்டும் அவன் மிகவும் உயர்ந்தவன்!) அதாவது, அநியாயக்காரர்களும் பொய்யர்களும் கூறுவதை விட்டும் அவன் பரிசுத்தமானவன், போற்றுதலுக்குரியவன் மற்றும் மிக உயர்ந்தவன்."},"93":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=98\" class=\"link\">23:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:98 ஐ பார்க்கவும்"},"94":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=98\" class=\"link\">23:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:98 ஐ பார்க்கவும்"},"95":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=98\" class=\"link\">23:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:98 ஐ பார்க்கவும்"},"96":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=98\" class=\"link\">23:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:98 ஐ பார்க்கவும்"},"97":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=98\" class=\"link\">23:98</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:98 ஐ பார்க்கவும்"},"98":{"html":"<strong>சோதனைகள் ஏற்படும்போது அல்லாஹ்வைப் பிரார்த்திப்பதற்கும், தீமையை நன்மையால் தடுப்பதற்கும், அல்லாஹ்விடம் பாதுகாப்புத் தேடுவதற்குமான கட்டளை</strong><br />\r\n<br />\r\nசோதனைகள் ஏற்படும்போது, அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களை இந்தத் துஆவின் மூலம் பிரார்த்திக்குமாறு பணிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">إِمَّا</span> <span class=\"quran-arabic-font text-success\">تُرِيَنِّى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span>  - <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْنِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span><br />\r\n<br />\r\n(என் இறைவா! அவர்களுக்கு வாக்களிக்கப்பட்ட (வேதனையை) எனக்கு நீ காட்டினால்,) என் இறைவா! அநியாயக்காரக் கூட்டத்தாருடன் என்னை நீ ஆக்கிவிடாதே! அதாவது, \"நான் பார்த்துக் கொண்டிருக்கும்போதே நீ அவர்களைத் தண்டித்தால், என்னை அக்கூட்டத்தாருடன் ஆக்கிவிடாதே\" என்று பொருளாகும். இமாம் அஹ்மத் மற்றும் அத்-திர்மிதி ஆகியோரால் பதிவு செய்யப்பட்டு, 'ஸஹீஹ்' என வகைப்படுத்தப்பட்ட ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">أَرَدْتَ</span> <span class=\"quran-arabic-font text-success\">بِقَومٍ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">فَتَوفَّنِي</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَفْتُون</span>»<br />\r\n<br />\r\n(நீ ஒரு கூட்டத்தாரைச் சோதிக்க நாடினால், அந்தச் சோதனைக்கு நான் ஆளாகாத நிலையில் என்னை உன்னளவில் மரணிக்கச் செய்திடு.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نُّرِيَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نَعِدُهُمْ</span> <span class=\"quran-arabic-font text-success\">لَقَادِرُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவர்களுக்கு வாக்களித்த (வேதனையை) உமக்குக் காட்ட நாம் பேராற்றல் உடையவர்களாவோம்.) அதாவது, \"நாம் நாடினால் அவர்கள் மீது இறக்கவிருக்கும் தண்டனையையும் சோதனையையும் உமக்குக் காட்ட முடியும்\" என்று அல்லாஹ் கூறுகிறான். பிறகு, மக்களுடன் பழகும்போது கடைபிடிக்க வேண்டிய மிகச் சிறந்த வழியை அல்லாஹ் அவருக்குக் காட்டுகிறான்; அதாவது, தன்னிடம் தீமையாக நடப்பவரிடமும் கனிவாக நடந்துகொள்வதாகும். அவ்வாறு செய்வதன் மூலம் அவரது உள்ளம் மென்மையடையும்; பகைமை நட்பாகவும், வெறுப்பு அன்பாகவும் மாறும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْفَعْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَةَ</span><br />\r\n<br />\r\n(தீமையை மிக அழகிய நன்மையைக் கொண்டு நீர் தடுத்திடுவீராக.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْفَعْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">بَيْنَكَ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">عَدَاوَةٌ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">وَلِىٌّ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٌ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُلَقَّاهَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span><br />\r\n<br />\r\n((தீமையை) எது மிக அழகியதோ அதைக் கொண்டு தடுத்திடுவீராக! அப்போது, உமக்கும் எவருக்கும் இடையில் பகை இருந்ததோ, அவர் ஒரு நெருங்கிய நண்பரைப் போலாகிவிடுவார். பொறுமையாக இருப்பவர்களைத் தவிர வேறு எவருக்கும் இது வழங்கப்படாது.) (<a href=\"qurandisp.php?sura=41&ayah=34\" class=\"link\">41:34</a>-35). அதாவது, இத்தகைய பண்பினைப் பெறவோ அல்லது இந்த அறிவுரையைப் பின்பற்றவோ எவருக்கும் இப்பாக்கியம் வழங்கப்பட மாட்டாது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span><br />\r\n<br />\r\n(பொறுமையாளர்களைத் தவிர.) அதாவது, மக்களின் சொல்லம்புகளையும், தீய நடத்தைகளையும் பொறுமையுடன் சகித்துக்கொண்டு, அவர்கள் தமக்குத் தீங்கு செய்யும்போது பதிலுக்கு நன்மையைச் செய்பவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُلَقَّاهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">حَظِّ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n(மேலும், மகத்தான பாக்கியம் உடையவர்களைத் தவிர வேறு எவருக்கும் இது வழங்கப்படாது.) இதன் பொருள், இவ்வுலகிலும் மறுமையிலும் (அவர்களுக்கு நற்பேறு உண்டு) என்பதாகும். மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَمَزَاتِ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينِ</span><br />\r\n<br />\r\n(மேலும் கூறுவீராக: \"என் இறைவா! ஷைத்தான்களின் ஊசலாட்டங்களை விட்டும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.\")<br />\r\n<br />\r\nஷைத்தான்களிடமிருந்து தன்னிடம் பாதுகாப்புத் தேடுமாறு அல்லாஹ் அவருக்குக் கட்டளையிட்டான். ஏனெனில் அவர்களுக்கு எதிராக எந்தத் தந்திரமும் பலிக்காது; அவர்களிடம் கனிவாக நடப்பதன் மூலம் உங்களைப் பாதுகாத்துக்கொள்ளவும் முடியாது. 'இஸ்திஆதா' (பாதுகாப்புத் தேடுதல்) பற்றி விளக்கும்போது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறுவார்கள் என்று நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">الرَّجِيمِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَمْزِهِ</span> <span class=\"quran-arabic-font text-success\">وَنَفْخِهِ</span> <span class=\"quran-arabic-font text-success\">وَنَفْثِه</span>»<br />\r\n<br />\r\n(அனைத்தையும் செவியேற்பவனும், அறிபவனுமாகிய அல்லாஹ்விடம், சபிக்கப்பட்ட ஷைத்தானிடமிருந்தும், அவனது ஊசலாட்டங்கள், அவனது தீய எண்ணங்கள் மற்றும் தூண்டுதல்களிலிருந்தும் நான் பாதுகாப்புத் தேடுகிறேன்.)<br />\r\n<br />\r\nஅவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَحْضُرُونِ</span><br />\r\n<br />\r\n(\"என் இறைவா! அவர்கள் என்னிடம் வருவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.\") இதன் பொருள், \"எனது வாழ்க்கையின் ஒவ்வொரு விவகாரத்திலும் அவர்கள் நெருங்குவதை விட்டும் பாதுகாப்புத் தேடுகிறேன்\" என்பதாகும்.<br />\r\n<br />\r\nஎனவே உண்ணும்போது, தாம்பத்திய உறவு கொள்ளும்போது, உணவுக்காக விலங்குகளை அறுக்கும்போது என எந்தவொரு காரியத்தைத் தொடங்கும்போதும் ஷைத்தான்களை விரட்டுவதற்காக அல்லாஹ்வின் திருப்பெயரைக் கூறுமாறு நாம் பணிக்கப்பட்டுள்ளோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறுவார்கள் என அபூதாவூத் (ரஹ்) பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْهَرَمِ،</span> <span class=\"quran-arabic-font text-success\">وَأَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْهَدْمِ</span> <span class=\"quran-arabic-font text-success\">وَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْغَرَقِ،</span> <span class=\"quran-arabic-font text-success\">وَأَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَتَخَبَّطَنِي</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانُ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">الْمَوْت</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! தள்ளாத முதுமையிலிருந்து உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். கட்டிடம் இடிந்து விழுவதிலிருந்தும், நீரில் மூழ்குவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். மரணத்தின்போது ஷைத்தான் என்னை நிலைகுலையச் செய்வதிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.)<br />\r\n<br />","text":"சோதனைகள் ஏற்படும்போது அல்லாஹ்வைப் பிரார்த்திப்பதற்கும், தீமையை நன்மையால் தடுப்பதற்கும், அல்லாஹ்விடம் பாதுகாப்புத் தேடுவதற்குமான கட்டளை\n\r\n\n\r\nசோதனைகள் ஏற்படும்போது, அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களை இந்தத் துஆவின் மூலம் பிரார்த்திக்குமாறு பணிக்கிறான்:\n\r\n\n\r\nرَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ  - رَبِّ فَلاَ تَجْعَلْنِى فِى الْقَوْمِ الظَّالِمِينَ\n\r\n\n\r\n(என் இறைவா! அவர்களுக்கு வாக்களிக்கப்பட்ட (வேதனையை) எனக்கு நீ காட்டினால்,) என் இறைவா! அநியாயக்காரக் கூட்டத்தாருடன் என்னை நீ ஆக்கிவிடாதே! அதாவது, \"நான் பார்த்துக் கொண்டிருக்கும்போதே நீ அவர்களைத் தண்டித்தால், என்னை அக்கூட்டத்தாருடன் ஆக்கிவிடாதே\" என்று பொருளாகும். இமாம் அஹ்மத் மற்றும் அத்-திர்மிதி ஆகியோரால் பதிவு செய்யப்பட்டு, 'ஸஹீஹ்' என வகைப்படுத்தப்பட்ட ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:\n\r\n\n\r\n«وَإِذَا أَرَدْتَ بِقَومٍ فِتْنَةً فَتَوفَّنِي إِلَيْكَ غَيْرَ مَفْتُون»\n\r\n\n\r\n(நீ ஒரு கூட்டத்தாரைச் சோதிக்க நாடினால், அந்தச் சோதனைக்கு நான் ஆளாகாத நிலையில் என்னை உன்னளவில் மரணிக்கச் செய்திடு.)\n\r\n\n\r\nوَإِنَّا عَلَى أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَادِرُونَ\n\r\n\n\r\n(நிச்சயமாக நாம் அவர்களுக்கு வாக்களித்த (வேதனையை) உமக்குக் காட்ட நாம் பேராற்றல் உடையவர்களாவோம்.) அதாவது, \"நாம் நாடினால் அவர்கள் மீது இறக்கவிருக்கும் தண்டனையையும் சோதனையையும் உமக்குக் காட்ட முடியும்\" என்று அல்லாஹ் கூறுகிறான். பிறகு, மக்களுடன் பழகும்போது கடைபிடிக்க வேண்டிய மிகச் சிறந்த வழியை அல்லாஹ் அவருக்குக் காட்டுகிறான்; அதாவது, தன்னிடம் தீமையாக நடப்பவரிடமும் கனிவாக நடந்துகொள்வதாகும். அவ்வாறு செய்வதன் மூலம் அவரது உள்ளம் மென்மையடையும்; பகைமை நட்பாகவும், வெறுப்பு அன்பாகவும் மாறும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nادْفَعْ بِالَّتِى هِىَ أَحْسَنُ السَّيِّئَةَ\n\r\n\n\r\n(தீமையை மிக அழகிய நன்மையைக் கொண்டு நீர் தடுத்திடுவீராக.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nادْفَعْ بِالَّتِى هِىَ أَحْسَنُ فَإِذَا الَّذِى بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِىٌّ حَمِيمٌ وَمَا يُلَقَّاهَا إِلاَّ الَّذِينَ صَبَرُواْ\n\r\n\n\r\n((தீமையை) எது மிக அழகியதோ அதைக் கொண்டு தடுத்திடுவீராக! அப்போது, உமக்கும் எவருக்கும் இடையில் பகை இருந்ததோ, அவர் ஒரு நெருங்கிய நண்பரைப் போலாகிவிடுவார். பொறுமையாக இருப்பவர்களைத் தவிர வேறு எவருக்கும் இது வழங்கப்படாது.) (41:34-35). அதாவது, இத்தகைய பண்பினைப் பெறவோ அல்லது இந்த அறிவுரையைப் பின்பற்றவோ எவருக்கும் இப்பாக்கியம் வழங்கப்பட மாட்டாது,\n\r\n\n\r\nإِلاَّ الَّذِينَ صَبَرُواْ\n\r\n\n\r\n(பொறுமையாளர்களைத் தவிர.) அதாவது, மக்களின் சொல்லம்புகளையும், தீய நடத்தைகளையும் பொறுமையுடன் சகித்துக்கொண்டு, அவர்கள் தமக்குத் தீங்கு செய்யும்போது பதிலுக்கு நன்மையைச் செய்பவர்கள்.\n\r\n\n\r\nوَمَا يُلَقَّاهَآ إِلاَّ ذُو حَظِّ عَظِيمٍ\n\r\n\n\r\n(மேலும், மகத்தான பாக்கியம் உடையவர்களைத் தவிர வேறு எவருக்கும் இது வழங்கப்படாது.) இதன் பொருள், இவ்வுலகிலும் மறுமையிலும் (அவர்களுக்கு நற்பேறு உண்டு) என்பதாகும். மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقُلْ رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ\n\r\n\n\r\n(மேலும் கூறுவீராக: \"என் இறைவா! ஷைத்தான்களின் ஊசலாட்டங்களை விட்டும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.\")\n\r\n\n\r\nஷைத்தான்களிடமிருந்து தன்னிடம் பாதுகாப்புத் தேடுமாறு அல்லாஹ் அவருக்குக் கட்டளையிட்டான். ஏனெனில் அவர்களுக்கு எதிராக எந்தத் தந்திரமும் பலிக்காது; அவர்களிடம் கனிவாக நடப்பதன் மூலம் உங்களைப் பாதுகாத்துக்கொள்ளவும் முடியாது. 'இஸ்திஆதா' (பாதுகாப்புத் தேடுதல்) பற்றி விளக்கும்போது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறுவார்கள் என்று நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:\n\r\n\n\r\n«أَعُوذُ بِاللهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِه»\n\r\n\n\r\n(அனைத்தையும் செவியேற்பவனும், அறிபவனுமாகிய அல்லாஹ்விடம், சபிக்கப்பட்ட ஷைத்தானிடமிருந்தும், அவனது ஊசலாட்டங்கள், அவனது தீய எண்ணங்கள் மற்றும் தூண்டுதல்களிலிருந்தும் நான் பாதுகாப்புத் தேடுகிறேன்.)\n\r\n\n\r\nஅவனது கூற்று:\n\r\n\n\r\nوَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ\n\r\n\n\r\n(\"என் இறைவா! அவர்கள் என்னிடம் வருவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.\") இதன் பொருள், \"எனது வாழ்க்கையின் ஒவ்வொரு விவகாரத்திலும் அவர்கள் நெருங்குவதை விட்டும் பாதுகாப்புத் தேடுகிறேன்\" என்பதாகும்.\n\r\n\n\r\nஎனவே உண்ணும்போது, தாம்பத்திய உறவு கொள்ளும்போது, உணவுக்காக விலங்குகளை அறுக்கும்போது என எந்தவொரு காரியத்தைத் தொடங்கும்போதும் ஷைத்தான்களை விரட்டுவதற்காக அல்லாஹ்வின் திருப்பெயரைக் கூறுமாறு நாம் பணிக்கப்பட்டுள்ளோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறுவார்கள் என அபூதாவூத் (ரஹ்) பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\n«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَرَمِ، وَأَعُوذُ بِكَ مِنَ الْهَدْمِ وَمِنَ الْغَرَقِ، وَأَعُوذُ بِكَ مِنْ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْت»\n\r\n\n\r\n(யா அல்லாஹ்! தள்ளாத முதுமையிலிருந்து உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன். கட்டிடம் இடிந்து விழுவதிலிருந்தும், நீரில் மூழ்குவதிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். மரணத்தின்போது ஷைத்தான் என்னை நிலைகுலையச் செய்வதிலிருந்தும் உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.)"},"99":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=100\" class=\"link\">23:100</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:100 ஐ பார்க்கவும்"},"100":{"html":"<strong>மரணம் நெருங்கும் போது நிராகரிப்பாளர்களின் எதிர்பார்ப்பு</strong><br />\r\nநிராகரிப்பாளர்களில் ஒருவருக்கோ அல்லது அல்லாஹ்வின் கட்டளைகளை அலட்சியப்படுத்தியவர்களில் ஒருவருக்கோ மரணம் நெருங்கும் போது என்ன நடக்கும் என்பதைப் பற்றி அல்லாஹ் நமக்குத் தெரிவிக்கிறான். அவன் என்ன கூறுவான் என்றும், தான் வாழ்ந்த காலத்தில் செய்த தவறுகளைச் சரிசெய்வதற்காக மீண்டும் இவ்வுலகிற்குத் திரும்பிச் செல்ல அவன் எவ்வாறு கோருவான் என்றும் அவன் கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">ارْجِعُونِ</span> <span class=\"quran-arabic-font text-success\">لَعَلِّى</span> <span class=\"quran-arabic-font text-success\">أَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">تَرَكْتُ</span> <span class=\"quran-arabic-font text-success\">كَلاَّ﴿</span><br />\r\n(\"என் இறைவனே! என்னைத் திருப்பி அனுப்புங்கள்; நான் விட்டு வந்தவற்றில் நற்செயல்களைச் செய்வதற்காக!\" - இல்லை!) இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنفِقُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">رَزَقْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِىَ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتُ﴿</span><br />\r\n(உங்களில் ஒருவருக்கு மரணம் வருவதற்கு முன்னதாகவே, நாம் உங்களுக்கு வழங்கியவற்றிலிருந்து நல்வழியில் செலவு செய்யுங்கள்,) என்று தொடங்கி அவன் கூறும் இந்த வசனம் வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ﴿</span><br />\r\n(மேலும், நீங்கள் செய்பவற்றை அல்லாஹ் நன்கு அறிந்தவன்) <a href=\"qurandisp.php?sura=63&ayah=10\" class=\"link\">63:10</a>-11.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنذِرِ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ﴿</span><br />\r\n<strong>(வேதனை அவர்களுக்கு வரும் நாளைப் பற்றி மனிதர்களுக்கு எச்சரிக்கை செய்வீராக!)</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زَوَالٍ﴿</span><br />\r\n(உங்களுக்கு அழிவே இல்லை என்று நீங்கள் சத்தியம் செய்து கொண்டிருந்தீர்களே!) என்று அவன் கூறும் வரை (<a href=\"qurandisp.php?sura=14&ayah=44\" class=\"link\">14:44</a>). மேலும் அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِى</span> <span class=\"quran-arabic-font text-success\">تَأْوِيلُهُ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">نَسُوهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَتْ</span> <span class=\"quran-arabic-font text-success\">رُسُلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">فَهَل</span> <span class=\"quran-arabic-font text-success\">لَّنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شُفَعَآءَ</span> <span class=\"quran-arabic-font text-success\">فَيَشْفَعُواْ</span> <span class=\"quran-arabic-font text-success\">لَنَآ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">فَنَعْمَلَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلُ﴿</span><br />\r\n(அதன் உண்மை வெளிப்படும் நாளில், இதற்கு முன் அதனை மறந்திருந்தவர்கள் கூறுவார்கள்: \"நிச்சயமாக எங்கள் இறைவனுடைய தூதர்கள் சத்தியத்தைக் கொண்டு வந்தார்கள். இப்போது எங்களுக்காகப் பரிந்துரை செய்யக்கூடிய பரிந்துரையாளர்கள் யாராவது இருக்கிறார்களா? அல்லது நாங்கள் செய்த செயல்களைத் தவிர வேறு நற்செயல்களைச் செய்வதற்காக நாங்கள் திருப்பி அனுப்பப்பட முடியுமா?\") <a href=\"qurandisp.php?sura=7&ayah=53\" class=\"link\">7:53</a>. மேலும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">نَاكِسُواْ</span> <span class=\"quran-arabic-font text-success\">رُءُوسِهِمْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَبْصَرْنَا</span> <span class=\"quran-arabic-font text-success\">وَسَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">فَارْجِعْنَا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُوقِنُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(குற்றவாளிகள் தங்கள் இறைவனுக்கு முன்னால் தலைகுனிந்து நின்று, \"எங்கள் இறைவனே! நாங்கள் பார்த்துவிட்டோம், கேட்டுவிட்டோம்; எனவே எங்களைத் திருப்பி அனுப்புவாயாக, நாங்கள் நற்செயல்களைச் செய்வோம்; நிச்சயமாக நாங்கள் இப்போது உறுதியாக நம்புகிறோம்\" என்று கூறுவதை நீர் பார்ப்பீரானால்!) <a href=\"qurandisp.php?sura=32&ayah=12\" class=\"link\">32:12</a>. மேலும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">وُقِفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">يَـلَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُكَذِّبَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا﴿</span><br />\r\n(நரக நெருப்பின் முன் அவர்கள் நிறுத்தப்படும்போது நீர் காண்பீரானால்! அவர்கள் கூறுவார்கள்: \"ஐயோ! நாங்கள் மீண்டும் (உலகிற்கு) திருப்பி அனுப்பப்படக்கூடாதா? அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்யாக்க மாட்டோம்...\") என்று அவன் கூறும் இந்த வசனம் வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ﴿</span><br />\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே.) <a href=\"qurandisp.php?sura=6&ayah=27\" class=\"link\">6:27</a>-28.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَتَرَى</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَرَدٍّ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سَبِيلٍ﴿</span><br />\r\n(வேதனையைக் காணும்போது அந்த அநியாயக்காரர்கள், \"திரும்பிச் செல்ல ஏதேனும் வழி உண்டா?\" என்று கூறுவதை நீர் காண்பீர்.) <a href=\"qurandisp.php?sura=42&ayah=44\" class=\"link\">42:44</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَمَتَّنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">وَأَحْيَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">اثْنَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">فَاعْتَرَفْنَا</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِنَا</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">خُرُوجٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سَبِيلٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நீ எங்களை இரண்டு முறை மரணிக்கச் செய்தாய்; இரண்டு முறை எங்களுக்கு உயிர் கொடுத்தாய்! இப்போது நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம். எனவே, இங்கிருந்து வெளியேற ஏதேனும் வழி உண்டா?\") <a href=\"qurandisp.php?sura=40&ayah=11\" class=\"link\">40:11</a>. மற்றும் அதற்கு அடுத்த வசனம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَصْطَرِخُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">صَـلِحاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كُـنَّا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">نُعَمِّرْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرَ</span> <span class=\"quran-arabic-font text-success\">وَجَآءَكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّذِيرُ</span> <span class=\"quran-arabic-font text-success\">فَذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">لِلظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نَّصِيرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அங்கு அவர்கள் கதறுவார்கள்: \"எங்கள் இறைவனே! எங்களை வெளியேற்றுவாயாக! நாங்கள் முன்பு செய்தவற்றைத் தவிர்த்து நற்செயல்களைச் செய்வோம்.\" (அதற்கு அல்லாஹ்,) \"நினைவுபடுத்திக் கொள்ள விரும்புபவர் நினைவுபடுத்திக் கொள்ளும் அளவுக்கு நீண்ட ஆயுளை நாம் உங்களுக்கு வழங்கவில்லையா? மேலும் உங்களிடம் எச்சரிக்கை செய்பவரும் வந்தாரே! எனவே வேதனையைச் சுவையுங்கள். அநியாயக்காரர்களுக்கு உதவி செய்பவர் எவருமில்லை\" (என்பான்).) <a href=\"qurandisp.php?sura=35&ayah=37\" class=\"link\">35:37</a>.<br />\r\n<br />\r\nமரணம் நெருங்கும் போதும், மறுமை நாளில் (அனைவரையும்) அடக்கி ஆள்பவனான அல்லாஹ்வுக்கு முன்னால் தீர்ப்புக்காக ஒன்றுதிரட்டப்படும் போதும், நரக வேதனையில் சிக்கித் தவிக்கும் போதும் அவர்கள் மீண்டும் உலகிற்குச் செல்ல அனுமதி கேட்பார்கள்; ஆனால் அவர்களின் கோரிக்கை ஏற்கப்படாது என்று அல்லாஹ் கூறுகிறான். இங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةٌ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَآئِلُهَا﴿</span><br />\r\n(அப்படியல்ல! அது அவன் பேசும் வெறும் வார்த்தையே!) 'கல்லா' (இல்லை/அப்படியல்ல) என்ற வார்த்தை ஒருவரை அதட்டுவதற்காகப் பயன்படுத்தப்படுவதாகும். இதன் பொருள்: \"இல்லை, அவன் கேட்பதை நாம் ஏற்க மாட்டோம், அவனது கோரிக்கைக்குப் பதிலளிக்க மாட்டோம்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةٌ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَآئِلُهَا﴿</span><br />\r\n(அது அவன் பேசும் வெறும் வார்த்தையே) என்பது, தான் நற்செயல்களைச் செய்வதற்காக மீண்டும் உலகிற்குத் திரும்பிச் செல்ல வேண்டும் என்று அவன் கேட்பதைக் குறிக்கிறது. இது அவனது வெறும் பேச்சே தவிர, இதற்கும் செயலுக்கும் எந்தச் சம்பந்தமும் இருக்காது. அவன் மீண்டும் உலகிற்குத் திருப்பி அனுப்பப்பட்டாலும், அவன் எந்த நற்செயலையும் செய்யமாட்டான்; அவன் பொய் கூறுகிறான். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رُدُّواْ</span> <span class=\"quran-arabic-font text-success\">لَعَـدُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">نُهُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ﴿</span><br />\r\n(ஆனால் அவர்கள் திருப்பி அனுப்பப்பட்டாலும், எதைவிட்டு அவர்கள் தடுக்கப்பட்டார்களோ அதற்கே நிச்சயமாகத் திரும்புவார்கள். மேலும் நிச்சயமாக அவர்கள் பொய்யர்களாவார்கள்.) <a href=\"qurandisp.php?sura=6&ayah=28\" class=\"link\">6:28</a>. கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக! அவன் தனது குடும்பத்தினரிடமோ, உறவினர்களிடமோ செல்வதற்கோ அல்லது இவ்வுலகப் பொருட்களைச் சேகரிப்பதற்கோ அல்லது தனது இச்சைகளை நிறைவேற்றிக் கொள்வதற்கோ திரும்பி வர விரும்பமாட்டான். மாறாக, அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடக்கக்கூடிய நற்செயல்களைச் செய்வதற்காகவே அவன் திரும்பி வர விரும்புவான். நரக வேதனையைக் காணும்போது ஒரு நிராகரிப்பாளன் எதைச் செய்ய விரும்புவானோ, அதை (இப்போதே இவ்வுலகில்) செய்யும் மனிதன் மீது அல்லாஹ் கருணை காட்டுவானாக!\"<br />\r\n<br />\r\n<strong>பர்ஸக் மற்றும் அதில் உள்ள தண்டனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">بَرْزَخٌ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ﴿</span><br />\r\n(மேலும், அவர்கள் உயிர்த்தெழுப்பப்படும் நாள் வரை அவர்களுக்கு முன்னால் ஒரு திரை (பர்ஸக்) இருக்கிறது.) அபூ ஸாலிஹ் (ரழி) அவர்களும் மற்றவர்களும் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِمْ﴿</span><br />\r\n(மேலும் அவர்களுக்கு முன்னால்) என்பதற்கு அவர்களுக்கு முன்பாக என்று பொருள். முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-பர்ஸக் என்பது இவ்வுலகிற்கும் மறுமைக்கும் இடையே உள்ள ஒரு தடையாகும்.\" முஹம்மது பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"பர்ஸக் என்பது இவ்வுலகிற்கும் மறுமைக்கும் இடைப்பட்ட நிலையாகும். அவர்கள் இவ்வுலக மக்களுடன் சேர்ந்து உண்பதோ குடிப்பதோ இல்லை; அதே சமயம் மறுமை மக்களுடன் சேர்ந்து தங்கள் செயல்களுக்கான நற்கூலியையோ அல்லது தண்டனையையோ பெறுபவர்களாகவும் இல்லை.\" அபூ ஸக்ர் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-பர்ஸக் என்பது மண்ணறைகளைக் (கப்ருகளை) குறிக்கும். அவர்கள் இவ்வுலகிலும் இல்லை, மறுமையிலும் இல்லை. உயிர்த்தெழுப்பப்படும் நாள் வரை அவர்கள் அங்கேயே இருப்பார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">بَرْزَخٌ﴿</span><br />\r\n(மேலும் அவர்களுக்கு முன்னால் பர்ஸக் உள்ளது). இந்தச் சொற்களில், அநியாயக்காரர்கள் மரணிக்கும் போது அவர்களுக்குக் கிடைக்கப் போகும் பர்ஸக் தண்டனை குறித்த அச்சுறுத்தல் உள்ளது. இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مِّن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمُ﴿</span><br />\r\n(அவர்களுக்கு முன்னால் நரகம் இருக்கிறது) <a href=\"qurandisp.php?sura=45&ayah=10\" class=\"link\">45:10</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">غَلِيظٌ﴿</span><br />\r\n(மேலும் அவனுக்கு முன்னால் மிகக் கடினமான வேதனை உண்டு) <a href=\"qurandisp.php?sura=14&ayah=17\" class=\"link\">14:17</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ﴿</span><br />\r\n(அவர்கள் உயிர்த்தெழுப்பப்படும் நாள் வரை). அதாவது, ஹதீஸில் கூறப்பட்டுள்ளபடி உயிர்த்தெழுப்பப்படும் நாள் வரை அவன் தொடர்ந்து தண்டிக்கப்படுவான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَزَالُ</span> <span class=\"quran-arabic-font text-success\">مُعَذَّبًا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அவன் அதில் தொடர்ந்து தண்டிக்கப்பட்டுக் கொண்டே இருப்பான்.) அதாவது பூமியில் (மண்ணறையில்).<br />\r\n<br />\r\n<br />\r\n<br />","text":"மரணம் நெருங்கும் போது நிராகரிப்பாளர்களின் எதிர்பார்ப்பு\n\r\nநிராகரிப்பாளர்களில் ஒருவருக்கோ அல்லது அல்லாஹ்வின் கட்டளைகளை அலட்சியப்படுத்தியவர்களில் ஒருவருக்கோ மரணம் நெருங்கும் போது என்ன நடக்கும் என்பதைப் பற்றி அல்லாஹ் நமக்குத் தெரிவிக்கிறான். அவன் என்ன கூறுவான் என்றும், தான் வாழ்ந்த காலத்தில் செய்த தவறுகளைச் சரிசெய்வதற்காக மீண்டும் இவ்வுலகிற்குத் திரும்பிச் செல்ல அவன் எவ்வாறு கோருவான் என்றும் அவன் கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾رَبِّ ارْجِعُونِ لَعَلِّى أَعْمَلُ صَـلِحاً فِيمَا تَرَكْتُ كَلاَّ﴿\n\r\n(\"என் இறைவனே! என்னைத் திருப்பி அனுப்புங்கள்; நான் விட்டு வந்தவற்றில் நற்செயல்களைச் செய்வதற்காக!\" - இல்லை!) இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\n﴾وَأَنفِقُواْ مِن مَّا رَزَقْنَـكُمْ مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ الْمَوْتُ﴿\n\r\n(உங்களில் ஒருவருக்கு மரணம் வருவதற்கு முன்னதாகவே, நாம் உங்களுக்கு வழங்கியவற்றிலிருந்து நல்வழியில் செலவு செய்யுங்கள்,) என்று தொடங்கி அவன் கூறும் இந்த வசனம் வரை:\n\r\n\n\r\n﴾وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ﴿\n\r\n(மேலும், நீங்கள் செய்பவற்றை அல்லாஹ் நன்கு அறிந்தவன்) 63:10-11.\n\r\n\n\r\n﴾وَأَنذِرِ النَّاسَ يَوْمَ يَأْتِيهِمُ الْعَذَابُ﴿\n\r\n(வேதனை அவர்களுக்கு வரும் நாளைப் பற்றி மனிதர்களுக்கு எச்சரிக்கை செய்வீராக!)\n\r\n\n\r\n﴾مَا لَكُمْ مِّن زَوَالٍ﴿\n\r\n(உங்களுக்கு அழிவே இல்லை என்று நீங்கள் சத்தியம் செய்து கொண்டிருந்தீர்களே!) என்று அவன் கூறும் வரை (14:44). மேலும் அவனது கூற்று:\n\r\n\n\r\n﴾يَوْمَ يَأْتِى تَأْوِيلُهُ يَقُولُ الَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُواْ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذِى كُنَّا نَعْمَلُ﴿\n\r\n(அதன் உண்மை வெளிப்படும் நாளில், இதற்கு முன் அதனை மறந்திருந்தவர்கள் கூறுவார்கள்: \"நிச்சயமாக எங்கள் இறைவனுடைய தூதர்கள் சத்தியத்தைக் கொண்டு வந்தார்கள். இப்போது எங்களுக்காகப் பரிந்துரை செய்யக்கூடிய பரிந்துரையாளர்கள் யாராவது இருக்கிறார்களா? அல்லது நாங்கள் செய்த செயல்களைத் தவிர வேறு நற்செயல்களைச் செய்வதற்காக நாங்கள் திருப்பி அனுப்பப்பட முடியுமா?\") 7:53. மேலும்:\n\r\n\n\r\n﴾وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُواْ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَـلِحاً إِنَّا مُوقِنُونَ ﴿\n\r\n(குற்றவாளிகள் தங்கள் இறைவனுக்கு முன்னால் தலைகுனிந்து நின்று, \"எங்கள் இறைவனே! நாங்கள் பார்த்துவிட்டோம், கேட்டுவிட்டோம்; எனவே எங்களைத் திருப்பி அனுப்புவாயாக, நாங்கள் நற்செயல்களைச் செய்வோம்; நிச்சயமாக நாங்கள் இப்போது உறுதியாக நம்புகிறோம்\" என்று கூறுவதை நீர் பார்ப்பீரானால்!) 32:12. மேலும்:\n\r\n\n\r\n﴾وَلَوْ تَرَى إِذْ وُقِفُواْ عَلَى النَّارِ فَقَالُواْ يَـلَيْتَنَا نُرَدُّ وَلاَ نُكَذِّبَ بِـَايَـتِ رَبِّنَا﴿\n\r\n(நரக நெருப்பின் முன் அவர்கள் நிறுத்தப்படும்போது நீர் காண்பீரானால்! அவர்கள் கூறுவார்கள்: \"ஐயோ! நாங்கள் மீண்டும் (உலகிற்கு) திருப்பி அனுப்பப்படக்கூடாதா? அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்யாக்க மாட்டோம்...\") என்று அவன் கூறும் இந்த வசனம் வரை:\n\r\n\n\r\n﴾وَإِنَّهُمْ لَكَـذِبُونَ﴿\n\r\n(நிச்சயமாக அவர்கள் பொய்யர்களே.) 6:27-28.\n\r\n\n\r\n﴾وَتَرَى الظَّـلِمِينَ لَمَّا رَأَوُاْ الْعَذَابَ يَقُولُونَ هَلْ إِلَى مَرَدٍّ مِّن سَبِيلٍ﴿\n\r\n(வேதனையைக் காணும்போது அந்த அநியாயக்காரர்கள், \"திரும்பிச் செல்ல ஏதேனும் வழி உண்டா?\" என்று கூறுவதை நீர் காண்பீர்.) 42:44.\n\r\n\n\r\n﴾قَالُواْ رَبَّنَآ أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَى خُرُوجٍ مِّن سَبِيلٍ ﴿\n\r\n(அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நீ எங்களை இரண்டு முறை மரணிக்கச் செய்தாய்; இரண்டு முறை எங்களுக்கு உயிர் கொடுத்தாய்! இப்போது நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம். எனவே, இங்கிருந்து வெளியேற ஏதேனும் வழி உண்டா?\") 40:11. மற்றும் அதற்கு அடுத்த வசனம்:\n\r\n\n\r\n﴾وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَـلِحاً غَيْرَ الَّذِى كُـنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُمْ مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ النَّذِيرُ فَذُوقُواْ فَمَا لِلظَّـلِمِينَ مِن نَّصِيرٍ ﴿\n\r\n(அங்கு அவர்கள் கதறுவார்கள்: \"எங்கள் இறைவனே! எங்களை வெளியேற்றுவாயாக! நாங்கள் முன்பு செய்தவற்றைத் தவிர்த்து நற்செயல்களைச் செய்வோம்.\" (அதற்கு அல்லாஹ்,) \"நினைவுபடுத்திக் கொள்ள விரும்புபவர் நினைவுபடுத்திக் கொள்ளும் அளவுக்கு நீண்ட ஆயுளை நாம் உங்களுக்கு வழங்கவில்லையா? மேலும் உங்களிடம் எச்சரிக்கை செய்பவரும் வந்தாரே! எனவே வேதனையைச் சுவையுங்கள். அநியாயக்காரர்களுக்கு உதவி செய்பவர் எவருமில்லை\" (என்பான்).) 35:37.\n\r\n\n\r\nமரணம் நெருங்கும் போதும், மறுமை நாளில் (அனைவரையும்) அடக்கி ஆள்பவனான அல்லாஹ்வுக்கு முன்னால் தீர்ப்புக்காக ஒன்றுதிரட்டப்படும் போதும், நரக வேதனையில் சிக்கித் தவிக்கும் போதும் அவர்கள் மீண்டும் உலகிற்குச் செல்ல அனுமதி கேட்பார்கள்; ஆனால் அவர்களின் கோரிக்கை ஏற்கப்படாது என்று அல்லாஹ் கூறுகிறான். இங்கே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾كَلاَّ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا﴿\n\r\n(அப்படியல்ல! அது அவன் பேசும் வெறும் வார்த்தையே!) 'கல்லா' (இல்லை/அப்படியல்ல) என்ற வார்த்தை ஒருவரை அதட்டுவதற்காகப் பயன்படுத்தப்படுவதாகும். இதன் பொருள்: \"இல்லை, அவன் கேட்பதை நாம் ஏற்க மாட்டோம், அவனது கோரிக்கைக்குப் பதிலளிக்க மாட்டோம்\" என்பதாகும்.\n\r\n\n\r\n﴾إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا﴿\n\r\n(அது அவன் பேசும் வெறும் வார்த்தையே) என்பது, தான் நற்செயல்களைச் செய்வதற்காக மீண்டும் உலகிற்குத் திரும்பிச் செல்ல வேண்டும் என்று அவன் கேட்பதைக் குறிக்கிறது. இது அவனது வெறும் பேச்சே தவிர, இதற்கும் செயலுக்கும் எந்தச் சம்பந்தமும் இருக்காது. அவன் மீண்டும் உலகிற்குத் திருப்பி அனுப்பப்பட்டாலும், அவன் எந்த நற்செயலையும் செய்யமாட்டான்; அவன் பொய் கூறுகிறான். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\n﴾وَلَوْ رُدُّواْ لَعَـدُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَـذِبُونَ﴿\n\r\n(ஆனால் அவர்கள் திருப்பி அனுப்பப்பட்டாலும், எதைவிட்டு அவர்கள் தடுக்கப்பட்டார்களோ அதற்கே நிச்சயமாகத் திரும்புவார்கள். மேலும் நிச்சயமாக அவர்கள் பொய்யர்களாவார்கள்.) 6:28. கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் மீது ஆணையாக! அவன் தனது குடும்பத்தினரிடமோ, உறவினர்களிடமோ செல்வதற்கோ அல்லது இவ்வுலகப் பொருட்களைச் சேகரிப்பதற்கோ அல்லது தனது இச்சைகளை நிறைவேற்றிக் கொள்வதற்கோ திரும்பி வர விரும்பமாட்டான். மாறாக, அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடக்கக்கூடிய நற்செயல்களைச் செய்வதற்காகவே அவன் திரும்பி வர விரும்புவான். நரக வேதனையைக் காணும்போது ஒரு நிராகரிப்பாளன் எதைச் செய்ய விரும்புவானோ, அதை (இப்போதே இவ்வுலகில்) செய்யும் மனிதன் மீது அல்லாஹ் கருணை காட்டுவானாக!\"\n\r\n\n\r\nபர்ஸக் மற்றும் அதில் உள்ள தண்டனை\n\r\n\n\r\n﴾وَمِن وَرَآئِهِمْ بَرْزَخٌ إِلَى يَوْمِ يُبْعَثُونَ﴿\n\r\n(மேலும், அவர்கள் உயிர்த்தெழுப்பப்படும் நாள் வரை அவர்களுக்கு முன்னால் ஒரு திரை (பர்ஸக்) இருக்கிறது.) அபூ ஸாலிஹ் (ரழி) அவர்களும் மற்றவர்களும் கூறினார்கள்:\n\r\n\n\r\n﴾وَمِن وَرَآئِهِمْ﴿\n\r\n(மேலும் அவர்களுக்கு முன்னால்) என்பதற்கு அவர்களுக்கு முன்பாக என்று பொருள். முஜாஹித் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-பர்ஸக் என்பது இவ்வுலகிற்கும் மறுமைக்கும் இடையே உள்ள ஒரு தடையாகும்.\" முஹம்மது பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"பர்ஸக் என்பது இவ்வுலகிற்கும் மறுமைக்கும் இடைப்பட்ட நிலையாகும். அவர்கள் இவ்வுலக மக்களுடன் சேர்ந்து உண்பதோ குடிப்பதோ இல்லை; அதே சமயம் மறுமை மக்களுடன் சேர்ந்து தங்கள் செயல்களுக்கான நற்கூலியையோ அல்லது தண்டனையையோ பெறுபவர்களாகவும் இல்லை.\" அபூ ஸக்ர் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-பர்ஸக் என்பது மண்ணறைகளைக் (கப்ருகளை) குறிக்கும். அவர்கள் இவ்வுலகிலும் இல்லை, மறுமையிலும் இல்லை. உயிர்த்தெழுப்பப்படும் நாள் வரை அவர்கள் அங்கேயே இருப்பார்கள்.\"\n\r\n\n\r\n﴾وَمِن وَرَآئِهِمْ بَرْزَخٌ﴿\n\r\n(மேலும் அவர்களுக்கு முன்னால் பர்ஸக் உள்ளது). இந்தச் சொற்களில், அநியாயக்காரர்கள் மரணிக்கும் போது அவர்களுக்குக் கிடைக்கப் போகும் பர்ஸக் தண்டனை குறித்த அச்சுறுத்தல் உள்ளது. இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾مِّن وَرَآئِهِمْ جَهَنَّمُ﴿\n\r\n(அவர்களுக்கு முன்னால் நரகம் இருக்கிறது) 45:10.\n\r\n\n\r\n﴾وَمِن وَرَآئِهِ عَذَابٌ غَلِيظٌ﴿\n\r\n(மேலும் அவனுக்கு முன்னால் மிகக் கடினமான வேதனை உண்டு) 14:17.\n\r\n\n\r\n﴾إِلَى يَوْمِ يُبْعَثُونَ﴿\n\r\n(அவர்கள் உயிர்த்தெழுப்பப்படும் நாள் வரை). அதாவது, ஹதீஸில் கூறப்பட்டுள்ளபடி உயிர்த்தெழுப்பப்படும் நாள் வரை அவன் தொடர்ந்து தண்டிக்கப்படுவான்:\n\r\n\n\r\n﴾«فَلَا يَزَالُ مُعَذَّبًا فِيهَا»﴿\n\r\n(அவன் அதில் தொடர்ந்து தண்டிக்கப்பட்டுக் கொண்டே இருப்பான்.) அதாவது பூமியில் (மண்ணறையில்)."},"101":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=104\" class=\"link\">23:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:104 ஐ பார்க்கவும்"},"102":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=104\" class=\"link\">23:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:104 ஐ பார்க்கவும்"},"103":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=104\" class=\"link\">23:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:104 ஐ பார்க்கவும்"},"104":{"html":"<strong>ஸூர் ஊதப்படுதலும், தராசில் அமல்கள் எடைபோடப்படுதலும்.</strong><br />\r\n<br />\r\nமறுமைக்காக ஸூர் (எக்காளம்) ஊதப்பட்டு, மக்கள் தங்கள் மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) எழும்போது, <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">نُفِخَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصُّورِ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">أَنسَابَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَتَسَاءَلُونَ﴿</span> (அந்நாளில் அவர்களுக்கிடையே எந்தவிதமான உறமுறைகளும் இருக்காது; அவர்கள் ஒருவரையொருவர் விசாரித்துக்கொள்ளவும் மாட்டார்கள்) என்று அல்லாஹ் கூறுகிறான். அதாவது, அந்நாளில் வம்சாவழித் தொடர்புகள் எந்தப் பயனும் அளிக்காது; ஒரு தந்தை தன் மகனைப் பற்றி விசாரிக்கவோ அல்லது அவன் மீது அக்கறை காட்டவோ மாட்டார்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلَا</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَمِيمًا</span> <span class=\"quran-arabic-font text-success\">يُبَصَّرُونَهُمْ﴿</span> (எந்தவொரு நண்பனும் மற்றொரு நண்பனைப் பற்றி விசாரிக்க மாட்டான்; அவர்கள் ஒருவருக்கொருவர் காட்டப்பட்ட போதிலும்) <a href=\"qurandisp.php?sura=70&ayah=10\" class=\"link\">70:10</a>-11. அதாவது, எந்தவொரு உறவினரும் மற்றொரு உறவினரைப் பற்றி விசாரிக்க மாட்டார்கள்; அவர் அவரை நேரில் கண்டாலும், அவர் ஒரு பெரும் சுமையைச் சுமந்துகொண்டிருந்தாலும் சரியே. இவ்வுலகில் அவர் அவருக்கு மிகவும் பிரியமானவராக இருந்திருந்தாலும், அவர் மீது அக்கறை காட்டமாட்டார் அல்லது அவரது சுமையில் ஒரு சிறு பகுதியைக் கூடப் பகிர்ந்து கொள்ள மாட்டார்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَفِرُّ</span> <span class=\"quran-arabic-font text-success\">الْمَرْءُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَخِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَأُمِّهِ</span> <span class=\"quran-arabic-font text-success\">وَأَبِيهِ</span> - <span class=\"quran-arabic-font text-success\">وَصَاحِبَتِهِ</span> <span class=\"quran-arabic-font text-success\">وَبَنِيهِ﴿</span> (அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) <a href=\"qurandisp.php?sura=80&ayah=34\" class=\"link\">80:34</a>-36. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"மறுமை நாளில், ஆரம்பகால மக்களையும் பிற்கால மக்களையும் அல்லாஹ் ஒன்றுதிரட்டுவான். பிறகு ஒரு குரல் ஒலிக்கும்: 'எவருக்கேனும் பிறரிடமிருந்து ஏதேனும் சேர வேண்டியிருந்தால், அவர் முன்வந்து அதை எடுத்துக் கொள்ளட்டும்.' ஒரு மனிதன், தான் அநீதி இழைக்கப்பட்டிருந்தாலோ அல்லது தன் தந்தை, பிள்ளை அல்லது மனைவியிடமிருந்து ஏதேனும் பாக்கி வர வேண்டியிருந்தாலோ, அது சிறிதளவாக இருந்தாலும் அதற்காக அவன் மகிழ்ச்சியடைவான்.\" இது அல்லாஹ்வின் வேதத்தில் உறுதிப்படுத்தப்பட்டுள்ளது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">نُفِخَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الصُّورِ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">أَنسَابَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَتَسَاءَلُونَ﴿</span> (பின்னர், ஸூர் ஊதப்படும்போது, அந்நாளில் அவர்களுக்கிடையே எந்தவிதமான உறமுறைகளும் இருக்காது; அவர்கள் ஒருவரையொருவர் விசாரித்துக்கொள்ளவும் மாட்டார்கள்.) இதனை இப்னு அபீ ஹாதிம் (ரஹ்) பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَمَن</span> <span class=\"quran-arabic-font text-success\">ثَقُلَتْ</span> <span class=\"quran-arabic-font text-success\">مَوَازِينُهُ</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُفْلِحُونَ﴿</span> (பின்னர், எவருடைய தராசுகள் கனமாக இருக்கின்றனவோ, அவர்களே வெற்றியாளர்கள்.) அதாவது, எவருடைய நன்மைகள் அவருடைய தீமைகளை விட ஒரு நன்மை அதிகமாக இருந்தாலும் சரி, அவர்களே வெற்றியாளர்கள் என்பது இதன் பொருளாகும். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُفْلِحُونَ﴿</span> (அவர்களே வெற்றியாளர்கள்.) அதாவது, வெற்றி பெற்று, நரகத்திலிருந்து காப்பாற்றப்பட்டு, சுவனத்தில் அனுமதிக்கப்பட்டவர்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இவர்களே தாங்கள் விரும்பியதை அடைந்தவர்கள்; தப்பிக்கவே முடியாத ஒரு தீங்கிலிருந்து காப்பாற்றப்பட்டவர்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَنْ</span> <span class=\"quran-arabic-font text-success\">خَفَّتْ</span> <span class=\"quran-arabic-font text-success\">مَوَازِينُهُ﴿</span> (மேலும் எவருடைய தராசுகள் இலேசாக இருக்கின்றனவோ,) அதாவது, எவருடைய தீமைகள் அவர்களுடைய நன்மைகளை விட அதிகமாக இருக்கின்றனவோ அவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">خَسِرُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَهُم﴿</span> (அவர்களே தங்களுக்குத் தாங்களே நஷ்டத்தை ஏற்படுத்திக்கொண்டவர்கள்,) அதாவது, அவர்கள் அழிந்துவிட்டார்கள், மிக மோசமான ஒரு முடிவை அடைந்துவிட்டார்கள்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فِي</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">خَالِدُونَ﴿</span> (நரகத்தில் அவர்கள் நிரந்தரமாகத் தங்கியிருப்பார்கள்.) அதாவது, அவர்கள் அங்கே என்றென்றும் இருப்பார்கள், அங்கிருந்து ஒருபோதும் வெளியேற மாட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَلْفَحُ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ﴿</span> (நெருப்பு அவர்களுடைய முகங்களைக் கரிக்கும்.) இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَتَغْشَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمْ</span> <span class=\"quran-arabic-font text-success\">النَّارُ﴿</span> (மேலும் நெருப்பு அவர்களுடைய முகங்களை மூடிக்கொள்ளும்) <a href=\"qurandisp.php?sura=14&ayah=50\" class=\"link\">14:50</a>. மேலும்: <span class=\"quran-arabic-font text-success\">﴾لَوْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَكُفُّونَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمُ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهِمْ﴿</span> (தங்கள் முகங்களிலிருந்தோ, தங்கள் முதுகுகளிலிருந்தோ நெருப்பைத் தடுத்து நிறுத்த முடியாத அந்த நேரத்தை நிராகரிப்பாளர்கள் அறிந்திருக்க வேண்டாமா!) <a href=\"qurandisp.php?sura=21&ayah=39\" class=\"link\">21:39</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">كَالِحُونَ﴿</span> (அதில் அவர்கள் உதடுகள் பிதுங்கி விகாரமான நிலையில் இருப்பார்கள்.) அலீ பின் அபீ தல்ஹா (ரஹ்) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, \"முகம் சுளித்திருப்பார்கள்\" என்று அறிவிக்கிறார்கள். இமாம் அஹ்மத் (ரஹ்) அவர்கள் அபூ ஸயீத் (ரழி) அவர்கள் வாயிலாக நபி (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"நெருப்பு அவர்களை எரிக்கும்; அப்போது மேல் உதடு சுருண்டு மண்டையின் நடுப்பகுதியை அடையும். கீழ் உதடு தொங்கித் தொப்புளை வந்தடையும்.\" இதனைத் திர்மிதி (ரஹ்) அவர்களும் பதிவு செய்துள்ளார்கள்; மேலும் அவர் இதனை 'ஹஸன், கரீப்' என்று கூறியுள்ளார்.<br />\r\n<br />","text":"ஸூர் ஊதப்படுதலும், தராசில் அமல்கள் எடைபோடப்படுதலும்.\n\r\n\n\r\nமறுமைக்காக ஸூர் (எக்காளம்) ஊதப்பட்டு, மக்கள் தங்கள் மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) எழும்போது, ﴾فَإِذَا نُفِخَ فِي الصُّورِ فَلَا أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَاءَلُونَ﴿ (அந்நாளில் அவர்களுக்கிடையே எந்தவிதமான உறமுறைகளும் இருக்காது; அவர்கள் ஒருவரையொருவர் விசாரித்துக்கொள்ளவும் மாட்டார்கள்) என்று அல்லாஹ் கூறுகிறான். அதாவது, அந்நாளில் வம்சாவழித் தொடர்புகள் எந்தப் பயனும் அளிக்காது; ஒரு தந்தை தன் மகனைப் பற்றி விசாரிக்கவோ அல்லது அவன் மீது அக்கறை காட்டவோ மாட்டார்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾وَلَا يَسْأَلُ حَمِيمٌ حَمِيمًا يُبَصَّرُونَهُمْ﴿ (எந்தவொரு நண்பனும் மற்றொரு நண்பனைப் பற்றி விசாரிக்க மாட்டான்; அவர்கள் ஒருவருக்கொருவர் காட்டப்பட்ட போதிலும்) 70:10-11. அதாவது, எந்தவொரு உறவினரும் மற்றொரு உறவினரைப் பற்றி விசாரிக்க மாட்டார்கள்; அவர் அவரை நேரில் கண்டாலும், அவர் ஒரு பெரும் சுமையைச் சுமந்துகொண்டிருந்தாலும் சரியே. இவ்வுலகில் அவர் அவருக்கு மிகவும் பிரியமானவராக இருந்திருந்தாலும், அவர் மீது அக்கறை காட்டமாட்டார் அல்லது அவரது சுமையில் ஒரு சிறு பகுதியைக் கூடப் பகிர்ந்து கொள்ள மாட்டார்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ - وَأُمِّهِ وَأَبِيهِ - وَصَاحِبَتِهِ وَبَنِيهِ﴿ (அந்நாளில் மனிதன் தன் சகோதரனை விட்டும், தன் தாயை விட்டும், தன் தந்தையை விட்டும், தன் மனைவியை விட்டும், தன் பிள்ளைகளை விட்டும் வெருண்டோடுவான்.) 80:34-36. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"மறுமை நாளில், ஆரம்பகால மக்களையும் பிற்கால மக்களையும் அல்லாஹ் ஒன்றுதிரட்டுவான். பிறகு ஒரு குரல் ஒலிக்கும்: 'எவருக்கேனும் பிறரிடமிருந்து ஏதேனும் சேர வேண்டியிருந்தால், அவர் முன்வந்து அதை எடுத்துக் கொள்ளட்டும்.' ஒரு மனிதன், தான் அநீதி இழைக்கப்பட்டிருந்தாலோ அல்லது தன் தந்தை, பிள்ளை அல்லது மனைவியிடமிருந்து ஏதேனும் பாக்கி வர வேண்டியிருந்தாலோ, அது சிறிதளவாக இருந்தாலும் அதற்காக அவன் மகிழ்ச்சியடைவான்.\" இது அல்லாஹ்வின் வேதத்தில் உறுதிப்படுத்தப்பட்டுள்ளது. அல்லாஹ் கூறுகிறான்: ﴾فَإِذَا نُفِخَ فِي الصُّورِ فَلَا أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَاءَلُونَ﴿ (பின்னர், ஸூர் ஊதப்படும்போது, அந்நாளில் அவர்களுக்கிடையே எந்தவிதமான உறமுறைகளும் இருக்காது; அவர்கள் ஒருவரையொருவர் விசாரித்துக்கொள்ளவும் மாட்டார்கள்.) இதனை இப்னு அபீ ஹாதிம் (ரஹ்) பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\n﴾فَمَن ثَقُلَتْ مَوَازِينُهُ فَأُوْلَـئِكَ هُمُ الْمُفْلِحُونَ﴿ (பின்னர், எவருடைய தராசுகள் கனமாக இருக்கின்றனவோ, அவர்களே வெற்றியாளர்கள்.) அதாவது, எவருடைய நன்மைகள் அவருடைய தீமைகளை விட ஒரு நன்மை அதிகமாக இருந்தாலும் சரி, அவர்களே வெற்றியாளர்கள் என்பது இதன் பொருளாகும். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும்.\n\r\n\n\r\n﴾فَأُوْلَـئِكَ هُمُ الْمُفْلِحُونَ﴿ (அவர்களே வெற்றியாளர்கள்.) அதாவது, வெற்றி பெற்று, நரகத்திலிருந்து காப்பாற்றப்பட்டு, சுவனத்தில் அனுமதிக்கப்பட்டவர்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இவர்களே தாங்கள் விரும்பியதை அடைந்தவர்கள்; தப்பிக்கவே முடியாத ஒரு தீங்கிலிருந்து காப்பாற்றப்பட்டவர்கள்.\"\n\r\n\n\r\n﴾وَمَنْ خَفَّتْ مَوَازِينُهُ﴿ (மேலும் எவருடைய தராசுகள் இலேசாக இருக்கின்றனவோ,) அதாவது, எவருடைய தீமைகள் அவர்களுடைய நன்மைகளை விட அதிகமாக இருக்கின்றனவோ அவர்கள்.\n\r\n\n\r\n﴾فَأُوْلَـئِكَ الَّذِينَ خَسِرُواْ أَنفُسَهُم﴿ (அவர்களே தங்களுக்குத் தாங்களே நஷ்டத்தை ஏற்படுத்திக்கொண்டவர்கள்,) அதாவது, அவர்கள் அழிந்துவிட்டார்கள், மிக மோசமான ஒரு முடிவை அடைந்துவிட்டார்கள்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾فِي جَهَنَّمَ خَالِدُونَ﴿ (நரகத்தில் அவர்கள் நிரந்தரமாகத் தங்கியிருப்பார்கள்.) அதாவது, அவர்கள் அங்கே என்றென்றும் இருப்பார்கள், அங்கிருந்து ஒருபோதும் வெளியேற மாட்டார்கள்.\n\r\n\n\r\n﴾تَلْفَحُ وُجُوهَهُمُ النَّارُ﴿ (நெருப்பு அவர்களுடைய முகங்களைக் கரிக்கும்.) இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَتَغْشَى وُجُوهَهُمْ النَّارُ﴿ (மேலும் நெருப்பு அவர்களுடைய முகங்களை மூடிக்கொள்ளும்) 14:50. மேலும்: ﴾لَوْ يَعْلَمُ الَّذِينَ كَفَرُواْ حِينَ لاَ يَكُفُّونَ عَن وُجُوهِهِمُ النَّارَ وَلاَ عَن ظُهُورِهِمْ﴿ (தங்கள் முகங்களிலிருந்தோ, தங்கள் முதுகுகளிலிருந்தோ நெருப்பைத் தடுத்து நிறுத்த முடியாத அந்த நேரத்தை நிராகரிப்பாளர்கள் அறிந்திருக்க வேண்டாமா!) 21:39.\n\r\n\n\r\n﴾وَهُمْ فِيهَا كَالِحُونَ﴿ (அதில் அவர்கள் உதடுகள் பிதுங்கி விகாரமான நிலையில் இருப்பார்கள்.) அலீ பின் அபீ தல்ஹா (ரஹ்) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, \"முகம் சுளித்திருப்பார்கள்\" என்று அறிவிக்கிறார்கள். இமாம் அஹ்மத் (ரஹ்) அவர்கள் அபூ ஸயீத் (ரழி) அவர்கள் வாயிலாக நபி (ஸல்) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"நெருப்பு அவர்களை எரிக்கும்; அப்போது மேல் உதடு சுருண்டு மண்டையின் நடுப்பகுதியை அடையும். கீழ் உதடு தொங்கித் தொப்புளை வந்தடையும்.\" இதனைத் திர்மிதி (ரஹ்) அவர்களும் பதிவு செய்துள்ளார்கள்; மேலும் அவர் இதனை 'ஹஸன், கரீப்' என்று கூறியுள்ளார்."},"105":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=107\" class=\"link\">23:107</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:107 ஐ பார்க்கவும்"},"106":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=107\" class=\"link\">23:107</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:107 ஐ பார்க்கவும்"},"107":{"html":"<strong>நரகவாசிகளைக் கண்டித்தல், அவர்கள் தங்களது துர்ப்பாக்கியத்தை ஒப்புக்கொள்ளுதல் மற்றும் நரகத்திலிருந்து வெளியேற்றப்படக் கோருதல்</strong><br />\r\n<br />\r\nஇது, நரகவாசிகள் செய்த நிராகரிப்பு (குஃப்ர்), பாவங்கள், தடுக்கப்பட்ட காரியங்கள் மற்றும் தீய செயல்களின் காரணமாக அவர்களை அல்லாஹ் கண்டிப்பதாகும். இவற்றின் காரணமாகவே அவர்கள் அழிவுக்குள்ளானார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُنْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِي</span> <span class=\"quran-arabic-font text-success\">تُتْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">فَكُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"உங்களுக்கு என்னுடைய வசனங்கள் ஓதிக் காட்டப்படவில்லையா? பின்னர், அவற்றை நீங்கள் பொய்ப்பித்துக் கொண்டிருந்தீர்களே!\") அதாவது, 'நான் உங்களுக்குத் தூதர்களை (அலை) அனுப்பினேன், வேதங்களை அருளினேன், மேலும் உங்களுக்கான சந்தேகங்களைத் தெளிவுபடுத்தினேன். எனவே, உங்களிடம் இப்போது எந்தச் சாக்குப்போக்கும் இல்லை.' இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِئَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حُجَّةٌ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلِ﴿</span><br />\r\n<br />\r\n(தூதர்களுக்குப் பிறகு அல்லாஹ்வுக்கு எதிராக மனிதர்களுக்கு எந்த ஒரு ஆதாரமும் (சாக்குப்போக்கும்) இருக்கக் கூடாது என்பதற்காக) <a href=\"qurandisp.php?sura=4&ayah=165\" class=\"link\">4:165</a>.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُعَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">نَبْعَثَ</span> <span class=\"quran-arabic-font text-success\">رَسُولاً﴿</span><br />\r\n<br />\r\n(மேலும், நாம் ஒரு தூதரை அனுப்பும் வரை (யாரையும்) தண்டிப்பதில்லை) <a href=\"qurandisp.php?sura=17&ayah=15\" class=\"link\">17:15</a>.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كُلَّمَا</span> <span class=\"quran-arabic-font text-success\">أُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَوْجٌ</span> <span class=\"quran-arabic-font text-success\">سَأَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">خَزَنَتُهَآ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتِكُمْ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு முறையும் ஒரு கூட்டம் அதில் எறியப்படும் போதெல்லாம், அதன் காவலர்கள் அவர்களிடம், \"உங்களிடம் எச்சரிப்பவர் எவரும் வரவில்லையா?\" என்று கேட்பார்கள்.) அல்லாஹ் இவ்வாறு கூறுவது வரை:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَسُحْقًا</span> <span class=\"quran-arabic-font text-success\">لِّأَصْحَابِ</span> <span class=\"quran-arabic-font text-success\">السَّعِيرِ﴿</span><br />\r\n<br />\r\n(ஆகவே, நரகவாசிகள் (அல்லாஹ்வின் அருளிலிருந்து) வெகு தொலைவில் அழிந்து போவார்களாக!) <a href=\"qurandisp.php?sura=67&ayah=8\" class=\"link\">67:8</a>-11 அவர்கள் கூறுவார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">غَلَبَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">شِقْوَتُنَا</span> <span class=\"quran-arabic-font text-success\">وَكُنَّا</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">ضَآلِّينَ﴿</span><br />\r\n<br />\r\n(\"எங்கள் இறைவா! எங்களது துர்ப்பாக்கியம் எங்களை மிகைத்துவிட்டது. நாங்கள் வழிதவறிய கூட்டமாகவே இருந்தோம்.\") அதாவது, எங்களுக்கு எதிராக ஆதாரம் நிலைநாட்டப்பட்டுவிட்டது. ஆனால் நாங்கள் வழிகேட்டில் மூழ்கியிருந்ததால் நேர்வழியைப் பின்பற்ற முடியவில்லை. எனவே நாங்கள் வழிதவறிச் சென்றோம், நேர்வழி பெறவில்லை.<br />\r\n<br />\r\nபிறகு அவர்கள் கூறுவார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عُدْنَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">ظَالِمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"எங்கள் இறைவா! எங்களை இதிலிருந்து வெளியேற்றுவாயாக! நாங்கள் மீண்டும் (தீமைக்குத்) திரும்பினால், நிச்சயமாக நாங்கள் அநியாயக்காரர்களாவோம்.\") அதாவது, எங்களை மீண்டும் இவ்வுலகிற்குத் திருப்பி அனுப்புவாயாக! நாங்கள் முன்பு செய்த பாவங்களுக்கு மீண்டும் திரும்பினால், அப்போது நிச்சயமாக நாங்கள் தண்டனைக்குரிய அநியாயக்காரர்களாகிவிடுவோம். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاعْتَرَفْنَا</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِنَا</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">خُرُوجٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">سَبِيلٍ﴿</span><br />\r\n<br />\r\n(\"இப்போது நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம். எனவே வெளியேறுவதற்கு ஏதேனும் வழி உண்டா?\") அவனது இந்தக் கூற்று வரை:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَالْحُكْمُ</span> <span class=\"quran-arabic-font text-success\">للَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيِّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرِ﴿</span><br />\r\n<br />\r\n(\"ஆகவே, தீர்ப்பு அல்லாஹ்விடமே உள்ளது; அவன் மிக உயர்ந்தவன், மிகப் பெரியவன்!\") <a href=\"qurandisp.php?sura=40&ayah=11\" class=\"link\">40:11</a>-12. அதாவது, (நரகத்திலிருந்து) வெளியேற எந்த வழியும் இல்லை. ஏனெனில் இறைநம்பிக்கையாளர்கள் அல்லாஹ்வை மாத்திரம் வணங்கியபோது, நீங்கள் அல்லாஹ்வுக்கு இணைகளை (ஷிர்க்) கற்பித்துக்கொண்டிருந்தீர்கள்.<br />\r\n<br />","text":"நரகவாசிகளைக் கண்டித்தல், அவர்கள் தங்களது துர்ப்பாக்கியத்தை ஒப்புக்கொள்ளுதல் மற்றும் நரகத்திலிருந்து வெளியேற்றப்படக் கோருதல்\n\r\n\n\r\nஇது, நரகவாசிகள் செய்த நிராகரிப்பு (குஃப்ர்), பாவங்கள், தடுக்கப்பட்ட காரியங்கள் மற்றும் தீய செயல்களின் காரணமாக அவர்களை அல்லாஹ் கண்டிப்பதாகும். இவற்றின் காரணமாகவே அவர்கள் அழிவுக்குள்ளானார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n﴾أَلَمْ تَكُنْ آيَاتِي تُتْلَى عَلَيْكُمْ فَكُنْتُمْ بِهَا تُكَذِّبُونَ ﴿\n\r\n\n\r\n(\"உங்களுக்கு என்னுடைய வசனங்கள் ஓதிக் காட்டப்படவில்லையா? பின்னர், அவற்றை நீங்கள் பொய்ப்பித்துக் கொண்டிருந்தீர்களே!\") அதாவது, 'நான் உங்களுக்குத் தூதர்களை (அலை) அனுப்பினேன், வேதங்களை அருளினேன், மேலும் உங்களுக்கான சந்தேகங்களைத் தெளிவுபடுத்தினேன். எனவே, உங்களிடம் இப்போது எந்தச் சாக்குப்போக்கும் இல்லை.' இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾لِئَلاَّ يَكُونَ لِلنَّاسِ عَلَى اللَّهِ حُجَّةٌ بَعْدَ الرُّسُلِ﴿\n\r\n\n\r\n(தூதர்களுக்குப் பிறகு அல்லாஹ்வுக்கு எதிராக மனிதர்களுக்கு எந்த ஒரு ஆதாரமும் (சாக்குப்போக்கும்) இருக்கக் கூடாது என்பதற்காக) 4:165.\n\r\n﴾وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً﴿\n\r\n\n\r\n(மேலும், நாம் ஒரு தூதரை அனுப்பும் வரை (யாரையும்) தண்டிப்பதில்லை) 17:15.\n\r\n﴾كُلَّمَا أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ﴿\n\r\n\n\r\n(ஒவ்வொரு முறையும் ஒரு கூட்டம் அதில் எறியப்படும் போதெல்லாம், அதன் காவலர்கள் அவர்களிடம், \"உங்களிடம் எச்சரிப்பவர் எவரும் வரவில்லையா?\" என்று கேட்பார்கள்.) அல்லாஹ் இவ்வாறு கூறுவது வரை:\n\r\n﴾فَسُحْقًا لِّأَصْحَابِ السَّعِيرِ﴿\n\r\n\n\r\n(ஆகவே, நரகவாசிகள் (அல்லாஹ்வின் அருளிலிருந்து) வெகு தொலைவில் அழிந்து போவார்களாக!) 67:8-11 அவர்கள் கூறுவார்கள்:\n\r\n﴾رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْماً ضَآلِّينَ﴿\n\r\n\n\r\n(\"எங்கள் இறைவா! எங்களது துர்ப்பாக்கியம் எங்களை மிகைத்துவிட்டது. நாங்கள் வழிதவறிய கூட்டமாகவே இருந்தோம்.\") அதாவது, எங்களுக்கு எதிராக ஆதாரம் நிலைநாட்டப்பட்டுவிட்டது. ஆனால் நாங்கள் வழிகேட்டில் மூழ்கியிருந்ததால் நேர்வழியைப் பின்பற்ற முடியவில்லை. எனவே நாங்கள் வழிதவறிச் சென்றோம், நேர்வழி பெறவில்லை.\n\r\n\n\r\nபிறகு அவர்கள் கூறுவார்கள்:\n\r\n﴾رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَالِمُونَ ﴿\n\r\n\n\r\n(\"எங்கள் இறைவா! எங்களை இதிலிருந்து வெளியேற்றுவாயாக! நாங்கள் மீண்டும் (தீமைக்குத்) திரும்பினால், நிச்சயமாக நாங்கள் அநியாயக்காரர்களாவோம்.\") அதாவது, எங்களை மீண்டும் இவ்வுலகிற்குத் திருப்பி அனுப்புவாயாக! நாங்கள் முன்பு செய்த பாவங்களுக்கு மீண்டும் திரும்பினால், அப்போது நிச்சயமாக நாங்கள் தண்டனைக்குரிய அநியாயக்காரர்களாகிவிடுவோம். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n﴾فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَى خُرُوجٍ مِّن سَبِيلٍ﴿\n\r\n\n\r\n(\"இப்போது நாங்கள் எங்கள் பாவங்களை ஒப்புக்கொள்கிறோம். எனவே வெளியேறுவதற்கு ஏதேனும் வழி உண்டா?\") அவனது இந்தக் கூற்று வரை:\n\r\n﴾فَالْحُكْمُ للَّهِ الْعَلِيِّ الْكَبِيرِ﴿\n\r\n\n\r\n(\"ஆகவே, தீர்ப்பு அல்லாஹ்விடமே உள்ளது; அவன் மிக உயர்ந்தவன், மிகப் பெரியவன்!\") 40:11-12. அதாவது, (நரகத்திலிருந்து) வெளியேற எந்த வழியும் இல்லை. ஏனெனில் இறைநம்பிக்கையாளர்கள் அல்லாஹ்வை மாத்திரம் வணங்கியபோது, நீங்கள் அல்லாஹ்வுக்கு இணைகளை (ஷிர்க்) கற்பித்துக்கொண்டிருந்தீர்கள்."},"108":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=111\" class=\"link\">23:111</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:111 ஐ பார்க்கவும்"},"109":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=111\" class=\"link\">23:111</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:111 ஐ பார்க்கவும்"},"110":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=111\" class=\"link\">23:111</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:111 ஐ பார்க்கவும்"},"111":{"html":"<strong>அல்லாஹ்வின் பதிலும், நிராகரிப்பாளர்களை அவன் நிராகரிப்பதும்</strong><br />\r\n<br />\r\nநரக நெருப்பிலிருந்து தங்களை வெளியேற்றி, மீண்டும் இவ்வுலகிற்குத் திருப்பி அனுப்புமாறு நிராகரிப்பாளர்கள் அல்லாஹ்விடம் கேட்கும்போது, அவன் அவர்களுக்கு அளிக்கும் பதில் இதுவாகும். அவன் கூறுவான்: <span class=\"quran-arabic-font text-success\">﴾اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்!) அதாவது, சிறுமைப்படுத்தப்பட்டவர்களாக, அவமதிக்கப்பட்டவர்களாக, வெறுக்கத்தக்க நிலையில் அங்கேயே நிலைத்திருங்கள். <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ﴿</span><br />\r\n<br />\r\n(மேலும் என்னிடம் பேசாதீர்கள்!) இதன் பொருள், 'இதை மீண்டும் என்னிடம் கேட்காதீர்கள், ஏனெனில் நான் உங்களுக்குப் பதிலளிக்க மாட்டேன்' என்பதாகும். இந்த வசனம் குறித்து அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ﴿</span><br />\r\n<br />\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்! மேலும் என்னிடம் பேசாதீர்கள்!) \"அவர்களை மௌனமாக்கும்போது அர்-ரஹ்மான் (அல்லாஹ்) கூறும் வார்த்தைகள் இவை.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறினார்கள், \"நரகவாசிகள் நாற்பது ஆண்டுகள் வரை (நரகத்தின் காவலரான) மாலிக்கை அழைப்பார்கள், ஆனால் அவர் அவர்களுக்குப் பதிலளிக்க மாட்டார். பிறகு அவர் பதிலளித்து, அவர்கள் அங்கேயே நிலைத்திருக்கப் போகிறார்கள் என்று கூறுவார். அல்லாஹ்வின் மீது சத்தியமாக, அவர்களின் கூக்குரல்கள் மாலிக்கிற்கோ அல்லது மாலிக்கின் இறைவனுக்கோ எவ்வித மாற்றத்தையும் ஏற்படுத்தாது. பிறகு அவர்கள் தங்கள் இறைவனை அழைத்து இவ்வாறு கூறுவார்கள்: <span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">غَلَبَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">شِقْوَتُنَا</span> <span class=\"quran-arabic-font text-success\">وَكُنَّا</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">ضَآلِّينَ</span> - <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عُدْنَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">ظَـلِمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவா! எங்கள் துரதிர்ஷ்டம் எங்களை மிகைத்துவிட்டது, நாங்கள் வழிதவறிய சமூகமாக இருந்தோம். எங்கள் இறைவா! எங்களை இதிலிருந்து வெளியேற்றுவாயாக. நாங்கள் மீண்டும் தீமையின் பக்கம் திரும்பினால், நிச்சயமாக நாங்கள் அநீதி இழைத்தவர்களாவோம்.) (<a href=\"qurandisp.php?sura=23&ayah=106\" class=\"link\">23:106</a>-107). இவ்வுலகின் காலத்தைப் போல இரண்டு மடங்கு காலத்திற்கு அல்லாஹ் அவர்களுக்குப் பதிலளிக்க மாட்டான். பின்னர் அவன் பதிலளிப்பான்: <span class=\"quran-arabic-font text-success\">﴾اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ﴿</span><br />\r\n<br />\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்! மேலும் என்னிடம் பேசாதீர்கள்!) அல்லாஹ்வின் மீது சத்தியமாக, அதன் பிறகு அந்த மக்கள் ஒரு வார்த்தை கூட பேச மாட்டார்கள். அவர்கள் நரக நெருப்பில் ஏறி இறங்கும் தொனியில் பெருமூச்சு விட்டுக் கொண்டிருப்பார்கள். அவர்களின் குரல்கள் கழுதைகளின் குரல்களுக்கு ஒப்பிடப்பட்டுள்ளன; அவை ஒரு உயர்ந்த தொனியில் தொடங்கித் தாழ்ந்த தொனியில் முடியும்.\" பிறகு அல்லாஹ் இவ்வுலகில் அவர்கள் செய்த பாவங்களையும், தன்னுடைய நம்பிக்கையாளர்களான அடியார்களையும் உற்ற நண்பர்களையும் அவர்கள் எவ்வாறு பரிகாசம் செய்தார்கள் என்பதையும் அவர்களுக்கு நினைவூட்டுவான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فَرِيقٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">فَاغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">وَارْحَمْنَا</span> <span class=\"quran-arabic-font text-success\">وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الرَّاحِمِينَ</span> <span class=\"quran-arabic-font text-success\">فَاتَّخَذْتُمُوهُمْ</span> <span class=\"quran-arabic-font text-success\">سِخْرِيّاً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, என் அடியார்களில் ஒரு பிரிவினர், \"எங்கள் இறைவா! நாங்கள் ஈமான் (நம்பிக்கை) கொண்டோம், எனவே எங்களை மன்னிப்பாயாக! எங்களுக்குக் கருணை காட்டுவாயாக! கருணையாளர்களிலெல்லாம் நீயே மிகச் சிறந்தவன்\" என்று வேண்டிக் கொண்டிருந்தார்கள். ஆனால் நீங்களோ அவர்களைப் பரிகாசப் பொருளாக ஆக்கிக் கொண்டீர்கள்.) அதாவது, 'அவர்கள் என்னை அழைத்துப் பிரார்த்தனை செய்ததற்காக நீங்கள் அவர்களைக் கேலி செய்தீர்கள்.' <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">أَنسَوْكُمْ</span> <span class=\"quran-arabic-font text-success\">ذِكْرِى﴿</span><br />\r\n<br />\r\n(எந்த அளவுக்கென்றால், அவர்கள் என் நினைவையே உங்களுக்கு மறக்கச் செய்துவிட்டார்கள்.) இதன் பொருள், அவர்கள் மீதான உங்கள் வெறுப்பு, நான் உங்களுக்கு அளிக்கப்போகும் தண்டனையை உங்களுக்கு மறக்கச் செய்துவிட்டது என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَكُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">تَضْحَكُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அவர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தீர்கள்!) அதாவது, அவர்களுடைய செயல்களையும் வணக்கங்களையும் கண்டு சிரித்தீர்கள். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَجْرَمُواْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">يَضْحَكُونَ</span> - <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَتَغَامَزُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாகக் குற்றம் செய்தவர்கள், ஈமான் கொண்டவர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தார்கள். அவர்கள் இவர்களைக் கடந்து செல்லும் போதெல்லாம், ஒருவர் மற்றவருக்குக் கண்ஜாடை காட்டிப் பரிகசிப்பார்கள்.) (<a href=\"qurandisp.php?sura=83&ayah=29\" class=\"link\">83:29</a>-30). அதாவது, அவர்கள் நம்பிக்கையாளர்களைக் கேலியாகப் பழிதூற்றினார்கள். பின்னர், அல்லாஹ் தன் நேசர்களுக்கும் நற்செயல் புரிந்த அடியார்களுக்கும் எவ்வாறு கூலி வழங்குவான் என்பதை விவரிக்கிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنِّى</span> <span class=\"quran-arabic-font text-success\">جَزَيْتُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் பொறுமையுடன் இருந்ததற்காக இந்த நாளில் நான் அவர்களுக்குரிய கூலியை வழங்கிவிட்டேன்.) அதாவது, 'நீங்கள் அவர்களுக்கு இழைத்த தீங்குகளையும் கேலிகளையும் அவர்கள் சகித்துக் கொண்டதற்காகவே இக்கூலி.' <span class=\"quran-arabic-font text-success\">﴾أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَآئِزُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்களே வெற்றி பெற்றவர்கள்.) மகிழ்ச்சி, பாதுகாப்பு, சொர்க்கம் ஆகியவற்றின் வெற்றியையும் நரக நெருப்பிலிருந்து விடுதலையையும் அவர்கள் அடையும்படி நான் செய்தேன்.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ்வின் பதிலும், நிராகரிப்பாளர்களை அவன் நிராகரிப்பதும்\n\r\n\n\r\nநரக நெருப்பிலிருந்து தங்களை வெளியேற்றி, மீண்டும் இவ்வுலகிற்குத் திருப்பி அனுப்புமாறு நிராகரிப்பாளர்கள் அல்லாஹ்விடம் கேட்கும்போது, அவன் அவர்களுக்கு அளிக்கும் பதில் இதுவாகும். அவன் கூறுவான்: ﴾اخْسَئُواْ فِيهَا﴿\n\r\n\n\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்!) அதாவது, சிறுமைப்படுத்தப்பட்டவர்களாக, அவமதிக்கப்பட்டவர்களாக, வெறுக்கத்தக்க நிலையில் அங்கேயே நிலைத்திருங்கள். ﴾وَلاَ تُكَلِّمُونِ﴿\n\r\n\n\r\n(மேலும் என்னிடம் பேசாதீர்கள்!) இதன் பொருள், 'இதை மீண்டும் என்னிடம் கேட்காதீர்கள், ஏனெனில் நான் உங்களுக்குப் பதிலளிக்க மாட்டேன்' என்பதாகும். இந்த வசனம் குறித்து அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: ﴾اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ﴿\n\r\n\n\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்! மேலும் என்னிடம் பேசாதீர்கள்!) \"அவர்களை மௌனமாக்கும்போது அர்-ரஹ்மான் (அல்லாஹ்) கூறும் வார்த்தைகள் இவை.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறினார்கள், \"நரகவாசிகள் நாற்பது ஆண்டுகள் வரை (நரகத்தின் காவலரான) மாலிக்கை அழைப்பார்கள், ஆனால் அவர் அவர்களுக்குப் பதிலளிக்க மாட்டார். பிறகு அவர் பதிலளித்து, அவர்கள் அங்கேயே நிலைத்திருக்கப் போகிறார்கள் என்று கூறுவார். அல்லாஹ்வின் மீது சத்தியமாக, அவர்களின் கூக்குரல்கள் மாலிக்கிற்கோ அல்லது மாலிக்கின் இறைவனுக்கோ எவ்வித மாற்றத்தையும் ஏற்படுத்தாது. பிறகு அவர்கள் தங்கள் இறைவனை அழைத்து இவ்வாறு கூறுவார்கள்: ﴾قَالُواْ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْماً ضَآلِّينَ - رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَـلِمُونَ ﴿\n\r\n\n\r\n(எங்கள் இறைவா! எங்கள் துரதிர்ஷ்டம் எங்களை மிகைத்துவிட்டது, நாங்கள் வழிதவறிய சமூகமாக இருந்தோம். எங்கள் இறைவா! எங்களை இதிலிருந்து வெளியேற்றுவாயாக. நாங்கள் மீண்டும் தீமையின் பக்கம் திரும்பினால், நிச்சயமாக நாங்கள் அநீதி இழைத்தவர்களாவோம்.) (23:106-107). இவ்வுலகின் காலத்தைப் போல இரண்டு மடங்கு காலத்திற்கு அல்லாஹ் அவர்களுக்குப் பதிலளிக்க மாட்டான். பின்னர் அவன் பதிலளிப்பான்: ﴾اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ﴿\n\r\n\n\r\n(இழிவடைந்தவர்களாக அதிலேயே தங்கியிருங்கள்! மேலும் என்னிடம் பேசாதீர்கள்!) அல்லாஹ்வின் மீது சத்தியமாக, அதன் பிறகு அந்த மக்கள் ஒரு வார்த்தை கூட பேச மாட்டார்கள். அவர்கள் நரக நெருப்பில் ஏறி இறங்கும் தொனியில் பெருமூச்சு விட்டுக் கொண்டிருப்பார்கள். அவர்களின் குரல்கள் கழுதைகளின் குரல்களுக்கு ஒப்பிடப்பட்டுள்ளன; அவை ஒரு உயர்ந்த தொனியில் தொடங்கித் தாழ்ந்த தொனியில் முடியும்.\" பிறகு அல்லாஹ் இவ்வுலகில் அவர்கள் செய்த பாவங்களையும், தன்னுடைய நம்பிக்கையாளர்களான அடியார்களையும் உற்ற நண்பர்களையும் அவர்கள் எவ்வாறு பரிகாசம் செய்தார்கள் என்பதையும் அவர்களுக்கு நினைவூட்டுவான்: ﴾إِنَّهُ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ فَاتَّخَذْتُمُوهُمْ سِخْرِيّاً﴿\n\r\n\n\r\n(நிச்சயமாக, என் அடியார்களில் ஒரு பிரிவினர், \"எங்கள் இறைவா! நாங்கள் ஈமான் (நம்பிக்கை) கொண்டோம், எனவே எங்களை மன்னிப்பாயாக! எங்களுக்குக் கருணை காட்டுவாயாக! கருணையாளர்களிலெல்லாம் நீயே மிகச் சிறந்தவன்\" என்று வேண்டிக் கொண்டிருந்தார்கள். ஆனால் நீங்களோ அவர்களைப் பரிகாசப் பொருளாக ஆக்கிக் கொண்டீர்கள்.) அதாவது, 'அவர்கள் என்னை அழைத்துப் பிரார்த்தனை செய்ததற்காக நீங்கள் அவர்களைக் கேலி செய்தீர்கள்.' ﴾حَتَّى أَنسَوْكُمْ ذِكْرِى﴿\n\r\n\n\r\n(எந்த அளவுக்கென்றால், அவர்கள் என் நினைவையே உங்களுக்கு மறக்கச் செய்துவிட்டார்கள்.) இதன் பொருள், அவர்கள் மீதான உங்கள் வெறுப்பு, நான் உங்களுக்கு அளிக்கப்போகும் தண்டனையை உங்களுக்கு மறக்கச் செய்துவிட்டது என்பதாகும். ﴾وَكُنْتُمْ مِّنْهُمْ تَضْحَكُونَ﴿\n\r\n\n\r\n(நீங்கள் அவர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தீர்கள்!) அதாவது, அவர்களுடைய செயல்களையும் வணக்கங்களையும் கண்டு சிரித்தீர்கள். இது பின்வரும் வசனத்தைப் போன்றது: ﴾إِنَّ الَّذِينَ أَجْرَمُواْ كَانُواْ مِنَ الَّذِينَ ءَامَنُواْ يَضْحَكُونَ - وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ ﴿\n\r\n\n\r\n(நிச்சயமாகக் குற்றம் செய்தவர்கள், ஈமான் கொண்டவர்களைப் பார்த்துச் சிரித்துக் கொண்டிருந்தார்கள். அவர்கள் இவர்களைக் கடந்து செல்லும் போதெல்லாம், ஒருவர் மற்றவருக்குக் கண்ஜாடை காட்டிப் பரிகசிப்பார்கள்.) (83:29-30). அதாவது, அவர்கள் நம்பிக்கையாளர்களைக் கேலியாகப் பழிதூற்றினார்கள். பின்னர், அல்லாஹ் தன் நேசர்களுக்கும் நற்செயல் புரிந்த அடியார்களுக்கும் எவ்வாறு கூலி வழங்குவான் என்பதை விவரிக்கிறான்: ﴾إِنِّى جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُواْ﴿\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் பொறுமையுடன் இருந்ததற்காக இந்த நாளில் நான் அவர்களுக்குரிய கூலியை வழங்கிவிட்டேன்.) அதாவது, 'நீங்கள் அவர்களுக்கு இழைத்த தீங்குகளையும் கேலிகளையும் அவர்கள் சகித்துக் கொண்டதற்காகவே இக்கூலி.' ﴾أَنَّهُمْ هُمُ الْفَآئِزُونَ﴿\n\r\n\n\r\n(நிச்சயமாக அவர்களே வெற்றி பெற்றவர்கள்.) மகிழ்ச்சி, பாதுகாப்பு, சொர்க்கம் ஆகியவற்றின் வெற்றியையும் நரக நெருப்பிலிருந்து விடுதலையையும் அவர்கள் அடையும்படி நான் செய்தேன்.\""},"112":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=116\" class=\"link\">23:116</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:116 ஐ பார்க்கவும்"},"113":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=116\" class=\"link\">23:116</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:116 ஐ பார்க்கவும்"},"114":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=116\" class=\"link\">23:116</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:116 ஐ பார்க்கவும்"},"115":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=116\" class=\"link\">23:116</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:116 ஐ பார்க்கவும்"},"116":{"html":"<strong>இந்த உலகில் அல்லாஹ்வுக்குக் கீழ்ப்படியாமலும், அவனை மட்டுமே வணங்காமலும் இருந்ததன் மூலம், அவர்கள் தங்களின் குறுகிய வாழ்க்கையை எவ்வளவு வீணடித்தார்கள் என்று அல்லாஹ் அவர்களுக்குக் கூறுகிறான்.</strong><br />\r\n<br />\r\nஇந்த உலகில் அவர்கள் தங்கியிருந்த குறுகிய காலத்தில் பொறுமையைக் கடைப்பிடித்திருந்தால், அல்லாஹ்வின் இறையச்சமுள்ள நேசர்களைப் போலவே அவர்களும் வெற்றியடைந்திருப்பார்கள்.<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">لَبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">عَدَدَ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவன் கேட்பான்: \"பூமியில் நீங்கள் எத்தனை ஆண்டுகள் தங்கியிருந்தீர்கள்?\") என்பது, இந்த உலகில் நீங்கள் எவ்வளவு காலம் தங்கியிருந்தீர்கள் என்பதைக் குறிக்கிறது.<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَبِثْنَا</span> <span class=\"quran-arabic-font text-success\">يَوْمًا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلِ</span> <span class=\"quran-arabic-font text-success\">الْعَادِّينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதற்கு அவர்கள்: \"நாங்கள் ஒரு நாள் அல்லது ஒரு நாளின் சிறு பகுதி தங்கியிருந்தோம்; எனவே (காலத்தைக்) கணக்கிடுபவர்களிடம் கேட்பாயாக!\" எனக் கூறுவார்கள்.) அதாவது, பதிவேடுகளைப் பராமரிப்பவர்களைக் குறிக்கிறது.<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّبِثْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً﴿</span><br />\r\n<br />\r\n(அதற்கு அவன்: \"நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள்...\" என்று கூறுவான்.) அதாவது, நீங்கள் எந்தக் கண்ணோட்டத்தில் பார்த்தாலும் அது ஒரு குறுகிய காலமே.<span class=\"quran-arabic-font text-success\">﴾لَّوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அறிந்திருந்தால்!) அதாவது, நிலைத்து நிற்காத இவ்வுலக வாழ்க்கையை நிலையான மறுமை வாழ்க்கையை விட நீங்கள் தேர்ந்தெடுத்திருக்க மாட்டீர்கள்; உங்களையே இந்தத் தீய நிலைக்கு ஆளாக்கி, இந்தக் குறுகிய காலத்தில் அல்லாஹ்வின் கோபத்தைச் சம்பாதித்திருக்கவும் மாட்டீர்கள். இறைநம்பிக்கையாளர்கள் செய்ததைப் போல நீங்களும் பொறுமையுடன் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து, அவனை வணங்கியிருந்தால், அவர்களைப் போலவே நீங்களும் வெற்றி பெற்றிருப்பீர்கள்.<br />\r\n<br />\r\n<strong>அல்லாஹ் தன் அடியார்களை வீணாகப் படைக்கவில்லை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَحَسِبْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">عَبَثًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"நாம் உங்களை வீணாகப் படைத்தோம் என்று நீங்கள் நினைத்தீர்களா?\") அதாவது, 'எந்த நோக்கமும் இன்றி, உங்களிடமிருந்து எதையும் எதிர்பார்க்காமல், நம்மிடம் எந்த ஞானமும் இன்றி நீங்கள் வீணாகப் படைக்கப்பட்டீர்கள் என்று நினைத்தீர்களா?' அல்லது \"விளையாட்டாக\" என்பது, எவ்வித நற்கூலியோ தண்டனையோ இல்லாத விலங்குகளைப் போல, நீங்கள் விளையாடி மகிழ்வதற்காகவே படைக்கப்பட்டீர்கள் என்று ஒரு கருத்து கூறப்பட்டது. ஆனால், நீங்கள் அல்லாஹ்வை வணங்குவதற்கும் அவனுடைய கட்டளைகளை நிறைவேற்றுவதற்கும் படைக்கப்பட்டீர்கள்.<span class=\"quran-arabic-font text-success\">﴾وَأَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ﴿</span><br />\r\n<br />\r\n(\"மேலும் நீங்கள் நம்மிடம் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள்\" என்றும் நினைத்தீர்களா?) அதாவது, நீங்கள் மறுமை வாழ்க்கைக்குத் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள் என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾أَيَحْسَبُ</span> <span class=\"quran-arabic-font text-success\">الْإِنسَانُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُتْرَكَ</span> <span class=\"quran-arabic-font text-success\">سُدًى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மனிதன் வீணாக விட்டுவிடப்படுவான் என்று எண்ணுகிறானா?) <a href=\"qurandisp.php?sura=75&ayah=36\" class=\"link\">75:36</a><span class=\"quran-arabic-font text-success\">﴾فَتَعَالَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ﴿</span><br />\r\n<br />\r\n(ஆகவே, உண்மையான அரசனாகிய அல்லாஹ் மிகவும் உயர்ந்தவன்.) அதாவது, எதையும் வீணாகப் படைப்பான் என்ற எண்ணத்தை விட்டும் அவன் தூய்மையானவன்; ஏனெனில் அவன் இத்தகைய செயல்களைச் செய்வதற்கு அப்பாற்பட்ட உண்மையான அரசன் ஆவான்.<span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">إِلَهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمِ﴿</span><br />\r\n<br />\r\n(அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; அவன் மகத்தான 'அர்ஷின்' (அரியாசனத்தின்) அதிபதி ஆவான்!) அர்ஷ் குறிப்பிடப்பட்டதற்குக் காரணம், அது படைப்புகளிலேயே மிக உயர்ந்த இடமாகும். மேலும் அது 'கரீம்' என விவரிக்கப்பட்டுள்ளது, அதற்கு அழகான தோற்றமும் சிறப்பான வடிவமும் கொண்டது என்று பொருள். இதனை அல்லாஹ் வேறொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾أَنبَتْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">زَوْجٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ﴿</span><br />\r\n<br />\r\n(அதில் ஒவ்வோர் அழகான இனத்தையும் நாம் முளைக்கச் செய்துள்ளோம்.) <a href=\"qurandisp.php?sura=26&ayah=7\" class=\"link\">26:7</a>.<br />\r\n<br />","text":"இந்த உலகில் அல்லாஹ்வுக்குக் கீழ்ப்படியாமலும், அவனை மட்டுமே வணங்காமலும் இருந்ததன் மூலம், அவர்கள் தங்களின் குறுகிய வாழ்க்கையை எவ்வளவு வீணடித்தார்கள் என்று அல்லாஹ் அவர்களுக்குக் கூறுகிறான்.\n\r\n\n\r\nஇந்த உலகில் அவர்கள் தங்கியிருந்த குறுகிய காலத்தில் பொறுமையைக் கடைப்பிடித்திருந்தால், அல்லாஹ்வின் இறையச்சமுள்ள நேசர்களைப் போலவே அவர்களும் வெற்றியடைந்திருப்பார்கள்.﴾قَالَ كَمْ لَبِثْتُمْ فِي الْأَرْضِ عَدَدَ سِنِينَ ﴿\n\r\n\n\r\n(அவன் கேட்பான்: \"பூமியில் நீங்கள் எத்தனை ஆண்டுகள் தங்கியிருந்தீர்கள்?\") என்பது, இந்த உலகில் நீங்கள் எவ்வளவு காலம் தங்கியிருந்தீர்கள் என்பதைக் குறிக்கிறது.﴾قَالُواْ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَاسْأَلِ الْعَادِّينَ ﴿\n\r\n\n\r\n(அதற்கு அவர்கள்: \"நாங்கள் ஒரு நாள் அல்லது ஒரு நாளின் சிறு பகுதி தங்கியிருந்தோம்; எனவே (காலத்தைக்) கணக்கிடுபவர்களிடம் கேட்பாயாக!\" எனக் கூறுவார்கள்.) அதாவது, பதிவேடுகளைப் பராமரிப்பவர்களைக் குறிக்கிறது.﴾قَالَ إِن لَّبِثْتُمْ إِلَّا قَلِيلاً﴿\n\r\n\n\r\n(அதற்கு அவன்: \"நீங்கள் மிகக் குறைந்த காலமே தங்கியிருந்தீர்கள்...\" என்று கூறுவான்.) அதாவது, நீங்கள் எந்தக் கண்ணோட்டத்தில் பார்த்தாலும் அது ஒரு குறுகிய காலமே.﴾لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ﴿\n\r\n\n\r\n(நீங்கள் அறிந்திருந்தால்!) அதாவது, நிலைத்து நிற்காத இவ்வுலக வாழ்க்கையை நிலையான மறுமை வாழ்க்கையை விட நீங்கள் தேர்ந்தெடுத்திருக்க மாட்டீர்கள்; உங்களையே இந்தத் தீய நிலைக்கு ஆளாக்கி, இந்தக் குறுகிய காலத்தில் அல்லாஹ்வின் கோபத்தைச் சம்பாதித்திருக்கவும் மாட்டீர்கள். இறைநம்பிக்கையாளர்கள் செய்ததைப் போல நீங்களும் பொறுமையுடன் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து, அவனை வணங்கியிருந்தால், அவர்களைப் போலவே நீங்களும் வெற்றி பெற்றிருப்பீர்கள்.\n\r\n\n\r\nஅல்லாஹ் தன் அடியார்களை வீணாகப் படைக்கவில்லை\n\r\n\n\r\n﴾أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا ﴿\n\r\n\n\r\n(\"நாம் உங்களை வீணாகப் படைத்தோம் என்று நீங்கள் நினைத்தீர்களா?\") அதாவது, 'எந்த நோக்கமும் இன்றி, உங்களிடமிருந்து எதையும் எதிர்பார்க்காமல், நம்மிடம் எந்த ஞானமும் இன்றி நீங்கள் வீணாகப் படைக்கப்பட்டீர்கள் என்று நினைத்தீர்களா?' அல்லது \"விளையாட்டாக\" என்பது, எவ்வித நற்கூலியோ தண்டனையோ இல்லாத விலங்குகளைப் போல, நீங்கள் விளையாடி மகிழ்வதற்காகவே படைக்கப்பட்டீர்கள் என்று ஒரு கருத்து கூறப்பட்டது. ஆனால், நீங்கள் அல்லாஹ்வை வணங்குவதற்கும் அவனுடைய கட்டளைகளை நிறைவேற்றுவதற்கும் படைக்கப்பட்டீர்கள்.﴾وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ﴿\n\r\n\n\r\n(\"மேலும் நீங்கள் நம்மிடம் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள்\" என்றும் நினைத்தீர்களா?) அதாவது, நீங்கள் மறுமை வாழ்க்கைக்குத் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள் என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:﴾أَيَحْسَبُ الْإِنسَانُ أَن يُتْرَكَ سُدًى ﴿\n\r\n\n\r\n(மனிதன் வீணாக விட்டுவிடப்படுவான் என்று எண்ணுகிறானா?) 75:36﴾فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ﴿\n\r\n\n\r\n(ஆகவே, உண்மையான அரசனாகிய அல்லாஹ் மிகவும் உயர்ந்தவன்.) அதாவது, எதையும் வீணாகப் படைப்பான் என்ற எண்ணத்தை விட்டும் அவன் தூய்மையானவன்; ஏனெனில் அவன் இத்தகைய செயல்களைச் செய்வதற்கு அப்பாற்பட்ட உண்மையான அரசன் ஆவான்.﴾لَا إِلَهَ إِلاَّ هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ﴿\n\r\n\n\r\n(அவனைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை; அவன் மகத்தான 'அர்ஷின்' (அரியாசனத்தின்) அதிபதி ஆவான்!) அர்ஷ் குறிப்பிடப்பட்டதற்குக் காரணம், அது படைப்புகளிலேயே மிக உயர்ந்த இடமாகும். மேலும் அது 'கரீம்' என விவரிக்கப்பட்டுள்ளது, அதற்கு அழகான தோற்றமும் சிறப்பான வடிவமும் கொண்டது என்று பொருள். இதனை அல்லாஹ் வேறொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:﴾أَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ﴿\n\r\n\n\r\n(அதில் ஒவ்வோர் அழகான இனத்தையும் நாம் முளைக்கச் செய்துள்ளோம்.) 26:7."},"117":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=23&ayah=118\" class=\"link\">23:118</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 23:118 ஐ பார்க்கவும்"},"118":{"html":"<strong>ஷிர்க் (இணைவைத்தல்) என்பது அநீதிகளிலேயே மிக மோசமான வடிவமாகும்; அதைச் செய்பவர் ஒருபோதும் வெற்றி பெற மாட்டார். அல்லாஹ்வுக்கு இணையாக எதனையும் கருதி, அவனுடன் சேர்த்து பிறவற்றையும் வணங்குபவர்களை அல்லாஹ் எச்சரிக்கிறான். அல்லாஹ்வுக்கு இணையாக மற்றவர்களைக் கருதுபவர்களைப் பற்றி அவன் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">بُرْهَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(அதற்கு அவனிடம் எந்த ஆதாரமும் இல்லை), அதாவது அவன் கூறுவதற்கு எந்த அத்தாட்சியும் இல்லை என்று பொருள். பின்னர் அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يَدْعُ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَـٰهًا</span> <span class=\"quran-arabic-font text-success\">آخَرَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">بُرْهَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(யார் அல்லாஹ்வுடன் வேறு ஒரு தெய்வத்தை அழைக்கிறாரோ - அதற்கு அவனிடம் எந்த ஆதாரமும் இல்லை;) இது ஒரு நிபந்தனை வாக்கியமாகும், இதன் நிறைவுப் பகுதி:<span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">حِسَابُهُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ﴿</span><br />\r\n<br />\r\n(அவருடைய கணக்கு அவருடைய இறைவனிடம் மட்டுமே உள்ளது.) அதாவது, அல்லாஹ் அதற்காக அவரிடம் விசாரணை செய்வான். பிறகு அல்லாஹ் நமக்குத் தெரிவிக்கிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُفْلِحُ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நிராகரிப்பாளர்கள் வெற்றி பெற மாட்டார்கள்.) அதாவது, மறுமை நாளில் அவர்கள் அல்லாஹ்விடம் வெற்றி அடைய மாட்டார்கள்; அவர்கள் ஈடேற்றம் பெறவோ அல்லது தப்பிக்கவோ மாட்டார்கள்.<span class=\"quran-arabic-font text-success\">﴾وَقُل</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">وَارْحَمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الرَّاحِمِينَ﴿</span><br />\r\n<br />\r\n(மேலும் (நபியே!) நீர் கூறுவீராக: \"என் இறைவா! மன்னிப்பாயாக! அருள்புரிவாயாக! அருள்புரிபவர்களில் நீயே மிகச் சிறந்தவன்!\") மன்னிப்புக் கோரும் இந்த துஆவை ஓதும்படி அல்லாஹ் இங்கே நமக்குக் கற்றுக்கொடுக்கிறான். பொதுவான அர்த்தத்தில் ‘மன்னிப்பு’ என்பது, பாவங்களைத் துடைத்து, அவற்றை மக்களிடமிருந்து மறைப்பதைக் குறிக்கிறது; 'கருணை' என்பது ஒருவருக்கு நேர்வழி காட்டி, அவர் நல்ல விஷயங்களைச் சொல்லவும் செய்யவும் உதவுவதைக் குறிக்கிறது. இத்துடன் ‘அல்முஃமினூன்’ அத்தியாயத்தின் விரிவுரை நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"ஷிர்க் (இணைவைத்தல்) என்பது அநீதிகளிலேயே மிக மோசமான வடிவமாகும்; அதைச் செய்பவர் ஒருபோதும் வெற்றி பெற மாட்டார். அல்லாஹ்வுக்கு இணையாக எதனையும் கருதி, அவனுடன் சேர்த்து பிறவற்றையும் வணங்குபவர்களை அல்லாஹ் எச்சரிக்கிறான். அல்லாஹ்வுக்கு இணையாக மற்றவர்களைக் கருதுபவர்களைப் பற்றி அவன் கூறுகிறான்:\n\r\n\n\r\n﴾لَا بُرْهَانَ لَهُ بِهِ﴿\n\r\n\n\r\n(அதற்கு அவனிடம் எந்த ஆதாரமும் இல்லை), அதாவது அவன் கூறுவதற்கு எந்த அத்தாட்சியும் இல்லை என்று பொருள். பின்னர் அல்லாஹ் கூறுகிறான்:﴾وَمَن يَدْعُ مَعَ اللَّهِ إِلَـٰهًا آخَرَ لاَ بُرْهَانَ لَهُ بِهِ﴿\n\r\n\n\r\n(யார் அல்லாஹ்வுடன் வேறு ஒரு தெய்வத்தை அழைக்கிறாரோ - அதற்கு அவனிடம் எந்த ஆதாரமும் இல்லை;) இது ஒரு நிபந்தனை வாக்கியமாகும், இதன் நிறைவுப் பகுதி:﴾فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ﴿\n\r\n\n\r\n(அவருடைய கணக்கு அவருடைய இறைவனிடம் மட்டுமே உள்ளது.) அதாவது, அல்லாஹ் அதற்காக அவரிடம் விசாரணை செய்வான். பிறகு அல்லாஹ் நமக்குத் தெரிவிக்கிறான்: ﴾إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ﴿\n\r\n\n\r\n(நிச்சயமாக நிராகரிப்பாளர்கள் வெற்றி பெற மாட்டார்கள்.) அதாவது, மறுமை நாளில் அவர்கள் அல்லாஹ்விடம் வெற்றி அடைய மாட்டார்கள்; அவர்கள் ஈடேற்றம் பெறவோ அல்லது தப்பிக்கவோ மாட்டார்கள்.﴾وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ﴿\n\r\n\n\r\n(மேலும் (நபியே!) நீர் கூறுவீராக: \"என் இறைவா! மன்னிப்பாயாக! அருள்புரிவாயாக! அருள்புரிபவர்களில் நீயே மிகச் சிறந்தவன்!\") மன்னிப்புக் கோரும் இந்த துஆவை ஓதும்படி அல்லாஹ் இங்கே நமக்குக் கற்றுக்கொடுக்கிறான். பொதுவான அர்த்தத்தில் ‘மன்னிப்பு’ என்பது, பாவங்களைத் துடைத்து, அவற்றை மக்களிடமிருந்து மறைப்பதைக் குறிக்கிறது; 'கருணை' என்பது ஒருவருக்கு நேர்வழி காட்டி, அவர் நல்ல விஷயங்களைச் சொல்லவும் செய்யவும் உதவுவதைக் குறிக்கிறது. இத்துடன் ‘அல்முஃமினூன்’ அத்தியாயத்தின் விரிவுரை நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
